window.__DICT_CHUNKS__=window.__DICT_CHUNKS__||{};window.__DICT_CHUNKS__["B"]={"527":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧by</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪbi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural babies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[young child]</strong> a very young child who has not yet learned to speak or walk: → test-tube baby</div><ul class=\"examples\"><li><em>The baby is crying.</em></li><li><em>She gave birth to a baby on Thursday.</em></li><li><em>What do you think of your new baby sister?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[young animal]</strong> a very young animal:</div><ul class=\"examples\"><li><em>baby birds</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[vegetable]</strong> a type of vegetable which is grown to be much smaller than usual or is eaten before it has grown to its normal size:</div><ul class=\"examples\"><li><em>baby carrots</em></li><li><em>baby sweetcorn</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[youngest]</strong> a younger child in a family, often the youngest:</div><ul class=\"examples\"><li><em>Clare is the baby of the family.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[woman]</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to address someone that you love:</div><ul class=\"examples\"><li><em>· Relax, baby – we’re on holiday.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>not polite</em> used to address a young woman that you do not know</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[silly person]</strong> someone, especially an older child, who is not behaving in a brave way:</div><ul class=\"examples\"><li><em>Don’t be a baby!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[responsibility]</strong> something special that someone has developed or is responsible for:</div><ul class=\"examples\"><li><em>Don’t ask me about the building contract – that’s Robert’s baby.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[thing]</strong> <em>informal</em> something, especially a piece of equipment or a machine, that you care about a lot:</div><ul class=\"examples\"><li><em>This baby can reach speeds of 130 miles per hour.</em></li></ul></div>","528":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bach‧e‧lor</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbætʃələ $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a man who has never been married: ► see thesaurus at married</div><ul class=\"examples\"><li><em>Gerald was 38, and a confirmed bachelor (=a man who has decided that he will never marry).</em></li><li><em>The Crown Prince was Japan’s most eligible bachelor (=a rich young man who has not yet married).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>Bachelor of Arts/Science/Education etc</strong> a first university degree in an arts subject, a science subject etc → BA, BSc, BEd</div></div>","529":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[return to place]</strong> in, into, or to the place or position where someone or something was before: GRAMMAR• You go back to a place: · We decided to go back to Athens.· I’m going back to school tomorrow.• You go back home: · It’s time to go back home. ✗Don’t say: go back to home</div><ul class=\"examples\"><li><em>I’ll be back in a minute.</em></li><li><em>Put that book back where you found it!</em></li><li><strong><em>back in/to/into etc</strong>: Rory plugged the cable back into the socket. / I feel like going back to bed.</em></li><li><strong><em>go/get/head etc back</strong>: We ought to try and get back before it gets dark.</em></li><li><em>He was back home by half past eleven.</em></li><li><em>It’s possible to travel there and back in a day.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[as before]</strong> in or into the condition or situation you were in before:</div><ul class=\"examples\"><li><em>Gary woke at 4 am and couldn’t get back to sleep.</em></li><li><em>It took me a long time to get my confidence back.</em></li><li><em>If you decide to marry him, there will be no going back (=you will not be able to get back to your previous situation).</em></li><li><strong><em>go/get back to (doing) something</strong>: There’s no way I’m going back to being poor. / It’ll take a while for things to get back to normal.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[previous place]</strong> in or to a place where you lived or worked before</div><ul class=\"examples\"><li><strong><em>back in/at</strong>: She was the one who had fired him from his first job back in South Africa.</em></li><li><strong><em>back home</strong> (=in the place that you come from and think of as your home): It reminded me of evenings back home.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[backwards]</strong> in the opposite direction from the way you are facing <em>OPP forwards</em>:</div><ul class=\"examples\"><li><em>He glanced back at the house.</em></li><li><em>Kirov stepped back a pace.</em></li><li><em>She tilted her head back to look at him.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[reply/reaction]</strong> if you do something back, you do it as a reply or reaction to what someone has said or done:</div><ul class=\"examples\"><li><em>Can I call you back later?</em></li><li><em>I’ll pay you back on Friday.</em></li><li><em>‘No, thanks!’ he shouted back.</em></li><li><em>If he hits you, you just hit him back.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[return something to somebody]</strong> if you give something, get something etc back, you return it to the person who first had it, or you have it returned to you:</div><ul class=\"examples\"><li><em>Can we have our ball back, please?</em></li><li><em>I want all my books back as soon as you’ve finished with them.</em></li><li><em>Give me back that letter! It’s none of your business!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[in the past]</strong> in or towards a time in the past:</div><ul class=\"examples\"><li><em>a pile of newspapers dating back to the 1970s</em></li><li><em>A lot of emotional problems can be traced back to childhood.</em></li><li><em>Looking back on it, I should have known he was unhappy.</em></li><li><em>At times, I think back to my life in Moscow.</em></li><li><strong><em>back in</strong>: The house was built back in 1235.</em></li><li><strong><em>three years/two months etc back</strong> (=three years etc ago): His wife died a couple of years back. / He called me a while back.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[again]</strong> once again:</div><ul class=\"examples\"><li><em>Go back over your work to check for any mistakes.</em></li><li><em>Liverpool were back level again two minutes later with a superb goal.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>sit/lie/lean back</strong> to sit or lie in a comfortable relaxed way:</div><ul class=\"examples\"><li><em>Sit back, relax, and enjoy the show!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[away]</strong> away from a surface, person, or thing:</div><ul class=\"examples\"><li><em>She pulled the bandage back very carefully.</em></li><li><em>Her hair was brushed back from her face.</em></li><li><em>The woman nodded and stood back, allowing Patrick to enter.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>back and forth</strong> going in one direction and then in the opposite direction, and repeating this several times:</div><ul class=\"examples\"><li><em>We travel back and forth all the time between Canada and England.</em></li><li><em>He was pacing back and forth.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[towards beginning]</strong> towards the beginning of a book, film, or computer document etc:</div><ul class=\"examples\"><li><em>Turn back to the summaries at the end of section 1.5.</em></li><li><em>Clicking on the icon will take you back to the previous web page.</em></li><li><em>Wind the tape back to the beginning.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[part of your body]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the part of the body between the neck and legs, on the opposite side to the stomach and chest:</div><ul class=\"examples\"><li><em>The cat arched its back and hissed.</em></li><li><em>My feet were sore and my back was aching.</em></li><li><em>Keep your head up and your back straight.</em></li><li><em>To avoid back problems, always bend your knees when you lift heavy objects.</em></li><li><em>He lay on his back and gazed at the ceiling.</em></li><li><em>Johnny was lying flat on his back in the middle of the floor.</em></li><li><em>Anna stood with her back to the window.</em></li><li><strong><em>on somebody’s back</strong> (=carried on someone’s back): The girl appeared again, now with a little baby on her back.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the bones between your neck and the top of your legs <em>SYN spine</em>:</div><ul class=\"examples\"><li><em>He broke his back in a motorbike accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[not at front]</strong> <span class=\"gram\">[usually singular]</span> the part of something that is furthest from the front <em>OPP front</em>:</div><ul class=\"examples\"><li><em>a T-shirt with a picture of a snake on the back</em></li><li><strong><em>back of</strong>: He kissed her on the back of her head. / Her window faced the backs of the houses.</em></li><li><strong><em>in the back (of something)</strong> (=used especially about the back of a vehicle): Two men were sitting in the back of the car.</em></li><li><strong><em>at the back (of something)</strong>: a small shop with an office at the back</em></li><li><strong><em>in back (of something)<em>American English</em></strong> (=in or at the back of something): Kids should always wear seat belts, even in back.</em></li><li><strong><em>out back<em>American English</em></strong> (=behind a house or other building): Tom’s working on the car out back.</em></li><li><strong><em>round/out the back<em>British English</em></strong> (=behind a house or building): Have you looked round the back?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[less important side]</strong> <span class=\"gram\">[usually singular]</span> the less important side or surface of something such as a piece of paper or card <em>OPP front</em>:</div><ul class=\"examples\"><li><em>Paul scribbled his address on the back of an envelope.</em></li><li><em>The credits are listed on the back of the album.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[part of seat]</strong> the part of a seat that you lean against when you are sitting</div><ul class=\"examples\"><li><strong><em>back of</strong>: He rested his arm on the back of the sofa.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[book/newspaper]</strong> <span class=\"gram\">[usually singular]</span> the last pages of a book or newspaper <em>OPP front</em></div><ul class=\"examples\"><li><strong><em>at the back (of)</strong>: The sports pages are usually at the back.</em></li><li><strong><em>in the back (of)</strong>: The answers are in the back of the book.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>at/in the back of your mind</strong> a thought that is at the back of your mind is one you try to ignore because you do not want it to be true:</div><ul class=\"examples\"><li><em>At the back of her mind was the thought that he might be with someone else.</em></li><li><strong><em>put/push something to the back of your mind</strong>: He tried to push these uncomfortable thoughts to the back of his mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>back to back</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> with the backs towards each other:</div><ul class=\"examples\"><li><em>Stand back to back and we’ll see who’s tallest.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> happening immediately one after the other: → back-to-back1</div><ul class=\"examples\"><li><em>He performed up to three times a day, often back to back.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>back to front</strong> <em>British English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in an incorrect position so that what should be at the back is at the front:</div><ul class=\"examples\"><li><em>You’ve got your sweater on back to front.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> doing something the wrong way round and starting with the part that should be at the end:</div><ul class=\"examples\"><li><em>He got the commands back to front and the program didn’t work.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>behind somebody’s back</strong> if you do something behind someone’s back, you do it without them knowing:</div><ul class=\"examples\"><li><em>I don’t like the idea of the two of them talking about me behind my back.</em></li><li><em>I should have realized that he’d go behind my back (=do something without telling me).</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>when/while somebody’s back is turned</strong> if something happens when your back is turned, it happens when you are not able to see or know what someone is doing:</div><ul class=\"examples\"><li><em>What are your kids up to when your back is turned?</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>get/put somebody’s back up</strong> <em>British English</em> <em>informal</em> to annoy someone:</div><ul class=\"examples\"><li><em>Simone was the kind of person who was always putting people’s backs up.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>get (somebody) off somebody’s back</strong> <em>spoken</em> to stop annoying someone with a lot of questions, criticisms etc, or to make someone stop annoying you in this way:</div><ul class=\"examples\"><li><em>Maybe the only way to get him off my back is to tell him the truth.</em></li><li><em>Do me a favour and get off my back!</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be on somebody’s back</strong> <em>spoken</em> to be trying to make someone do something they do not want to do:</div><ul class=\"examples\"><li><em>Why are you and Dad always on my back?</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>on the back of something</strong> as a result of something that already exists or something you have already done:</div><ul class=\"examples\"><li><em>The company should be able to generate business on the back of existing contracts.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>on the backs of somebody</strong> using the work of a particular group to achieve something that they will not get any advantage from:</div><ul class=\"examples\"><li><em>Economic prosperity was won on the backs of the urban poor.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[sports]</strong> a defending player in a sports team <em>SYN defender</em></div><div class=\"sense\"><span class=\"snum\">17</span> <strong>the back of beyond</strong> <em>informal</em> a place that is a long way from other places and is difficult to get to:</div><ul class=\"examples\"><li><em>It’s a nice little cottage but it really is in the back of beyond.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>be (flat) on your back</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be lying on your back – used to emphasize that someone seems unlikely to get up soon:</div><ul class=\"examples\"><li><em>He was drunk and flat on his back on the street.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be so ill that you cannot get out of bed:</div><ul class=\"examples\"><li><em>Their best player was flat on his back in hospital.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> if a business, country, economy etc is on its back, it is not successful:</div><ul class=\"examples\"><li><em>The UK market was flat on its back.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>put your back into it</strong> <em>informal</em> to work extremely hard at something:</div><ul class=\"examples\"><li><em>If we really put our backs into it, we could finish today.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>be glad/delighted/pleased etc to see the back of somebody/something</strong> to be happy that someone is leaving or because you no longer have to deal with something:</div><ul class=\"examples\"><li><em>No, I’m not too upset that he left – in fact, I was glad to see the back of him.</em></li><li><em>I can’t wait to see the back of this project, I can tell you (=I will be happy when it ends).</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>have your back to/against the wall</strong> <em>informal</em> to be in a difficult situation with no choice about what to do</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>at your back</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> behind you:</div><ul class=\"examples\"><li><em>They had the wind at their backs as they set off.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> supporting you:</div><ul class=\"examples\"><li><em>Caesar marched into Rome with an army at his back.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>on your back</strong> <em>informal</em> <em>not polite</em> if someone achieves something on their back, they achieve it by having sex with someone</div><div class=\"sense\"><span class=\"snum\">24</span> <strong>high-backed/straight-backed/low-backed etc</strong> with a high, straight, low etc back:</div><ul class=\"examples\"><li><em>a high-backed chair</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[support]</strong> <span class=\"gram\">[transitive]</span> ► see thesaurus at support GRAMMAR Back is usually passive in this meaning.</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to support someone or something, especially by giving them money or using your influence:</div><ul class=\"examples\"><li><em>The scheme has been backed by several major companies in the region.</em></li><li><em>Some suspected that the rebellion was backed and financed by the US.</em></li><li><em>government-backed loans</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also back up) to support an idea by providing facts, proof etc:</div><ul class=\"examples\"><li><em>His claims are not backed by any scientific evidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[move backwards]</strong> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to move backwards, or make someone or something move backwards</div><ul class=\"examples\"><li><strong><em>back into/out of/away from etc</strong>: She backed into a doorway to let the crowds pass by.</em></li><li><strong><em>back somebody into/towards/out of etc something</strong>: He began to back her towards the open door.</em></li><li><strong><em>back something into/towards/out of etc something</strong>: I backed the car into the garage.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[put something on the back]</strong> <span class=\"gram\">[transitive]</span> to put a material or substance onto the back of something, in order to protect it or make it stronger: GRAMMAR Back is usually passive in this meaning.</div><ul class=\"examples\"><li><em>The photograph is backed with cardboard.</em></li><li><em>a plastic-backed shower curtain</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[be behind something]</strong> <span class=\"gram\">[transitive]</span> to be at the back of something or behind it: GRAMMAR Back is usually passive in this meaning.</div><ul class=\"examples\"><li><em>The Jandia Peninsula is a stretch of white sands backed by a mountain range.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[music]</strong> <span class=\"gram\">[transitive]</span> to play or sing the music that supports the main singer or musician: GRAMMAR Back is usually passive in this meaning.</div><ul class=\"examples\"><li><em>They performed all their hits, backed by a 40-piece orchestra.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[risk money]</strong> <span class=\"gram\">[transitive]</span> to risk money on whether a particular horse, dog, team etc wins something</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>back the wrong horse</strong> to support someone or something that is not successful</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> at or in the back of something <em>OPP front</em>: → back door</div><ul class=\"examples\"><li><em>You’ll be sleeping in the back bedroom.</em></li><li><em>Turn to the back page.</em></li><li><em>I keep my keys in my back pocket.</em></li><li><em>There was the sound of giggling from the back row.</em></li><li><em>The rabbit had one of its back legs caught in a trap.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> behind something, especially a building <em>OPP front</em>:</div><ul class=\"examples\"><li><em>the back garden</em></li><li><em>We left by the back gate.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> from the back:</div><ul class=\"examples\"><li><em>The back view of the hotel was even less appealing than the front.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>back street/lane/road etc</strong> a street etc that is away from the main streets:</div><ul class=\"examples\"><li><em>a short cut down a back lane</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>back rent/taxes/pay etc</strong> money that someone owes from an earlier date</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>back issue/copy/number</strong> a copy of a magazine or newspaper from an earlier date</div><div class=\"sense\"><span class=\"snum\">7</span> <em>technical</em> a back vowel sound is made by lifting your tongue at the back of your mouth</div></div></div>","530":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧bone</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækbəʊn $ -boʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the row of connected bones that go down the middle of your back <em>SYN spine</em></div><div class=\"sense\"><span class=\"snum\">2</span> <strong>the backbone of something</strong> the most important part of an organization or group of people:</div><ul class=\"examples\"><li><em>Farmers are the backbone of this community.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> courage and determination:</div><ul class=\"examples\"><li><em>Stuart doesn’t have the backbone to be a good manager.</em></li></ul></div>","531":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧fire</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbækˈfaɪə $ ˈbækfaɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if a plan or action backfires, it has the opposite effect to the one you intended: ► see thesaurus at fail</div><ul class=\"examples\"><li><em>The company’s new policy backfired when a number of employees threatened to quit.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if a car backfires, it makes a sudden loud noise because the engine is not working correctly</div></div>","532":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧ground</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækɡraʊnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> someone’s family, education, previous work etc:</div><ul class=\"examples\"><li><em>Students with a background in chemistry will probably find the course easier.</em></li><li><em>It’s important to understand other people, people from different backgrounds.</em></li><li><em>Do you know anything about his background?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the situation or past events that explain why something happens in the way that it does</div><ul class=\"examples\"><li><strong><em>background to</strong>: Without knowing the background to the case, I couldn’t possibly comment.</em></li><li><strong><em>against a background of something</strong>: The peace talks are being held against a background of increasing violence.</em></li><li><strong><em>background information/details/data etc</strong>: The author included a new chapter of background material for the second edition of the book.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable usually singular]</span> the area that is behind the main thing that you are looking at, especially in a picture:</div><ul class=\"examples\"><li><em>The background looks out of focus.</em></li><li><strong><em>in the background</strong>: In the background, you can see my college friends.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> the pattern or colour on top of which something has been drawn, printed etc:</div><ul class=\"examples\"><li><em>red lettering on a white background</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>in the background</strong> someone who keeps or stays in the background tries not to be noticed:</div><ul class=\"examples\"><li><em>The president’s advisors are content to remain in the background.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable, uncountable]</span> the sounds that you can hear apart from the main thing that you are listening to</div><ul class=\"examples\"><li><strong><em>in the background</strong>: In the background, I could hear the sound of traffic.</em></li><li><em>All of the background noise made it difficult to have a phone conversation.</em></li></ul></div>","533":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> support or help, especially with money:</div><ul class=\"examples\"><li><em>She flew to New York to try to raise some financial backing for the project.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> material that is used to make the back of an object</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the music that is played at the same time as a singer’s voice</div></div>","534":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧pack</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækpæk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a rucksack</div></div>","535":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧slash</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækslæʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a line () used in writing to separate words, numbers, or letters</div></div>","536":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧up</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækʌp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something that you can use to replace something that does not work or is lost:</div><ul class=\"examples\"><li><em>Always have a backup plan.</em></li><li><em>a backup generator</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a copy of a computer document, program etc, which is made in case the original becomes lost or damaged:</div><ul class=\"examples\"><li><em>Make a backup of any work you do on the computer.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> people or things that can be used to provide support and help if they are needed:</div><ul class=\"examples\"><li><em>Army units can only operate if they have sufficient backup.</em></li><li><em>a backup team</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>American English</em> someone who will play in a sports team if one of the other players is injured or ill <em>SYN reserve</em>:</div><ul class=\"examples\"><li><em>a backup goalie</em></li></ul></div>","537":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧ward</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækwəd $ -wərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> looking or facing in the direction that is behind you <em>OPP forward</em>:</div><ul class=\"examples\"><li><em>She went without a backward glance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> developing slowly and less successfully than most others:</div><ul class=\"examples\"><li><em>a backward country</em></li><li><em>a backward child</em></li></ul></div>","538":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> back‧wards</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbækwədz $ -wərdz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in the direction that is behind you <em>OPP forwards</em>:</div><ul class=\"examples\"><li><em>Hannah took a step backward.</em></li><li><em>She pushed me and I fell backwards into the chair.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> towards the beginning or the past <em>OPP forwards</em>:</div><ul class=\"examples\"><li><em>Count backwards from 100.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> with the back part in front:</div><ul class=\"examples\"><li><em>Your T-shirt is on backwards.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> towards a worse state <em>OPP forwards</em>:</div><ul class=\"examples\"><li><em>The new measures are seen by some as a major step backwards.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>backwards and forwards</strong> first in one direction and then in the opposite direction, usually many times:</div><ul class=\"examples\"><li><em>Kip stumbled backwards and forwards before falling down.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>bend/lean over backwards (to do something)</strong> to try as hard as possible to help or please someone:</div><ul class=\"examples\"><li><em>City officials bent over backwards to help downtown businesses.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>know something backwards</strong> <em>British English,</em> <strong>know something backwards and forwards</strong> <em>American English</em> to know something very well or perfectly:</div><ul class=\"examples\"><li><em>She practiced her part until she knew it backwards and forwards.</em></li></ul></div>","539":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧con</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪkən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> salted or smoked meat from the back or sides of a pig, often served in narrow thin pieces:</div><ul class=\"examples\"><li><em>bacon and eggs</em></li><li><strong><em>rasher of bacon<em>British English</em></strong> (=piece of bacon)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bring home the bacon</strong> <em>informal</em> to provide enough money to support your family</div></div>","540":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bac‧te‧ri‧a</span><span class=\"meta-item\"><strong>IPA:</strong> /bækˈtɪəriə $ -ˈtɪr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">very small living things, some of which cause illness or disease → virus</div></div>","541":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative worse /wɜːs $ wɜːrs/, superlative worst /wɜːst $ wɜːrst/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[not good]</strong> unpleasant or likely to cause problems <em>OPP good</em>:</div><ul class=\"examples\"><li><em>I have some bad news for you.</em></li><li><em>I thought things couldn’t possibly get any worse.</em></li><li><em>The plane was delayed for several hours by bad weather.</em></li><li><em>It’s difficult to break bad habits.</em></li><li><em>a bad smell</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[low quality]</strong> low in quality or below an acceptable standard <em>OPP good</em>:</div><ul class=\"examples\"><li><em>The failure of the company was due to bad management.</em></li><li><em>Your handwriting is so bad I can hardly read it.</em></li><li><em>That was the worst movie I’ve ever seen.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[not sensible]</strong> <span class=\"gram\">[usually before noun]</span> not sensible, or not suitable in a particular situation <em>OPP good</em>:</div><ul class=\"examples\"><li><em>Cutting spending at this time is a bad idea.</em></li><li><em>Making big changes in your diet all at once is a bad thing to do.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[morally wrong]</strong> morally wrong or evil <em>OPP good</em>: → bad guy</div><ul class=\"examples\"><li><em>He’s a bad man – keep away from him.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[wrong behaviour]</strong> <em>spoken</em> doing something you should not do, or behaving in a wrong way – used especially about children or pets <em>SYN naughty</em>:</div><ul class=\"examples\"><li><em>Katie was very bad today!</em></li><li><strong><em>bad girl/dog etc</strong>: Bad cat! Get off the table!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[serious]</strong> serious or severe:</div><ul class=\"examples\"><li><em>He was in a bad accident.</em></li><li><em>The pain in my side is worse than it was yesterday.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>a bad time/moment etc</strong> a time that is not suitable or causes problems:</div><ul class=\"examples\"><li><em>It’s a bad time to have to borrow money, with interest rates so high.</em></li><li><em>You’ve come at the worst possible moment. I have a meeting in five minutes.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[harmful]</strong> damaging or harmful:</div><ul class=\"examples\"><li><em>Pollution is having a bad effect on fish stocks.</em></li><li><strong><em>bad for</strong>: Smoking is bad for your health. / Too much salt can be bad for you.</em></li><li><em>It is bad for kids to be on their own so much.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[food]</strong> food that is bad is not safe to eat because it has decayed:</div><ul class=\"examples\"><li><em>bad fish</em></li><li><em>This milk has gone bad.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[no skill]</strong> having no skill or ability in a particular activity</div><ul class=\"examples\"><li><strong><em>bad at (doing) something</strong>: I’m really bad at chess.</em></li><li><em>They have got to be the worst band on the planet.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>bad heart/leg/back etc</strong> a heart, leg etc that is injured or does not work correctly:</div><ul class=\"examples\"><li><em>I haven’t been able to do much because of my bad back.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[language]</strong> bad language is rude or offensive:</div><ul class=\"examples\"><li><em>We were shocked to hear the little boy using bad language in front of his mother.</em></li><li><em>Jacky said a bad word!</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be in a bad mood</strong> (also be in a bad temper<em>British English</em>) to feel annoyed or angry:</div><ul class=\"examples\"><li><em>The boss is in a bad mood.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>feel bad</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to feel ashamed or sorry about something</div><ul class=\"examples\"><li><strong><em>feel bad about (doing) something</strong>: I felt bad about not being able to come last night.</em></li><li><strong><em>bad for</strong>: I feel bad for Ann – she studied so hard for that test and she still didn’t pass.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to feel ill</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>not bad</strong> <em>spoken</em> used to say that something is good, or better than you expected:</div><ul class=\"examples\"><li><em>‘How are you?’ ‘Oh, not bad.’</em></li><li><em>That’s not a bad idea.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>not too/so bad</strong> <em>spoken</em> used to say that something is not as bad as expected:</div><ul class=\"examples\"><li><em>The exams weren’t so bad.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>too bad</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that you do not care that something bad happens to someone:</div><ul class=\"examples\"><li><em>‘I’m going to be late now!’ ‘Too bad – you should have gotten up earlier.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that you are sorry that something bad has happened to someone:</div><ul class=\"examples\"><li><em>It’s too bad that you couldn’t come to the party last night.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>go from bad to worse</strong> to become even more unpleasant or difficult:</div><ul class=\"examples\"><li><em>The schools have gone from bad to worse in this area.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>be in a bad way</strong> <em>informal</em> to be very ill, unhappy, or injured, or not in a good condition:</div><ul class=\"examples\"><li><em>She was in a bad way after the funeral.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>a bad name</strong> if something has a bad name, people do not respect or trust it</div><ul class=\"examples\"><li><strong><em>have/get a bad name</strong>: The bar had a bad name and was avoided by all the locals.</em></li><li><strong><em>give somebody/something a bad name</strong>: These annoying tourists give all Americans a bad name.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>bad lot/sort/type</strong> <em>British English</em> <em>old-fashioned</em> someone who is morally bad or cannot be trusted</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>bad penny</strong> <em>British English</em> someone or something that causes trouble and is difficult to avoid:</div><ul class=\"examples\"><li><em>Sure enough, Steve turned up like the proverbial bad penny (=suddenly appeared).</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>be taken bad</strong> <em>British English</em> <em>informal</em> to become ill:</div><ul class=\"examples\"><li><em>He was taken bad in the middle of the night.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>in bad faith</strong> if someone does something in bad faith, they are behaving dishonestly and have no intention of keeping a promise:</div><ul class=\"examples\"><li><em>In order to sue, you have to prove that the company was acting in bad faith.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>bad news</strong> <em>spoken</em> <em>informal</em> someone or something that always causes trouble:</div><ul class=\"examples\"><li><em>I’d avoid her if I were you. She’s bad news.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>bad form</strong> <em>British English</em> <em>old-fashioned</em> socially unacceptable behaviour:</div><ul class=\"examples\"><li><em>It’s bad form to argue with the umpire.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>bad blood</strong> angry or bitter feelings between people</div><ul class=\"examples\"><li><strong><em>bad between</strong>: There’s too much bad blood between them.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>not have a bad word to say about/against somebody</strong> if no one has a bad word to say about a particular person, everyone likes and respects that person</div><div class=\"sense\"><span class=\"snum\">29</span> <strong>it’s bad enough...</strong> <em>spoken</em> used to say that you already have one problem, so that you do not want to worry about or deal with another one:</div><ul class=\"examples\"><li><em>It’s bad enough having to bring up three kids on your own, without having to worry about money as well!</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>something can’t be bad</strong> <em>spoken</em> used to persuade someone that something is good or worth doing:</div><ul class=\"examples\"><li><em>You only pay £10 deposit and no interest – that can’t be bad, can it?</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> (comparative badder, superlative baddest) <em>spoken</em> <em>informal</em> <em>especially American English</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when you think something is very good:</div><ul class=\"examples\"><li><em>Now that’s a bad car!</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> someone who is bad is very determined and does not always obey rules – used to show approval</div></div>","542":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌbad-ˈtempered</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">someone who is bad-tempered becomes easily annoyed and talks in an angry way to people <em>SYN irritable</em> ► see thesaurus at angry</div></div>","543":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bædʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a small piece of metal, cloth, or plastic with a picture or words on it, worn to show rank, membership of a group, support for a political idea etc SYN button, pin<em>American English</em>:</div><ul class=\"examples\"><li><em>We were each handed a badge with our name on it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small piece of metal or plastic that you carry to show people that you work for a particular organization, for example that you are a police officer</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>a badge of honour/courage etc</strong> something that shows that you have a particular quality:</div><ul class=\"examples\"><li><em>He now sees his wartime injuries as a badge of honor.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (also merit badge<em>American English</em>) a small piece of cloth with a picture on it, given to scouts, guides etc to show what skills they have learned:</div><ul class=\"examples\"><li><em>Steve won a photography badge in the Boy Scouts.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>badge of office</strong> <em>British English</em> an object which shows that you have an official position:</div><ul class=\"examples\"><li><em>Mayors wear chains around their necks as badges of office.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> an icon that provides a link to another web page, for example to your page on a social networking site:</div><ul class=\"examples\"><li><em>How do I add a badge to my blog?</em></li></ul></div>","544":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bad‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbædli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(comparative worse /wɜːs $ wɜːrs/, superlative worst /wɜːst $ wɜːrst/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in an unsatisfactory or unsuccessful way <em>OPP well</em>:</div><ul class=\"examples\"><li><em>The company has been very badly managed.</em></li><li><em>The novel was translated badly into English.</em></li><li><em>badly made furniture</em></li><li><em>Rob did very badly in the History exam.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to a great or serious degree:</div><ul class=\"examples\"><li><em>He’s been limping badly ever since the skiing accident.</em></li><li><em>We badly wanted to help, but there was nothing we could do.</em></li><li><em>He was beaten so badly that his brother didn’t recognize him.</em></li><li><em>The school is badly in need of (=very much needs) some new computers.</em></li><li><em>Things started to go badly wrong (=go wrong in a serious way) for Eric after he lost his job.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>think badly of somebody/something</strong> to have a bad opinion of someone or something:</div><ul class=\"examples\"><li><em>I’m sure they won’t think badly of you if you tell them you need some help.</em></li></ul></div>","545":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> baf‧fle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">if something baffles you, you cannot understand or explain it at all:</div><ul class=\"examples\"><li><em>The question baffled me completely.</em></li></ul></div>","546":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[container]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a container made of paper, cloth, or thin plastic, that usually opens at the top:</div><ul class=\"examples\"><li><em>a paper bag</em></li><li><em>a plastic bag</em></li><li><em>a garbage bag</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a handbag:</div><ul class=\"examples\"><li><em>Don’t leave your bag in the car.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> a large bag that you use to carry your clothes etc when you are travelling:</div><ul class=\"examples\"><li><em>Just throw your bags in the back of the car.</em></li><li><em>a garment bag</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[amount]</strong> the amount that a bag will hold</div><ul class=\"examples\"><li><strong><em>bag of</strong>: a bag of popcorn</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>old/stupid bag</strong> <em>spoken</em> an insulting word for an old woman:</div><ul class=\"examples\"><li><em>You silly old bag!</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[a lot of something]</strong> <strong>bags of something</strong> <em>British English</em> <em>spoken</em> a lot of something <em>SYN plenty</em>:</div><ul class=\"examples\"><li><em>She’s got bags of money.</em></li><li><em>No need to rush – we’ve got bags of time.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>pack your bags</strong> <em>informal</em> to leave a place where you have been living, usually after an argument:</div><ul class=\"examples\"><li><em>We told her to pack her bags at once.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[eyes]</strong> <strong>bags</strong> <span class=\"gram\">[plural]</span> dark circles or loose skin under your eyes, usually because of old age or being tired</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>a bag of bones</strong> <em>informal</em> a person or animal who is too thin</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>in the bag</strong> <em>informal</em> certain to be won or achieved:</div><ul class=\"examples\"><li><em>The governor’s advisors believe the election is in the bag.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[trousers]</strong> <strong>bags</strong> <span class=\"gram\">[plural]</span> <em>British English</em> <em>old-fashioned</em> loose-fitting trousers:</div><ul class=\"examples\"><li><em>Oxford bags</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>not somebody’s bag</strong> <em>old-fashioned</em> <em>informal</em> something that someone is not very interested in or not very good at:</div><ul class=\"examples\"><li><em>Thanks, but dancing is not really my bag.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>bag and baggage</strong> <em>British English</em> with all your possessions:</div><ul class=\"examples\"><li><em>They threw her out of the house, bag and baggage.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[hunting]</strong> <span class=\"gram\">[usually singular]</span> <em>British English</em> the number of birds or animals that someone kills when they go hunting:</div><ul class=\"examples\"><li><em>We had a good bag that day.</em></li></ul></div>","547":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bag‧gage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæɡɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> <em>especially American English</em> the cases, bags, boxes etc carried by someone who is travelling <em>SYN luggage</em>: RegisterIn everyday English, people usually say bags rather than baggage:· Shall I help you take your bags upstairs? GRAMMAR: Countable or uncountable?• Baggage is an uncountable noun and is not used in the plural. You say: · We can put our baggage in the locker. ✗Don’t say: We can put our baggages in the locker.• Baggage is always followed by a singular verb: · What happens if my baggage gets lost?• When talking about one suitcase or bag, you say a piece of baggage or an item of baggage: · Each piece of baggage can weigh up to 20 kilos.</div><ul class=\"examples\"><li><em>Check your baggage in at the desk.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> <em>informal</em> the beliefs, opinions, and experiences that someone has, which make them think in a particular way, especially in a way that makes it difficult to have good relationships:</div><ul class=\"examples\"><li><em>Each employee brings his or her own psychological baggage to the workplace.</em></li></ul></div>","548":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> money left with a court of law to make sure that a prisoner will return when their trial starts:</div><ul class=\"examples\"><li><em>Carpenter is free on bail while he appeals his conviction.</em></li><li><em>She was murdered by a man who was out on bail for rape.</em></li><li><em>The three men were released on bail pending an appeal.</em></li><li><em>He is not likely to be granted bail.</em></li><li><em>Carter has been refused bail and will remain in custody.</em></li><li><em>The judge ordered that Jones be held without bail.</em></li><li><em>Why can’t you ask your father to put up bail for you?</em></li><li><em>Two of the defendants jumped bail and fled to New York.</em></li><li><em>Bail was set at $30,000.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> one of the two small pieces of wood laid on top of the stumps in a game of cricket</div></div>","549":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> food used to attract fish, animals, or birds so that you can catch them:</div><ul class=\"examples\"><li><em>We used worms as bait.</em></li><li><em>The fish wouldn’t take the bait.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something attractive that is offered to someone to make them do something or buy something, especially when this is done in a dishonest way that tricks people:</div><ul class=\"examples\"><li><em>Plenty of people took the bait (=accepted what was on offer) and lost their life savings.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>rise to the bait</strong> to become angry when someone is deliberately trying to make you angry:</div><ul class=\"examples\"><li><em>Senator O&#x27;Brien just smiled, refusing to rise to the bait.</em></li></ul></div>","550":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to cook something using dry heat, in an oven: ► see thesaurus at cook</div><ul class=\"examples\"><li><em>I’m baking some bread.</em></li><li><em>baked potatoes</em></li><li><em>Bake at 250 degrees for 20 minutes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make something become hard by heating it:</div><ul class=\"examples\"><li><em>The bricks were baked in the sun.</em></li></ul></div>","551":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bak‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪkə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who bakes bread and cakes, especially in order to sell them in a shop</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>baker’s</strong> <em>British English</em> a shop that makes and sells bread and cakes <em>SYN bakery</em></div></div>","552":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bak‧er‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪkəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural bakeries)</span></div><div class=\"entry-body\"><div class=\"sense\">a place where bread and cakes are baked, or a shop where they are sold</div></div>","553":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧ance</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæləns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[steady]</strong> <span class=\"gram\">[uncountable]</span> a state in which all your weight is evenly spread so that you do not fall:</div><ul class=\"examples\"><li><em>I lost my balance and fell on my face.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[equal amounts]</strong> <span class=\"gram\">[singular, uncountable]</span> a state in which opposite forces or influences exist in equal or the correct amounts, in a way that is good <em>OPP imbalance</em></div><ul class=\"examples\"><li><strong><em>balance between</strong>: Try to keep a balance between work and play.</em></li><li><strong><em>balance of</strong>: Pesticides seriously upset the balance of nature.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on balance</strong> if you think something on balance, you think it after considering all the facts:</div><ul class=\"examples\"><li><em>I think on balance I prefer the old system.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[surprise somebody]</strong> <strong>catch/throw somebody off balance</strong> to surprise someone and make them confused and no longer calm:</div><ul class=\"examples\"><li><em>The question caught him off balance.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[bank]</strong> <span class=\"gram\">[countable]</span> the amount of money that you have in your bank account:</div><ul class=\"examples\"><li><em>My bank balance isn’t good.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[money owed]</strong> <span class=\"gram\">[countable]</span> the balance of a debt is the amount of money that you still owe after you have paid some of it:</div><ul class=\"examples\"><li><em>The balance is due at the end of the month.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[remaining]</strong> <strong>the balance</strong> the amount of something that remains after some has been used, spent, mentioned etc <em>SYN the rest</em>:</div><ul class=\"examples\"><li><em>The firm owns about 96% of the portfolio, with the balance belonging to our family.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be/hang in the balance</strong> if the future or success of something hangs in the balance, you cannot yet know whether the result will be bad or good:</div><ul class=\"examples\"><li><em>Meanwhile, the fate of the refugees continues to hang in the balance.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>tip/swing the balance</strong> to influence the result of an event:</div><ul class=\"examples\"><li><em>The dignity and courage shown by the president may tip the balance in his party’s favour.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[for weighing]</strong> <span class=\"gram\">[countable]</span> an instrument for weighing things, with two dishes that hang from a bar <em>SYN scales</em></div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[mental/emotional health]</strong> <span class=\"gram\">[singular]</span> when someone’s mind is healthy and their emotional state is normal:</div><ul class=\"examples\"><li><em>The death of her friend had disturbed the balance of her mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>the balance of evidence/probability etc</strong> the most likely answer or result produced by opposing information, reasons etc</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to be in or get into a steady position, without falling to one side or the other, or to put something into this position</div><ul class=\"examples\"><li><strong><em>balance something on something</strong>: She was balancing a plate of food on her knees.</em></li><li><strong><em>balance on</strong>: He turned around, balancing awkwardly on one foot.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to be equal in importance, amount, value, or effect to something that has the opposite effect:</div><ul class=\"examples\"><li><em>Job losses in manufacturing were balanced by job increases in the service sector.</em></li><li><em>just enough sugar to balance the acidity of the fruit</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to consider the importance of one thing in relation to something else when you are making a decision</div><ul class=\"examples\"><li><strong><em>balance something against something</strong>: The courts must balance our liberty against the security of the nation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>balance the budget</strong> if a government balances the budget, they make the amount of money that they spend equal to the amount of money available</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>balance the books</strong> to show that the amount of money a business has received is equal to the amount spent</div></div></div>","554":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧anced</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbælənst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> giving equal attention to all sides or opinions <em>SYN fair</em> ► see thesaurus at fair</div><ul class=\"examples\"><li><strong><em>a balanced view/account</strong>: a balanced account of what happened</em></li><li><em>balanced reporting of the election campaign</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> arranged to include things or people of different kinds in the right amounts:</div><ul class=\"examples\"><li><em>a balanced programme of events</em></li><li><em>the importance of a balanced diet (=one that is healthy because it contains the right foods in the right amounts)</em></li><li><em>Nature is perfectly balanced.</em></li><li><strong><em>finely/delicately balanced</strong> (=very carefully balanced): soup with a delicately balanced flavor</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> someone who is balanced is calm and sensible, and has good mental health <em>OPP unbalanced</em></div><div class=\"sense\"><span class=\"snum\">4</span> <strong>balanced budget</strong> when a government is not spending more money than it has available</div></div>","555":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧co‧ny</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbælkəni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural balconies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a structure that you can stand on, that is attached to the outside wall of a building, above ground level:</div><ul class=\"examples\"><li><em>Has your flat got a balcony?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the seats upstairs at a theatre → stalls</div></div>","556":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɔːld $ bɒːld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having little or no hair on your head:</div><ul class=\"examples\"><li><em>a bald man</em></li><li><em>his shiny bald head</em></li><li><em>Dad started going bald when he was in his thirties.</em></li><li><em>He combed his hair and tried to hide his bald patch (=part of someone’s head where there is no hair).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not having enough of what usually covers something:</div><ul class=\"examples\"><li><em>The car’s tires are completely bald.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>bald statement/facts/truth</strong> a statement etc that is correct but gives no additional information to help you understand or accept what is said:</div><ul class=\"examples\"><li><em>The bald truth was that Lori didn’t love her husband anymore.</em></li></ul></div>","557":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɔːl $ bɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[round object]</strong> <span class=\"gram\">[countable]</span> a round object that is thrown, kicked, or hit in a game or sport</div><ul class=\"examples\"><li><strong><em>throw/hit/kick/catch etc a ball</strong>: Weiskopf hit the ball 330 yards and a cheer went up.</em></li><li><strong><em>a tennis/golf/cricket etc ball</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[round shape]</strong> <span class=\"gram\">[countable]</span> something formed or rolled into a round shape:</div><ul class=\"examples\"><li><em>a ball of string</em></li><li><em>Shape the dough into balls.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[game/sport]</strong> <span class=\"gram\">[uncountable]</span> any game or sport played with a ball, especially baseball or basketball:</div><ul class=\"examples\"><li><em>D&#x27;you want to go out and play ball?</em></li><li><em>Dad likes college ball.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[foot/hand]</strong> <strong>the ball of the foot/hand</strong> the rounded part of the foot at the base of the toes, or the rounded part of the hand at the base of the thumb</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>on the ball</strong> <em>informal</em> able to think or act quickly and intelligently:</div><ul class=\"examples\"><li><em>an assistant who’s really on the ball</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>set/start/keep the ball rolling</strong> to start something happening:</div><ul class=\"examples\"><li><em>To start the ball rolling, the government was asked to contribute £1 million.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the ball is in somebody’s court</strong> it is their turn to take action or to reply:</div><ul class=\"examples\"><li><em>I’ve emailed him – now the ball’s in his court.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[formal occasion]</strong> <span class=\"gram\">[countable]</span> a large formal occasion at which people dance ► see thesaurus at party</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>have a ball</strong> <em>informal</em> to have a very good time</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>balls</strong> <span class=\"gram\">[plural]</span> <em>informal</em> <em>not polite</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> testicles</div><div class=\"subsense\"><span class=\"subnum\">b)</span> courage:</div><ul class=\"examples\"><li><em>· I didn’t have the balls to ask.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <em>British English</em> <em>spoken</em> something that is stupid or wrong <em>SYN nonsense</em>: → balls1</div><ul class=\"examples\"><li><em>· That’s a load of balls!</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>a fast/good/long etc ball</strong> a ball that is thrown, hit, or kicked fast etc in a game or sport:</div><ul class=\"examples\"><li><em>He hit a long ball to right field.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[cricket]</strong> <strong>no ball</strong> a ball that is thrown too high, low etc towards someone trying to hit it, in the game of cricket or rounders</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>[baseball]</strong> <strong>no ball</strong> <span class=\"gram\">[countable]</span> a ball that the hitter does not try to hit, because it is not within the correct area</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>the whole ball of wax</strong> <em>American English</em> <em>informal</em> the whole thing <em>SYN everything</em></div><div class=\"sense\"><span class=\"snum\">15</span> <strong>a ball of fire</strong> <em>informal</em> someone who has a lot of energy and enthusiasm</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>keep several/too many etc balls in the air</strong> to struggle to deal with more than one problem or job at the same time:</div><ul class=\"examples\"><li><em>The company just won’t be able to keep that many balls in the air.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>drop the ball</strong> (also take your eye off the ball) to make a mistake when dealing with something because you stop thinking carefully or paying attention</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>ball-buster/ball-breaker</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a problem that is very difficult to deal with</div><div class=\"subsense\"><span class=\"subnum\">b)</span> an offensive word for a woman who uses her authority over men</div></div>","558":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧lad</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæləd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a slow love song</div><div class=\"sense\"><span class=\"snum\">2</span> a short story in the form of a poem or song</div></div>","559":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧le‧ri‧na</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbæləˈriːnə/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a woman who dances in ballets</div></div>","560":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæleɪ $ bæˈleɪ, ˈbæleɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a performance in which dancing and music tell a story without any speaking:</div><ul class=\"examples\"><li><em>We’re going to the ballet tomorrow evening.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> this type of dancing</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a group of ballet dancers who work together:</div><ul class=\"examples\"><li><em>the Bolshoi ballet</em></li></ul></div>","561":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧loon</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈluːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an object made of brightly coloured thin rubber, that is filled with air and used as a toy or decoration for parties:</div><ul class=\"examples\"><li><em>Can you help me blow up these balloons?</em></li><li><em>He burst the balloon in my face.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also hot-air balloon) a large bag of strong light cloth filled with gas or heated air so that it can float in the air. It has a basket hanging below it for people to stand in:</div><ul class=\"examples\"><li><em>a balloon flight over the Yorkshire Moors</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the circle drawn around the words spoken by the characters in a cartoon <em>SYN bubble</em></div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a balloon payment</strong> <em>American English</em> money borrowed that must be paid back in one large sum after several smaller payments have been made:</div><ul class=\"examples\"><li><em>a $10,000 balloon payment due in two years</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the balloon goes up</strong> <em>British English</em> <em>informal</em> used to refer to the moment when a situation starts to become really bad:</div><ul class=\"examples\"><li><em>We’ll have to get out of there before the balloon goes up.</em></li></ul></div>","562":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bal‧lot</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbælət/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a system of voting, usually in secret, or an occasion when you vote in this way: ► see thesaurus at election</div><ul class=\"examples\"><li><em>The party leader is elected by secret ballot.</em></li><li><em>Workers at the plant held a ballot and rejected strike action.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a piece of paper on which you make a secret vote <em>SYN ballot paper</em>:</div><ul class=\"examples\"><li><em>Only 22% of voters cast their ballots.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the ballot</strong> the total number of votes in an election <em>SYN the vote</em>:</div><ul class=\"examples\"><li><em>He won 54% of the ballot.</em></li></ul></div>","563":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an official order that prevents something from being used or done</div><ul class=\"examples\"><li><strong><em>ban on</strong>: a total ban on cigarette advertising</em></li><li><em>a call to lift the ban on homosexuals in the military</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle banned, present participle banning)</span></div><div class=\"entry-body\"><div class=\"sense\">to say that something must not be done, seen, used etc <em>SYN prohibit</em> <em>OPP allow</em>: ► see thesaurus at forbid</div><ul class=\"examples\"><li><em>Smoking is banned in the building.</em></li><li><strong><em>ban somebody from doing something</strong>: Charlie’s been banned from driving for a year.</em></li><li><strong><em>a banned substance/drug</strong> (=a drug that people competing in a sport are not allowed to take because it improves their performance)</em></li></ul></div></div>","564":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧nal</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈnɑːl, bəˈnæl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">ordinary and not interesting, because of a lack of new or different ideas <em>SYN trivial</em>:</div><ul class=\"examples\"><li><em>conversations about the most banal subjects</em></li></ul></div>","565":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧na‧na</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈnɑːnə $ -ˈnæ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a long curved tropical fruit with a yellow skin</div></div>","566":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a group of musicians, especially a group that plays popular music: → big band, brass band, marching band, one-man band GRAMMAR: Singular or plural verb?• In this meaning, band is usually followed by a singular verb: · The band has made a video.• In British English, you can also use a plural verb: · The band have made a video.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>The band was playing old Beatles songs.</em></li><li><em>I grew up playing in rock bands.</em></li><li><em>Smith joined the band in 1989.</em></li><li><em>They formed a band when they were still at school.</em></li><li><em>The entertainment includes a disco and live band.</em></li><li><em>interviews with band members</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of people formed because of a common belief or purpose</div><ul class=\"examples\"><li><strong><em>band of</strong>: a small band of volunteers / bands of soldiers</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a range of numbers within a system:</div><ul class=\"examples\"><li><em>Interest rates stayed within a relatively narrow band.</em></li><li><strong><em>age/tax/income etc band</strong>: people within the $20,000–$30,000 income band</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a flat narrow piece of something with one end joined to the other to form a circle:</div><ul class=\"examples\"><li><em>papers held together with a rubber band</em></li><li><em>a slim gold band on her finger</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a narrow area of light, colour, land etc that is different from the areas around it:</div><ul class=\"examples\"><li><em>The birds have a distinctive blue band round their eyes.</em></li><li><strong><em>band of</strong>: a thin band of cloud</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>technical</em> a range of radio signals <em>SYN waveband</em></div></div>","567":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ban‧dage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbændɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a narrow piece of cloth that you tie around a wound or around a part of the body that has been injured</div></div>","568":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a sudden loud noise caused by something such as a gun or an object hitting a hard surface: ► see thesaurus at sound</div><ul class=\"examples\"><li><em>There was a loud bang outside the kitchen door.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a painful blow to the body when you hit against something or something hits you <em>SYN bump</em>:</div><ul class=\"examples\"><li><em>a bang on the head</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>bangs</strong> <span class=\"gram\">[plural]</span> <em>American English</em> hair cut straight across your forehead SYN fringe<em>British English</em></div><div class=\"sense\"><span class=\"snum\">4</span> <strong>with a bang</strong> in a very successful way:</div><ul class=\"examples\"><li><em>Stock markets started the year with a bang.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>(get) a bigger/better etc bang for your buck</strong> <em>informal</em> something that gives you a good effect or a lot of value for the effort or money you spend on it:</div><ul class=\"examples\"><li><em>Are taxpayers getting enough bang for their buck?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>get a bang out of something</strong> <em>American English</em> <em>spoken</em> to enjoy something very much</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to hit something hard, making a loud noise ► see thesaurus at hit</div><ul class=\"examples\"><li><strong><em>bang on</strong>: Stop banging on the door!</em></li><li><strong><em>bang your fist/hand on something</strong>: She banged her fist on the table.</em></li><li><em>The baby kept banging the table with his spoon.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to put something down or against something with a lot of force, making a loud noise</div><ul class=\"examples\"><li><strong><em>bang something down</strong>: She banged the phone down.</em></li><li><strong><em>bang something on/against something</strong>: He banged a teapot on the table.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to close something violently, making a loud noise, or to be closed in this way <em>SYN slam</em>:</div><ul class=\"examples\"><li><em>I ran out, banging the door behind me.</em></li><li><em>The window banged shut.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to hit a part of your body, or something you are carrying, against something by accident <em>SYN bump</em></div><ul class=\"examples\"><li><strong><em>bang something on something</strong>: I fell and banged my head on the pavement.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[intransitive]</span> to make a loud noise or loud noises:</div><ul class=\"examples\"><li><em>The gate keeps banging in the wind.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[transitive]</span> <em>not polite</em> to have sex with someone</div></div></div>","569":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ban‧ish</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbænɪʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to not allow someone or something to stay in a particular place</div><ul class=\"examples\"><li><strong><em>banish somebody/something from/to something</strong>: I was banished to a distant corridor.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to send someone away permanently from their country or the area where they live, especially as an official punishment <em>SYN exile</em></div><ul class=\"examples\"><li><strong><em>banish somebody from/to</strong>: Thousands were banished to Siberia.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>literary</em> to try to stop thinking about something or someone</div><ul class=\"examples\"><li><strong><em>banish the memory/thought/image etc (of somebody/something)</strong>: They tried to banish the memory from their minds.</em></li></ul></div>","570":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[place for money]</strong> → clearing bank, merchant bank</div><div class=\"subsense\"><span class=\"subnum\">a)</span> a business that keeps and lends money and provides other financial services</div><ul class=\"examples\"><li><strong><em>in the bank</strong>: We have very little money in the bank.</em></li><li><em>Barclays Bank</em></li><li><em>a bank loan</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a local office of a bank:</div><ul class=\"examples\"><li><em>I have to go to the bank at lunch time.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[river/lake]</strong> land along the side of a river or lake</div><ul class=\"examples\"><li><strong><em>bank of</strong>: the banks of the River Dee</em></li><li><em>the river bank</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>blood/sperm/organ bank</strong> a place where human blood etc is stored until someone needs it</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[clouds/mist]</strong> a large mass of clouds, mist etc:</div><ul class=\"examples\"><li><em>a fog bank</em></li><li><strong><em>bank of</strong>: banks of mist</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[raised area]</strong> a large sloping mass of earth, sand, snow etc:</div><ul class=\"examples\"><li><em>She was sitting on a grassy bank.</em></li><li><strong><em>bank of</strong>: steep banks of snow / banks of flowers</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[machines]</strong> a large number of machines, television screens etc arranged close together in a row</div><ul class=\"examples\"><li><strong><em>bank of</strong>: banks of TV monitors</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[game]</strong> a supply of money used to gamble, that people can win → break the bank at break1(24)</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>be makin&#x27; bank</strong> <em>American English</em> <em>spoken</em> <em>informal</em> to earn a lot of money for the work that you do:</div><ul class=\"examples\"><li><em>Check out Omar’s new car. The brother must be makin&#x27; bank.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>the bank of Mum and Dad</strong> <em>British English</em> <em>informal</em> used when saying that your parents will provide you with the money that you need for something:</div><ul class=\"examples\"><li><em>Some young people turn to the bank of Mum and Dad when they want to buy a house.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[road]</strong> a slope made at a bend in a road or racetrack to make it safer for cars to go around</div></div>","571":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bank‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæŋkə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who works in a bank in an important position</div><div class=\"sense\"><span class=\"snum\">2</span> the player who is in charge of the money in some gambling games</div></div>","572":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bank‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæŋkɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the business of a bank:</div><ul class=\"examples\"><li><em>the international banking system</em></li></ul></div>","573":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bank‧rupt</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæŋkrʌpt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> without enough money to pay what you owe <em>SYN insolvent</em>:</div><ul class=\"examples\"><li><em>The firm went bankrupt before the building work was completed.</em></li><li><em>In 1977 he was declared bankrupt (=by a court).</em></li><li><em>Mr Trent lost his house when he was made bankrupt.</em></li><li><em>Seventeen years of war left the country bankrupt.</em></li><li><em>a bankrupt electrical company</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> completely lacking a particular good quality:</div><ul class=\"examples\"><li><em>The opposition attacked the government as morally bankrupt.</em></li></ul></div>","574":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bank‧rupt‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæŋkrʌptsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural bankruptcies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the state of being unable to pay your debts <em>SYN insolvency</em>:</div><ul class=\"examples\"><li><em>In 1999 it was revealed that he was close to bankruptcy.</em></li><li><em>When inflation rises, so do bankruptcies.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a total lack of a particular good quality:</div><ul class=\"examples\"><li><em>the moral bankruptcy of terrorism</em></li></ul></div>","575":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ban‧ner</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbænə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a long piece of cloth on which something is written, often carried between two poles:</div><ul class=\"examples\"><li><em>The onlookers were shouting, cheering, and waving banners.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a belief or principle</div><ul class=\"examples\"><li><strong><em>carry/raise/wave etc the banner of something</strong> (=publicly support a particular belief etc): She’d never felt the need to carry the banner of feminism.</em></li><li><strong><em>under the banner of something</strong>: They marched under the banner of equal educational opportunity.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>under the banner of something</strong> as part of a particular group or organization:</div><ul class=\"examples\"><li><em>The oil-producing countries joined together under the banner of OPEC.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a flag</div></div>","576":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ban‧quet</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæŋkwɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a formal dinner for many people on an important occasion:</div><ul class=\"examples\"><li><em>a state banquet (=one attended by heads of government and other important people)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large and impressive meal</div></div>","577":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bap‧tis‧m</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæptɪzəm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a Christian religious ceremony in which someone is touched or covered with water to welcome them into the Christian faith, and sometimes to officially name them → christening</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>baptism of/by fire</strong> a difficult or painful first experience of something:</div><ul class=\"examples\"><li><em>The campaign has been a baptism of fire.</em></li></ul></div>","578":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bap‧tize</span><span class=\"meta-item\"><strong>IPA:</strong> /bæpˈtaɪz $ ˈbæptaɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to perform the ceremony of baptism on someone → christen</div><div class=\"sense\"><span class=\"snum\">2</span> to accept someone as a member of a particular Christian church by a ceremony of baptism:</div><ul class=\"examples\"><li><em>He was baptized a Roman Catholic.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to give a child a name in a baptism ceremony:</div><ul class=\"examples\"><li><em>She was baptized Jane.</em></li></ul></div>","579":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɑː $ bɑːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[place to drink in]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a place where alcoholic drinks are served → pub:</div><ul class=\"examples\"><li><em>The hotel has a licensed bar.</em></li><li><em>a cocktail bar</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> one of the rooms inside a pub:</div><ul class=\"examples\"><li><em>The public bar was crowded.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[place to buy drink]</strong> a counter where alcoholic drinks are served:</div><ul class=\"examples\"><li><em>They stood at the bar.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a wine/coffee/snack etc bar</strong> a place where a particular kind of food or drink is served</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a breakfast bar</strong> <em>British English</em> a place in your kitchen at home where you eat breakfast or a quick meal</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[block shape]</strong> a small block of solid material that is longer than it is wide:</div><ul class=\"examples\"><li><em>a chocolate bar</em></li><li><em>a candy bar</em></li><li><strong><em>bar of</strong>: a bar of soap</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[piece of metal/wood]</strong> a length of metal or wood put across a door, window etc to keep it shut or to prevent people going in or out: ► see thesaurus at piece</div><ul class=\"examples\"><li><em>houses with bars across the windows</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>behind bars</strong> <em>informal</em> in prison:</div><ul class=\"examples\"><li><em>Her killer was finally put behind bars.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[music]</strong> a group of notes and rests, separated from other groups by vertical lines, into which a line of written music is divided:</div><ul class=\"examples\"><li><em>a few bars of the song</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bar to (doing) something</strong> <em>written</em> something that prevents you from achieving something that you want:</div><ul class=\"examples\"><li><em>I could see no bar to our happiness.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>the bar</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> the group of people who are barristers</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>American English</em> an organization consisting of lawyers</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>be called to the bar</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> to become a barrister</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>American English</em> to become a lawyer</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[on computer screen]</strong> a long narrow shape along the sides or at the top of a computer screen, usually containing signs that you can click on: → scroll bar</div><ul class=\"examples\"><li><em>the main menu bar at the top of the screen</em></li><li><em>the toolbar</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[in sports]</strong> the long piece of wood or metal across the top of the goal in sports such as football:</div><ul class=\"examples\"><li><em>The ball hit the bar.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[pile of sand/stones]</strong> a long pile of sand or stones under the water at the entrance to a harbour</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>[colour/light]</strong> a narrow band of colour or light</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>[uniforms]</strong> a narrow band of metal or cloth worn on a military uniform to show rank</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>[heater]</strong> <em>British English</em> the part of an electric heater that provides heat and has a red light</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle barred, present participle barring)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to officially prevent someone from entering a place or from doing something ► see thesaurus at forbid</div><ul class=\"examples\"><li><strong><em>bar somebody from (doing) something</strong>: They seized his passport and barred him from leaving the country.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to prevent people from going somewhere by placing something in their way:</div><ul class=\"examples\"><li><em>She ran back, but Francis barred her way.</em></li><li><em>A locked gate barred my entrance to the wood.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (also bar up) to shut a door or window using a bar or piece of wood so that people cannot get in or out</div></div></div>","580":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈbar code</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a group of thin and thick lines printed on products you buy in a shop, that a computer can read. It contains information such as the price.</div></div>","581":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧bar‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /bɑːˈbærɪk $ bɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">very cruel and violent <em>SYN barbarous</em>: ► see thesaurus at cruel</div><ul class=\"examples\"><li><em>The way the whales are killed is nothing short of barbaric.</em></li></ul></div>","582":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧be‧cue</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɑːbɪkjuː $ ˈbɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (written abbreviation BBQ) a meal or party during which food is cooked on a metal frame over a fire and eaten outdoors:</div><ul class=\"examples\"><li><em>We had a barbecue on the beach.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a metal frame for cooking food on outdoors</div></div>","583":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beə $ ber/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[without clothes]</strong> not covered by clothes <em>SYN naked</em>:</div><ul class=\"examples\"><li><em>a ragged child with bare feet</em></li><li><em>She felt the warm sun on her bare arms.</em></li><li><strong><em>bare-headed/bare-chested/bare-legged etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[land/trees]</strong> not covered by trees or grass, or not having any leaves:</div><ul class=\"examples\"><li><em>The trees soon gave way to bare rock.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[not covered/empty]</strong> empty, not covered by anything, or not having any decorations: ► see thesaurus at empty</div><ul class=\"examples\"><li><em>She looked round her tiny bare room.</em></li><li><em>a bare wood staircase</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the bare facts</strong> a statement that tells someone only what they need to know, with no additional details:</div><ul class=\"examples\"><li><em>The newspaper had simply published the bare facts.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[smallest amount necessary]</strong> <span class=\"gram\">[only before noun]</span> the very least amount of something that you need to do something:</div><ul class=\"examples\"><li><em>He got 40% – a bare pass.</em></li><li><em>The room had the bare minimum (=the smallest amount possible) of furniture.</em></li><li><strong><em>the bare essentials/necessities</strong>: Her bag was light, packed with only the bare essentials.</em></li><li><em>If you ask her about herself, she gives only the barest (=the smallest amount possible) of details.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>the bare bones</strong> the most important parts or facts of something without any detail:</div><ul class=\"examples\"><li><em>We have outlined only the bare bones of the method.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>lay something bare</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to uncover something that was previously hidden:</div><ul class=\"examples\"><li><em>When the river is low, vast stretches of sand are laid bare.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make known something that was secret:</div><ul class=\"examples\"><li><em>historical writing which seeks to lay bare the true nature of an event</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>with your bare hands</strong> without using a weapon or a tool:</div><ul class=\"examples\"><li><em>He had killed a man with his bare hands.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bare infinitive</strong> <em>technical</em> the basic form of a verb, for example ‘go’ or ‘eat’</div></div>","584":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bare‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeəli $ ˈberli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> only with great difficulty or effort <em>SYN only just</em>:</div><ul class=\"examples\"><li><em>She was very old and barely able to walk.</em></li><li><em>Mary had barely enough money to live on.</em></li><li><strong><em>barely audible/perceptible/visible/discernible etc</strong>: His voice was barely audible.</em></li><li><em>She could barely understand English.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> almost not <em>SYN hardly</em>:</div><ul class=\"examples\"><li><em>She was barely aware of his presence.</em></li><li><em>Joe and his brother are barely on speaking terms.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to emphasize that something happens immediately after a previous action SYN only just<em>British English</em>:</div><ul class=\"examples\"><li><em>Graham had barely finished his coffee when Henry returned.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used before amounts or numbers to emphasize that they are surprisingly small <em>SYN only</em>:</div><ul class=\"examples\"><li><em>Nowadays, the village has barely 100 inhabitants.</em></li></ul></div>","585":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧gain</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɑːɡɪn $ ˈbɑːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> something you buy cheaply or for less than its usual price:</div><ul class=\"examples\"><li><em>There are no bargains in the clothes shops at the moment.</em></li><li><em>It’s an attractive little home, and I think it’s a bargain.</em></li><li><em>That second-hand table was a real bargain.</em></li><li><em>Good watches don&#x27;t come at bargain prices.</em></li><li><em>Bargain hunters (=people looking for things to buy at low prices) queued outside the store for hours.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an agreement, made between two people or groups, to do something in return for something else → drive a hard bargain at hard1(18)</div><ul class=\"examples\"><li><strong><em>make/strike a bargain</strong>: Management and unions have struck a bargain over wage increases.</em></li><li><em>I’ve kept my side of the bargain and I expect you to keep yours.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>into the bargain</strong> (also in the bargain<em>American English</em>) in addition to everything else:</div><ul class=\"examples\"><li><em>I am now tired, cold, and hungry, with a headache into the bargain.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to discuss the conditions of a sale, agreement etc, for example to try and get a lower price</div><ul class=\"examples\"><li><strong><em>bargain for</strong>: workers bargaining for better pay</em></li><li><strong><em>bargain over</strong>: They bargained over the level of wages.</em></li><li><strong><em>bargain with</strong>: women bargaining with traders</em></li></ul></div></div>","586":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɑːk $ bɑːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> when a dog barks, it makes a short loud sound or series of sounds → growl</div><ul class=\"examples\"><li><strong><em>bark at</strong>: The dog always barks at strangers.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also bark out) <span class=\"gram\">[transitive]</span> to say something quickly in a loud voice</div><ul class=\"examples\"><li><strong><em>bark at</strong>: ‘Don’t just stand there, give me a hand,’ she barked at the shop assistant.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>bark up the wrong tree</strong> <em>informal</em> to have a wrong idea, or do something in a way that will not give you the information or result you want:</div><ul class=\"examples\"><li><em>The police spent three months barking up the wrong tree on the murder investigation.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to rub the skin off your knee, elbow etc by falling or knocking against something <em>SYN graze</em>:</div><ul class=\"examples\"><li><em>I barked my shin against the step.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the sharp loud sound made by a dog</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the outer covering of a tree</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a loud sound or voice:</div><ul class=\"examples\"><li><em>Amy’s voice was a hoarse bark.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>somebody’s bark is worse than their bite</strong> used to say that someone who seems unpleasant or difficult to deal with is not really too bad</div></div></div>","587":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧rage</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbærɑːʒ $ bəˈrɑːʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> the continuous firing of guns, dropping of bombs etc, especially to protect soldiers as they move towards an enemy</div><ul class=\"examples\"><li><strong><em>barrage of</strong>: a barrage of anti-aircraft fire</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a lot of criticism, questions, complaints etc that are said at the same time, or very quickly one after another</div><ul class=\"examples\"><li><strong><em>barrage of</strong>: a barrage of questions</em></li></ul></div>","588":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧rel</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbærəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large curved container with a flat top and bottom, made of wood or metal, and used for storing beer, wine etc:</div><ul class=\"examples\"><li><em>The wine is aged in oak barrels.</em></li><li><strong><em>barrel of</strong>: barrels of beer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a unit of measurement for oil, equal to 159 litres</div><ul class=\"examples\"><li><strong><em>barrel of</strong>: two million barrels of oil</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the part of a gun that the bullets are fired through</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>have somebody over a barrel</strong> to put someone in a situation in which they are forced to accept or do what you want:</div><ul class=\"examples\"><li><em>The manager has us over a barrel – either we work on a Saturday or we lose our jobs.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be a barrel of laughs</strong> <span class=\"gram\">[often in negatives]</span> to be very enjoyable:</div><ul class=\"examples\"><li><em>Life is not exactly a barrel of laughs at the moment.</em></li></ul></div>","589":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧ren</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbærən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> land or soil that is barren has no plants growing on it:</div><ul class=\"examples\"><li><em>Thousands of years ago the surface was barren desert.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>old-fashioned</em> unable to produce children or baby animals – used of a woman or of female animals <em>SYN infertile</em> <em>OPP fertile</em></div><div class=\"sense\"><span class=\"snum\">3</span> a tree or plant that is barren does not produce fruit or seeds</div><div class=\"sense\"><span class=\"snum\">4</span> used to describe something that does not look interesting or attractive:</div><ul class=\"examples\"><li><em>The sports hall was a rather barren concrete building.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to describe a period of time during which you do not achieve anything or get any useful results:</div><ul class=\"examples\"><li><em>I scored five in the first seven games, but I’ve had a bit of a barren patch since then.</em></li></ul></div>","590":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧ri‧cade</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbærəkeɪd, ˌbærəˈkeɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a temporary wall or fence across a road, door etc that prevents people from going through:</div><ul class=\"examples\"><li><em>The fans were kept back behind barricades.</em></li></ul></div>","591":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bar‧ri‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbæriə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a rule, problem etc that prevents people from doing something, or limits what they can do:</div><ul class=\"examples\"><li><em>He advocated the removal of trade barriers.</em></li><li><strong><em>barrier to</strong>: Problems with childcare remain the biggest barrier to women succeeding at work.</em></li><li><strong><em>barrier between</strong>: barriers between doctors and patients</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a type of fence or gate that prevents people from moving in a particular direction:</div><ul class=\"examples\"><li><em>Crowds burst through the barriers and ran onto the pitch.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a physical object that keeps two areas, people etc apart</div><ul class=\"examples\"><li><strong><em>barrier between</strong>: The mountains form a natural barrier between the two countries.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the 10-second/40% etc barrier</strong> a level or amount of 10 seconds, 40% etc that is seen as a limit which it is difficult to get beyond:</div><ul class=\"examples\"><li><em>I’m hoping to crash the 20-second barrier in the final and get a bronze.</em></li></ul></div>","592":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[transitive]</span> to have your main place of work, business etc in a particular place: → based GRAMMAR In this meaning, base is usually either passive or reflexive (=followed by myself/itself etc).</div><ul class=\"examples\"><li><em>The paper had intended to base itself in London.</em></li><li><strong><em>be based in something</strong>: The new organization will be based in Dallas.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[lowest part]</strong> <span class=\"gram\">[countable usually singular]</span> ► see thesaurus at bottom</div><div class=\"subsense\"><span class=\"subnum\">a)</span> the lowest part or surface of something <em>SYN bottom</em></div><ul class=\"examples\"><li><strong><em>base of</strong>: There is a door at the base of the tower. / the base of a triangle</em></li><li><em>a frozen dessert with a biscuit base</em></li><li><em>a wine glass with a heavy base</em></li><li><em>The leather of his left trainer was coming away from its rubber base.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the lowest point on a plant or part of your body, where it joins another part <em>SYN bottom</em></div><ul class=\"examples\"><li><strong><em>base of</strong>: a hole in the base of the tree / He was killed by an axe blow to the base of his skull.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[knowledge/ideas]</strong> <span class=\"gram\">[countable]</span> the most important part of something, from which new ideas develop <em>SYN foundation</em>:</div><ul class=\"examples\"><li><em>India has a good scientific research base.</em></li><li><strong><em>base for</strong>: They were laying the base for a new economic recovery.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[military]</strong> <span class=\"gram\">[countable]</span> a place where people in a military organization live and work</div><ul class=\"examples\"><li><strong><em>military/naval/air base</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[company/organization]</strong> <span class=\"gram\">[countable, uncountable]</span> the main place from which a person, company, or organization controls their activities</div><ul class=\"examples\"><li><strong><em>base for</strong>: He used the house as a base for his printing business.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[people/groups]</strong> <span class=\"gram\">[countable usually singular]</span> the people, money, groups etc that form the main part of something: → power base</div><ul class=\"examples\"><li><em>The company has built up a loyal customer base.</em></li><li><em>By broadening the tax base (=all the people who pay taxes), he could raise more revenues.</em></li><li><em>an attempt to strengthen the city’s economic base (=things that produce jobs and money)</em></li><li><em>The country’s manufacturing base (=all the factories, companies etc that produce goods in a country) has shrunk by 20%.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[substance/mixture]</strong> <span class=\"gram\">[singular, uncountable]</span> the main part of a substance, meal etc to which other things are added:</div><ul class=\"examples\"><li><em>paint with an oil base</em></li><li><strong><em>base for</strong>: Vodka is the base for many cocktails.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[sport]</strong> <span class=\"gram\">[countable]</span> one of the four places that a player must touch in order to get a point in games such as baseball</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>be off base</strong> <em>American English</em> <em>informal</em> to be completely wrong:</div><ul class=\"examples\"><li><em>His estimate for painting the kitchen seems way off base.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[chemical]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> a chemical substance that combines with an acid to form a salt</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[numbers]</strong> <span class=\"gram\">[countable usually singular]</span> <em>technical</em> the number in relation to which a number system or mathematical table is built up, for example 10 in the decimal system</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>touch base (with somebody)</strong> to talk to someone to find out what is happening about something</div></div></div>","593":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> base‧ball</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsbɔːl $ -bɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> an outdoor game between two teams of nine players, in which players try to get points by hitting a ball and running around four bases</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the ball used in baseball</div></div>","594":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> base‧ment</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsmənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a room or area in a building that is under the level of the ground → cellar</div></div>","595":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧sic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> forming the most important or most necessary part of something → basics:</div><ul class=\"examples\"><li><em>the basic principles of chemistry</em></li><li><em>The basic idea is simple.</em></li><li><em>basic research</em></li><li><em>basic information</em></li><li><strong><em>basic to</strong>: medical techniques basic to the control of infection</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> at the simplest or least developed level → basics:</div><ul class=\"examples\"><li><em>the basic skills of programming</em></li><li><em>Their knowledge is very basic.</em></li><li><em>The farm lacks even basic equipment.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>basic salary/pay/pension etc</strong> the amount of money that you are paid before any special payments are added:</div><ul class=\"examples\"><li><em>On top of the basic salary, there are numerous other benefits.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[only before noun]</span> basic rights, needs etc are ones that everyone needs or should have:</div><ul class=\"examples\"><li><em>basic human rights</em></li><li><em>poor families unable to meet their basic needs</em></li></ul></div>","596":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧sic‧ally</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsɪkli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[sentence adverb]</span> <em>spoken</em> used to emphasize the most important reason or fact about something, or a simple explanation of something:</div><ul class=\"examples\"><li><em>Basically, I’m just lazy.</em></li><li><em>Well, basically, it’s a matter of filling in a few forms.</em></li><li><em>I used to see him every night, basically.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in the main or most important ways, without considering additional details or differences <em>SYN fundamentally</em>:</div><ul class=\"examples\"><li><em>All cheeses are made in basically the same way.</em></li><li><em>I believe that human beings are basically good.</em></li><li><em>Basically, he hadn’t changed at all.</em></li></ul></div>","597":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧sics</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsɪks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the most important and necessary facts about something, from which other possibilities and ideas may develop</div><ul class=\"examples\"><li><strong><em>basics of</strong>: the basics of French grammar</em></li><li><em>Here are some of the basics you will need to know.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> things that everyone needs in order to live or to deal with a particular situation:</div><ul class=\"examples\"><li><em>basics like food and education</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>back to basics</strong> used to describe a return to teaching or doing the most important or simplest things:</div><ul class=\"examples\"><li><em>A lot of parents want schools to get back to basics.</em></li></ul></div>","598":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧sin</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a round container attached to the wall in a bathroom, where you wash your hands and face <em>SYN sink</em>:</div><ul class=\"examples\"><li><em>a wash basin</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large bowl-shaped container for liquids or food:</div><ul class=\"examples\"><li><em>Fill the basin with the cake mixture.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (also basinful /ˈbeɪsənfʊl/) the amount of liquid that a basin can contain:</div><ul class=\"examples\"><li><em>a basin of hot water</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> an area of land that is lower at the centre than at the edges, especially one from which water runs down into a river:</div><ul class=\"examples\"><li><em>the Amazon basin</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a place where the Earth’s surface is lower than in other areas:</div><ul class=\"examples\"><li><em>the Pacific Basin</em></li></ul></div>","599":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧sis</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɪsɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\">(plural bases /-siːz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the facts, ideas, or things from which something can be developed: ► see thesaurus at reason</div><ul class=\"examples\"><li><em>Their claim had no basis in fact (=it was not true).</em></li><li><strong><em>basis of</strong>: Bread forms the basis of their daily diet.</em></li><li><strong><em>basis for</strong>: The video will provide a basis for class discussion.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>on the basis of something</strong> because of a particular fact or situation:</div><ul class=\"examples\"><li><em>discrimination on the basis of sex</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> the way that something happens, or the way that something is organized or done</div><ul class=\"examples\"><li><strong><em>on a regular/daily/weekly etc basis</strong> (=regularly, every day, week, etc): I’m saving money on a regular basis. / Board meetings are held on a weekly basis.</em></li><li><strong><em>on a voluntary/part-time/temporary etc basis</strong>: Nurses are employed on a full-time basis.</em></li></ul></div>","600":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bas‧ket</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɑːskɪt $ ˈbæ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a container made of thin pieces of plastic, wire, or wood woven together, used to carry things or put things in:</div><ul class=\"examples\"><li><em>a shopping basket</em></li><li><em>a basket full of vegetables</em></li><li><strong><em>clothes/laundry basket</strong> (=for dirty clothes)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a net with a hole at the bottom, attached to a metal ring, through which the ball is thrown in basketball</div><ul class=\"examples\"><li><strong><em>make/shoot a basket</strong> (=to throw the ball through the basket)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> the average or total value of a number of different goods or currencies</div><div class=\"sense\"><span class=\"snum\">4</span> the part of a website, often represented by a picture of a basket, where you collect things to buy</div></div>","601":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bas‧ket‧ball</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɑːskətbɔːl $ ˈbæskətbɒːl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a game played indoors between two teams of five players, in which each team tries to win points by throwing a ball through a net</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> the ball used in this game</div></div>","602":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bæt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small animal like a mouse with wings that flies around at night → fruit bat</div><div class=\"sense\"><span class=\"snum\">2</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> a long wooden stick with a special shape that is used in some sports and games:</div><ul class=\"examples\"><li><em>a baseball bat</em></li><li><em>a cricket bat</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> a round flat piece of wood with a handle, used to hit a ball in table tennis SYN paddle<em>American English</em></div><div class=\"sense\"><span class=\"snum\">3</span> <strong>be at bat</strong> to be the person who is trying to hit the ball in a game of baseball</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>do something off your own bat</strong> <em>British English</em> <em>informal</em> to do something without being told to do it:</div><ul class=\"examples\"><li><em>She went to see a solicitor off her own bat.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>do something right off the bat</strong> <em>American English</em> <em>informal</em> to do something immediately:</div><ul class=\"examples\"><li><em>He said yes right off the bat.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>like a bat out of hell</strong> <em>informal</em> very fast:</div><ul class=\"examples\"><li><em>I drove like a bat out of hell to the hospital.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>old bat</strong> <em>spoken</em> an unpleasant old woman</div></div>","603":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bætʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a group of people or things that arrive or are dealt with together</div><ul class=\"examples\"><li><strong><em>batch of</strong>: Every day another batch of papers reaches the manager, demanding his attention.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a quantity of food, medicine etc that is produced or prepared at the same time</div><ul class=\"examples\"><li><strong><em>batch of</strong>: She was in the kitchen taking a batch of bread out of the oven.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a set of jobs that are dealt with together on a computer:</div><ul class=\"examples\"><li><em>an overnight batch file</em></li><li><em>a batch job</em></li></ul></div>","604":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɑːθ $ bæθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural baths /bɑːðz, bɑːθs $ bæðz, bæθs/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if you take a bath, you wash your body in a bath:</div><ul class=\"examples\"><li><em>After a week of camping, I really needed a bath.</em></li><li><strong><em>have a bath<em>British English</em></strong> <strong>take a bath</em>American English</strong><em>: I’ll have a bath and go to bed. / How often do you take a bath?</em></li><li><em>I’ll give the children their bath (=wash them in a bath).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> a large long container that you fill with water and sit or lie in to wash yourself SYN bathtub<em>American English</em></div><div class=\"sense\"><span class=\"snum\">3</span> water that you sit or lie in to wash yourself:</div><ul class=\"examples\"><li><em>a hot bath</em></li><li><em>She ran a bath (=put water into a bath).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a bathroom, used especially in advertising:</div><ul class=\"examples\"><li><em>All our luxury bedrooms have a private bath.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a container full of liquid in which something is placed for a particular purpose</div><ul class=\"examples\"><li><strong><em>bath of</strong>: Plunge the fabric into a bath of black dye.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>baths</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> <em>old-fashioned</em> a public building in which there is a swimming pool</div><div class=\"subsense\"><span class=\"subnum\">b)</span> a public building where people could go in the past to wash themselves:</div><ul class=\"examples\"><li><em>the Roman baths at Cirencester</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>take a bath</strong> <em>American English</em> <em>informal</em> to lose money, especially in a business deal:</div><ul class=\"examples\"><li><em>We took a bath in the market over that stock.</em></li></ul></div>","605":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɪð/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>especially American English</em> to wash yourself or someone else in a bath SYN bath<em>British English</em>:</div><ul class=\"examples\"><li><em>I bathed, washed my hair, and got dressed.</em></li><li><em>He bathed the children and put them to bed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> <em>British English</em> <em>old-fashioned</em> to swim in the sea, a river, or a lake: RegisterIn everyday English, people usually say go for/have a swim rather than bathe:· They went for a swim in the lake.</div><ul class=\"examples\"><li><em>They bathed in the lake in the moonlight.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to wash or cover part of your body with a liquid, especially as a medical treatment: ► see thesaurus at clean</div><ul class=\"examples\"><li><em>She brought a bowl of water and began to bathe the injured arm.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be bathed in light/sunshine etc</strong> <em>written</em> an area or building that is bathed in light has light shining onto it in a way that makes it look pleasant or attractive:</div><ul class=\"examples\"><li><em>The top of Pea Hill was bathed in brilliant sunshine.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be bathed in sweat</strong> <em>written</em> to be covered in sweat:</div><ul class=\"examples\"><li><em>I was tired and bathed in sweat.</em></li></ul></div>","606":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bath‧room</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɑːθrʊm, -ruːm $ ˈbæθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a room where there is a bath or shower, a basin, and sometimes a toilet</div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a room where there is a toilet:</div><ul class=\"examples\"><li><em>Where’s the bathroom?</em></li><li><em>I really need to go to the bathroom (=use a toilet).</em></li></ul></div>","607":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bath‧tub</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɑːθtʌb $ ˈbæθ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>especially American English</em> a long large container that you fill with water and sit or lie in to wash yourself SYN bath<em>British English</em></div></div>","608":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bat‧ter‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbætəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\">(plural batteries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[electricity]</strong> <span class=\"gram\">[countable]</span> an object that provides a supply of electricity for something such as a radio, car, or toy:</div><ul class=\"examples\"><li><em>You have to take the top off to change the batteries.</em></li><li><em>When the red light comes on, you should recharge the battery.</em></li><li><em>The car’s got a flat battery.</em></li><li><em>a battery-operated hairdryer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a battery of something</strong> a group of many things of the same type:</div><ul class=\"examples\"><li><em>a battery of medical tests</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[farm]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> a row of small cages in which chickens are kept, so that the farm can produce large numbers of eggs: → free-range</div><ul class=\"examples\"><li><em>battery hens</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[guns]</strong> <span class=\"gram\">[countable]</span> several large guns used together:</div><ul class=\"examples\"><li><em>an anti-aircraft battery</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[crime]</strong> <span class=\"gram\">[uncountable]</span> <em>law</em> the crime of hitting someone: → assault and battery</div><ul class=\"examples\"><li><em>He was charged with assault and battery.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>recharge your batteries</strong> <em>informal</em> to rest or relax in order to get back your energy:</div><ul class=\"examples\"><li><em>A week in the mountains should recharge my batteries.</em></li></ul></div>","609":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bat‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbætl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fight]</strong> a fight between opposing armies, groups of ships, groups of people etc, especially one that is part of a larger war: ► see thesaurus at war</div><ul class=\"examples\"><li><em>the Battle of Trafalgar</em></li><li><strong><em>in battle</strong>: Her son was killed in battle.</em></li><li><strong><em>into battle</strong>: a knight riding into battle</em></li><li><strong><em>battle between</strong>: battles between government forces and the rebels</em></li><li><em>a pitched battle (=a long and serious battle) between police and drug gangs</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[competition/argument]</strong> a situation in which opposing groups or people compete or argue with each other when trying to achieve success or control:</div><ul class=\"examples\"><li><em>a long-running legal battle</em></li><li><strong><em>battle for</strong>: a battle for custody of their children</em></li><li><strong><em>battle between</strong>: a fierce ratings battle between rival TV stations</em></li><li><strong><em>battle with</strong>: an ongoing battle with my mother about eating properly</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[change bad situation]</strong> an attempt to solve a difficult problem or change an unpleasant situation</div><ul class=\"examples\"><li><strong><em>battle against</strong>: a battle against the racism of the school system</em></li><li><strong><em>battle with</strong>: a long battle with lung cancer</em></li><li><strong><em>battle for</strong>: Scientology has fought long battles for acceptance as a religion.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be half the battle</strong> to be a difficult or important part of what you have to do:</div><ul class=\"examples\"><li><em>Just getting an interview is half the battle.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a battle of wits</strong> a situation in which opposing sides try to win by using their intelligence:</div><ul class=\"examples\"><li><em>A good mystery story is a battle of wits between author and reader.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>battle of wills</strong> a situation in which opposing sides refuse to change what they want, in the hope that the other side will decide to change first:</div><ul class=\"examples\"><li><em>a battle of wills between teacher and student</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>do battle (with somebody)</strong> to argue with someone or fight against someone:</div><ul class=\"examples\"><li><em>She walked into the room with her eyes blazing, ready to do battle.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>fight your own battles</strong> to argue with someone, or compete in a difficult situation, without having help from other people – used to show approval:</div><ul class=\"examples\"><li><em>It’s all right, Mum. I can fight my own battles.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>the battle of the sexes</strong> the relationship between men and women when it is considered as a fight for power</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>the battle of the bulge</strong> the act of trying to lose weight – used humorously</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to try very hard to achieve something that is difficult or dangerous:</div><ul class=\"examples\"><li><em>Firefighters battled the flames.</em></li><li><strong><em>battle against/with</strong>: She had battled against cancer.</em></li><li><strong><em>battle for</strong>: a pressure group battling for better schools</em></li><li><strong><em>battle to do something</strong>: Doctors battled to save his life.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>battle it out</strong> to keep fighting or opposing each other until one person or team wins:</div><ul class=\"examples\"><li><em>Sixteen teams will battle it out.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> <em>literary</em> to take part in a fight or war</div></div></div>","610":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bat‧tle‧field</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbætlfiːld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a place where a battle is being fought or has been fought</div><div class=\"sense\"><span class=\"snum\">2</span> a subject that people disagree or argue a lot about:</div><ul class=\"examples\"><li><em>Education has become a political battleground.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a place where an argument or disagreement happens, or where people are competing against each other:</div><ul class=\"examples\"><li><em>a battleground state during the election</em></li></ul></div>","611":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[sea]</strong> a part of the sea that is partly enclosed by a curve in the land:</div><ul class=\"examples\"><li><em>a house with a view across the bay</em></li><li><em>Montego Bay</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>keep/hold something at bay</strong> to prevent something dangerous or unpleasant from happening or from coming too close:</div><ul class=\"examples\"><li><em>A thick wall keeps the noise at bay.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[area]</strong> an area within a large room or just outside a building that is used for a particular purpose:</div><ul class=\"examples\"><li><em>a storage bay</em></li><li><em>loading bay</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[for cargo]</strong> the part of a ship or plane where things are stored:</div><ul class=\"examples\"><li><em>the cargo bay</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[tree]</strong> (also bay tree) a tree that has leaves that smell sweet and are often used in cooking</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[horse]</strong> a horse that is a reddish brown colour</div></div>","612":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ba‧zaar</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈzɑː $ -ˈzɑːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a market or area where there are a lot of small shops, especially in India or the Middle East</div><div class=\"sense\"><span class=\"snum\">2</span> an occasion when a lot of people sell different things to collect money for a good purpose:</div><ul class=\"examples\"><li><em>a church bazaar</em></li></ul></div>","613":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">auxiliary verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bi; strong biː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense was, were, past participle been, present participle being, first person singular am, second person singular and plural are, third person singular is)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used with a present participle to form the continuous(4) tenses of verbs:</div><ul class=\"examples\"><li><em>Don’t disturb me while I’m working.</em></li><li><em>Gemma was reading.</em></li><li><em>They’ve been asking a lot of questions.</em></li><li><em>That guy’s always causing trouble.</em></li><li><em>We’ll be starting in about an hour.</em></li><li><em>He isn’t leaving, is he?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used with past participles to form the passive:</div><ul class=\"examples\"><li><em>Smoking is not permitted.</em></li><li><em>I was told about it yesterday.</em></li><li><em>The house is being painted.</em></li><li><em>She’s been invited to a party.</em></li><li><em>The flames could be seen several miles away.</em></li><li><em>The police should have been informed about this.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be to do something</strong> <em>formal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to talk about arrangements for the future:</div><ul class=\"examples\"><li><em>Audrey and Jimmy are to be married in June.</em></li><li><em>Two men are to appear in court on charges of armed robbery.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to give an order or to tell someone about a rule:</div><ul class=\"examples\"><li><em>You are to wait here in this room until I return.</em></li><li><em>All staff are to wear uniforms.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to say or ask what someone should do or what should happen:</div><ul class=\"examples\"><li><em>What am I to tell her?</em></li><li><em>He is not to be blamed.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> used to ask how something can be done:</div><ul class=\"examples\"><li><em>How are we to get out of the present mess?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be to be seen/found/heard etc</strong> used to say that something can be seen, found, or heard somewhere:</div><ul class=\"examples\"><li><em>A large range of species are to be seen in the aquarium.</em></li><li><em>We searched everywhere but the ring was nowhere to be found (=could not be found).</em></li><li><em>The only sound to be heard was the twittering of the birds above us.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>was/were to do something</strong> used when talking about a time in the past to say what happened later:</div><ul class=\"examples\"><li><em>This discovery was to have a major effect on the treatment of heart disease.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> used in conditional1(2) sentences about an imagined situation</div><ul class=\"examples\"><li><strong><em>were somebody to do something/if somebody were to do something</strong>: Even if England were to win the next two matches, Germany would still be three points ahead. / Were we to offer you the job, would you take it?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used in conditional sentences to introduce an aim when you are saying what must be done in order to achieve it</div><ul class=\"examples\"><li><strong><em>if somebody/something is to do something</strong>: If we are to succeed in this enterprise, we shall need to plan everything very carefully.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <em>old use</em> used instead of ‘have’ to form the perfect3 tense of some verbs:</div><ul class=\"examples\"><li><em>The hour is come.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[linking verb]</span> used to say that someone or something is the same as the subject of the sentence:</div><ul class=\"examples\"><li><em>My name is Susan.</em></li><li><em>These are my favourite pictures.</em></li><li><em>He’s my brother.</em></li><li><em>The problem is finding the time to get things done.</em></li><li><em>Our aim was to reduce the number of accidents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> used to say where something or someone is:</div><ul class=\"examples\"><li><em>Jane’s upstairs.</em></li><li><em>Are my keys in the drawer?</em></li><li><em>The principal’s in his office.</em></li><li><em>How long has she been here?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> used to say when something happens:</div><ul class=\"examples\"><li><em>The concert was last night.</em></li><li><em>The party is on Saturday.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[linking verb]</span> used to describe someone or something, or say what group or type they belong to:</div><ul class=\"examples\"><li><em>The sky was grey.</em></li><li><em>Spiders are not really insects.</em></li><li><em>Mr Cardew was a tall thin man.</em></li><li><em>She wants to be a doctor when she leaves school.</em></li><li><em>Her dress was pure silk.</em></li><li><em>I’m not ready yet.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>there is/are</strong> used to say that something exists or happens:</div><ul class=\"examples\"><li><em>There’s a hole in your trousers.</em></li><li><em>There was a loud explosion.</em></li><li><em>‘I thought there was going to be a party.’ ‘No, there isn’t.’</em></li><li><em>Is there a problem?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[linking verb]</span> to behave in a particular way:</div><ul class=\"examples\"><li><em>He was just being rude.</em></li><li><em>Don’t be silly.</em></li><li><em>You’d better be careful.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[linking verb]</span> used to say how old someone is:</div><ul class=\"examples\"><li><em>His mother died when he was 20.</em></li><li><em>Rachel will be three in November.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <span class=\"gram\">[linking verb]</span> used to say who something belongs to:</div><ul class=\"examples\"><li><em>Whose is this bag? It isn’t mine and it isn’t Sarah’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <span class=\"gram\">[linking verb]</span> used to talk about the price of something: ► see thesaurus at cost</div><ul class=\"examples\"><li><em>‘How much are the melons?’ ‘The big ones are £2 each.’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <span class=\"gram\">[linking verb]</span> to be equal to a particular number or amount:</div><ul class=\"examples\"><li><em>32 divided by 8 is 4.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be that as it may</strong> <em>formal</em> used to say that even though you accept that something is true, it does not change a situation:</div><ul class=\"examples\"><li><em>‘He was only joking.’ ‘Be that as it may, silly remarks like that can do a lot of harm.’</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <span class=\"gram\">[intransitive]</span> <em>formal</em> to exist:</div><ul class=\"examples\"><li><em>What was once a great and powerful empire has effectively ceased to be.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be yourself</strong> to behave in a natural way, rather than trying to pretend to be different:</div><ul class=\"examples\"><li><em>Don’t try too hard – just be yourself.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>not be yourself</strong> to be behaving in a way that is unusual for you, especially because you are ill or upset:</div><ul class=\"examples\"><li><em>Sorry – I’m not myself this morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>the be-all and end-all</strong> the most important part of a situation or of someone’s life</div><ul class=\"examples\"><li><strong><em>be of</strong>: For Jim, making money was the be-all and end-all of his job.</em></li></ul></div></div>","614":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an area of sand or small stones at the edge of the sea or a lake:</div><ul class=\"examples\"><li><em>There is a beautiful sandy beach.</em></li><li><em>It&#x27;s a nice day for going to the beach.</em></li><li><em>We walked along the beach.</em></li><li><em>Our hotel was right next to the beach.</em></li></ul></div>","615":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bea‧con</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbiːkən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a light that is put somewhere to warn or guide people, ships, vehicles, or aircraft</div><div class=\"sense\"><span class=\"snum\">2</span> a radio or radar signal used by aircraft or boats to help them find their position and direction</div><div class=\"sense\"><span class=\"snum\">3</span> <em>especially literary</em> a person, idea etc that guides or encourages you</div><ul class=\"examples\"><li><strong><em>beacon of</strong>: The education program offers a beacon of hope to these children.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a fire on top of a hill used in the past as a signal</div></div>","616":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> one of a set of small, usually round, pieces of glass, wood, plastic etc, that you can put on a string and wear as jewellery:</div><ul class=\"examples\"><li><em>She wore a string of green glass beads around her neck.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small drop of liquid such as water or blood:</div><ul class=\"examples\"><li><em>Beads of sweat trickled down his face.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>draw a bead on somebody/something</strong> to aim carefully before shooting a weapon</div></div>","617":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the hard pointed mouth of a bird <em>SYN bill</em></div><div class=\"sense\"><span class=\"snum\">2</span> a large pointed nose – used humorously</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the beak</strong> <em>British English</em> <em>old-fashioned</em> <em>informal</em> a judge or a male teacher</div></div>","618":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> a line of light shining from the sun, a lamp etc:</div><ul class=\"examples\"><li><em>the beam of a powerful flashlight</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a line of light, energy etc that you cannot see:</div><ul class=\"examples\"><li><em>a laser beam</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a long heavy piece of wood or metal used in building houses, bridges etc</div><div class=\"sense\"><span class=\"snum\">3</span> a wide happy smile:</div><ul class=\"examples\"><li><em>a beam of delight</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>off beam</strong> <em>British English</em> <em>informal</em> incorrect or mistaken:</div><ul class=\"examples\"><li><em>Our guesses were way off beam.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> a balance beam</div><div class=\"sense\"><span class=\"snum\">6</span> <em>technical</em> the widest part of a ship from side to side</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to smile very happily:</div><ul class=\"examples\"><li><em>Sherman looked at his sons and beamed proudly.</em></li><li><strong><em>beam with</strong>: Connie beamed with pleasure.</em></li><li><strong><em>beam at</strong>: McLeish beamed at her.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to send a radio or television signal through the air, especially to somewhere very distant:</div><ul class=\"examples\"><li><em>the first sports broadcast to be beamed across the Atlantic</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to send out a line of light, heat, energy etc:</div><ul class=\"examples\"><li><em>The sun beamed through the clouds.</em></li></ul></div></div>","619":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a seed or a pod (=case containing seeds), that comes from a climbing plant and is cooked as food. There are very many types of beans:</div><ul class=\"examples\"><li><em>baked beans</em></li><li><em>Soak the beans overnight.</em></li><li><em>kidney beans</em></li><li><em>green beans</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a plant that produces beans</div><div class=\"sense\"><span class=\"snum\">3</span> a seed used in making some types of food or drinks:</div><ul class=\"examples\"><li><em>coffee beans</em></li><li><em>cocoa beans</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be full of beans</strong> <em>informal</em> to be very eager and full of energy:</div><ul class=\"examples\"><li><em>She’s full of beans this morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>not have a bean</strong> <em>British English</em> <em>informal</em> to have no money at all</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>not know/care beans (about somebody/something)</strong> <em>American English</em> <em>informal</em> to not know anything or care at all about someone or something</div></div>","620":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beə $ ber/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense bore /bɔː $ bɔːr/, past participle borne /bɔːn $ bɔːrn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[deal with something]</strong> to bravely accept or deal with a painful, difficult, or upsetting situation <em>SYN stand</em>: RegisterIn everyday English, people usually say that they can’t stand something, rather than that they can&#x27;t bear it:· I couldn’t stand the noise any longer.</div><ul class=\"examples\"><li><em>She was afraid she wouldn’t be able to bear the pain.</em></li><li><em>Overcrowding makes prison life even harder to bear.</em></li><li><em>Make the water as hot as you can bear.</em></li><li><em>The humiliation was more than he could bear.</em></li><li><em>Black people continue to bear the brunt of most racial violence (=have to deal with the most difficult or damaging part).</em></li><li><em>Passengers could be insulting, and stewardesses just had to grin and bear it (=accept it without complaining).</em></li><li><em>Experts were worried the financial system would not be able to bear the strain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>can’t bear something</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be so upset about something that you feel unable to accept it or let it happen <em>SYN can’t stand</em>:</div><ul class=\"examples\"><li><em>Please don’t leave me. I couldn’t bear it.</em></li><li><strong><em>can’t bear the thought of (doing) something</strong>: I just can’t bear the thought of having to start all over.</em></li><li><strong><em>can’t bear to do something</strong>: I can’t bear to see her cry.</em></li><li><strong><em>can’t bear doing something</strong>: I couldn’t bear not seeing him again.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to dislike something or someone very much, often so that they make you feel annoyed or impatient <em>SYN can’t stand</em>:</div><ul class=\"examples\"><li><em>Oh, I really can’t bear him.</em></li><li><strong><em>can’t bear somebody doing something</strong>: He can’t bear people smoking while he’s eating.</em></li><li><strong><em>can’t bear doing something</strong>: I can’t bear being cold.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>bear (something) in mind</strong> to remember a fact or piece of information that is important or could be useful in the future <em>SYN keep (something) in mind</em></div><ul class=\"examples\"><li><strong><em>bear in mind (that)</strong>: Bear in mind that some children will need help.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[accept/be responsible for]</strong> <em>formal</em> to be responsible for or accept something</div><ul class=\"examples\"><li><strong><em>bear the costs/burden</strong>: Each company will bear half the costs of development.</em></li><li><em>Fares have gone up, perhaps to more than the market will bear.</em></li><li><strong><em>bear the responsibility/blame etc</strong>: Developed countries bear much of the responsibility for environmental problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[support]</strong> to be under something and support it <em>SYN hold</em>:</div><ul class=\"examples\"><li><em>My leg was painful, and I wasn’t sure it would bear my weight.</em></li><li><em>a tray bearing a bottle and several glasses</em></li><li><em>a load-bearing wall</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[sign/mark]</strong> <em>formal</em> to have or show a sign, mark, or particular appearance, especially when this shows that something has happened or is true <em>SYN have</em>:</div><ul class=\"examples\"><li><em>The letter bore no signature.</em></li><li><em>a car bearing diplomatic license plates</em></li><li><em>The labels bear a yellow and black symbol.</em></li><li><em>The town still bears the scars of the bombings during the war.</em></li><li><em>The store bears the hallmarks (=it has the qualities) of a family-owned business.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bear a resemblance/relation to somebody/something</strong> to be similar to someone or something else:</div><ul class=\"examples\"><li><em>The child bore a striking resemblance to his father.</em></li><li><em>The things she says bear little relation to what she actually does.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[baby]</strong> <em>formal</em> to give birth to a baby:</div><ul class=\"examples\"><li><em>She might never be able to bear children.</em></li><li><strong><em>bear somebody a child/son/daughter</strong>: She bore him three sons.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bear fruit</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a plan, decision etc bears fruit, it is successful, especially after a long period of time:</div><ul class=\"examples\"><li><em>Charles’s diplomacy eventually bore fruit.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a tree bears fruit, it produces fruit</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[able to be examined/compared etc]</strong> <span class=\"gram\">[often in negatives]</span> to be suitable or good enough to be examined, compared, repeated etc without failing or being wrong:</div><ul class=\"examples\"><li><em>The production figures did not bear scrutiny.</em></li><li><em>We believe our pupils’ results will bear comparison with any in Scotland.</em></li><li><em>The story is well known, but it certainly bears repeating.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>something doesn’t bear thinking about</strong> used to say that something is so upsetting or shocking that you prefer not to think about it:</div><ul class=\"examples\"><li><em>The long-term consequences of a nuclear leak don’t bear thinking about.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>bear interest</strong> if a bank account, investment etc bears interest, the bank pays you a particular amount of money for keeping your money in the account</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>[carry]</strong> <em>literary</em> to carry someone or something, especially something important:</div><ul class=\"examples\"><li><em>The wedding guests arrived, bearing gifts.</em></li><li><em>The US Constitution states that the people have a right to bear arms.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>bring pressure/influence to bear (on somebody/something)</strong> to use your influence or power to get what you want:</div><ul class=\"examples\"><li><em>Unions can bring pressure to bear on governments.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>bear witness/testimony to something</strong> <em>formal</em> to show that something is true or exists:</div><ul class=\"examples\"><li><em>The empty workshops bear witness to the industrial past.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>[have feelings]</strong> <em>formal</em> to have a particular feeling, especially a bad feeling</div><ul class=\"examples\"><li><strong><em>bear (somebody) a grudge</strong> (=continue to feel annoyed after a long time): It was an accident. I don’t bear any grudges.</em></li><li><strong><em>bear somebody no malice/ill will etc</strong> (=not feel angry): He was just doing his job, and I bore him no malice.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>bear right/left</strong> to turn towards the right or left:</div><ul class=\"examples\"><li><em>When you reach the fork in the trail, bear left.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>bear yourself</strong> <em>formal</em> to walk, stand etc in a particular way, especially when this shows your character:</div><ul class=\"examples\"><li><em>She bore herself with great dignity.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>[wind/water]</strong> <em>literary</em> if wind, water, or air bears something, it carries it somewhere:</div><ul class=\"examples\"><li><em>The sound of music was borne along on the wind.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[name/title]</strong> <em>formal</em> to have a particular name or title:</div><ul class=\"examples\"><li><em>He bore the name ‘Magnus’.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large strong animal with thick fur, that eats flesh, fruit, and insects: → grizzly bear, polar bear, teddy bear</div><ul class=\"examples\"><li><em>a mother bear and her cubs</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> <em>informal</em> something that is very difficult to do or to deal with:</div><ul class=\"examples\"><li><em>The chemistry test was a bear.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be like a bear with a sore head</strong> <em>British English</em> <em>informal</em> to be rude to people because you are feeling bad-tempered</div><div class=\"sense\"><span class=\"snum\">4</span> <em>technical</em> someone who sells shares or goods when they expect the price to fall → bull</div></div></div>","621":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪəd $ bɪrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> hair that grows around a man’s chin and cheeks → moustache</div><div class=\"sense\"><span class=\"snum\">2</span> something similar to a beard, such as hair growing on an animal’s chin</div></div>","622":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>written</em> an animal, especially a large or dangerous one ► see thesaurus at animal</div><div class=\"sense\"><span class=\"snum\">2</span> <em>old-fashioned</em> someone who is cruel or unpleasant:</div><ul class=\"examples\"><li><em>You beast! Let go!</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> something of a particular type or that has a particular quality – usually used humorously <em>SYN animal</em>:</div><ul class=\"examples\"><li><em>A city at night is a very different beast.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the beast in somebody</strong> the part of someone’s character that makes them experience hatred, strong sexual feelings, violence etc</div></div>","623":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(past tense beat, past participle beaten /ˈbiːtn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[competition/election]</strong> <span class=\"gram\">[transitive]</span> to get the most points, votes etc in a game, race, or competition <em>SYN defeat</em>:</div><ul class=\"examples\"><li><em>Brazil were beaten 2–1.</em></li><li><em>Labour easily beat the Conservatives in the last election.</em></li><li><strong><em>beat somebody at/in something</strong>: I beat him more often at pool than he beats me.</em></li><li><strong><em>beat somebody hollow<em>British English,</em></strong> <strong>beat the pants off somebody</em>American English</strong><em> (=defeat them easily)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[hit]</strong> <span class=\"gram\">[transitive]</span> to hit someone or something many times with your hand, a stick etc: ► see thesaurus at hit</div><ul class=\"examples\"><li><em>photographs of rioters beating a policeman</em></li><li><em>He was questioned and beaten.</em></li><li><em>The woman had been beaten to death by her husband.</em></li><li><em>Two prisoners were beaten unconscious.</em></li><li><strong><em>beat somebody black and blue</strong> (=hit someone until it makes marks on their body)</em></li><li><strong><em>beat the living daylights out of somebody</strong> (=beat someone very hard)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[hit against]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to hit against something many times or continuously</div><ul class=\"examples\"><li><strong><em>beat on/against/at etc</strong>: Waves beat against the cliffs. / rain beating on the windows / Sid beat on the door with his hand.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[do better]</strong> <span class=\"gram\">[transitive]</span> to do something better, faster etc than what was best before</div><ul class=\"examples\"><li><strong><em>beat a record/score etc</strong>: The record set by Kierson in &#x27;84 has yet to be beaten.</em></li><li><em>The company’s profits are unlikely to beat last year’s £10 million.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[be better]</strong> <span class=\"gram\">[transitive not in progressive]</span> <em>especially spoken</em> to be much better and more enjoyable than something else:</div><ul class=\"examples\"><li><em>Fresh milk beats powdered milk any time.</em></li><li><strong><em>beat doing something</strong>: ‘Well,’ said Culley, ‘it beats going to the office.’</em></li><li><em>You can’t beat swimming as a good all-body exercise.</em></li><li><em>Nothing beats homemade cake.</em></li><li><strong><em>you can’t beat something (for something)</strong>: For excitement, you just can’t beat college basketball.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[food]</strong> <span class=\"gram\">[intransitive, transitive]</span> to mix things together quickly with a fork or special kitchen machine: ► see thesaurus at mix</div><ul class=\"examples\"><li><em>Beat the eggs, then add the milk.</em></li><li><strong><em>beat something in</strong>: Gradually beat in the sugar.</em></li><li><strong><em>beat something together</strong>: Beat the butter and sugar together until fluffy.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[control/deal with]</strong> <span class=\"gram\">[transitive]</span> to successfully deal with a problem that you have been struggling with <em>SYN conquer</em>:</div><ul class=\"examples\"><li><em>advice on how to beat depression</em></li><li><em>the government’s long fight to beat inflation</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[heart]</strong> <span class=\"gram\">[intransitive]</span> when your heart beats, it moves in a regular rhythm as it pumps your blood:</div><ul class=\"examples\"><li><em>The average person’s heart beats 70 times a minute.</em></li><li><em>Jennifer’s heart was beating fast.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[drums]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you beat drums, or if drums beat, they make a regular continuous sound</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[wings]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a bird beats its wings, or if its wings beat, they move up and down quickly and regularly <em>SYN flap</em></div><div class=\"sense\"><span class=\"snum\">11</span> <strong>take some beating</strong> if something or someone will take some beating, it will be difficult for anyone or anything to be or do better:</div><ul class=\"examples\"><li><em>Raikkonen has 42 points, which will take some beating.</em></li><li><em>Florida takes some beating as a vacation destination.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[avoid]</strong> <span class=\"gram\">[transitive]</span> to avoid situations in which a lot of people are trying to do something, usually by doing something early:</div><ul class=\"examples\"><li><em>We left at four a.m. to beat the traffic.</em></li><li><em>Shopping by mail order lets you beat the queues.</em></li><li><em>Shop now and beat the Christmas rush!</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[do before somebody else]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to get or do something before someone else, especially if you are both trying to do it first</div><ul class=\"examples\"><li><strong><em>beat somebody to something</strong>: John had beaten me to the breakfast table.</em></li><li><em>I wanted the last piece of pie, but somebody beat me to it.</em></li><li><em>They wanted to make it into a film, but another studio beat them to the punch.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>beat about/around the bush</strong> to avoid or delay talking about something embarrassing or unpleasant:</div><ul class=\"examples\"><li><em>Don’t beat around the bush. Ask for your account to be paid, and paid quickly.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>beat the system</strong> to find ways of avoiding or breaking the rules of an organization, system etc, in order to achieve what you want:</div><ul class=\"examples\"><li><em>Accountants know a few ways to beat the system.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>beat a path to somebody’s door</strong> (also beat down somebody’s door) if people beat a path to your door, they are interested in something you are selling, a service you are providing etc:</div><ul class=\"examples\"><li><em>The new design was supposed to have consumers beating a path to their door.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>beat a (hasty) retreat</strong> to leave somewhere or stop doing something very quickly, in order to avoid a bad situation:</div><ul class=\"examples\"><li><em>He beat a hasty retreat when he spotted me.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>beat the clock</strong> to finish something very quickly, especially before a particular time:</div><ul class=\"examples\"><li><em>The company managed to beat the clock on delivering its new system.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>beat the rap</strong> <em>American English</em> <em>informal</em> to avoid being punished for something you have done</div><div class=\"sense\"><span class=\"snum\">25</span> <strong>beat time</strong> to make regular movements or sounds to show the speed at which music should be played:</div><ul class=\"examples\"><li><em>a conductor beating time with his baton</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>beat a path/track</strong> to make a path by walking over an area of land</div><div class=\"sense\"><span class=\"snum\">27</span> <strong>to beat the band</strong> <em>American English</em> <em>informal</em> in large amounts or with great force:</div><ul class=\"examples\"><li><em>It’s raining to beat the band.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>beat the heat</strong> <em>American English</em> <em>informal</em> to make yourself cooler:</div><ul class=\"examples\"><li><em>Fresh lemonade is a great way to beat the heat.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>[metal]</strong> (also beat out) <span class=\"gram\">[transitive]</span> to hit metal with a hammer in order to shape it or make it thinner</div><div class=\"sense\"><span class=\"snum\">30</span> <strong>[hunting]</strong> <span class=\"gram\">[intransitive, transitive]</span> to force wild birds and animals out of bushes, long grass etc so that they can be shot for sport</div><div class=\"sense\"><span class=\"snum\">31</span> <strong>beat your breast</strong> <em>literary</em> to show clearly that you are very upset or sorry about something</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one of a series of regular movements or hitting actions:</div><ul class=\"examples\"><li><em>a heart rate of 80 beats a minute</em></li><li><em>the steady beat of the drum</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a regular repeated noise <em>SYN rhythm</em></div><ul class=\"examples\"><li><strong><em>beat of</strong>: the beat of marching feet</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the main rhythm that a piece of music or a poem has:</div><ul class=\"examples\"><li><em>a song with a beat you can dance to</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular]</span> a subject or area of a city that someone is responsible for as their job:</div><ul class=\"examples\"><li><em>journalists covering the Washington beat</em></li><li><strong><em>on the beat</strong>: People like to see police officers on the beat.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> one of the notes in a piece of music that sounds stronger than the other notes</div></div></div>","624":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> beau‧ti‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbjuːtəfəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone or something that is beautiful is extremely attractive to look at:</div><ul class=\"examples\"><li><em>She was even more beautiful than I had remembered.</em></li><li><em>a beautiful bunch of flowers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very good or giving you great pleasure <em>SYN lovely</em>: ► see thesaurus at good</div><ul class=\"examples\"><li><em>beautiful music</em></li><li><em>What a beautiful shot!</em></li><li><em>The weather was beautiful.</em></li></ul></div>","625":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> beau‧ty</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbjuːti/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\">(plural beauties)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[appearance]</strong> <span class=\"gram\">[uncountable]</span> a quality that people, places, or things have that makes them very attractive to look at:</div><ul class=\"examples\"><li><em>her beauty and grace</em></li><li><em>an area of outstanding natural beauty</em></li><li><em>Millions of dollars are spent each year on beauty products.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[woman]</strong> <span class=\"gram\">[countable]</span> a woman who is very beautiful:</div><ul class=\"examples\"><li><em>She was considered a great beauty in her youth.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[poem/music/emotion etc]</strong> <span class=\"gram\">[uncountable]</span> a quality that something such as a poem, song, emotion etc has that gives you pleasure or joy</div><ul class=\"examples\"><li><strong><em>beauty of</strong>: the beauty of Shakespeare’s verse</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[advantage]</strong> <strong>the beauty of something</strong> a particularly good quality that makes something especially suitable or useful:</div><ul class=\"examples\"><li><em>The beauty of e-mail is its speed and ease of use.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> <em>spoken</em> a very good, large etc example of something:</div><ul class=\"examples\"><li><em>You should have seen the boat – a real beauty.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>beauty is in the eye of the beholder</strong> used to say that different people have different opinions about what is beautiful</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>beauty is only skin-deep</strong> used to say that how someone looks is not as important as a good character</div></div>","626":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧cause</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈkɒz, bɪˈkəz $ bɪˈkɒːz, bɪˈkəz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used when you are giving the reason for something:</div><ul class=\"examples\"><li><em>We didn’t enjoy the day because the weather was so awful.</em></li><li><em>‘Why can’t I go?’ ‘Because you’re not old enough.’</em></li><li><em>Hubert never experienced any fear, and this was partly because he was not particularly intelligent.</em></li><li><em>Many exam candidates lose marks simply because they do not read the questions properly.</em></li><li><em>I decided to go with them, mainly because I had nothing better to do.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>just because...</strong> <em>spoken</em> used to say that, although one thing is true, it does not mean that something else is true:</div><ul class=\"examples\"><li><em>Just because you’re my brother doesn’t mean I have to like you!</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>because of somebody/something</strong> used to say who or what causes something to happen or is the reason for something: RegisterIn written English, people often prefer to use the expressions due to something, owing to something, or as a result of something, which sound more formal than because of something: · Many businesses fail due to cash-flow problems.</div><ul class=\"examples\"><li><em>He had to retire because of ill health.</em></li><li><em>We spent three hours waiting in the rain because of you!</em></li></ul></div></div>","627":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> beck‧on</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbekən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to make a signal to someone with your hand, to show that you want them to come towards you or to follow you:</div><ul class=\"examples\"><li><em>I could see my husband beckoning me.</em></li><li><strong><em>beckon (to) somebody to do something</strong>: She beckoned to the waitress to bring more wine.</em></li><li><strong><em>beckon somebody forward/over etc</strong>: He beckoned us over and introduced us to his wife.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> if something such as a place or opportunity beckons, it appears so attractive that you want to have it:</div><ul class=\"examples\"><li><em>A career in the film industry beckoned.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> if something beckons for someone, it will probably happen to them</div><ul class=\"examples\"><li><strong><em>beckon for</strong>: Early retirement beckoned for George.</em></li></ul></div>","628":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧come</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈkʌm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense became /-ˈkeɪm/, past participle become)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[linking verb]</span> to start to have a feeling or quality, or to start to develop into something:</div><ul class=\"examples\"><li><em>The weather became warmer.</em></li><li><em>Slowly my eyes became accustomed to the darkness.</em></li><li><em>Helen became increasingly anxious about her husband’s strange behaviour.</em></li><li><em>Pollution from cars has become a major problem.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[linking verb]</span> to start to have a job or position:</div><ul class=\"examples\"><li><em>George became king at the age of 54.</em></li><li><em>When did you first want to become a teacher?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive not in progressive]</span> <em>formal</em> to be suitable for someone, or to look attractive on them <em>SYN suit</em>:</div><ul class=\"examples\"><li><em>Blue really becomes her.</em></li><li><em>Don’t try to be clever – it doesn’t become you.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>what became of...? whatever will become of...?</strong> used to ask what has happened to someone or something, especially when you have not seen them for a long time, or what will happen to someone that you are worried about:</div><ul class=\"examples\"><li><em>What became of those Chinese vases that Mum used to have?</em></li><li><em>Whatever will become of Sam when his wife dies?</em></li></ul></div>","629":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bed/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[sleep]</strong> <span class=\"gram\">[countable, uncountable]</span> a piece of furniture that you sleep on → camp bed, four-poster bed, sofa bed</div><ul class=\"examples\"><li><strong><em>in bed</strong>: Simon lay in bed thinking.</em></li><li><em>You should go to bed early.</em></li><li><em>She got into bed and turned out the light.</em></li><li><strong><em>before bed</strong> (=before going to bed): Dad has a whisky before bed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sex]</strong> <span class=\"gram\">[uncountable]</span> <em>informal</em> used to refer to having sex:</div><ul class=\"examples\"><li><em>I came home and found him in bed with (=having sex with) my best friend.</em></li><li><em>He wanted me to go to bed with him.</em></li><li><em>He’s been trying to get his secretary into bed.</em></li><li><em>She told me he was good in bed (=a skilful lover).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[river/lake/sea]</strong> <span class=\"gram\">[countable]</span> the flat ground at the bottom of a river, lake, or sea: ► see thesaurus at bottom</div><ul class=\"examples\"><li><em>the sea bed</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[garden]</strong> <span class=\"gram\">[countable]</span> an area of a garden, park etc that has been prepared for plants to grow in:</div><ul class=\"examples\"><li><em>rose beds</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[rock]</strong> <span class=\"gram\">[countable]</span> a layer of rock → bedrock(2)</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[lowest layer]</strong> <span class=\"gram\">[singular]</span> a layer of something that forms a base that other things are put on top of</div><ul class=\"examples\"><li><strong><em>bed of</strong>: prawns on a bed of lettuce</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[in river/water]</strong> <span class=\"gram\">[countable]</span> an area at the edge of a river or in deeper water where things grow:</div><ul class=\"examples\"><li><em>an oyster bed</em></li><li><em>The birds build their nests in reed beds along the river bank.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>get out of bed on the wrong side</strong> <em>British English</em>, get up on the wrong side of the bed<em>American English</em> to feel slightly angry or annoyed for no particular reason</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>not a bed of roses</strong> not a happy, comfortable, or easy situation:</div><ul class=\"examples\"><li><em>Life isn’t always a bed of roses, you know.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>you’ve made your bed and you must lie on it</strong> <em>spoken</em> used to say that you must accept the results of your actions, even if they are bad</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>put something to bed</strong> <em>technical</em> to complete a newspaper, magazine, or book, so that it is ready to be printed</div></div>","630":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bed‧room</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbedrʊm, -ruːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a room for sleeping in:</div><ul class=\"examples\"><li><em>a hotel with 50 bedrooms</em></li><li><strong><em>three-bedroomed/five-bedroomed etc</strong>: They’ve just bought a new four-bedroomed house in Edinburgh.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bedroom eyes</strong> a look in your eyes that shows that you are sexually attracted to someone</div></div>","631":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a black and yellow flying insect that makes honey and can sting you: → bumblebee</div><ul class=\"examples\"><li><em>a swarm of bees</em></li><li><em>a bee sting</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>have a bee in your bonnet (about something)</strong> <em>informal</em> to think something is so important, so necessary etc that you keep mentioning it or thinking about it:</div><ul class=\"examples\"><li><em>Dad’s got a bee in his bonnet about saving electricity.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>sewing/quilting etc bee</strong> <em>American English</em> <em>informal</em> an occasion when people, usually women, meet in order to do a particular type of work</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a busy bee</strong> <em>spoken</em> someone who enjoys being busy or active</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>be the bee’s knees</strong> <em>spoken</em> <em>old-fashioned</em> to be very good:</div><ul class=\"examples\"><li><em>She thought the party was just the bee’s knees.</em></li></ul></div>","632":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the meat from a cow:</div><ul class=\"examples\"><li><em>roast beef</em></li><li><em>We have both dairy and beef cattle on the farm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>informal</em> a complaint:</div><ul class=\"examples\"><li><em>OK, so what’s the beef this time?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>where’s the beef?</strong> <em>American English</em> <em>spoken</em> used when you think someone’s promises sound good, but you want to know what they actually plan to do</div></div>","633":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /biːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> if a machine beeps, it makes a short high sound <em>SYN bleep</em>: ► see thesaurus at sound</div><ul class=\"examples\"><li><em>Why does the computer keep beeping?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> if a car horn beeps, or if you beep your car horn, it makes a loud noise</div></div>","634":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪə $ bɪr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> an alcoholic drink made from malt and hops:</div><ul class=\"examples\"><li><em>a pint of beer</em></li><li><em>We sell draught beer (=beer served from a large container, not a bottle).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a glass, bottle, or can of beer:</div><ul class=\"examples\"><li><em>Do you fancy a beer?</em></li></ul></div>","635":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧fore</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈfɔː $ -ˈfɔːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> earlier than a particular event or action <em>OPP after</em>:</div><ul class=\"examples\"><li><em>Say goodbye before you go.</em></li><li><em>I saw her a few days before she died.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> so that something does not or cannot happen:</div><ul class=\"examples\"><li><em>Put that money somewhere safe before it gets stolen.</em></li><li><em>That dog ought to be destroyed before it attacks any more children.</em></li><li><em>Before I could say anything more, Holmes had rushed off towards the station.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that something happens after a period of time:</div><ul class=\"examples\"><li><em>It was several minutes before we realised what was happening.</em></li><li><em>It will be a while before we know the results.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say that something must happen in order for something else to be possible:</div><ul class=\"examples\"><li><em>You have to pass a test before you can get a licence.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>spoken</em> used to warn someone that something bad will happen to them if they do not do something:</div><ul class=\"examples\"><li><em>Get out before I call the police!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to emphasize that someone does not want to do something:</div><ul class=\"examples\"><li><em>She would die before she would admit she was wrong.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> earlier than something or someone <em>OPP after</em>:</div><ul class=\"examples\"><li><em>The new road should be completed before the end of the year.</em></li><li><em>Let’s meet at our house before the show.</em></li><li><em>Larry arrived home before me.</em></li><li><strong><em>five minutes/two hours etc before something</strong>: Hugh arrived just five minutes before the ceremony.</em></li><li><strong><em>before doing something</strong>: I usually take a shower before having my breakfast.</em></li><li><em>We only got back from Scotland the day before yesterday (=two days ago).</em></li><li><em>Other students joined in the protest, and before long (=soon) there was a crowd of 200 or so.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> ahead of someone or something else in a list or order <em>OPP after</em>:</div><ul class=\"examples\"><li><em>You were before me in the queue.</em></li><li><em>The files are in alphabetical order, so B1 comes before C1.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that something happens where it can be watched by people <em>SYN in front of</em>:</div><ul class=\"examples\"><li><em>Italy will face Brazil this afternoon before a crowd of 100,000 spectators.</em></li><li><em>an actor who had performed before the Queen</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say that someone or something comes to be judged or considered by a person or group of people:</div><ul class=\"examples\"><li><em>The proposal was put before the planning committee.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to say that one thing or person is considered more important than another:</div><ul class=\"examples\"><li><em>I put my wife and kids before anyone else.</em></li><li><em>In the air transport business, safety must always come before profit.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <em>formal</em> in front of something or someone:</div><ul class=\"examples\"><li><em>The priest stood before the altar.</em></li><li><em>The sea stretched out before them.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> if one place is before another place on a road or journey, the first place is nearer to you than the second, so you will reach it first <em>OPP after</em>:</div><ul class=\"examples\"><li><em>The pub is 100 metres before the church on the right.</em></li><li><em>the last station before the Simplon Tunnel</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <em>formal</em> if there is a job or situation before you, you will have to do the job or face the situation <em>SYN ahead of</em>:</div><ul class=\"examples\"><li><em>The task of emptying the house lay before us.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <em>formal</em> if a period of time is before you, it is about to start and you can do what you want during it <em>SYN in front of</em>:</div><ul class=\"examples\"><li><em>We had a glorious summer afternoon before us to do as we pleased.</em></li><li><em>You have your whole life before you.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> at an earlier time:</div><ul class=\"examples\"><li><em>Haven’t I met you before somewhere?</em></li><li><em>Never before had he seen so many people starving.</em></li><li><em>She looked just the same as before.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the day/week/month etc before</strong> the previous day, week, month etc <em>OPP after</em>:</div><ul class=\"examples\"><li><em>She was in Paris last week and in Rome the week before.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>old use</em> ahead of someone or something else:</div><ul class=\"examples\"><li><em>The king’s herald walked before.</em></li></ul></div></div>","636":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧fore‧hand</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈfɔːhænd $ -ˈfɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">before something else happens or is done: ► see thesaurus at before</div><ul class=\"examples\"><li><em>The police need to be briefed beforehand on how to deal with this sort of situation.</em></li><li><em>When you give a speech, it’s natural to feel nervous beforehand.</em></li></ul></div>","637":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /beɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle begged, present participle begging)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[ask]</strong> <span class=\"gram\">[intransitive, transitive]</span> to ask for something in an anxious or urgent way, because you want it very much: ► see thesaurus at ask</div><ul class=\"examples\"><li><em>She begged and pleaded with them until they finally agreed.</em></li><li><em>She fought back the sudden urge to run to him and beg his forgiveness.</em></li><li><strong><em>beg to do something</strong>: The children begged to come with us.</em></li><li><strong><em>beg somebody to do something</strong>: I begged Helen to stay, but she wouldn’t listen.</em></li><li><strong><em>beg (somebody) for something</strong>: She ran to the nearest house and begged for help. / We could hear the prisoners begging for mercy.</em></li><li><strong><em>I beg of you<em>formal</em></strong> (=please): Listen, I beg of you.</em></li><li><strong><em>beg leave to do something<em>formal</em></strong> (=ask permission to do something)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[money/food]</strong> <span class=\"gram\">[intransitive, transitive]</span> to ask people to give you food, money etc, usually because you are very poor</div><ul class=\"examples\"><li><strong><em>beg (something) from somebody</strong>: a ragged child begging from passing shoppers</em></li><li><strong><em>beg for</strong>: The old man went from door to door begging for food.</em></li><li><em>a begging letter (=a letter asking for money)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[animal]</strong> <span class=\"gram\">[intransitive]</span> if a dog begs, it sits up with its front legs off the ground</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>I beg your pardon</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to ask someone to repeat what they have just said:</div><ul class=\"examples\"><li><em>‘The meeting’s on Wednesday.’ ‘I beg your pardon?’ ‘I said the meeting’s on Wednesday.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say sorry when you have made a mistake, or said something wrong or embarrassing:</div><ul class=\"examples\"><li><em>Oh, I beg your pardon. I thought you said 15 pence, not 50.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to show that you strongly disagree with something that someone has said, or think it is unacceptable:</div><ul class=\"examples\"><li><em>‘Chicago’s an awful place.’ ‘I beg your pardon, that’s where I’m from!’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>I beg to differ</strong> <em>spoken</em> <em>formal</em> used to say firmly that you do not agree with something that has been said:</div><ul class=\"examples\"><li><em>I must beg to differ on this point.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>beg the question</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make you want to ask a question that has not yet been answered</div><ul class=\"examples\"><li><strong><em>beg of</strong>: This proposal begs the question of who is going to pay for the new building.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to treat an idea as though it were true or had been proved, when this may not be the case</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be going begging</strong> <em>British English</em> <em>spoken</em> if something is going begging, it is available for anyone who wants it:</div><ul class=\"examples\"><li><em>There’s a beer going begging, if anyone’s interested.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>beg, borrow, or steal</strong> to do whatever you must in order to get what you want – often used humorously:</div><ul class=\"examples\"><li><em>She’d beg, borrow, or steal the money for those shoes.</em></li></ul></div>","638":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> beg‧gar</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeɡə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who lives by asking people for food and money:</div><ul class=\"examples\"><li><em>the beggars on the streets</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>lucky/lazy/cheeky etc beggar</strong> <em>British English</em> <em>spoken</em> used when speaking to or about someone you like:</div><ul class=\"examples\"><li><em>‘How’s Dave?’ ‘The lucky beggar’s in the South of France!’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>beggars can’t be choosers</strong> used to say that, when you have no money or no power to choose, you have to accept whatever you are given</div></div>","639":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧gin</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈɡɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense began /-ˈɡæn/, past participle begun /-ˈɡʌn/, present participle beginning)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[start doing something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to start doing something: ► see thesaurus at start</div><ul class=\"examples\"><li><em>As everybody’s here, let’s begin.</em></li><li><em>In the third year, students begin the study of classical Chinese.</em></li><li><em>The president begins talks with the prime minister tonight.</em></li><li><strong><em>begin to do something</strong>: She began to feel a sense of panic.</em></li><li><strong><em>begin doing something</strong>: I began teaching in 1984.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[start happening]</strong> <span class=\"gram\">[intransitive, transitive]</span> if something begins, or you begin something, it starts to happen or exist from a particular time:</div><ul class=\"examples\"><li><em>It was the coldest winter since records began.</em></li><li><strong><em>begin at</strong>: The meeting begins at 10.30 am.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[do first]</strong> <span class=\"gram\">[intransitive]</span> if you begin with something or begin by doing something, this is the first thing you do</div><ul class=\"examples\"><li><strong><em>begin with</strong>: Shall we begin with a prayer?</em></li><li><strong><em>begin by doing something</strong>: I’ll begin by thanking you all for being here tonight.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[book/word etc]</strong> <span class=\"gram\">[intransitive]</span> if a book, film, or word begins with something, it starts with a particular event or letter RegisterIn everyday English, people usually say start rather than begin:· The movie starts at 7.45.· Let’s start by introducing ourselves.· Not many English names start with X.</div><ul class=\"examples\"><li><strong><em>begin with</strong>: ‘Psychosis’ begins with a P.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[speech]</strong> <span class=\"gram\">[intransitive, transitive]</span> to start speaking:</div><ul class=\"examples\"><li><em>‘Ladies and gentlemen,’ he began. ‘I am delighted to be here.’</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>to begin with</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>spoken</em> used to introduce the first and most important point you want to make:</div><ul class=\"examples\"><li><em>Well, to begin with, he shouldn’t even have been driving my car.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that something was already in a particular condition before something else happened:</div><ul class=\"examples\"><li><em>I didn’t break it! It was like that to begin with.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> during the first part of a process or activity:</div><ul class=\"examples\"><li><em>The kids helped me to begin with, but they soon got bored.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>can’t begin to understand/imagine etc</strong> <em>spoken</em> used to emphasize how difficult something is to understand etc:</div><ul class=\"examples\"><li><em>I can’t begin to imagine how awful it was.</em></li></ul></div>","640":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧gin‧ner</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈɡɪnə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who has just started to do or learn something:</div><ul class=\"examples\"><li><em>an absolute beginner</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>beginner’s luck</strong> unusual success that you have when you start something new</div></div>","641":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧gin‧ning</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈɡɪnɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable usually singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the start or first part of an event, story, period of time etc</div><ul class=\"examples\"><li><strong><em>beginning of</strong>: She’s been here since the beginning of the year.</em></li><li><em>There’s a short poem at the beginning of every chapter.</em></li><li><em>From the beginning of my career as a journalist, I’ve been writing about gender issues.</em></li><li><em>I thought he loved me; perhaps he did in the beginning.</em></li><li><em>That chance meeting marked the beginning of a long and happy relationship.</em></li><li><em>This is just the beginning of a new and different life for you.</em></li><li><em>I said he would cause trouble, right from the beginning.</em></li><li><em>I opposed it from the very beginning.</em></li><li><em>The whole trip was a disaster from beginning to end.</em></li><li><em>I feel like I’ve been offered a new beginning.</em></li><li><em>Could we start at the beginning? Tell me where you first met him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>beginnings</strong> <span class=\"gram\">[plural]</span> the early signs or stages of something that later develops into something bigger or more important</div><ul class=\"examples\"><li><strong><em>beginning of</strong>: I think I have the beginnings of a cold.</em></li><li><strong><em>from humble/small beginnings</strong>: He rose from humble beginnings to great wealth.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the beginning of the end</strong> the time when something good starts to end</div></div>","642":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧half</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈhɑːf $ bɪˈhæf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><strong>on behalf of somebody</strong> (also in behalf of somebody<em>American English</em>)</div><div class=\"subsense\"><span class=\"subnum\">a)</span> instead of someone, or as their representative:</div><ul class=\"examples\"><li><em>She asked the doctor to speak to her parents on her behalf.</em></li><li><em>On behalf of everyone here, may I wish you a very happy retirement.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> because of or for someone:</div><ul class=\"examples\"><li><em>Oh, don’t go to any trouble on my behalf.</em></li></ul></div>","643":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧have</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈheɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adverb/preposition]</span> to do things that are good, bad, sensible etc <em>SYN act</em>:</div><ul class=\"examples\"><li><em>She behaved in a very responsible way.</em></li><li><strong><em>behave towards</strong>: I think he behaved disgracefully towards you.</em></li><li><strong><em>behave like</strong>: grown men behaving like schoolboys</em></li><li><strong><em>behave as if/though</strong>: He was a little boy, but he behaved as if he was an adult.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also behave yourself) to not do things that annoy or offend people <em>OPP misbehave</em>:</div><ul class=\"examples\"><li><em>Will you children please behave!</em></li><li><em>I hope Nicholas behaved himself at the party.</em></li><li><strong><em>well-behaved/badly-behaved</strong>: a badly-behaved class</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[always + adverb/preposition]</span> if something behaves in a particular way, it does those things:</div><ul class=\"examples\"><li><em>Quantum mechanics is the study of the way atoms behave.</em></li></ul></div>","644":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧hav‧iour</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈheɪvjə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the things that a person or animal does:</div><ul class=\"examples\"><li><em>It is important to reward good behaviour.</em></li><li><strong><em>behaviour towards</strong>: She complained of her boss’s inappropriate behavior towards her. / the effects of alcohol on human behaviour</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be on your best behaviour</strong> to behave as well and politely as you can in order to please someone:</div><ul class=\"examples\"><li><em>I want you both to be on your best behaviour at Grandad’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the things that something in science normally does</div><ul class=\"examples\"><li><strong><em>behaviour of</strong>: the behaviour of human chromosomes</em></li></ul></div>","645":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧hind</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈhaɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> at or towards the back of a thing or person: ► Don’t say ‘behind of’: He hid behind a chair (NOT behind of a chair).</div><ul class=\"examples\"><li><em>I turned to speak to the person standing behind me.</em></li><li><em>Someone could easily creep up behind us.</em></li><li><em>The car behind was hooting impatiently.</em></li><li><em>Jane shut the door behind her.</em></li><li><em>The manager was sitting behind a large desk.</em></li><li><strong><em>close behind/not far behind</strong>: He set off down the road with the rest of us following close behind.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not as successful or not having made as much progress as someone or something else:</div><ul class=\"examples\"><li><em>Mark’s always behind the rest of his class in mathematics.</em></li><li><em>This victory lifts Ferguson’s team into fifth place, nine points behind leaders Norwich.</em></li><li><em>Europe was falling behind in the important field of computer technology.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that someone is late in doing what they have to do:</div><ul class=\"examples\"><li><em>This work should have been finished yesterday. I’m getting terribly behind.</em></li><li><em>Victor had fallen behind with his mortgage payments after losing his job.</em></li><li><em>an important research project that is already two years behind schedule (=not ready at the time planned)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used for talking about the hidden reason for something:</div><ul class=\"examples\"><li><em>I wonder what’s behind this change of plan.</em></li><li><em>Perhaps a bitter experience lay behind her anger.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> supporting a person, idea etc:</div><ul class=\"examples\"><li><em>The workers are very much behind these proposals.</em></li><li><em>I suppose I’m lucky because my parents were behind me all the way.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> responsible for a plan, idea etc or for organizing something:</div><ul class=\"examples\"><li><em>It was alleged that foreign agents were behind the recent violence.</em></li><li><em>The Rotary Club is behind the fund-raising for the new hospital.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> if an unpleasant experience or situation is behind you, it no longer upsets you or affects your life:</div><ul class=\"examples\"><li><em>Now you can put all these worries behind you.</em></li><li><em>a chance to start a new life and leave all your troubles behind</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> if you have experience behind you, you have gained valuable skills or important qualities that can be used:</div><ul class=\"examples\"><li><em>Marjorie is one of the top designers in the business, with years of experience behind her.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> used when the real facts about a situation or someone’s character are hidden by the way things seem or by the way a person behaves:</div><ul class=\"examples\"><li><em>We were determined to find the truth behind this mystery.</em></li><li><em>You could see the burning hatred behind Graham’s calm manner.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> if a student stays behind after school or after a lesson, they stay after it has finished</div></div>","646":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>come into being/be brought into being</strong> to start to exist:</div><ul class=\"examples\"><li><em>a law that first came into being in 1912</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a living thing, especially a person:</div><ul class=\"examples\"><li><em>a human being</em></li><li><strong><em>intelligent/conscious/rational etc being</strong>: a story about alien beings who invade Earth</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> <em>literary</em> the most important quality or nature of something, especially of a person</div><ul class=\"examples\"><li><strong><em>the core/roots/whole of somebody’s being</strong>: The whole of her being had been taken over by a desire to return to her homeland.</em></li></ul></div>","647":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧lief</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈliːf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> the feeling that something is definitely true or definitely exists</div><ul class=\"examples\"><li><strong><em>belief in</strong>: a strong belief in God</em></li><li><strong><em>belief that</strong>: her sincere belief that her brother was not the murderer</em></li><li><strong><em>in the belief that</strong>: Thieves broke into the building in the mistaken belief that there was expensive computer equipment inside.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> the feeling that something is good and can be trusted</div><ul class=\"examples\"><li><strong><em>belief in</strong>: If you’re selling, you have to have genuine belief in the product.</em></li><li><em>When you get something wrong, it can shake your belief in yourself.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an idea that you believe to be true, especially one that forms part of a system of ideas:</div><ul class=\"examples\"><li><em>religious beliefs</em></li><li><em>Several members hold very right-wing beliefs.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>beyond belief</strong> used to emphasize that something is so extreme that it is difficult to believe:</div><ul class=\"examples\"><li><em>What she did was stupid beyond belief.</em></li></ul></div>","648":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧lieve</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈliːv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to be sure that something is true or that someone is telling the truth:</div><ul class=\"examples\"><li><em>You shouldn’t believe everything you read.</em></li><li><em>I believed him, even though his story sounded unlikely.</em></li><li><strong><em>believe (that)</strong>: I don’t believe he’s only 25.</em></li><li><em>I don’t believe a word of it (=I think it is completely untrue).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to think that something is true or possible, although you are not completely sure ► see thesaurus at think</div><ul class=\"examples\"><li><strong><em>believe (that)</strong>: Detectives believe that the victim knew his killer.</em></li><li><strong><em>it is believed (that)</strong>: It is believed that the house was built in 1735.</em></li><li><strong><em>believe so</strong> (=think that something is true): ‘Have they arrived yet?’ ‘Yes, I believe so.’</em></li><li><strong><em>be believed to be something</strong>: At 115, Mrs Jackson is believed to be the oldest person in the country.</em></li><li><em>The four men are widely believed (=believed by a lot of people) to have been killed by their captors.</em></li><li><em>Did you honestly believe that I’d be stupid enough to do that?</em></li><li><em>I firmly believe that the business will be a success.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>it’s difficult/hard to believe (that)</strong> used when you are surprised that something is true:</div><ul class=\"examples\"><li><em>Sometimes, it’s hard to believe we’ve been married for 50 years.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <span class=\"gram\">[intransitive]</span> to have a religious faith:</div><ul class=\"examples\"><li><em>She says those who believe will go to heaven.</em></li></ul></div>","649":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧liev‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈliːvə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be a (great/firm) believer in something</strong> to believe strongly that something is good and effective:</div><ul class=\"examples\"><li><em>I’m a great believer in regular exercise.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who believes in a particular god, religion, or system of beliefs <em>OPP unbeliever</em></div></div>","650":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bel/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a piece of electrical equipment that makes a ringing sound, used as a signal or to get someone’s attention</div><ul class=\"examples\"><li><strong><em>ring/press the bell</strong>: He rang the bell and waited for someone to answer the door. / She pressed the bell for the nurse.</em></li><li><strong><em>a bell rings/goes</strong>: The bell went and everyone rushed out of the classroom.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a hollow metal object like a cup with a piece of metal hanging inside it, that makes a ringing noise when it moves or you shake it:</div><ul class=\"examples\"><li><em>church bells</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>give somebody a bell</strong> <em>British English</em> <em>spoken</em> to telephone someone:</div><ul class=\"examples\"><li><em>I must give Vicky a bell later.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> something that is shaped like a bell:</div><ul class=\"examples\"><li><em>the bell of a flower</em></li></ul></div>","651":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bel‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbeli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural bellies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> your stomach:</div><ul class=\"examples\"><li><em>a full belly</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> the front part of your body between your chest and your legs <em>SYN abdomen</em>:</div><ul class=\"examples\"><li><em>She was lying on her belly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the middle part of an animal’s body, near its stomach</div><div class=\"sense\"><span class=\"snum\">3</span> <em>literary</em> a curved or rounded part of an object:</div><ul class=\"examples\"><li><em>the belly of a plane</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>black-bellied/fat-bellied/big-bellied etc</strong> having a black, fat, big etc stomach</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>go belly up</strong> <em>informal</em> if a business or company goes belly up, it stops operating because it cannot pay its debts</div></div>","652":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧long</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈlɒŋ $ bɪˈlɒːŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[always + adverb/preposition]</span> if something belongs somewhere, that is the right place or situation for it:</div><ul class=\"examples\"><li><em>Put the chair back where it belongs.</em></li><li><strong><em>belong in</strong>: an attitude that doesn’t belong in modern society</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> if you feel you belong in a place or situation, you feel happy and comfortable in it, because you have the same interests and ideas as other people:</div><ul class=\"examples\"><li><em>I worked there for five years but never really felt I belonged.</em></li></ul></div>","653":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧long‧ings</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈlɒŋɪŋz $ bɪˈlɒːŋ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the things you own, especially things that you can carry with you <em>SYN possessions</em>:</div><ul class=\"examples\"><li><em>an insurance policy that covers your personal belongings</em></li></ul></div>","654":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧low</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈləʊ $ -ˈloʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a lower place or position, or on a lower level <em>OPP above</em>: ► see thesaurus at under</div><ul class=\"examples\"><li><em>an animal that lives below ground</em></li><li><em>Water was dripping onto the floor below.</em></li><li><em>I could hear voices in the courtyard below my window.</em></li><li><em>They camped a few hundred feet below the summit.</em></li><li><em>Down below, people were talking and laughing.</em></li><li><em>Somewhere far below, a door slammed.</em></li><li><em>The kitchen is directly below her bedroom.</em></li><li><em>Captain Parker went below (=to the lower level of the ship), leaving Clooney in charge.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> of a lower rank or having a less important job than someone else <em>OPP above</em>:</div><ul class=\"examples\"><li><em>No one below the level of senior manager was present at the meeting.</em></li><li><strong><em>and/or below</strong>: officers of the rank of captain and below</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> less than a particular number, amount, level etc <em>OPP above</em>:</div><ul class=\"examples\"><li><em>Test scores below 50 were classed as ‘unsatisfactory’.</em></li><li><em>In June the rate of inflation fell below 3%.</em></li><li><em>Tom’s spelling is well below average (=much worse than the normal standard).</em></li><li><strong><em>below freezing/zero</strong> (=lower than the temperature at which water freezes): In winter, temperatures dip to 40 degrees below freezing.</em></li><li><strong><em>and/or below</strong>: free travel for children four years old and below</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> lower on the same page, or on a later page <em>OPP above</em>:</div><ul class=\"examples\"><li><em>Details of courses are listed below.</em></li><li><em>For more information, see below.</em></li></ul></div>","655":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /belt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a band of leather, cloth etc that you wear around your waist to hold up your clothes or for decoration:</div><ul class=\"examples\"><li><em>He unbuckled his leather belt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large area of land that has particular features or where particular people live: → green belt</div><ul class=\"examples\"><li><em>America’s farming belt</em></li><li><em>the green (=countryside) belt</em>British English**</li></ul><div class=\"sense\"><span class=\"snum\">3</span> a circular band of something such as rubber that connects or moves parts of a machine → conveyor belt, fan belt</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>below the belt</strong> <em>informal</em> unfair or cruel:</div><ul class=\"examples\"><li><em>That was a bit below the belt, Paul.</em></li><li><em>The comments hit below the belt (=they were unfair or cruel).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>have something under your belt</strong> to have achieved something useful or important:</div><ul class=\"examples\"><li><em>a secretary with several years’ experience under her belt</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>belt and braces</strong> <em>British English</em> <em>informal</em> a belt and braces way of doing something is one in which you do more than necessary in order to make sure that it succeeds</div></div>","656":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bentʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[outdoor seat]</strong> <span class=\"gram\">[countable]</span> a long seat for two or more people, especially outdoors:</div><ul class=\"examples\"><li><em>We sat on a park bench.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[in a law court]</strong> <strong>the bench</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the seat where a judge or magistrate sits in a court of law:</div><ul class=\"examples\"><li><em>Would the prisoner please approach the bench?</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the position of being a judge or magistrate in a court of law:</div><ul class=\"examples\"><li><em>He was appointed to the bench last year.</em></li><li><strong><em>sit/serve on the bench</strong> (=work as a judge or magistrate)</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[sports]</strong> <strong>the bench</strong> the seat where members of a sports team sit when they are not playing in the game:</div><ul class=\"examples\"><li><em>Batts and Dorigo are on the bench tonight.</em></li><li><em>Simpson came off the bench to play in midfield.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[parliament]</strong> <strong>benches</strong> <span class=\"gram\">[plural]</span> <em>British English</em> the seats in the British parliament where members of a particular party sit: → backbench, backbenches, front bench</div><ul class=\"examples\"><li><em>There was cheering from the Conservative benches.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[table]</strong> <span class=\"gram\">[countable]</span> a long heavy table used for working on with tools or equipment:</div><ul class=\"examples\"><li><em>a carpenter’s bench</em></li></ul></div>","657":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bench‧mark</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbentʃmɑːk $ -mɑːrk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something that is used as a standard by which other things can be judged or measured:</div><ul class=\"examples\"><li><em>benchmark data</em></li><li><em>The valuation becomes a benchmark against which to judge other prices.</em></li><li><strong><em>benchmark for</strong>: figures that are a useful benchmark for measuring the company’s performance</em></li><li><strong><em>benchmark of</strong>: results that are used as a benchmark of success</em></li></ul></div>","658":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\">(past tense and past participle bent /bent/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to move part of your body so that it is not straight or so that you are not upright:</div><ul class=\"examples\"><li><em>Lee bent and kissed her.</em></li><li><em>She bent her head.</em></li><li><em>Bend your knees, but keep your back straight.</em></li><li><strong><em>bend over</strong>: Emma bent over to pick up the coins.</em></li><li><strong><em>bend down</strong>: I bent down to lift the box off the floor.</em></li><li><strong><em>bend towards/across etc</strong>: He bent towards me and whispered in my ear.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to push or press something so that it is no longer flat or straight:</div><ul class=\"examples\"><li><em>You need a special tool to bend the steel.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive]</span> to become curved and no longer flat or straight:</div><ul class=\"examples\"><li><em>Several branches started bending towards the ground.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> when a road bends, it changes direction to form a curve:</div><ul class=\"examples\"><li><em>The road bends sharply to the left.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>bend the truth</strong> to say something that is not completely true</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>bend over backwards (to do something)</strong> to try very hard to be helpful:</div><ul class=\"examples\"><li><em>We bent over backwards to finish it on time.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bend somebody’s ear</strong> <em>spoken</em> to talk to someone, especially for a long time, about something that is worrying you</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>on bended knee</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> trying very hard to persuade someone to do something:</div><ul class=\"examples\"><li><em>He begged on bended knee for another chance.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> in a kneeling position:</div><ul class=\"examples\"><li><em>He went down on bended knee and asked her to marry him.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bend your mind/efforts to something</strong> <em>formal</em> to give all your energy or attention to one activity, plan etc</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>bend to somebody’s will</strong> <em>formal</em> to do what someone else wants, especially when you do not want to</div></div>","659":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧neath</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈniːθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in or to a lower position than something, or directly under something <em>SYN underneath</em>: ► see thesaurus at under RegisterIn everyday English, people usually use underneath (as an adverb or preposition) or under (as a preposition) when talking about position:· They hid under the table.· a picture with a caption underneath</div><ul class=\"examples\"><li><em>The dolphins disappeared beneath the waves.</em></li><li><em>Jo enjoyed feeling the warm sand beneath her feet.</em></li><li><em>He was standing on the bridge looking at the river beneath.</em></li><li><em>Some roofs collapsed beneath the weight of (=unable to support the weight of) so much snow.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> covered by something:</div><ul class=\"examples\"><li><em>Shiona shivered beneath the bedclothes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used to say that someone’s real character or feelings are not shown because their appearance or behaviour is different <em>SYN underneath</em>:</div><ul class=\"examples\"><li><em>Dave sensed that something more sinister lay beneath the woman’s cheerful exterior.</em></li><li><em>Beneath the surface she was angry.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> not good enough or suitable for someone:</div><ul class=\"examples\"><li><em>She acts as if even speaking to us is beneath her.</em></li><li><em>He felt it would be beneath his dignity to comment.</em></li><li><em>His mother felt he was marrying beneath him (=marrying someone who was not good enough).</em></li><li><em>I consider such behaviour to be beneath contempt (=so bad that you have no respect for the person involved).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> in a lower, less important rank or job than someone else <em>SYN below</em></div></div>","660":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ben‧e‧fi‧cial</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbenɪˈfɪʃəl◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\">having a good effect <em>OPP detrimental</em>:</div><ul class=\"examples\"><li><em>a drug that has a beneficial effect on the immune system</em></li><li><strong><em>beneficial to/for</strong>: Cycling is highly beneficial to health and the environment.</em></li><li><em>an arrangement that is mutually beneficial (=it has advantages for everyone who is involved)</em></li></ul></div>","661":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ben‧e‧fi‧cia‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbenəˈfɪʃəri $ -ˈfɪʃieri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural beneficiaries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who gets advantages from an action or change</div><ul class=\"examples\"><li><strong><em>beneficiary of</strong>: The rich were the main beneficiaries of the tax cuts.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who receives money or property from someone else who has died</div><ul class=\"examples\"><li><strong><em>beneficiary of</strong>: He was the chief beneficiary of his father’s will.</em></li></ul></div>","662":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ben‧e‧fit</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbenəfɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[advantage]</strong> <span class=\"gram\">[countable, uncountable]</span> an advantage, improvement, or help that you get from something → beneficial ► see thesaurus at advantage</div><ul class=\"examples\"><li><strong><em>benefit of</strong>: the benefits of contact lenses</em></li><li><em>I never had the benefit of a university education.</em></li><li><em>The new credit cards will be of great benefit to our customers.</em></li><li><em>I hope that the decision taken today will be to the benefit of the whole nation.</em></li><li><strong><em>for somebody’s benefit</strong>: Could you just explain again for Mark’s benefit?</em></li><li><strong><em>without the benefit of something</strong>: Most motorists manage without the benefit of four-wheel drive.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[money from government]</strong> <span class=\"gram\">[countable, uncountable]</span> <em>British English</em> money provided by the government to people who are sick, unemployed, or have little money SYN welfare<em>American English</em></div><ul class=\"examples\"><li><strong><em>unemployment/housing/child etc benefit</strong>: You might be entitled to housing benefit.</em></li><li><strong><em>on benefit</strong>: families on benefit</em></li><li><em>those people eligible to claim benefit</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[extra things]</strong> <span class=\"gram\">[countable usually plural]</span> extra money or other advantages that you get as part of your job or from insurance that you have → perk: → fringe benefit</div><ul class=\"examples\"><li><em>We offer an excellent benefits package.</em></li><li><em>medical benefits</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>give somebody the benefit of the doubt</strong> to accept what someone tells you, even though you think they may be wrong or lying but you cannot be sure:</div><ul class=\"examples\"><li><em>The referee gave him the benefit of the doubt.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>with the benefit of hindsight/experience</strong> used to say it is easier to know the right thing to do after something has happened or if you have a lot of experience:</div><ul class=\"examples\"><li><em>He admitted that, with the benefit of hindsight, the original launch had not been large enough.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>benefit concert/performance/match</strong> a concert, performance etc arranged to make money for charity:</div><ul class=\"examples\"><li><em>a benefit concert for famine relief</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span><span class=\"meta-item\">(past tense and past participle benefited, present participle benefiting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"gram\">[intransitive, transitive]</span> if you benefit from something, or it benefits you, it gives you an advantage, improves your life, or helps you in some way:</div><ul class=\"examples\"><li><em>They are working together to benefit the whole community.</em></li><li><strong><em>benefit from/by</strong>: Many thousands have benefited from the new treatment. / They would benefit by reducing their labour costs.</em></li><li><strong><em>benefit greatly/enormously/considerably etc</strong>: I’m sure you’ll benefit greatly from the visit.</em></li></ul></div></div>","663":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧nign</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈnaɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> kind and gentle:</div><ul class=\"examples\"><li><em>He shook his head in benign amusement.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a benign tumour (=unnatural growth in the body) is not caused by cancer <em>OPP malignant</em></div></div>","664":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ber‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈberi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural berries)</span></div><div class=\"entry-body\"><div class=\"sense\">a small soft fruit with small seeds</div></div>","665":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧side</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈsaɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> next to or very close to the side of someone or something: ► Do not confuse beside (=next to) and besides (=in addition to): He sat down beside Mary. | Who was there besides you?</div><ul class=\"examples\"><li><em>Wendy came up and sat beside me.</em></li><li><em>the table beside the bed</em></li><li><em>I was standing right beside her at the time.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in comparison with something or someone:</div><ul class=\"examples\"><li><em>This year’s sales figures don’t look very good beside last year’s results.</em></li><li><em>The children seemed tiny beside him.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be beside yourself</strong> to be feeling so angry, excited etc that you find it difficult to control yourself:</div><ul class=\"examples\"><li><em>The poor girl was almost beside herself.</em></li><li><strong><em>be beside yourself with anger/excitement/rage etc</strong>: Mom and Dad will be beside themselves with worry.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be beside the point</strong> to not be directly connected with the main subject or problem that you are talking about:</div><ul class=\"examples\"><li><em>He’s very charming, but that’s beside the point.</em></li></ul></div>","666":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧sides</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈsaɪdz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>spoken</em> used when adding another reason: RegisterIn written English, people do not usually use besides as a sentence adverb. They start a sentence with the more formal moreover instead:· Moreover, smoking is linked with heart disease and strokes.</div><ul class=\"examples\"><li><em>I need the money. And besides, when I agree to do something, I do it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in addition to someone or something else that you are mentioning:</div><ul class=\"examples\"><li><em>The area has stunning scenery, beautiful beaches, and much more besides.</em></li><li><em>People choose jobs for other reasons besides money.</em></li><li><em>Besides myself, the only English people there were Keith and Doreen.</em></li><li><strong><em>besides doing something</strong>: Besides being heartbroken, she felt foolish.</em></li></ul></div>","667":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /best/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[superlative of good]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> better than anything else or anyone else in quality, skill, how effective it is etc:</div><ul class=\"examples\"><li><em>He won the best actor award.</em></li><li><em>What’s the best way to cook this fish?</em></li><li><em>The best thing to do is to stop worrying.</em></li><li><strong><em>it’s best to do something</strong>: It’s best to go later in the season.</em></li><li><strong><em>easily the best/by far the best</strong> (=much better than anything else): John’s idea is by far the best option.</em></li><li><em>Our pilots are given the best possible training.</em></li><li><em>We use only the very best ingredients.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>best friend</strong> the friend that you know and like better than anyone else:</div><ul class=\"examples\"><li><em>She was my best friend in college.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>best dress/shoes/clothes etc</strong> clothing that you keep for special occasions:</div><ul class=\"examples\"><li><em>I put on my best suit for the wedding.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the next best thing</strong> something that is not exactly what you want but is as similar to it as possible:</div><ul class=\"examples\"><li><em>If sterile equipment isn’t available, the next best thing is to clean equipment with disinfectant.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>best of all</strong> used to introduce the fact about a situation that is even better than the other good things:</div><ul class=\"examples\"><li><em>It’s clean and well-located, but best of all, it’s affordable.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>best before</strong> <em>British English</em> written on food packets with the date that the food should be eaten before:</div><ul class=\"examples\"><li><em>Best before 13 July.</em></li><li><em>a best-before date</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[superlative of well]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a way that is better than any other:</div><ul class=\"examples\"><li><em>It works best if you let it warm up first.</em></li><li><em>This can best be described as a series of steps.</em></li><li><em>the best-dressed man in Paris</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to the greatest degree <em>SYN most</em>:</div><ul class=\"examples\"><li><em>You know him best – you should ask him.</em></li><li><em>The part I like best is the meal afterwards.</em></li><li><em>He’s perhaps best known for his role in ‘Midnight Cowboy’.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>as best you can</strong> <em>spoken</em> as well as you can, even if this is not very good:</div><ul class=\"examples\"><li><em>I’ll try and fix it as best I can.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>had best</strong> <em>spoken</em> ought to: → had better at better2(3)</div><ul class=\"examples\"><li><em>We’d best be getting back.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the best</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> the most helpful, most successful etc situation or results that you can achieve:</div><ul class=\"examples\"><li><em>We all want the best for our children.</em></li><li><em>It’s the best we can do in the circumstances.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the person or thing that is better than any other:</div><ul class=\"examples\"><li><em>She’s the best of the new young writers.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>do your best</strong> to try as hard as you can to do something:</div><ul class=\"examples\"><li><em>As long as you do your best, we’ll be happy.</em></li><li><strong><em>do your best to do something</strong>: She did her best to make him comfortable.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>at best</strong> used to emphasize that something is not very good, pleasant, honest etc even if you consider it in the best possible way:</div><ul class=\"examples\"><li><em>The campaign was at best only partially successful.</em></li><li><em>The technique is at best ineffective and at worst dangerous.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>to the best of your knowledge/belief/ability etc</strong> used to say that something is as much as you know, believe, or are able to do:</div><ul class=\"examples\"><li><em>I’m sure he’ll do the work to the best of his ability.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the best of something</strong> used to refer to something very good:</div><ul class=\"examples\"><li><em>We wish him the best of luck with this venture.</em></li><li><em>He hasn’t been in the best of health lately.</em></li><li><em>They didn’t part on the best of terms.</em></li><li><em>They became the best of friends (=very close friends).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>with the best of intentions/for the best of reasons</strong> used to mean that someone does something with good intentions or for good reasons, even if the result is not always good:</div><ul class=\"examples\"><li><em>I’m sure he went there with the best of intentions.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>the best of both worlds</strong> a situation in which you have the advantages of two different things without any of the disadvantages:</div><ul class=\"examples\"><li><em>They live in a village but it’s only an hour from London, so they have the best of both worlds.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>at your best</strong> performing as well or effectively as you are able to:</div><ul class=\"examples\"><li><em>At her best, she’s a really stylish player.</em></li><li><em>He was never at his best early in the morning.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>make the best of something</strong> (also make the best of a bad job/situation etc<em>British English</em>) to accept a situation that is not very good, and do whatever you can to make it better:</div><ul class=\"examples\"><li><em>We are stuck here, so we might as well make the best of it.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>all the best</strong> used to express good wishes to someone for the future:</div><ul class=\"examples\"><li><em>We’d just like to wish him all the best in his new job.</em></li><li><strong><em>best for</strong>: All the best for the New Year!</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>at the best of times</strong> if something is not very good, pleasant etc at the best of times, it is usually even worse than this:</div><ul class=\"examples\"><li><em>It’s crowded at the best of times, but today it was unbearable.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>the best of a bad lot/bunch</strong> <em>British English</em> the least bad person or thing in a group of not very good people or things</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>be for the best</strong> <em>especially spoken</em> used to say that a particular event may seem bad now, but might have a good result later:</div><ul class=\"examples\"><li><em>I still don’t want him to go, but maybe it’s for the best.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>your Sunday best</strong> <em>old-fashioned</em> your best clothes, that you only wear on special occasions</div></div></div>","668":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bet/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span><span class=\"meta-item\">(past tense and past participle bet, present participle betting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to risk money on the result of a race, game, competition, or other future event → gamble:</div><ul class=\"examples\"><li><em>How much do you want to bet?</em></li><li><strong><em>bet (somebody) that</strong>: He bet me £10 that I wouldn’t do it.</em></li><li><strong><em>bet (something) on something</strong>: She bet all her money on a horse that came last.</em></li><li><strong><em>bet against</strong>: I wouldn’t bet against him winning the championship this year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>I bet/I’ll bet</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that you are fairly sure that something is true, something is happening etc, although you cannot prove this:</div><ul class=\"examples\"><li><em>Bet you wish you’d arrived earlier.</em></li><li><em>I bet you she won’t come.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to show that you understand or can imagine the situation that someone has just told you about:</div><ul class=\"examples\"><li><em>‘God, I was so angry.’ ‘I bet you were.’</em></li><li><em>‘It makes things much easier.’ ‘Yeah, I’ll bet it does.’</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> used to show that you do not believe what someone has just told you:</div><ul class=\"examples\"><li><em>‘I’m definitely going to give up smoking this time.’ ‘Yeah, I bet!’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>you bet!</strong> <em>spoken</em> used to emphasize that you agree with someone or are keen to do what they suggest:</div><ul class=\"examples\"><li><em>‘Going to the party on Saturday?’ ‘You bet!’</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>(do you) want to bet?/wanna bet?</strong> <em>spoken</em> used to say that you think something that someone has just said is not true or not likely to happen:</div><ul class=\"examples\"><li><em>‘I’m sure Tom’ll be here soon.’ ‘Wanna bet?’</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>don’t bet on it/I wouldn’t bet on it</strong> <em>spoken</em> used to say that you do not think something is likely to happen:</div><ul class=\"examples\"><li><em>He said he’d finish by tomorrow, but I wouldn’t bet on it.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>you (can) bet your life/your bottom dollar</strong> <em>spoken</em> used when you are sure that you know what someone will do or what will happen:</div><ul class=\"examples\"><li><em>You can bet your bottom dollar he won’t be back.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bet the farm/ranch</strong> <em>American English</em> <em>informal</em> to risk everything that you own:</div><ul class=\"examples\"><li><em>Do we really want to bet the ranch on this deal?</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an agreement to risk money on the result of a race, game etc or on something happening, or the money that you risk:</div><ul class=\"examples\"><li><em>a £50 bet</em></li><li><strong><em>bet on</strong>: A few of us had a bet on who’d get married first.</em></li><li><strong><em>place/put/lay a bet</strong>: We placed bets on three horses.</em></li><li><em>Bookmakers are already taking bets on the outcome.</em></li><li><strong><em>win/lose a bet</strong>: If he scores now, I’ll win my bet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>your best bet</strong> <em>spoken</em> used when advising someone what to do:</div><ul class=\"examples\"><li><em>Your best bet is to put an advert in the local newspaper.</em></li><li><em>The train might be a better bet.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a good/safe bet</strong> an action or situation that is likely to be successful or does not involve much risk: → hedge your bets at hedge2(2)</div><ul class=\"examples\"><li><em>If you’re looking for long-term growth, the government’s own saving certificates are a pretty good bet.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>it’s a safe/sure/fair bet (that)</strong> <em>spoken</em> used to say that something seems almost certain:</div><ul class=\"examples\"><li><em>I think it’s a pretty safe bet that he’ll get the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>my bet</strong> <em>spoken</em> used when saying what you expect to happen in the future:</div><ul class=\"examples\"><li><em>My bet is he’ll be back this time next week.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>do something for a bet</strong> to do something stupid, dangerous etc to win money from someone or to prove that you can do it:</div><ul class=\"examples\"><li><em>He climbed the tree for a bet.</em></li></ul></div></div>","669":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧tray</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈtreɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[friends]</strong> to be disloyal to someone who trusts you, so that they are harmed or upset:</div><ul class=\"examples\"><li><em>He felt that she had betrayed him.</em></li><li><strong><em>betray somebody to somebody</strong>: What kind of man would betray his own sister to the police?</em></li><li><em>She had betrayed her parents&#x27; trust.</em></li><li><em>I would never betray a confidence (=tell a secret that someone has trusted me with).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[country]</strong> to be disloyal to your country, company etc, for example by giving secret information to its enemies:</div><ul class=\"examples\"><li><em>people who betray their country for money</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[emotions]</strong> to show feelings that you are trying to hide <em>SYN give away</em>:</div><ul class=\"examples\"><li><em>His voice betrayed his nervousness.</em></li><li><em>His face betrayed nothing (=showed no emotion).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[truth]</strong> to show that something is true or exists, especially when it is not easily noticed <em>SYN give away</em>:</div><ul class=\"examples\"><li><em>The slightest sound might betray his presence.</em></li><li><em>The crumpled sheets betrayed the fact that someone had been sleeping there.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>betray your beliefs/principles/ideals etc</strong> to stop supporting your old beliefs and principles, especially in order to get power or avoid trouble</div></div>","670":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧tray‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈtreɪəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">when you betray your country, friends, or someone who trusts you</div><ul class=\"examples\"><li><strong><em>betrayal of</strong>: a ruthless betrayal of their election pledges</em></li><li><em>She felt a great sense of betrayal.</em></li></ul></div>","671":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bet‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbetə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[comparative of good]</span> more useful, interesting, satisfactory, effective, suitable etc <em>OPP worse</em>: ► Better is a comparative form. Don’t say ‘more better’.</div><ul class=\"examples\"><li><em>Your stereo is better than mine.</em></li><li><em>There must be a better way to do this.</em></li><li><em>a better-quality car</em></li><li><strong><em>much/a lot/far better</strong>: We now have a much better understanding of the disease.</em></li><li><strong><em>better still/even better</strong>: It was even better than last year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[comparative of well]</span> ► see thesaurus at healthy</div><div class=\"subsense\"><span class=\"subnum\">a)</span> more healthy or less ill or painful than before <em>OPP worse</em>:</div><ul class=\"examples\"><li><em>She is a little better today, the doctor says.</em></li><li><em>I’m feeling much better, thank you.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> completely well again after an illness:</div><ul class=\"examples\"><li><em>When you’re better we can see about planning a trip.</em></li><li><em>I hope he gets better (=recovers from an illness) soon.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>it is better/it would be better</strong> used to give your opinion or make a suggestion about what you think should be done or happen</div><ul class=\"examples\"><li><strong><em>it is better to do something</strong>: It’s much better to get a proper written agreement.</em></li><li><strong><em>better if</strong>: It might be better if you stayed here.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>get better</strong> to improve:</div><ul class=\"examples\"><li><em>Her English isn’t really getting any better.</em></li><li><em>Things can only get better.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>no better</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> not better than something else or something before:</div><ul class=\"examples\"><li><em>The following day the weather was no better.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that something is the best</div><ul class=\"examples\"><li><strong><em>there is no better way/example/place etc</strong>: There’s no better way of exploring the region.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>nothing better</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that you really like something or think that something is very good</div><ul class=\"examples\"><li><strong><em>like/love/enjoy nothing better (than)</strong>: She likes nothing better than a nice long walk along the beach.</em></li><li><em>There’s nothing better than beating someone who’s playing well.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to say that a thing or situation is not very good, but is the only thing possible or available</div><ul class=\"examples\"><li><strong><em>have nothing better to do</strong>: Have you got nothing better to do than sit there playing that silly game?</em></li><li><em>I only picked it up because there was nothing better to read.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>that’s better</strong> <em>spoken</em> used to say that something has improved, that you are happier or more comfortable, or to encourage someone:</div><ul class=\"examples\"><li><em>Ah, that’s better. I needed to sit down.</em></li><li><em>‘Can you turn it down?’ ‘Is that better?’</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>better late than never</strong> <em>spoken</em> used to say that it is better for someone or something to be late than never to arrive or happen at all</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[comparative of well]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to a higher standard or quality <em>OPP worse</em>: → fare better at fare2</div><ul class=\"examples\"><li><em>He can speak French a lot better than I can.</em></li><li><em>Your bike will run better if you oil it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to a higher degree <em>SYN more</em>:</div><ul class=\"examples\"><li><em>She knows this town better than you do.</em></li><li><em>I think I like the red one better.</em></li><li><em>Potter is better known for his TV work.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>had better</strong> ► In speech, people usually shorten had to ’d, and may not pronounce it at all. But do not leave out had or ’d in writing: You’d better (NOT You better) come here!</div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to give advice about what someone should do, or to say what you should do or need to do:</div><ul class=\"examples\"><li><em>I’d better go and get ready.</em></li><li><em>I think you’d better ask Jo first.</em></li><li><em>You had better not tell Oliver (=it is not a good idea).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used to threaten someone:</div><ul class=\"examples\"><li><em>You’d better keep your mouth shut about this.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>do better</strong> to perform better or reach a higher standard:</div><ul class=\"examples\"><li><em>We did better than all the other schools.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the sooner the better/the bigger the better etc</strong> used to emphasize that you would prefer something to happen as soon as possible, want something to be as big as possible etc:</div><ul class=\"examples\"><li><em>School finishes at the end of the week, and the sooner the better as far as I’m concerned.</em></li><li><em>The younger you start learning a language, the better you’ll speak it.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>go one better (than somebody)</strong> <em>informal</em> to do something more successfully than someone else:</div><ul class=\"examples\"><li><em>The following year Lewis went one better by winning the gold medal.</em></li><li><em>Of course, they had to go one better and have the whole garden redesigned.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the better</strong> the one that is higher in quality, more suitable etc when you are comparing two similar people or things:</div><ul class=\"examples\"><li><em>It’s hard to decide which one’s the better.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>get the better of somebody</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if your feelings or wishes get the better of you, they make you behave in a way you would not normally behave:</div><ul class=\"examples\"><li><em>My curiosity finally got the better of me and I opened the letter.</em></li><li><em>I think her nerves got the better of her.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to defeat someone or deal successfully with a problem</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>for the better</strong> in a way that improves the situation:</div><ul class=\"examples\"><li><em>a definite change for the better</em></li><li><em>The president’s fortunes seem, at last, to have taken a turn for the better (=started to improve).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>so much the better</strong> used to say that something would be even better or bring even more advantages:</div><ul class=\"examples\"><li><em>If they can do them both at the same time, then so much the better.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be all the better for something</strong> to be improved by a particular action, change etc:</div><ul class=\"examples\"><li><em>I think it’s all the better for that extra ten minutes’ cooking.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>for better or (for) worse</strong> used to say that something must be accepted, whether it is good or bad, because it cannot be changed:</div><ul class=\"examples\"><li><em>Work is, for better or worse, becoming more flexible nowadays.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>your betters</strong> <em>old-fashioned</em> people who are more important than you or deserve more respect</div></div></div>","672":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧tween</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈtwiːn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also in between) in or through the space that separates two things, people, or places:</div><ul class=\"examples\"><li><em>I sat down between Sue and Jane.</em></li><li><em>a house and stables, with a yard in between</em></li><li><em>The ball rolled between his feet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also in between) in the time that separates two times or events:</div><ul class=\"examples\"><li><em>Are there any public holidays between Christmas and Easter?</em></li><li><em>You shouldn’t eat between meals.</em></li><li><em>The team have a lot of work to do between now and Sunday.</em></li><li><em>A lot of students spend a year abroad in between school and university.</em></li><li><em>I’ve had a few jobs, with long periods of unemployment in between.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> within a range of amounts, numbers, distances etc:</div><ul class=\"examples\"><li><em>The project will cost between eight and ten million dollars.</em></li><li><em>Most of the victims were young men between the ages of 16 and 21.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> used to say which two places are joined or connected by something:</div><ul class=\"examples\"><li><em>They’re building a new road between Manchester and Sheffield.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to say which people or things are involved in something together or are connected:</div><ul class=\"examples\"><li><em>the long-standing friendship between Bob and Bryan</em></li><li><em>co-operation between the two countries</em></li><li><em>She had overheard a private conversation between two MPs.</em></li><li><em>the link between serious sunburn and deadly skin cancer</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> used to say which people or things get, have, or are involved in something that is shared:</div><ul class=\"examples\"><li><em>Tom divided his money between his children.</em></li><li><em>Between the four of them they managed to lift her into the ambulance.</em></li><li><em>We collected £17 between us.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to say which two things or people you are comparing:</div><ul class=\"examples\"><li><em>the contrast between town and country life</em></li><li><em>In her book she makes a comparison between Russian and British ballet.</em></li><li><em>the difference between good music and really great music</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>between you and me</strong> (also between ourselves) <em>spoken</em> used before telling someone something that you do not want them to tell anyone else:</div><ul class=\"examples\"><li><em>Between you and me, I think Schmidt’s about to resign.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>come between somebody</strong> if something comes between two people, it causes an argument or problems between them:</div><ul class=\"examples\"><li><em>I let my stupid pride come between us.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> used when it is difficult to give an exact description of something and you therefore have to compare it to two things that are similar to it:</div><ul class=\"examples\"><li><em>He uttered a sound that was something between a sigh and a groan.</em></li></ul></div>","673":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bev‧er‧age</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbevərɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>formal</em> a hot or cold drink: ► see thesaurus at drink</div><ul class=\"examples\"><li><em>alcoholic beverages</em></li><li><em>the Food and Beverage Manager</em></li></ul></div>","674":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧ware</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈweə $ -ˈwer/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive only in imperative and infinitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">used to warn someone to be careful because something is dangerous</div><ul class=\"examples\"><li><strong><em>beware of</strong>: Beware of the dog!</em></li><li><strong><em>beware of doing something</strong>: They should beware of making hasty decisions.</em></li><li><em>Police warned drivers to beware.</em></li></ul></div>","675":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧wil‧dered</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈwɪldəd $ -ərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">totally confused: ► see thesaurus at confused</div><ul class=\"examples\"><li><em>a bewildered expression on his face</em></li></ul></div>","676":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧wil‧der‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈwɪldərɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">confusing, especially because there are too many choices or things happening at the same time</div><ul class=\"examples\"><li><strong><em>a bewildering variety/array/range</strong>: a bewildering variety of choices</em></li></ul></div>","677":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> be‧yond</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈjɒnd $ -ˈjɑːnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> on or to the further side of something:</div><ul class=\"examples\"><li><em>They crossed the mountains and headed for the valleys beyond.</em></li><li><em>Beyond the river, cattle were grazing.</em></li><li><em>She drove through Westport, and stopped a few miles beyond at a wayside inn.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> later than a particular time, date etc <em>SYN after</em>:</div><ul class=\"examples\"><li><em>What changes await us in the coming year and beyond?</em></li><li><em>The ban has been extended beyond 2003.</em></li><li><em>The disco went on until beyond midnight.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> more or greater than a particular amount, level, or limit:</div><ul class=\"examples\"><li><em>More people are choosing to work beyond retirement age.</em></li><li><em>Inflation has risen beyond the 5% level.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> outside the range or limits of something or someone:</div><ul class=\"examples\"><li><em>Such tasks are far beyond the scope of the average schoolkid.</em></li><li><em>expensive luxuries that are beyond the reach of ordinary people</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> used to say that something is impossible to do</div><ul class=\"examples\"><li><strong><em>beyond repair/control/belief etc</strong> (=impossible to repair, control, believe etc): Scott’s equipment was damaged beyond repair. / The town centre had changed beyond all recognition. / Due to circumstances beyond our control, the performance has had to be cancelled.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be beyond somebody</strong> to be too difficult for someone to understand:</div><ul class=\"examples\"><li><em>The whole problem was quite beyond him.</em></li><li><em>Why Joan ever married such an idiot in the first place is beyond me.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> used to mean ‘except’ in negative sentences:</div><ul class=\"examples\"><li><em>Fred owns nothing beyond the clothes on his back.</em></li></ul></div>","678":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧as</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbaɪəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular, uncountable]</span> an opinion about whether a person, group, or idea is good or bad that influences how you deal with it → discrimination</div><ul class=\"examples\"><li><strong><em>political/gender/racial etc bias</strong>: political bias in the press</em></li><li><em>Students were evaluated without bias.</em></li><li><strong><em>bias against/towards/in favour of</strong>: It’s clear that the company has a bias against women and minorities.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a natural skill or interest in one type of thing:</div><ul class=\"examples\"><li><em>Lydia has a strong artistic bias.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>on the bias</strong> in a diagonal direction</div></div>","679":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧ased</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbaɪəst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unfairly preferring one person or group over another:</div><ul class=\"examples\"><li><em>Of course I’m biased, but I thought my daughter’s paintings were the best.</em></li><li><em>racially biased attitudes</em></li><li><strong><em>biased against/towards/in favour of</strong>: news reporting that was heavily biased towards the government</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> more interested in a particular thing than in another</div><ul class=\"examples\"><li><strong><em>biased towards</strong>: The majority of infants are biased towards being social rather than being antisocial.</em></li></ul></div>","680":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bib‧li‧og‧ra‧phy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbɪbliˈɒɡrəfi $ -ˈɑːɡ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural bibliographies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a list of all the books and articles used in preparing a piece of writing</div><div class=\"sense\"><span class=\"snum\">2</span> a list of books and articles that are all about a particular subject</div></div>","681":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧cy‧cle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbaɪsɪkəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a vehicle with two wheels that you ride by pushing its pedals with your feet <em>SYN bike</em>: → exercise bike</div><ul class=\"examples\"><li><em>Can James ride a bicycle yet?</em></li></ul></div>","682":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an offer to pay a particular price for something, especially at an auction</div><ul class=\"examples\"><li><strong><em>bid for</strong>: They put in a bid for the house.</em></li><li><em>the person who places the highest bid</em></li><li><em>We’ve made a bid of nearly £400 million for the company.</em></li><li><em>A takeover bid for the airline was launched today.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an offer to do work or provide services for a specific price</div><ul class=\"examples\"><li><strong><em>bid for</strong>: rival bids for the cleaning contract</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an attempt to achieve or obtain something</div><ul class=\"examples\"><li><strong><em>bid for</strong>: a bid for power</em></li><li><strong><em>a bid to do something</strong>: a desperate bid to free herself from a loveless marriage</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a statement of how many points you hope to win in a card game</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle bid, present participle bidding)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to offer to pay a particular price for goods, especially in an auction</div><ul class=\"examples\"><li><strong><em>bid (somebody) something for something</strong>: She bid £100 for a Victorian chair. / What am I bid for lot 227? Shall we start at $500?</em></li><li><strong><em>bid against</strong>: The two men ended up bidding against each other at the auction.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> to offer to do work or provide services for a specific price, in competition with other offers</div><ul class=\"examples\"><li><strong><em>bid for</strong>: Three firms bid for the contract on the new buildings.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to say how many points you think you will win in a game of cards</div></div></div>","683":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bid‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪdə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who offers to pay a particular amount of money for something that is being sold:</div><ul class=\"examples\"><li><em>The antiques will be sold to the highest bidder (=the person who offers to pay the most).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone who offers to do work or provide services for a particular amount of money, in competition with others:</div><ul class=\"examples\"><li><em>one of 13 bidders for the contract</em></li></ul></div>","684":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative bigger, superlative biggest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[size]</strong> of more than average size or amount: ► see thesaurus at fat</div><ul class=\"examples\"><li><em>a big house</em></li><li><em>I need a bigger desk.</em></li><li><em>She had a big grin on her face.</em></li><li><em>a big increase in crime</em></li><li><em>Los Angeles is the biggest city in California.</em></li><li><em>The garage isn’t big enough for two cars.</em></li><li><em>When they lose, they lose in a big way (=to a large degree).</em></li><li><em>There was this great big (=extremely big) spider in the sink.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[important]</strong> important and serious: ► see thesaurus at important</div><ul class=\"examples\"><li><em>a big decision</em></li><li><em>Buying your own house is a big commitment.</em></li><li><em>The big game is on Friday.</em></li><li><em>There’s a big difference between understanding something and being able to explain it to others.</em></li><li><em>Everyone was getting ready for the big day (=a day when an important event will happen).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[popular/successful]</strong> successful or popular, especially in business or entertainment: → big cheese, big noise, → big shot at shot1(14), → big time1</div><ul class=\"examples\"><li><em>Julia Roberts became a big star.</em></li><li><em>She’s very big in Australia.</em></li><li><em>After years as a small-time actor, he suddenly made it big (=became very successful) in Hollywood.</em></li><li><strong><em>the big boys</strong> (=the most powerful people or companies)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[older]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>big sister/brother</strong> your older sister or brother</div><div class=\"subsense\"><span class=\"subnum\">b)</span> older or more like an adult – used especially by children or when you are talking to children:</div><ul class=\"examples\"><li><em>Come on, don’t cry. You’re a big girl now.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[large degree]</strong> <span class=\"gram\">[only before noun]</span> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> doing something to a large degree</div><ul class=\"examples\"><li><strong><em>a big eater/drinker/spender etc</strong>: Des is a big gambler, you know.</em></li><li><strong><em>be a big fan/admirer of somebody/something</em></strong></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> done to a large degree or with great energy</div><ul class=\"examples\"><li><strong><em>give somebody a big hug/kiss</strong>: Mama gave me a big hug.</em></li><li><strong><em>give somebody a big hand</strong> (=hit your hands together with enthusiasm, to show you have enjoyed a performance)</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[bad]</strong> <span class=\"gram\">[only before noun]</span> <em>informal</em> used to emphasize how bad something is:</div><ul class=\"examples\"><li><em>AIDS remains a big problem in many parts of the world.</em></li><li><em>Buying that house was a big mistake.</em></li><li><em>I never said that, you big liar!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>have big ideas/plans</strong> to have impressive plans for the future:</div><ul class=\"examples\"><li><em>I’ve got big plans for this place.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be big on something</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to like something very much:</div><ul class=\"examples\"><li><em>I’m not big on kids.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have a lot of a quality or feature:</div><ul class=\"examples\"><li><em>The new BMW is big on safety features.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>what’s the big idea?</strong> <em>spoken</em> used when someone has done something annoying, especially when you want them to explain why they did it:</div><ul class=\"examples\"><li><em>Hey, what’s the big idea? Who said you could use my computer?</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[generous]</strong> <strong>it is big of somebody to do something</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used to say that someone is very kind or generous to do something</div><div class=\"subsense\"><span class=\"subnum\">b)</span> used when you really think that someone is not kind or helpful at all:</div><ul class=\"examples\"><li><em>£5! That was big of her!</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>big mouth</strong> <em>spoken</em> someone who has a big mouth cannot be trusted to keep things secret: → bigmouth</div><ul class=\"examples\"><li><em>I’m sorry. I shouldn’t have opened my big mouth.</em></li><li><strong><em>me and my big mouth</strong> (=said when you wish you had not told someone a secret)</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[letters]</strong> <em>informal</em> big letters are capitals, for example G, R, A etc</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>[words]</strong> <em>informal</em> big words are long or unusual and are difficult to read or understand</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>be/get too big for your boots</strong> <em>informal</em> to be too proud of yourself</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>use/wield the big stick</strong> <em>informal</em> to threaten to use your power to get what you want</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>a big girl’s blouse</strong> <em>British English</em> <em>informal</em> someone, especially a man, who is not brave</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>big up (to/for) somebody</strong> <em>spoken</em> <em>informal</em> used when you want to praise someone:</div><ul class=\"examples\"><li><em>Big up to Kelly Holmes! She ran a superb race.</em></li></ul></div>","685":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> big-head‧ed</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbɪɡˈhedɪd◂/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><em>informal</em> someone who is big-headed thinks they are very important, clever etc – used to show disapproval <em>OPP modest</em> ► see thesaurus at proud</div></div>","686":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a bicycle:</div><ul class=\"examples\"><li><em>Let’s go for a bike ride.</em></li><li><strong><em>by bike</strong>: They’ll be coming by bike.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> a motorcycle</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>on your bike!</strong> <em>British English</em> <em>spoken</em> used to tell someone rudely to go away</div></div>","687":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧ki‧ni</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈkiːni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a set of clothes worn by women for swimming, which consists of a top part covering the breasts, and a bottom part</div></div>","688":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧lat‧er‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /baɪˈlætərəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">involving two groups or nations</div><ul class=\"examples\"><li><strong><em>bilateral relations/trade/agreements/negotiations etc</strong>: bilateral negotiations between Israel and Syria</em></li></ul></div>","689":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧lin‧gual</span><span class=\"meta-item\"><strong>IPA:</strong> /baɪˈlɪŋɡwəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> written or spoken in two languages:</div><ul class=\"examples\"><li><em>a bilingual dictionary</em></li><li><em>The report proposed bilingual education in schools.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> able to speak two languages equally well:</div><ul class=\"examples\"><li><em>Their kids are bilingual.</em></li><li><strong><em>bilingual in</strong>: Louis is virtually bilingual in Dutch and German.</em></li></ul></div>","690":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[request for payment]</strong> a written list showing how much you have to pay for services you have received, work that has been done etc</div><ul class=\"examples\"><li><strong><em>bill for</strong>: The bill for the repairs came to $650.</em></li><li><em>Have you paid the phone bill?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[restaurant]</strong> <em>especially British English</em> a list showing how much you have to pay for food you have eaten in a restaurant SYN check<em>American English</em>:</div><ul class=\"examples\"><li><em>Could we have the bill, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[law]</strong> a written proposal for a new law, that is brought to a parliament so that it can be discussed</div><ul class=\"examples\"><li><strong><em>approve/pass/veto a bill</strong>: The House of Representatives passed a new gun-control bill.</em></li><li><em>The senator introduced a bill that would increase the minimum wage.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[money]</strong> <em>American English</em> a piece of paper money SYN note<em>British English</em> → coin:</div><ul class=\"examples\"><li><em>a five-dollar bill</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>fit/fill the bill</strong> to be exactly what you need:</div><ul class=\"examples\"><li><em>This car fits the bill perfectly. It’s cheap and gets good mileage.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[concert/show etc]</strong> a programme of entertainment at a theatre, concert, cinema etc, with details of who is performing, what is being shown etc:</div><ul class=\"examples\"><li><em>Tricia topped the bill (=was the most important performer) at the Children’s Variety Show.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>give somebody/something a clean bill of health</strong> to officially state that someone is in good health or that something is working correctly:</div><ul class=\"examples\"><li><em>Maddox was given a clean bill of health.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[bird]</strong> a bird’s beak</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[advertisement]</strong> a printed notice advertising an event</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[part of a hat]</strong> <em>American English</em> the front part that sticks out on a hat such as a baseball cap</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>the (old) bill</strong> <em>British English</em> <em>spoken</em> the police</div></div>","691":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bil‧lion</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪljən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W2</span><span class=\"meta-item\">(plural billion or billions)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the number 1,000,000,000:</div><ul class=\"examples\"><li><em>The final cost could be as much as one billion dollars.</em></li><li><strong><em>two/three/four etc billion</strong>: 3.5 billion years ago / Overseas debt is a staggering £16 billion.</em></li><li><strong><em>billions of pounds/dollars etc</strong>: Airlines have lost billions of dollars.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an extremely large number of things or people</div><ul class=\"examples\"><li><strong><em>a billion</strong>: A billion stars shone in the night sky.</em></li><li><strong><em>billions of something</strong>: There are billions of things I want to say.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>old use</em> the number 1,000,000,000,000</div></div>","692":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a container for putting waste in → trash can, waste paper basket: → dustbin, litter bin</div><ul class=\"examples\"><li><em>Throw it in the bin.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a large container for storing things, such as goods in a shop or substances in a factory</div></div>","693":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle bound /baʊnd/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[tie/fasten]</strong> <span class=\"gram\">[transitive]</span> <em>written</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to tie someone so that they cannot move or escape:</div><ul class=\"examples\"><li><em>They bound my arms and legs with rope.</em></li><li><strong><em>bound and gagged</strong> (=tied up, and with cloth tied around your mouth so you cannot speak)</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> (also bind up) to tie things firmly together with cloth or string:</div><ul class=\"examples\"><li><em>The pile of newspapers was bound with string.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[form a connection]</strong> <span class=\"gram\">[transitive]</span> to form a strong emotional or economic connection between two people, countries etc <em>SYN unite</em></div><ul class=\"examples\"><li><strong><em>bind somebody/something together</strong>: Their shared experiences in war helped to bind the two communities together.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[make somebody do something]</strong> <span class=\"gram\">[transitive]</span> if you are bound by an agreement, promise etc, you must do what you have agreed to do or promised to do GRAMMAR Bind is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be bound by something</strong>: The monks are bound by vows of silence.</em></li><li><strong><em>be bound to do something</strong>: Employees are not bound to give their reasons for leaving.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[stick together]</strong> <span class=\"gram\">[intransitive, transitive]</span> <em>technical</em> to stick together in a mass, or to make small pieces of something stick together:</div><ul class=\"examples\"><li><em>The flour mixture isn’t wet enough to bind properly.</em></li><li><strong><em>bind with</strong>: The hydrogen molecule binds with the oxygen molecule.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[book]</strong> <span class=\"gram\">[transitive]</span> to fasten the pages of a book together and put them in a cover → bound2(9)</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[stitch]</strong> <span class=\"gram\">[transitive]</span> to sew cloth over the edge of a piece of material, or stitch over it, to strengthen it:</div><ul class=\"examples\"><li><em>The edges of the blanket were bound with ribbon.</em></li></ul></div>","694":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧noc‧u‧lars</span><span class=\"meta-item\"><strong>IPA:</strong> /bɪˈnɒkjələz, baɪ- $ -ˈnɑːkjələrz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a pair of special glasses, that you hold up to your eyes to look at objects that are a long distance away <em>SYN field glasses</em></div></div>","695":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧og‧ra‧phy</span><span class=\"meta-item\"><strong>IPA:</strong> /baɪˈɒɡrəfi $ -ˈɑːɡ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural biographies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a book that tells what has happened in someone’s life, written by someone else ► see thesaurus at book</div><ul class=\"examples\"><li><strong><em>biography of</strong>: Boswell’s biography of Samuel Johnson</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> literature that consists of biographies → autobiography</div></div>","696":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧o‧lo‧gi‧cal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbaɪəˈlɒdʒɪkəl◂ $ -ˈlɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> relating to the natural processes performed by living things:</div><ul class=\"examples\"><li><em>the biological functions of the body</em></li><li><em>Depression is both biological and psychological.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>biological weapons/warfare/attack etc</strong> weapons, attacks etc that involve the use of living things, including bacteria, to harm other living things:</div><ul class=\"examples\"><li><em>a ban on chemical and biological weapons</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> relating to biology:</div><ul class=\"examples\"><li><em>the biological sciences</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>biological parent/father/mother etc</strong> a child’s parent through birth, rather than through adoption</div></div>","697":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧ol‧o‧gist</span><span class=\"meta-item\"><strong>IPA:</strong> /baɪˈɒlədʒɪst $ -ˈɑːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who studies or works in biology</div></div>","698":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧ol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /baɪˈɒlədʒi $ -ˈɑːl-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the scientific study of living things:</div><ul class=\"examples\"><li><em>a degree in biology</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the scientific laws that control the life of a particular type of animal, plant etc:</div><ul class=\"examples\"><li><em>the biology of bacteria</em></li></ul></div>","699":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧o‧tech‧nol‧o‧gy</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbaɪəʊtekˈnɒlədʒi $ ˌbaɪoʊtekˈnɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the use of living things such as cells, bacteria etc to make drugs, destroy waste matter etc:</div><ul class=\"examples\"><li><em>the biotech industries</em></li></ul></div>","700":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɜːd $ bɜːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a creature with wings and feathers that can usually fly. Many birds sing and build nests, and female birds lay eggs:</div><ul class=\"examples\"><li><em>wild birds</em></li><li><em>The dawn was filled with the sound of birds.</em></li><li><em>a flock of birds (=a group of birds flying together)</em></li><li><em>a wooden bird cage</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> <em>informal</em> <em>not polite</em> a word meaning a young woman, which some people think is offensive</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the birds and the bees</strong> the facts about sex – used humorously or to children</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a little bird told me (something)</strong> <em>informal</em> used to say that you know something, but you will not say how you found out:</div><ul class=\"examples\"><li><em>A little bird told me that you’ve got engaged.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>birds of a feather (flock together)</strong> <em>informal</em> used to say that two or more people have similar attitudes, beliefs etc</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>give somebody the bird</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>American English</em> <em>informal</em> to make a very rude sign at someone by holding your middle finger up</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> to show strong disapproval of someone who is performing or speaking in public, by shouting, making rude noises etc</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>a bird in the hand (is worth two in the bush)</strong> used to say that it is better to keep what you have than to risk losing it by trying to get more</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>the bird has flown</strong> <em>informal</em> used to say that the person you are looking for has already left or escaped</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>be (strictly) for the birds</strong> <em>old-fashioned</em> <em>informal</em> to be silly, useless, or not practical</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>wise/wily/funny/weird etc old bird</strong> <em>old-fashioned</em> <em>informal</em> a person who seems wise, funny etc</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>do bird</strong> <em>British English</em> <em>old-fashioned</em> <em>informal</em> to serve a prison sentence <em>SYN do time</em></div></div>","701":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɜːθ $ bɜːrθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>give birth (to somebody)</strong> if a woman gives birth, she produces a baby from her body:</div><ul class=\"examples\"><li><em>Patsy was celebrating last night after giving birth to twins.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the time when a baby comes out of its mother’s body:</div><ul class=\"examples\"><li><em>Congratulations on the birth of your daughter!</em></li><li><em>He only weighed 2 kilos at birth.</em></li><li><em>Henry has been blind from birth.</em></li><li><em>What’s your date of birth?</em></li><li><em>The exact place of birth is not recorded.</em></li><li><em>They believe that the position of the planets at the time of birth determines the fate of the individual.</em></li><li><em>More and more women are choosing to have home births.</em></li><li><em>Smoking in pregnancy has been linked to premature birth.</em></li><li><em>the association between birth weight and blood pressure</em></li><li><em>The drug was found to cause serious birth defects.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> the time when something new starts to exist ► see thesaurus at beginning</div><ul class=\"examples\"><li><strong><em>birth of</strong>: the birth of a nation</em></li><li><em>The film gave birth to a TV show of the same name.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[uncountable]</span> the character, language, social position etc that you have because of the family or country you come from:</div><ul class=\"examples\"><li><em>a woman of noble birth</em></li><li><strong><em>French/German etc by birth</em></strong></li></ul></div>","702":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> birth‧day</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɜːθdeɪ $ ˈbɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> your birthday is a day that is an exact number of years after the day you were born:</div><ul class=\"examples\"><li><em>It’s my birthday on Monday.</em></li><li><em>My aunt called to wish me a happy birthday.</em></li><li><em>Anne’s birthday party</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a day that is an exact number of years since an organization was established or an event first happened → anniversary:</div><ul class=\"examples\"><li><em>The City of Cleveland Orchestra is celebrating its 200th birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in your birthday suit</strong> <em>informal</em> not wearing any clothes – used humorously</div></div>","703":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bis‧cuit</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪskɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> <em>British English</em> a small thin dry cake that is usually sweet and made for one person to eat SYN cookie<em>American English</em>:</div><ul class=\"examples\"><li><em>a packet of chocolate biscuits</em></li><li><em>cheese and biscuits</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>American English</em> a type of soft bread baked in small round pieces</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> a light brown colour</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>take the biscuit</strong> <em>British English</em> <em>informal</em> to be the most surprising, annoying etc thing you have ever heard <em>SYN take the cake</em> <em>especially American English</em>:</div><ul class=\"examples\"><li><em>I’ve heard some excuses, but this really takes the biscuit!</em></li></ul></div>","704":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[only slightly]</strong> <strong>a bit</strong> <em>especially British English</em> RegisterIn written English, people usually avoid a (little) bit and use slightly, rather, or somewhat instead:· This system is slightly more efficient.· The final cost was somewhat higher than expected.</div><div class=\"subsense\"><span class=\"subnum\">a)</span> slightly or to a small degree <em>SYN a little</em>:</div><ul class=\"examples\"><li><em>Could you turn the TV up a bit?</em></li><li><em>That’s a bit odd.</em></li><li><em>‘Are you sorry to be leaving?’ ‘Yes, I am a bit.’</em></li><li><em>Aren’t you being a little bit unfair?</em></li><li><em>I think you’re a bit too young to be watching this.</em></li><li><em>She looks a bit like my sister.</em></li><li><strong><em>a bit better/older/easier etc</strong>: I feel a bit better now.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> sometimes, but not very often:</div><ul class=\"examples\"><li><em>I used to act a bit when I was younger.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[amount]</strong> <strong>a bit</strong> <em>especially British English</em> <em>informal</em> a small amount of a substance or of something that is not a physical object <em>SYN a little</em></div><ul class=\"examples\"><li><strong><em>bit of</strong>: I may need a bit of help. / He still likes to do a bit of gardening. / I want to spend a bit of time with him before he goes. / With a bit of luck, we should have finished by five o’clock.</em></li><li><em>Everyone needs a little bit of encouragement.</em></li><li><em>‘Would you like cream in your coffee?’ ‘Yes please, just a bit.’</em></li><li><strong><em>a bit more/less</strong>: Can we have a bit less noise, please?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[quite a lot]</strong> <strong>quite a bit</strong> (also a good bit<em>British English</em>) a fairly large amount or to a fairly large degree:</div><ul class=\"examples\"><li><em>She’s quite a bit older than you, isn’t she?</em></li><li><em>He knows quite a bit about painting.</em></li><li><strong><em>bit of</strong>: I expect you do quite a bit of travelling?</em></li><li><strong><em>quite a bit more/less</strong>: They’re worth quite a bit more than I thought.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[time/distance]</strong> <strong>a bit</strong> <em>especially British English</em> a short period of time or a short distance <em>SYN a while</em>:</div><ul class=\"examples\"><li><em>You’ll have to wait a bit.</em></li><li><em>I walked on a bit.</em></li><li><strong><em>in a bit</strong>: I’ll see you in a bit.</em></li><li><strong><em>for a bit</strong>: We sat around for a bit, chatting.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>a bit of a something</strong> <em>especially British English</em> used to show that the way you describe something is only true to a limited degree:</div><ul class=\"examples\"><li><em>The news came as a bit of a shock.</em></li><li><em>I felt a bit of a fool.</em></li><li><em>It looks like they left in a bit of a hurry.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not a bit/not one bit</strong> <em>especially British English</em> not at all:</div><ul class=\"examples\"><li><em>You’re not a bit like your brother.</em></li><li><em>Am I cross? No, not a bit of it.</em></li><li><em>I’m not in the least bit interested in whose fault it is.</em></li><li><em>Well, you haven’t surprised me, not one bit.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>every bit as important/bad/good etc</strong> <em>especially British English</em> used to emphasize that something is equally important, bad etc as something else:</div><ul class=\"examples\"><li><em>Jodi plays every bit as well as the men.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>bit by bit</strong> <em>especially British English</em> gradually:</div><ul class=\"examples\"><li><em>Bit by bit, I was starting to change my mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a/one bit at a time</strong> <em>especially British English</em> in several small parts or stages:</div><ul class=\"examples\"><li><em>Memorize it a bit at a time.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>take a bit of doing/explaining etc</strong> <em>British English</em> to be difficult to do, explain etc:</div><ul class=\"examples\"><li><em>The new system took a bit of getting used to.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be a bit much</strong> <em>British English</em> to be unacceptable, impolite, or unfair:</div><ul class=\"examples\"><li><em>It’s a bit much when he criticizes us for doing something that he does himself.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>be a bit of all right</strong> <em>British English</em> <em>informal</em> used to say that someone is sexually attractive</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>bit on the side</strong> <em>British English</em> <em>informal</em> someone’s bit on the side is a person they are having a sexual relationship with, even though they already have a wife, husband, or partner – used humorously or to show disapproval:</div><ul class=\"examples\"><li><em>She stayed, in the hope that he’d tire of his bit on the side.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>a bit of stuff/fluff/skirt</strong> <em>British English</em> <em>informal</em> <em>not polite</em> offensive expressions meaning a young woman, especially one who is sexually attractive</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>a bit of rough</strong> <em>British English</em> <em>informal</em> someone of a lower social class that someone has a sexual relationship with – used humorously</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[piece]</strong> a small piece of something ► see thesaurus at piece</div><ul class=\"examples\"><li><strong><em>bit of</strong>: bits of broken glass / He wedged the door open with a bit of wood.</em></li><li><strong><em>break/rip/shake etc something to bits</strong>: The aircraft was blown to bits.</em></li><li><em>He’s taken the engine to bits.</em></li><li><strong><em>fall/come to bits</strong>: The old house was falling to bits.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[part]</strong> <em>British English</em> <em>informal</em> a part of something larger: ► see thesaurus at part</div><ul class=\"examples\"><li><em>This is the boring bit.</em></li><li><strong><em>bit of</strong>: We did the last bit of the journey on foot.</em></li><li><strong><em>bit about</strong>: Did you like the bit about the monkey?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>to bits</strong> <em>British English</em> <em>informal</em> very much or extremely:</div><ul class=\"examples\"><li><em>Mark’s a darling – I love him to bits.</em></li><li><strong><em>thrilled/chuffed/pleased to bits</strong>: I’ve always wanted a car, so I’m thrilled to bits.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[computer]</strong> the smallest unit of information that a computer uses:</div><ul class=\"examples\"><li><em>a 32-bit processor</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[tool]</strong> the sharp part of a tool for cutting or making holes:</div><ul class=\"examples\"><li><em>a drill bit</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[horse]</strong> the metal bar attached to a horse’s bridle that is put into its mouth and used to control it → be champing at the bit at champ1(2)</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>bits and pieces</strong> (also bits and bobs<em>British English</em>) <em>informal</em> any small things of various kinds:</div><ul class=\"examples\"><li><em>Let me get all my bits and pieces together.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>do your bit</strong> <em>informal</em> to do a fair share of the work, effort etc that is needed to achieve something good or important:</div><ul class=\"examples\"><li><em>Everyone should do their bit for the environment.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>get the bit between your teeth</strong> <em>British English</em>, take the bit between your teeth<em>American English</em> to do something or deal with something in a very determined way, so that you are not likely to stop until it is done</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[money]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>two bits/four bits</strong> <em>American English</em> <em>informal</em> 25 cents or 50 cents</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> <em>old-fashioned</em> a small coin</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>pull something to bits</strong> <em>British English</em> <em>informal</em> to criticize something strongly:</div><ul class=\"examples\"><li><em>The critics pulled his new play to bits.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[typical behaviour/experience]</strong> <em>informal</em> used to mean a kind of behaviour or experience that is typical of someone or something</div><ul class=\"examples\"><li><strong><em>the (whole) student/movie star/travelling etc bit</strong>: Then she gave us the concerned mother bit.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>be in bits</strong> <em>British English</em> <em>spoken</em> <em>informal</em> to be extremely upset because something unpleasant or disappointing has happened:</div><ul class=\"examples\"><li><em>She was in bits after the race, and looked totally gutted.</em></li></ul></div></div>","705":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\">(past tense bit /bɪt/, past participle bitten /ˈbɪtn/, present participle biting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[teeth]</strong> <span class=\"gram\">[intransitive, transitive]</span> to use your teeth to cut, crush, or chew something:</div><ul class=\"examples\"><li><em>The dog bit him and made his hand bleed.</em></li><li><strong><em>bite into/through/at/down</strong>: She bit into a croissant and took a sip of coffee. / An adult conger eel can easily bite through a man’s leg. / Nina pushed her fist into her mouth and bit down hard.</em></li><li><strong><em>bite something off</strong>: a man whose arm was bitten off by an alligator</em></li><li><strong><em>bite your nails</strong> (=bite the nails on your fingers, especially because you are nervous): I wish I could stop biting my nails.</em></li><li><strong><em>bite your lip</strong> (=because you are upset or not sure what to say): She paused uncertainly, biting her lip.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[insect/snake]</strong> <span class=\"gram\">[intransitive, transitive]</span> to injure someone by making a hole in their skin → sting:</div><ul class=\"examples\"><li><em>I think I’ve been bitten.</em></li><li><em>The dog’s been badly bitten by fleas.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[press hard]</strong> <span class=\"gram\">[intransitive]</span> if an object bites into a surface, it presses firmly into it and does not move or slip</div><ul class=\"examples\"><li><strong><em>bite into</strong>: The hooves of the galloping horses had bitten deep into the soft earth. / He wore boots that bit into the ice.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[effect]</strong> <span class=\"gram\">[intransitive]</span> to start to have an unpleasant effect:</div><ul class=\"examples\"><li><em>The new tobacco taxes have begun to bite.</em></li><li><strong><em>bite into</strong>: The recession is biting into the music industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[accept]</strong> <span class=\"gram\">[intransitive]</span> to believe what someone tells you, or to buy something they are selling, especially when they have persuaded you to do this:</div><ul class=\"examples\"><li><em>The new camcorders were withdrawn after consumers failed to bite.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[fish]</strong> <span class=\"gram\">[intransitive]</span> if a fish bites, it takes food from a hook and so gets caught:</div><ul class=\"examples\"><li><em>The fish just aren’t biting today.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bite your tongue</strong> to stop yourself from saying what you really think, even though this is difficult:</div><ul class=\"examples\"><li><em>She should have bitten her tongue.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>bite the dust</strong> <em>informal</em> to die, fail, or be defeated:</div><ul class=\"examples\"><li><em>Italy’s championship hopes eventually bit the dust.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bite the bullet</strong> <em>informal</em> to start dealing with an unpleasant or dangerous situation because you cannot avoid it any longer:</div><ul class=\"examples\"><li><em>I finally bit the bullet and left.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>bite off more than you can chew</strong> to try to do more than you are able to do</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>he/she won’t bite</strong> <em>spoken</em> used to say that there is no need to be afraid of someone, especially someone in authority:</div><ul class=\"examples\"><li><em>Well, go and ask him – he won’t bite!</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>what’s biting you/her etc?</strong> <em>spoken</em> used to ask why someone is annoyed or upset</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>somebody/something bites</strong> <em>spoken</em> <em>not polite</em> used to say that you dislike someone or something very much or think that something is very bad</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>once bitten, twice shy</strong> used to say that if you have failed or been hurt once, you will be more careful next time</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>bite the hand that feeds you</strong> to harm someone who has helped or supported you</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>be bitten by the showbiz/travel/flying etc bug</strong> to develop a very strong interest in something</div><div class=\"sense\"><span class=\"snum\">17</span> <strong>Bite me!</strong> <em>American English</em> <em>spoken</em> <em>informal</em> used to show that you are offended by something someone has just said about you</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[using teeth]</strong> <span class=\"gram\">[countable]</span> the act of cutting or crushing something with your teeth:</div><ul class=\"examples\"><li><em>Antonio devoured half his burger in one bite.</em></li><li><strong><em>take/have a bite (of something/out of something)</strong>: She picked up the sandwich and took a bite. / Can I have a bite of your apple?</em></li><li><strong><em>give somebody a bite</strong>: Some fish can give you a nasty bite.</em></li><li><em>Her body was covered in bite marks.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[wound]</strong> <span class=\"gram\">[countable]</span> a small hole made where an animal or insect has bitten you</div><ul class=\"examples\"><li><strong><em>snake/ant etc bite</em></strong></li><li><strong><em>bite of</strong>: The infection is passed by the bite of a mosquito.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bite (to eat)</strong> <em>informal</em> a small meal:</div><ul class=\"examples\"><li><em>We had a bite to eat and a couple of drinks before the flight.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[taste]</strong> <span class=\"gram\">[uncountable]</span> a pleasantly sharp taste:</div><ul class=\"examples\"><li><em>Goat’s cheese adds extra bite to any pasta dish.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cold]</strong> <span class=\"gram\">[singular]</span> a feeling of coldness:</div><ul class=\"examples\"><li><em>There was no mistaking the approach of winter; he could feel its bite.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[strong effect]</strong> <span class=\"gram\">[uncountable]</span> a special quality in a performance, piece of writing etc that makes its arguments very effective and likely to persuade people:</div><ul class=\"examples\"><li><em>The film gains incisive bite from Sellers’ performance as the union chief.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[fish]</strong> <span class=\"gram\">[countable]</span> when a fish takes the food from a hook:</div><ul class=\"examples\"><li><em>Sometimes I sit for hours and never get a bite.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>another/a second bite at the cherry</strong> <em>British English</em> a second chance to do something</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[jaw]</strong> <span class=\"gram\">[countable usually singular]</span> <em>technical</em> the way that a person or animal’s top and bottom teeth touch when their mouth is closed:</div><ul class=\"examples\"><li><em>Our dentist said that Emmy should wear a brace to improve her bite.</em></li></ul></div></div>","706":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bit‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> feeling angry, jealous, and upset because you think you have been treated unfairly → bitterly</div><ul class=\"examples\"><li><strong><em>bitter about</strong>: I feel very bitter about it.</em></li><li><em>a bitter old man</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[only before noun]</span> making you feel very unhappy and upset → bitterly</div><ul class=\"examples\"><li><strong><em>a bitter disappointment/blow</strong>: If he failed, it would be a bitter disappointment to his parents.</em></li><li><em>His photo stirred up bitter memories.</em></li><li><strong><em>from bitter experience</strong> (=because of your own very unpleasant experiences): She knew from bitter experience that it would be impossible to talk it over with Julian.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a bitter argument, battle etc is one in which people oppose or criticize each other with strong feelings of hate and anger</div><ul class=\"examples\"><li><strong><em>bitter dispute/battle/struggle etc</strong>: The couple are locked in a bitter battle for custody of the children. / The government faces bitter opposition to these policies. / The countries are still bitter enemies.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> having a strong sharp taste, like black coffee without sugar → sour, sweet: ► see thesaurus at taste</div><ul class=\"examples\"><li><em>Enjoy the beer’s bitter taste as you slowly drink it.</em></li><li><em>bitter chocolate</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> unpleasantly cold → bitterly:</div><ul class=\"examples\"><li><em>a bitter wind</em></li><li><em>the bitter cold of the Midwestern winters</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>to the bitter end</strong> continuing until the end, even though this is difficult:</div><ul class=\"examples\"><li><em>Employees have vowed to fight the closure to the bitter end.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>a bitter pill (to swallow)</strong> something very unpleasant that you must accept:</div><ul class=\"examples\"><li><em>The knowledge that his friends no longer trusted him was a bitter pill to swallow.</em></li></ul></div>","707":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bit‧ter‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪtəli $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a way that produces or shows feelings of great sadness or anger:</div><ul class=\"examples\"><li><em>He complained bitterly about his exam grades.</em></li><li><em>I was bitterly disappointed.</em></li><li><em>The march was bitterly opposed by local residents.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bitterly cold</strong> very cold</div></div>","708":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bi‧zarre</span><span class=\"meta-item\"><strong>IPA:</strong> /bəˈzɑː $ -ˈzɑːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">very unusual or strange: ► see thesaurus at strange</div><ul class=\"examples\"><li><em>a bizarre coincidence</em></li><li><em>dancers in rather bizarre costumes</em></li></ul></div>","709":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blæk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(comparative blacker, superlative blackest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[colour]</strong> having the darkest colour, like coal or night:</div><ul class=\"examples\"><li><em>a black evening dress</em></li><li><strong><em>jet/inky black</strong> (=very dark): jet black hair</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[no light]</strong> very dark because there is no light:</div><ul class=\"examples\"><li><em>It was still pitch black (=very dark) out.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[people]</strong> (also Black)</div><div class=\"subsense\"><span class=\"subnum\">a)</span> belonging to the race of people who originally came from Africa and who have dark brown skin → white:</div><ul class=\"examples\"><li><em>Over half the students are black.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[only before noun]</span> relating to black people:</div><ul class=\"examples\"><li><em>politics from a black perspective</em></li><li><em>Black and Asian music</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[drink]</strong> <span class=\"gram\">[only before noun]</span> black coffee or tea does not have milk in it <em>OPP white</em>:</div><ul class=\"examples\"><li><em>Black coffee, no sugar, please.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[dirty]</strong> <em>informal</em> very dirty</div><ul class=\"examples\"><li><strong><em>be black with soot/dirt/age etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[without hope]</strong> sad and without hope for the future:</div><ul class=\"examples\"><li><em>the blackest period of European history</em></li><li><em>a mood of black despair</em></li><li><em>It’s been another black day for the car industry, with more job losses announced.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[humour]</strong> making jokes about serious subjects, especially death:</div><ul class=\"examples\"><li><em>a very black joke</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[angry]</strong> <span class=\"gram\">[only before noun]</span> full of feelings of anger or hate → blackly:</div><ul class=\"examples\"><li><em>Denise gave me a black look.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a black mark (against somebody)</strong> if there is a black mark against you, someone has a bad opinion of you because of something you have done</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>not be as black as you are painted</strong> not to be as bad as people say you are</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[bad]</strong> <em>literary</em> very bad:</div><ul class=\"examples\"><li><em>black deeds</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> the dark colour of coal or night: → coal-black</div><ul class=\"examples\"><li><em>You look good wearing black.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also Black) <span class=\"gram\">[countable]</span> someone who belongs to the race of people who originally came from Africa and who have dark brown skin → white:</div><ul class=\"examples\"><li><em>laws that discriminated against blacks</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be in the black</strong> to have money in your bank account <em>OPP be in the red</em></div></div></div>","710":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> black‧board</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblækbɔːd $ -bɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a board with a dark smooth surface, used in schools for writing on with chalk</div></div>","711":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> black‧mail</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblækmeɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> when someone tries to get money from you or make you do what they want by threatening to tell other people your secrets</div><div class=\"sense\"><span class=\"snum\">2</span> when someone tries to make you do what they want by making threats or by making you feel guilty if you do not do it:</div><ul class=\"examples\"><li><em>She had already tried emotional blackmail (=tried to make him feel guilty) to stop him leaving.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to use blackmail against someone: ► see thesaurus at force</div><ul class=\"examples\"><li><em>He was jailed for four years for blackmailing gay businessmen.</em></li><li><strong><em>blackmail somebody into (doing) something</strong>: I refuse to be blackmailed into making a quick decision.</em></li></ul></div></div>","712":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bleɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the flat cutting part of a tool or weapon → edge</div><ul class=\"examples\"><li><strong><em>blade of</strong>: The blade of the knife flashed in the moonlight.</em></li><li><em>a razor blade</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the flat wide part of an object that pushes against air or water:</div><ul class=\"examples\"><li><em>the blade of an oar</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>blade of grass</strong> a single thin flat piece of grass</div><div class=\"sense\"><span class=\"snum\">4</span> the metal part on the bottom of an ice-skate</div><div class=\"sense\"><span class=\"snum\">5</span> a thin curved piece of a strong material that someone with the lower part of their leg missing attaches to their leg in order to run</div></div>","713":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bleɪm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to say or think that someone or something is responsible for something bad:</div><ul class=\"examples\"><li><em>Don’t blame me – it’s not my fault.</em></li><li><em>I blame his mother. She does everything for him.</em></li><li><strong><em>blame somebody/something for something</strong>: Marie still blames herself for Patrick’s death. / The report blames poor safety standards for the accident. / The decision to increase interest rates was widely blamed (=blamed by many people) for the crisis.</em></li><li><strong><em>blame something on somebody/something</strong>: One of the computers is broken and she’s blaming it on me. / The crash was blamed on pilot error.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>somebody/something is to blame (for something)</strong> used to say that someone or something is responsible for something bad: RegisterIn everyday English, people usually say something is someone&#x27;s fault, rather than saying they are to blame: He was to blame for the accident. ➔ The accident was his fault.</div><ul class=\"examples\"><li><em>Officials believe that more than one person may be to blame for the fire.</em></li><li><strong><em>partly/largely/entirely etc to blame</strong>: Television is partly to blame.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>I don’t blame you/you can hardly blame him etc</strong> <em>spoken</em> used to say that you think it was right or reasonable for someone to do what they did:</div><ul class=\"examples\"><li><em>‘She’s left her husband.’ ‘I don’t blame her, after the way he treated her.’</em></li><li><em>You can hardly blame him for not waiting.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>don’t blame me</strong> <em>spoken</em> used when you are advising someone not to do something but you think that they will do it in spite of your advice:</div><ul class=\"examples\"><li><em>Buy it then, but don’t blame me when it breaks down.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>somebody only has himself/herself to blame</strong> <em>spoken</em> used to say that someone’s problems are their own fault:</div><ul class=\"examples\"><li><em>If he fails his exams, he’ll only have himself to blame.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">responsibility for a mistake or for something bad</div><ul class=\"examples\"><li><strong><em>blame for</strong>: Do you accept any blame for what happened?</em></li><li><em>I always get the blame (=am blamed) for his mistakes!</em></li><li><em>She stole the money but she’s trying to put the blame on (=blame) me.</em></li></ul></div></div>","714":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> without any excitement, strong opinions, or special character <em>SYN dull</em>:</div><ul class=\"examples\"><li><em>a few bland comments</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> food that is bland has very little taste <em>SYN tasteless</em>: ► see thesaurus at taste</div><ul class=\"examples\"><li><em>a bland diet</em></li></ul></div>","715":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blæŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> without any writing, print, or recorded sound: ► see thesaurus at empty</div><ul class=\"examples\"><li><em>Leave the last page blank.</em></li><li><em>a blank cassette</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a blank face or look shows no emotion, understanding, or interest → blankly</div><ul class=\"examples\"><li><strong><em>blank face/look/expression/eyes</strong>: Zoe looked at me with a blank expression.</em></li><li><em>She gazed at him in blank astonishment.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>go blank</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if your mind goes blank, or if you go blank, you are suddenly unable to remember something:</div><ul class=\"examples\"><li><em>My heart began to race and my mind went blank.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to stop showing any images, writing etc:</div><ul class=\"examples\"><li><em>Suddenly the screen went blank.</em></li></ul></div>","716":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> blan‧ket</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblæŋkɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a cover for a bed, usually made of wool → duvet</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> a thick covering or area of something</div><ul class=\"examples\"><li><strong><em>blanket of</strong>: The hills were covered with a blanket of snow.</em></li><li><strong><em>blanket of fog/cloud</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> something that makes it hard for you to find information or the truth about something <em>SYN cloak</em></div><ul class=\"examples\"><li><strong><em>blanket of</strong>: The trial was held under a blanket of secrecy.</em></li></ul></div>","717":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bleə $ bler/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make a very loud unpleasant noise:</div><ul class=\"examples\"><li><em>Horns blared in the street outside.</em></li></ul></div>","718":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɑːst $ blæst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[air/wind]</strong> a sudden strong movement of wind or air</div><ul class=\"examples\"><li><strong><em>blast of</strong>: A blast of cold air swept through the hut.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[explosion]</strong> an explosion, or the very strong movement of air that it causes</div><ul class=\"examples\"><li><strong><em>in the blast</strong>: Thirty-six people died in the blast.</em></li><li><strong><em>bomb/shotgun/nuclear etc blast</strong>: A bomb blast completely destroyed the building.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[loud noise]</strong> a sudden very loud noise, especially one made by a whistle or horn</div><ul class=\"examples\"><li><strong><em>blast on</strong>: The station master gave a blast on his whistle and we were off.</em></li><li><strong><em>long/short blast</strong>: a long trumpet blast</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>(at) full blast</strong> as powerfully or loudly as possible:</div><ul class=\"examples\"><li><em>I had the gas fire going full blast.</em></li><li><em>The radio was on at full blast.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[fun]</strong> <strong>a blast</strong> <em>informal</em> an enjoyable and exciting experience:</div><ul class=\"examples\"><li><em>The concert was a blast.</em></li><li><em>We had a blast at the fair.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[emotion]</strong> a sudden strong expression of a powerful emotion</div><ul class=\"examples\"><li><strong><em>blast of</strong>: She was totally unprepared for the blast of criticism she received.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>a blast from the past</strong> <em>informal</em> something from the past that you remember, see, or hear again, and that reminds you of that time in your life:</div><ul class=\"examples\"><li><em>That’s a blast from the past. No one has called me that for years.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[gun/bomb]</strong> <span class=\"gram\">[transitive]</span> to damage or destroy something, or to injure or kill someone, using a gun or a bomb</div><ul class=\"examples\"><li><strong><em>blast somebody with something</strong>: She blasted her husband with a shotgun because he was having an affair.</em></li><li><em>The first shot missed and blasted a hole in the far wall.</em></li><li><em>The plane was blasted out of the sky by a terrorist bomb.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[break something into pieces]</strong> <span class=\"gram\">[intransitive, transitive]</span> to break something into pieces using explosives, especially in order to build something such as a road</div><ul class=\"examples\"><li><strong><em>blast something through something</strong>: A 1.5 km tunnel was blasted through the mountain.</em></li><li><strong><em>blast something out of something</strong>: The road will have to be blasted out of solid rock.</em></li><li><strong><em>blast through</strong>: Railway workers had blasted through the mountains 90 years before.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[loud noise]</strong> (also blast out) <span class=\"gram\">[intransitive, transitive]</span> to produce a lot of loud noise, especially music:</div><ul class=\"examples\"><li><em>He was woken by the radio alarm clock blasting out rock music.</em></li><li><strong><em>blast from</strong>: Dance music blasted from the stereo.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[criticize]</strong> <span class=\"gram\">[transitive]</span> to criticize someone or something very strongly – used especially in news reports</div><ul class=\"examples\"><li><strong><em>blast somebody for (doing) something</strong>: Union leaders blasted the government for failing to tackle the jobs crisis.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[kick/hit a ball]</strong> <span class=\"gram\">[transitive]</span> to hit or kick a ball very hard:</div><ul class=\"examples\"><li><em>With six minutes remaining, he blasted the ball through the Coleraine defences for his 19th goal of the season.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[air/water]</strong> <span class=\"gram\">[intransitive, transitive]</span> if air or water is blasted somewhere, or if it blasts somewhere, it moves there with great force:</div><ul class=\"examples\"><li><em>The wind ripped through the trees and blasted a curtain of rain up the meadow.</em></li><li><em>Icy winds and driving snow blasted through the pine trees.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[sports]</strong> <span class=\"gram\">[transitive]</span> <em>American English</em> <em>informal</em> to beat another team very easily:</div><ul class=\"examples\"><li><em>The Seahawks were blasted 35–14 by the Broncos.</em></li></ul></div></div>","719":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bla‧tant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbleɪtənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">something bad that is blatant is very clear and easy to see, but the person responsible for it does not seem embarrassed or ashamed: ► see thesaurus at obvious</div><ul class=\"examples\"><li><em>blatant discrimination</em></li></ul></div>","720":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bleɪz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fire]</strong> ► see thesaurus at fire</div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[countable usually singular]</span> a big dangerous fire – used especially in news reports → ablaze:</div><ul class=\"examples\"><li><em>It took almost 100 firemen to bring the blaze under control.</em></li><li><strong><em>fight/tackle/control a blaze</strong>: Helicopters were used to help fight the blaze.</em></li><li><strong><em>house/factory/barn etc blaze</strong>: a huge chemical factory blaze</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[singular]</span> a fire burning with strong bright flames:</div><ul class=\"examples\"><li><em>I lit the fire and soon had a cheerful blaze going.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[light/colour]</strong> <span class=\"gram\">[singular]</span> very bright light or colour → ablaze</div><ul class=\"examples\"><li><strong><em>blaze of</strong>: the blaze of light from the security lamps / The garden is a blaze of colour at this time of year.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>blaze of publicity/glory</strong> a lot of public attention or success and praise:</div><ul class=\"examples\"><li><em>As soon as the trial was over, the blaze of publicity surrounding him vanished.</em></li><li><em>She played the Canada tournament, then retired, going out in a blaze of glory (=ending her career with a lot of success and praise).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular]</span> a sudden show of very strong emotion:</div><ul class=\"examples\"><li><em>A blaze of anger flashed across his face.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>what the blazes/who the blazes etc</strong> <em>old-fashioned</em> <em>spoken</em> used to emphasize a question when you are annoyed:</div><ul class=\"examples\"><li><em>What the blazes is going on here?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>like blazes</strong> <em>old-fashioned</em> <em>spoken</em> as fast, as much, or as strongly as possible:</div><ul class=\"examples\"><li><em>We had to run like blazes.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <span class=\"gram\">[countable usually singular]</span> a white mark, especially one down the front of a horse’s face</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[fire]</strong> to burn very brightly and strongly → blazing: ► see thesaurus at burn</div><ul class=\"examples\"><li><em>The room was warm, with a fire blazing in the hearth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[light]</strong> to shine with a very bright light: ► see thesaurus at shine</div><ul class=\"examples\"><li><em>A huge truck was advancing towards us, its headlights blazing.</em></li><li><em>The sun blazed down as we walked along the valley.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[eyes]</strong> <span class=\"gram\">[usually in progressive]</span> <em>literary</em> if someone’s eyes are blazing, their eyes are shining brightly because they are feeling a very strong emotion, usually anger</div><ul class=\"examples\"><li><strong><em>blaze with</strong>: Linda leapt to her feet, her dark eyes blazing with anger.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[gun]</strong> (also blaze away) if guns blaze, they fire bullets quickly and continuously:</div><ul class=\"examples\"><li><em>An enemy plane roared overhead, its guns blazing.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>blaze a trail</strong> to develop or do something new and important, or to do something important that no one has done before:</div><ul class=\"examples\"><li><em>an innovative young company that has blazed a trail for others to follow</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be blazed across/all over something</strong> if something is blazed across a newspaper etc, it is written in a way that everyone will notice:</div><ul class=\"examples\"><li><em>News of their divorce was blazed across all the tabloids.</em></li></ul></div></div>","721":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bliːtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a chemical used to make things pale or white, or to kill germs</div></div>","722":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bliːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> without anything to make you feel happy or hopeful</div><ul class=\"examples\"><li><strong><em>a bleak future/prospect</strong>: The company still hopes to find a buyer, but the future looks bleak.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> cold and without any pleasant or comfortable features:</div><ul class=\"examples\"><li><em>a bleak January afternoon</em></li><li><em>The landscape was bleak.</em></li></ul></div>","723":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bliːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle bled /bled/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[blood]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> to lose blood, especially because of an injury:</div><ul class=\"examples\"><li><em>Your nose is bleeding.</em></li><li><em>Tragically, she bled to death.</em></li><li><strong><em>bleed profusely/heavily</strong> (=bleed a lot): Mrs Burke was found unconscious and bleeding profusely.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> to take some blood from someone’s body, done in the past in order to treat a disease:</div><ul class=\"examples\"><li><em>When he fell sick several days later, he had a doctor bleed him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[money]</strong> <span class=\"gram\">[transitive]</span> to force someone to pay an unreasonable amount of money over a period of time:</div><ul class=\"examples\"><li><em>His ex-wife clearly intends to bleed him for every last penny.</em></li><li><strong><em>bleed somebody dry/white</strong> (=take all their money, possessions etc): The ten-year war has bled the country dry.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[air/liquid]</strong> <span class=\"gram\">[transitive]</span> to remove air or liquid from a system in order to make it work properly, for example from a heating system:</div><ul class=\"examples\"><li><em>We need to bleed the radiators.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[colour]</strong> <span class=\"gram\">[intransitive]</span> to spread from one area of cloth or paper to another <em>SYN run</em>:</div><ul class=\"examples\"><li><em>Wash it in cold water so the colours don’t bleed.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>bleed red ink</strong> <em>informal</em> if a company or business bleeds red ink, it loses a lot of money, rather than making money:</div><ul class=\"examples\"><li><em>Analysts predict the retailer will continue to bleed red ink, with losses topping $180 million.</em></li></ul></div>","724":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to combine different things in a way that produces an effective or pleasant result, or to become combined in this way:</div><ul class=\"examples\"><li><em>a story that blends fact and legend</em></li><li><strong><em>blend with/together</strong>: Leave the sauce to allow the flavours to blend together.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to thoroughly mix together soft or liquid substances to form a single smooth substance: ► see thesaurus at mix</div><ul class=\"examples\"><li><em>Blend the sugar, eggs, and flour.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to produce tea, tobacco, whisky etc by mixing several different types together: GRAMMAR Blend is usually passive in this meaning.</div><ul class=\"examples\"><li><em>blended whisky</em></li></ul></div>","725":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bles/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>bless you!</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> what you say when someone sneezes</div><div class=\"subsense\"><span class=\"subnum\">b)</span> used to thank someone for doing something for you</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>bless (him/her etc)</strong> <em>spoken</em> used to show that you are fond of someone, amused by them, or pleased by something they have done:</div><ul class=\"examples\"><li><em>He’s always willing to help. Bless him!</em></li><li><em>‘Jess made this card for me.’ ‘Bless!’</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be blessed with something</strong> to have a special ability, good quality etc:</div><ul class=\"examples\"><li><em>We’re both blessed with good health.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> if God blesses someone or something, he helps and protects them:</div><ul class=\"examples\"><li><em>May God bless you.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to ask God to protect someone or something:</div><ul class=\"examples\"><li><em>The couple later had their marriage blessed in their local parish church.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> to make something holy:</div><ul class=\"examples\"><li><em>Then the priest blesses the bread and wine.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bless my soul/I’ll be blessed!</strong> <em>old-fashioned</em> <em>spoken</em> used to express surprise</div></div>","726":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bless‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblesɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something that you have or something that happens which is good because it improves your life, helps you in some way, or makes you happy:</div><ul class=\"examples\"><li><em>The dishwasher has been a real blessing!</em></li><li><strong><em>it is a blessing (that)</strong>: It’s a blessing no one was badly hurt.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> someone’s approval or encouragement for a plan, activity, idea etc</div><ul class=\"examples\"><li><strong><em>with somebody’s blessing</strong>: They were determined to marry, with or without their parents’ blessing.</em></li><li><em>The Defense Department has given its blessing to the scheme.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a mixed blessing</strong> a situation that has both good and bad parts:</div><ul class=\"examples\"><li><em>Having children so early in their marriage was a mixed blessing.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a blessing in disguise</strong> something that seems to be bad or unlucky at first, but which you later realize is good or lucky</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>count your blessings</strong> used to tell someone to remember how lucky they are, especially when they are complaining about something</div><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable, uncountable]</span> protection and help from God, or words spoken to ask for this:</div><ul class=\"examples\"><li><em>The priest gave the blessing.</em></li></ul></div>","727":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blaɪnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[unable to see]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> unable to see → colour-blind, visually impaired, handicapped:</div><ul class=\"examples\"><li><em>a school for blind children</em></li><li><em>the needs of blind people</em></li><li><strong><em>totally/completely/almost/partially blind</strong>: She’s almost blind in her right eye.</em></li><li><em>He was slowly going blind (=becoming blind).</em></li><li><em>Beverley was born blind.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>the blind</strong> <span class=\"gram\">[plural]</span> people who are unable to see:</div><ul class=\"examples\"><li><em>talking books for the blind</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <strong>as blind as a bat</strong> unable to see well – used humorously:</div><ul class=\"examples\"><li><em>I’m as blind as a bat without my glasses.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">d)</span> <strong>blind with tears/rage/pain etc</strong> unable to see because of tears, pain, or a strong emotion → blindly:</div><ul class=\"examples\"><li><em>She screamed at him, her eyes blind with tears.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be blind to something</strong> to completely fail to notice or realize something → blindly:</div><ul class=\"examples\"><li><em>International companies are all too often blind to local needs.</em></li><li><em>He was totally blind to the faults of his children.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>turn a blind eye (to something)</strong> to deliberately ignore something that you know should not be happening:</div><ul class=\"examples\"><li><em>Teachers were turning a blind eye to smoking in school.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>not take/pay a blind bit of notice</strong> <em>British English</em> <em>informal</em> to completely ignore what someone does or says, especially in a way that is annoying:</div><ul class=\"examples\"><li><em>He never pays a blind bit of notice to what his staff tell him.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>not make a blind bit of difference</strong> <em>British English</em> <em>informal</em> used to emphasize that whatever someone says or does will not change the situation at all:</div><ul class=\"examples\"><li><em>Try and talk to her if you want, but I don’t think it’ll make a blind bit of difference.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[feelings]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>blind faith/prejudice/obedience etc</strong> strong feelings that someone has without thinking about why they have them – used to show disapproval:</div><ul class=\"examples\"><li><em>Blind faith sent thousands of people to a pointless war.</em></li><li><em>a story about blind loyalty</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>blind panic/rage</strong> strong feelings of fear or anger that you cannot control:</div><ul class=\"examples\"><li><em>In a moment of blind panic, she had pulled the trigger and shot the man dead.</em></li><li><em>Blind rage took hold of him.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[road]</strong> <strong>blind bend/corner</strong> a corner in a road that you cannot see beyond when you are driving</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>the blind leading the blind</strong> used to say that people who do not know much about what they are doing are guiding or advising others who know nothing at all</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[aircraft]</strong> blind flying is when you use only instruments to fly an aircraft because you cannot see through cloud, mist etc</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make it difficult for someone to see for a short time:</div><ul class=\"examples\"><li><em>For a moment, I was blinded by the glare of headlights coming towards me.</em></li><li><em>The dust choked and blinded him.</em></li><li><em>Blinded by tears, I walked towards the door.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to make someone lose their good sense or judgment and be unable to see the truth about something:</div><ul class=\"examples\"><li><em>He should have known better, but he was blinded by his own wants.</em></li><li><strong><em>blind somebody to something</strong>: Children’s bad behaviour should not blind us to their need for love. / His single-minded determination to win the war is blinding him to other dangers.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to permanently destroy someone’s ability to see:</div><ul class=\"examples\"><li><em>He had been blinded in an explosion.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>blind somebody with science</strong> to confuse or trick someone by using complicated language</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also (window) shade<em>American English</em>) <span class=\"gram\">[countable]</span> a covering, especially one made of cloth, that can be rolled up and down to cover a window inside a building: → roller blind, Venetian blind</div><ul class=\"examples\"><li><em>The blinds were drawn (=pulled down) to protect the new furniture from the sun.</em></li><li><strong><em>open/pull down/draw the blinds</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>American English</em> a small shelter where you can watch birds or animals without being seen by them SYN hide<em>British English</em></div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> a trick or excuse to stop someone from discovering the truth</div></div></div>","728":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to shut and open your eyes quickly:</div><ul class=\"examples\"><li><em>I blinked as I came out into the sunlight.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> if lights blink, they shine unsteadily or go on and off quickly:</div><ul class=\"examples\"><li><em>The light on your answering machine is blinking.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>not (even) blink</strong> to not seem at all surprised:</div><ul class=\"examples\"><li><em>When I told her how much it would cost, she didn’t even blink.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>before you could blink</strong> <em>spoken</em> extremely quickly</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>blink back/away tears</strong> to shut and open your eyes in order to get rid of tears:</div><ul class=\"examples\"><li><em>Lynn laughed, blinking back unexpected tears.</em></li></ul></div>","729":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">perfect happiness or enjoyment</div><ul class=\"examples\"><li><strong><em>domestic/wedded/marital bliss</strong>: six months of wedded bliss</em></li><li><em>I didn’t have to get up till 11 – it was sheer bliss.</em></li></ul></div>","730":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> blis‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblɪstə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a swelling on your skin containing clear liquid, caused, for example, by a burn or continuous rubbing:</div><ul class=\"examples\"><li><em>New shoes always give me blisters.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a swelling on the surface of metal, rubber, painted wood etc</div></div>","731":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bliz‧zard</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblɪzəd $ -ərd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a severe snowstorm: ► see thesaurus at storm</div><ul class=\"examples\"><li><em>We got stuck in a blizzard.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a sudden large amount of something unpleasant or annoying that you must deal with → flood</div><ul class=\"examples\"><li><strong><em>blizzard of</strong>: a blizzard of emails</em></li></ul></div>","732":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɒk $ blɑːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[solid material]</strong> a piece of hard material such as wood or stone with straight sides → breeze-block, building block, cinder block ► see thesaurus at piece</div><ul class=\"examples\"><li><strong><em>block of</strong>: a block of ice</em></li><li><em>a wall made of concrete blocks</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[streets/area]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>American English</em> the distance along a city street from where one street crosses it to the next:</div><ul class=\"examples\"><li><em>Head for 44th Street, a few blocks east of Sixth Avenue.</em></li><li><em>The church is down the block.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the four city streets that form a square around an area of buildings:</div><ul class=\"examples\"><li><em>Let’s walk round the block.</em></li><li><em>She grew up playing with the other kids on the block.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <em>Australian English</em> a large piece of land:</div><ul class=\"examples\"><li><em>a ten-acre block near the city</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[large building]</strong> a large building divided into separate parts</div><ul class=\"examples\"><li><strong><em>block of</strong>: a block of flats</em></li><li><em>an office block</em></li><li><em>an apartment block</em></li><li><em>the school science block</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[quantity of things]</strong> a quantity of things of the same kind, considered as a single unit</div><ul class=\"examples\"><li><strong><em>block of</strong>: New employees receive a block of shares in the firm. / Set aside blocks of time for doing your homework.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>block booking/voting</strong> an arrangement that is made for a whole group to buy something or to vote together</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[inability to think]</strong> <span class=\"gram\">[usually singular]</span> the temporary loss of your normal ability to think, learn, write etc:</div><ul class=\"examples\"><li><em>I have a mental block whenever I try to remember my password.</em></li><li><em>After his second novel, Garland had writer’s block (=he could not write anything).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[stopping movement]</strong> <span class=\"gram\">[usually singular]</span> something that prevents movement or progress → roadblock, stumbling block</div><ul class=\"examples\"><li><strong><em>block to</strong>: a major block to progress</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[punishment]</strong> <strong>the block</strong> in the past, a solid block of wood on which someone’s head was cut off as a punishment</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>put your head/neck on the block</strong> to risk destroying other people’s opinion of you or losing your job by doing or saying something:</div><ul class=\"examples\"><li><em>I’m not prepared to put my head on the block for him.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[sport]</strong> a movement in sport that stops an opponent going forward or playing the ball forward</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[sell]</strong> <strong>go on the block</strong> to be sold, especially at an auction:</div><ul class=\"examples\"><li><em>$500 million worth of art will go on the block.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also block up) to prevent anything moving through a space by being or placing something across it or in it:</div><ul class=\"examples\"><li><em>A fallen tree is blocking the road.</em></li><li><em>The sink’s blocked up.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>block somebody’s way/path/exit/escape etc</strong> to stand in front of someone, so that they cannot go past:</div><ul class=\"examples\"><li><em>I tried to get through, but there were people blocking my way.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to stop something happening, developing, or succeeding:</div><ul class=\"examples\"><li><em>The Senate blocked publication of the report.</em></li><li><em>laws designed to block imports of cheap tobacco</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>block somebody’s view</strong> to be in front of someone, so that they cannot see something:</div><ul class=\"examples\"><li><em>The huge building across the street blocked our view of the sea.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> (also block out) to stop light reaching a place:</div><ul class=\"examples\"><li><em>Can you move? You’re blocking my light.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> to stop a ball, a blow etc from getting to where your opponent wants it to:</div><ul class=\"examples\"><li><em>a shot blocked by the goalkeeper</em></li></ul></div></div>","733":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɒɡ $ blɑːɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a web page containing information or opinions from a particular person or about a particular subject, to which new information is added regularly <em>SYN web log</em></div></div>","734":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bləʊk $ bloʊk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>British English</em> <em>informal</em> a man:</div><ul class=\"examples\"><li><em>He’s a nice bloke.</em></li></ul></div>","735":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɒnd $ blɑːnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> another spelling of blonde</div><div class=\"sense\"><span class=\"snum\">2</span> a man who is blond has pale or yellow hair</div></div>","736":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɒnd $ blɑːnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> blonde hair is pale or yellow in colour</div><div class=\"sense\"><span class=\"snum\">2</span> a woman who is blonde has pale or yellow hair</div></div>","737":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blʌd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W1</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the red liquid that your heart pumps around your body:</div><ul class=\"examples\"><li><em>Her body was found in a pool of blood.</em></li><li><em>Blood oozed from a cut on his forehead.</em></li><li><em>Blood tests proved he was not the father.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>(have) somebody’s blood on your hands</strong> to have caused someone’s death:</div><ul class=\"examples\"><li><em>dictators with blood on their hands</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>in cold blood</strong> in a cruel and deliberate way:</div><ul class=\"examples\"><li><em>Evans had been murdered in cold blood.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>make somebody’s blood boil</strong> to make someone extremely angry:</div><ul class=\"examples\"><li><em>The way they treat people makes my blood boil.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>make somebody’s blood run cold</strong> to make someone feel extremely frightened</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>like getting blood out of a stone</strong> almost impossible:</div><ul class=\"examples\"><li><em>Getting the truth out of her is like getting blood out of a stone.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>blood is thicker than water</strong> used to say that family relationships are more important than any other kind</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>be after somebody’s blood</strong> to be angry enough to want to hurt someone</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>somebody’s blood is up</strong> <em>British English</em> someone is extremely angry about something and determined to do something about it:</div><ul class=\"examples\"><li><em>They tried to stop me, but my blood was up.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> the family to which you belong from the time that you are born:</div><ul class=\"examples\"><li><em>There’s Irish blood on his mother’s side.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be/run in somebody’s blood</strong> if an ability or tendency is in, or runs in, someone’s blood, it is natural to them and others in their family</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>sweat blood</strong> to work extremely hard to achieve something:</div><ul class=\"examples\"><li><em>Beth sweated blood over that article.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>blood, sweat, and tears</strong> extremely hard work</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>new/fresh blood</strong> new members in a group or organization who bring new ideas and energy:</div><ul class=\"examples\"><li><em>We need to bring in some new blood and fresh ideas.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>blood on the carpet</strong> a situation where people have a very strong disagreement, with the result that something serious happens, such as someone losing his or her job</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>young blood</strong> <em>old-fashioned</em> a fashionable young man</div><div class=\"sense\"><span class=\"snum\">17</span> <em>spoken</em> <em>informal</em> a way of greeting a friend, used by young men</div></div>","738":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> blos‧som</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblɒsəm $ ˈblɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a flower or the flowers on a tree or bush:</div><ul class=\"examples\"><li><em>pale pink blossoms</em></li><li><em>The cherry tree was covered in blossom.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>in (full) blossom</strong> with the flowers fully open</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> if trees blossom, they produce flowers:</div><ul class=\"examples\"><li><em>The apple trees are just beginning to blossom.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also blossom out) to become happier, more beautiful, more successful etc:</div><ul class=\"examples\"><li><em>Pete’s blossomed out in his new school.</em></li><li><strong><em>blossom into</strong>: The idea blossomed into a successful mail order business.</em></li></ul></div></div>","739":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɒt $ blɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle blotted, present participle blotting)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to make a wet surface become dry by pressing soft paper or cloth on it</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>blot your copybook</strong> <em>British English</em> <em>informal</em> to do something that spoils the idea that people have of you</div></div>","740":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blaʊz $ blaʊs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a shirt for women:</div><ul class=\"examples\"><li><em>a silk blouse</em></li></ul></div>","741":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bləʊ $ bloʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(past tense blew /bluː/, past participle blown /bləʊn $ bloʊn/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[wind moving]</strong> <span class=\"gram\">[intransitive, transitive]</span> if the wind or a current of air blows, it moves:</div><ul class=\"examples\"><li><em>A cold breeze was blowing hard.</em></li><li><em>It was blowing from an easterly direction.</em></li><li><em>Outside, the weather was blowing a gale.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[wind moving something]</strong> <span class=\"gram\">[intransitive, transitive usually + adverb/preposition]</span> to move, or to move something, by the force of the wind or a current of air:</div><ul class=\"examples\"><li><em>Her hair was blowing in the breeze.</em></li><li><em>The wind blew the rain into our faces.</em></li><li><em>My ticket blew away.</em></li><li><strong><em>blow (something) open/shut</strong>: A sudden draught blew the door shut.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[air from your mouth]</strong> <span class=\"gram\">[intransitive, transitive always + adverb/preposition]</span> to send air out from your mouth</div><ul class=\"examples\"><li><strong><em>blow (something) into/onto/out etc</strong>: She blew onto her coffee to cool it down.</em></li><li><em>He blew the smoke right in my face.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[make a noise]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make a sound by passing air through a whistle, horn etc:</div><ul class=\"examples\"><li><em>The whistle blew for half time.</em></li><li><em>A truck went by and blew its horn at her.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[violence]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to damage or destroy something violently with an explosion or by shooting</div><ul class=\"examples\"><li><strong><em>blow something away/out/off something</strong>: Part of his leg had been blown off.</em></li><li><strong><em>blow somebody/something to pieces/bits/smithereens</strong>: A bomb like that could blow you to bits.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[lose an opportunity]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to lose a good opportunity by making a mistake or by being careless:</div><ul class=\"examples\"><li><em>We’ve blown our chances of getting that contract.</em></li><li><em>You’ve got a great future ahead of you. Don’t blow it.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[waste money]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to spend a lot of money in a careless way, especially on one thing: ► see thesaurus at spend</div><ul class=\"examples\"><li><em>I blew all the money I won on a trip to Hawaii.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>blow your nose</strong> to clean your nose by forcing air through it into a cloth or a piece of soft paper</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>blow somebody a kiss</strong> to kiss your hand and then pretend to blow the kiss towards someone:</div><ul class=\"examples\"><li><em>She leant out of the window and blew him a kiss.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[electricity stops]</strong> <span class=\"gram\">[intransitive, transitive]</span> if an electrical fuse blows, or a piece of electrical equipment blows a fuse, the electricity suddenly stops working because a thin wire has melted:</div><ul class=\"examples\"><li><em>The floodlights blew a fuse.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[tyre]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a tyre blows, or if a car blows a tyre, it bursts</div><div class=\"sense\"><span class=\"snum\">12</span> <strong>[make a shape]</strong> <span class=\"gram\">[transitive]</span> to make or shape something by sending air out from your mouth:</div><ul class=\"examples\"><li><em>The kids were blowing bubbles in the backyard.</em></li><li><strong><em>blow glass</strong> (=shape glass by blowing into it when it is very hot and soft)</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[surprise/annoyance]</strong> <strong>blow/blow me/blow it etc</strong> <em>British English</em> <em>spoken</em> said to show annoyance or surprise:</div><ul class=\"examples\"><li><em>Blow it! I forgot to phone Jane.</em></li><li><em>Blow me down if she didn’t just run off!</em></li><li><em>Well, I’m blowed!</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[tell a secret]</strong> <span class=\"gram\">[transitive]</span> to make known something that was meant to be a secret:</div><ul class=\"examples\"><li><em>Your coming here has blown the whole operation.</em></li><li><strong><em>blow somebody’s cover</strong> (=make known what someone’s real job or name is): It would only take one phone call to blow his cover.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>blow somebody’s mind</strong> <em>spoken</em> to make you feel very surprised and excited by something: → mind-blowing</div><ul class=\"examples\"><li><em>Seeing her again really blew my mind.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>blow your top/stack/cool</strong> (also blow a fuse/gasket) <em>informal</em> to become extremely angry quickly or suddenly:</div><ul class=\"examples\"><li><em>One day, I just blew my top and hit him.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>blow the whistle on somebody</strong> <em>informal</em> to tell someone in authority about something wrong that someone is doing: → whistle-blower</div><ul class=\"examples\"><li><em>He blew the whistle on his colleagues.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>blow something (up) out of (all) proportion</strong> to make something seem much more serious or important than it is</div><div class=\"sense\"><span class=\"snum\">19</span> <strong>blow your own trumpet</strong> <em>especially BrE,</em> <strong>blow your own horn</strong> <em>American English</em> <em>informal</em> to talk a lot about your own achievements – used to show disapproval:</div><ul class=\"examples\"><li><em>Dave spent the whole evening blowing his own trumpet.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>blow somebody/something out of the water</strong> to defeat someone or something that you are competing with, or to achieve much more than they do:</div><ul class=\"examples\"><li><em>Motown had blown all the other record companies out of the water.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>blow hot and cold</strong> <em>British English</em> <em>informal</em> to keep changing your attitude towards someone or something</div><div class=\"sense\"><span class=\"snum\">22</span> <strong>blow something sky-high</strong> <em>British English</em> to destroy an idea, plan etc by showing that it cannot be true or effective:</div><ul class=\"examples\"><li><em>This new information blows his theory sky-high.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[BAD EFFECT]</strong> an action or event that causes difficulty or sadness for someone:</div><ul class=\"examples\"><li><em>Joe resigned, which was a severe blow because we needed him desperately.</em></li><li><em>His mother’s death was a shattering blow.</em></li><li><em>The election result dealt a further blow to the party.</em></li><li><em>The factory closures came as a blow to the local economy.</em></li><li><em>The final blow for many firms was the government’s abolition of import duties.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[hard hit]</strong> a hard hit with someone’s hand, a tool, or a weapon: RegisterIn everyday English, people usually say that someone gets hit or that something hits them, rather than using the noun blow: He received a blow to the head. ➔ He got hit on the head.</div><ul class=\"examples\"><li><em>She died from a heavy blow to the head.</em></li><li><em>He struck a blow which threw her to the floor.</em></li><li><em>Martin received a blow on the nose.</em></li><li><em>He had been struck a glancing blow (=a blow that did not hit him directly) by the car.</em></li><li><strong><em>blow to</strong>: He gave her a violent blow to the head.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[blowing]</strong> an action of blowing:</div><ul class=\"examples\"><li><em>One big blow and the candles were out.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>come to blows (with somebody)</strong> if two people come to blows, they start arguing or hitting each other because they disagree about something</div><ul class=\"examples\"><li><strong><em>blow over</strong>: They almost came to blows over the money.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>soften/cushion the blow</strong> to make something unpleasant easier for someone to accept:</div><ul class=\"examples\"><li><em>A reduction in interest rates would soften the blow of tax increases.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>low blow</strong> <em>American English</em> <em>informal</em> something unkind you say to deliberately embarrass or upset someone</div></div></div>","742":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bluː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having the colour of the sky or the sea on a fine day → navy, navy blue:</div><ul class=\"examples\"><li><em>the blue waters of the lake</em></li><li><strong><em>dark/light/pale/bright blue</strong>: a dark blue raincoat</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[not before noun]</span> <em>informal</em> sad and without hope <em>SYN depressed</em>:</div><ul class=\"examples\"><li><em>I’ve been feeling kind of blue.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>informal</em> blue jokes, stories etc are about sex, in a way that might offend some people → blue movie</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>argue/talk etc till you’re blue in the face</strong> <em>informal</em> to argue, talk etc about something a lot, but without achieving what you want:</div><ul class=\"examples\"><li><em>You can tell them till you’re blue in the face, but they’ll still do what they want.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>blue with cold</strong> <em>especially British English</em> someone who is blue with cold looks extremely cold</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>go blue</strong> <em>British English</em> if someone goes blue, their skin becomes blue because they are cold or cannot breathe properly</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>talk a blue streak</strong> <em>American English</em> <em>informal</em> to talk very quickly without stopping</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the colour of the sky or the sea on a fine day:</div><ul class=\"examples\"><li><em>She nearly always dresses in blue.</em></li><li><em>the rich greens and blues of the tapestry</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>blues</strong> (also the blues) <span class=\"gram\">[uncountable]</span> a slow sad style of music that came from the southern US: → rhythm and blues</div><ul class=\"examples\"><li><em>a blues singer</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the blues</strong> <span class=\"gram\">[plural]</span> <em>informal</em> feelings of sadness:</div><ul class=\"examples\"><li><em>A lot of women get the blues after the baby is born.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>out of the blue</strong> <em>informal</em> if something happens out of the blue, it is very unexpected → a bolt from/out of the blue at bolt1(3)</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>Blue</strong> <span class=\"gram\">[countable]</span> <em>British English</em> someone who has represented Oxford or Cambridge University at a sport, or the title given to such a person</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>the blue</strong> <em>literary</em> the sea or the sky → boys in blue at boy1(9)</div></div></div>","743":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blʌnt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> not sharp or pointed <em>OPP sharp</em>:</div><ul class=\"examples\"><li><em>Sharpen all your blunt knives.</em></li><li><em>a blunt pencil</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> speaking in an honest way even if this upsets people → bluntly: ► see thesaurus at honest</div><ul class=\"examples\"><li><em>To be blunt, many of the candidates cannot read or write.</em></li><li><em>Julian’s blunt words hurt her.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>blunt instrument</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a heavy object that is used to hit someone:</div><ul class=\"examples\"><li><em>The victim suffered a blow to the head from a blunt instrument.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a method of doing something that does not work very well because it has a lot of other effects that you do not want:</div><ul class=\"examples\"><li><em>The exams are a blunt instrument that will reveal little about children’s abilities.</em></li></ul></div>","744":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> blunt‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈblʌntli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">speaking in a direct honest way that sometimes upsets people:</div><ul class=\"examples\"><li><em>‘You’re drunk,’ she said bluntly.</em></li><li><em>To put it bluntly, she’s not up to the job.</em></li></ul></div>","745":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɜː $ blɜːr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually singular]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a shape that you cannot see clearly</div><ul class=\"examples\"><li><strong><em>blur of</strong>: I saw the blur of the car as it passed in front of me.</em></li><li><em>The island was a blur through misty rain.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something that you cannot remember clearly:</div><ul class=\"examples\"><li><em>The days before the accident were a blur.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle blurred, present participle blurring)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to become difficult to see, or to make something difficult to see, because the edges are not clear:</div><ul class=\"examples\"><li><em>The street lights were blurred by the fog.</em></li><li><em>Many of the details in the picture are blurred.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to be unable to see clearly:</div><ul class=\"examples\"><li><em>Tears blurred her eyes.</em></li><li><em>His vision was blurred.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> to make the difference between two ideas, subjects etc less clear:</div><ul class=\"examples\"><li><em>His films blur the boundaries between fact and fiction.</em></li><li><em>The design of the conservatory is meant to blur the distinction between the house and the garden.</em></li></ul></div></div>","746":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blɜːd $ blɜːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> unclear in shape, or making it difficult to see shapes:</div><ul class=\"examples\"><li><em>a blurred photo</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> difficult to remember or understand clearly:</div><ul class=\"examples\"><li><em>blurred memories</em></li></ul></div>","747":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /blʌʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to become red in the face, usually because you are embarrassed: RegisterIn everyday British English, people often say go red rather than blush:· She went red when he looked at her.</div><ul class=\"examples\"><li><em>Wilson saw she was watching him and blushed.</em></li><li><em>Joan blushed at the unexpected compliment.</em></li><li><em>Kate blushed scarlet.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to feel ashamed or embarrassed about something</div><ul class=\"examples\"><li><strong><em>blush to do something</strong>: I blush to admit that I haven’t read it.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>something that would make somebody blush</strong> something so shocking that it would shock someone who is not normally easily shocked:</div><ul class=\"examples\"><li><em>language that would make a sailor blush</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the blushing bride</strong> a young woman on her wedding day – used humorously</div></div>","748":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɔːd $ bɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[information]</strong> <span class=\"gram\">[countable]</span> a flat wide piece of wood, plastic etc that you can use to show information → billboard, blackboard, noticeboard, scoreboard</div><ul class=\"examples\"><li><strong><em>on a board</strong>: The plan of the new building is displayed on a board at the back of the room. / I’ve put a list of names up on the board.</em></li><li><em>I’ll check the departure board for train times.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[for putting things on]</strong> <span class=\"gram\">[countable]</span> a flat piece of wood, plastic, card etc that you use for a particular purpose such as cutting things on, or for playing indoor games: → breadboard, cheeseboard, chopping board</div><ul class=\"examples\"><li><em>Martha was chopping vegetables on a wooden board.</em></li><li><em>a chess board</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[group of people]</strong> (also Board) <span class=\"gram\">[countable]</span> a group of people in a company or other organization who make the rules and important decisions GRAMMAR: Singular or plural verb?• Board is usually followed by a singular verb in this meaning: · The board meets once a month.• In British English, you can also use a plural verb: · The board meet once a month.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><strong><em>board of</strong>: The Board of Directors met yesterday. / There was disagreement among the agency&#x27;s board of governors.</em></li><li><strong><em>sit on a board/have a seat on a board</strong> (=be a member of a board): He gave up his seat on the board after 40 years.</em></li><li><em>a board meeting</em></li><li><em>a board member</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in names]</strong> <strong>Board</strong> used in the name of some organizations:</div><ul class=\"examples\"><li><em>the New York State Board of Elections</em></li><li><em>the British Boxing Board of Control</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[in building]</strong> <span class=\"gram\">[countable]</span> a long thin flat piece of wood used for making floors, walls, fences etc: → floorboard</div><ul class=\"examples\"><li><em>We’ll have to take the boards up to check the wiring.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>on board</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> on a ship, plane, or spacecraft <em>SYN aboard</em>:</div><ul class=\"examples\"><li><em>There are 12 children on board the ship.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> involved with something or working for an organization:</div><ul class=\"examples\"><li><em>Supporters of the treaty say that it will be necessary to have the United States on board.</em></li><li><em>He came on board in the late sixties and spent two decades with the agency.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[meals]</strong> <span class=\"gram\">[uncountable]</span> the meals that are provided for you when you pay to stay somewhere: → full board, half board</div><ul class=\"examples\"><li><em>In the nursing home she will have to pay for room and board.</em></li><li><em>The landlord provides board and lodging (=meals and a place to stay).</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>go by the board</strong> if an idea, way of behaving, or plan goes by the board, it fails to happen, ends, or is no longer possible:</div><ul class=\"examples\"><li><em>Loyalty has gone by the board.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[in water sports]</strong> <span class=\"gram\">[countable]</span> a surfboard or sailboard</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>across the board</strong> if something happens or is done across the board, it affects everyone in a particular group, place etc:</div><ul class=\"examples\"><li><em>The changes will affect local authorities across the board.</em></li><li><em>We find jobs for people right across the board, from chief executives to cleaners.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>take something on board</strong> to listen to and accept a suggestion, idea etc:</div><ul class=\"examples\"><li><em>The school refused to take any of the parents’ criticisms on board.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[electricity]</strong> <span class=\"gram\">[countable]</span> a circuit board</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>[theatre]</strong> <strong>the boards</strong> <span class=\"gram\">[plural]</span> the stage in a theatre → tread the boards at tread1(7)</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>[sports area]</strong> <strong>boards</strong> <span class=\"gram\">[plural]</span> <em>American English</em> the low wooden wall around the area in which you play ice hockey</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>college/medical boards</strong> <em>American English</em> examinations that you take in the US when you formally ask to be accepted as a student at a college or medical school</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> <em>formal</em> to get on a bus, plane, train etc in order to travel somewhere: RegisterIn everyday English, people usually say get on a bus, plane etc rather than board:· When she heard the news, she got on the next plane for Chicago.</div><ul class=\"examples\"><li><em>The couple boarded the train for New York.</em></li><li><em>Passengers were standing on the dock, waiting to board.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be boarding</strong> if a plane or ship is boarding, passengers are getting onto it:</div><ul class=\"examples\"><li><em>Olympic Airways Flight 172 to Istanbul is now boarding at Gate No. 37.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to stay in a room in someone’s house that you pay for:</div><ul class=\"examples\"><li><em>Several students boarded with Mrs. Smith.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> to stay at a school at night as well as during the day:</div><ul class=\"examples\"><li><em>Dickie was sent away to school as soon as he was old enough to board.</em></li></ul></div></div>","749":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊst $ boʊst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to talk too proudly about your abilities, achievements, or possessions:</div><ul class=\"examples\"><li><em>‘I wouldn’t be afraid,’ she boasted.</em></li><li><strong><em>boast that</strong>: Amy boasted that her son was a genius.</em></li><li><strong><em>boast about</strong>: He’s boasting about how much money he has made.</em></li><li><strong><em>boast of</strong>: The company is inclined to boast of its success.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive not in progressive]</span> if a place, object, or organization boasts something, it has something that is very good:</div><ul class=\"examples\"><li><em>The city boasts two excellent museums.</em></li><li><em>The Society boasts 3,000 members worldwide.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">something that you like telling people because you are proud of it:</div><ul class=\"examples\"><li><em>It is the company’s proud boast that it can deal with all a customer’s needs in one phone call.</em></li><li><em>Philip’s boast is that he started out without any outside financial backing.</em></li><li><strong><em>an empty/idle/vain boast</strong> (=a false statement that something is good or possible): ‘Making knowledge work’ is the university’s phrase, and it is no idle boast (=not a boast, but true).</em></li></ul></div></div>","750":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> boast‧ful</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbəʊstfəl $ ˈboʊst-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">talking too proudly about yourself <em>OPP modest</em></div></div>","751":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊt $ boʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a vehicle that travels across water: → lifeboat, motorboat, powerboat, speedboat, steamboat</div><ul class=\"examples\"><li><em>a fishing boat</em></li><li><em>The boat capsized (=turned over) in heavy seas.</em></li><li><em>a boat trip around the islands</em></li><li><strong><em>by boat</strong>: Some of the beaches can only be reached by boat.</em></li><li><strong><em>on/in a boat</strong>: MacKay said he would sleep on his boat.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> a ship, especially one that carries passengers:</div><ul class=\"examples\"><li><em>We’re taking the night boat to St. Malo.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be in the same boat (as somebody)</strong> to be in the same unpleasant situation as someone else:</div><ul class=\"examples\"><li><em>Everyone has lost their job. We’re all in the same boat.</em></li></ul></div>","752":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bod‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒdi $ ˈbɑːdi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(plural bodies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[people/animals]</strong> <span class=\"gram\">[countable]</span> the physical structure of a person or animal:</div><ul class=\"examples\"><li><em>the human body</em></li><li><em>My fingers were numb and my whole body ached.</em></li><li><strong><em>body weight/temperature/size</strong>: Your body temperature is higher in the daytime than at night. / For their body size, these birds lay very small eggs.</em></li><li><em>He needs to overcome a negative body image (=what you think about your own body).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[dead person]</strong> <span class=\"gram\">[countable]</span> the dead body of a person:</div><ul class=\"examples\"><li><em>A dog found the body of a girl in the woods.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[group]</strong> <span class=\"gram\">[countable]</span> a group of people who work together to do a particular job or who are together for a particular purpose: ► see thesaurus at organization</div><ul class=\"examples\"><li><em>The British Medical Association is the doctors’ professional body.</em></li><li><strong><em>body of</strong>: There were reports of a large body of armed men near the border.</em></li><li><em>Kaplan served on the governing body of the museum (=the group who control the museum).</em></li><li><em>The student body (=all the students in a school or college) numbers 5,000.</em></li><li><em>The research will be used by government departments and other public bodies (=groups whose work is connected to the government).</em></li><li><strong><em>in a body</strong> (=as a group, together): The women moved towards the building in a body.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>body of something</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a large amount or mass of something, especially something that has been collected</div><ul class=\"examples\"><li><strong><em>body of knowledge/evidence/opinion etc</strong>: There is now a considerable body of knowledge of the different stages of childhood. / There is a growing body of evidence that charges are too high.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the main, central, or most important part of something:</div><ul class=\"examples\"><li><em>The arguments are explained in the body of the text.</em></li><li><em>Leave three blank lines between the date and the body of the letter.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>body of water</strong> a large area of water such as a lake:</div><ul class=\"examples\"><li><em>The city was built near a large body of water.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[middle part]</strong> <span class=\"gram\">[countable]</span> the central part of a person or animal’s body, not including the head, arms, legs, or wings:</div><ul class=\"examples\"><li><em>Nick had bruises on his face and body.</em></li><li><em>The bird has a small body and long wings.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[vehicle]</strong> <span class=\"gram\">[countable]</span> the main structure of a vehicle not including the engine, wheels etc:</div><ul class=\"examples\"><li><em>Workers at the factory are making steel bodies for cars.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[object]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> an object that is separate from other objects: → heavenly body at heavenly(3)</div><ul class=\"examples\"><li><em>Keep the caps on the bottles to prevent foreign bodies entering them (=objects that should not be there).</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[hair]</strong> <span class=\"gram\">[uncountable]</span> if your hair has body, it is thick and healthy:</div><ul class=\"examples\"><li><em>This shampoo will give more body to your hair.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[taste]</strong> <span class=\"gram\">[uncountable]</span> if food or an alcoholic drink has body, it has a strong flavour (=taste):</div><ul class=\"examples\"><li><em>A small amount of tomato paste will give extra colour and body to the sauce.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>keep body and soul together</strong> to continue to exist with only just enough food, money etc:</div><ul class=\"examples\"><li><em>He’s working at the shop to keep body and soul together.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>body and soul</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> completely:</div><ul class=\"examples\"><li><em>She threw herself body and soul into her work.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> the whole of a person:</div><ul class=\"examples\"><li><em>They think they own the employees, body and soul.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[instrument]</strong> <span class=\"gram\">[countable]</span> the wide part of a musical instrument such as a violin or guitar, or of a sports racket (=bat):</div><ul class=\"examples\"><li><em>The guitar is 16 inches wide across the body.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[clothing]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> a type of tight-fitting shirt worn by women that fastens between their legs SYN body suit<em>American English</em></div></div>","753":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈbody ˌlanguage</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">changes in your body position and movements that show what you are feeling or thinking:</div><ul class=\"examples\"><li><em>It was obvious from Luke’s body language that he was nervous.</em></li></ul></div>","754":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bod‧y‧guard</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒdiɡɑːd $ ˈbɑːdiɡɑːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone whose job is to protect an important person:</div><ul class=\"examples\"><li><em>The senator arrived, surrounded by personal bodyguards.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a group of people who work together to protect an important person</div></div>","755":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɔɪl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> when a liquid boils, or when you boil it, it becomes hot enough to turn into gas</div><ul class=\"examples\"><li><strong><em>boil at</strong>: The solution boiled at 57.4°C.</em></li><li><em>Put the spaghetti into plenty of boiling salted water.</em></li><li><em>We were advised to boil the water before drinking it.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to cook something in boiling water: ► see thesaurus at cook</div><ul class=\"examples\"><li><em>a boiled egg</em></li><li><em>Boil the rice for 15 minutes.</em></li><li><em>She fried the chicken and put the vegetables on to boil.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> if something containing liquid boils, the liquid inside it is boiling:</div><ul class=\"examples\"><li><em>The kettle’s boiling – shall I turn it off?</em></li><li><em>The saucepan boiled dry on the stove.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to wash something, using boiling water:</div><ul class=\"examples\"><li><em>I always boil the cotton sheets.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[intransitive]</span> if you are boiling with anger, you are extremely angry</div><ul class=\"examples\"><li><strong><em>boil with</strong>: Lewis was boiling with rage and misery.</em></li></ul></div>","756":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> boil‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔɪlə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a container for boiling water that is part of a steam engine, or is used to provide heating in a house</div></div>","757":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> boil‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔɪlɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><em>spoken</em> very hot <em>OPP freezing</em>:</div><ul class=\"examples\"><li><em>Can I open a window? It’s boiling in here.</em></li><li><em>It was a boiling hot morning.</em></li></ul></div>","758":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊld $ boʊld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[person/action]</strong> not afraid of taking risks and making difficult decisions: ► see thesaurus at brave</div><ul class=\"examples\"><li><em>In a surprisingly bold move, he is threatening court action against the company.</em></li><li><em>My aunt Flo was a bold determined woman.</em></li><li><em>He had the ability to take bold imaginative decisions.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[manner/appearance]</strong> so confident or determined that you sometimes offend people:</div><ul class=\"examples\"><li><em>You should be feeling confident and bold when you meet your bank manager.</em></li><li><em>She marched into his office as bold as brass (=very confident and not showing enough respect).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[colours/shapes]</strong> very strong or bright so that you notice them:</div><ul class=\"examples\"><li><em>bold geometric shapes</em></li><li><em>Stripes are bold, bright, and fun to wear.</em></li><li><em>bold colours</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[lines/writing]</strong> written or drawn in a very clear way:</div><ul class=\"examples\"><li><em>an envelope addressed to her in a bold black hand</em></li><li><em>The graphics are bold and colourful.</em></li><li><em>The print should be bold and easy to read.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[printed letters]</strong> printed in letters that are darker and thicker than ordinary printed letters:</div><ul class=\"examples\"><li><em>All the headings are in bold type.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>make/be so bold (as to do something)</strong> <em>formal</em> to do something that other people feel is rude or not acceptable:</div><ul class=\"examples\"><li><em>I see you have been so bold as to ask for food at this hour.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>if I may be so bold</strong> <em>British English</em> <em>spoken</em> <em>formal</em> used when asking someone a question, to show that you are slightly annoyed with them:</div><ul class=\"examples\"><li><em>Tell me, if I may be so bold as to ask, precisely what you are talking about.</em></li></ul></div>","759":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bol‧ster</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbəʊlstə $ ˈboʊlstər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to help someone to feel better and more positive <em>SYN boost</em>:</div><ul class=\"examples\"><li><em>He is making a bold attempt to bolster the territory’s confidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to improve something <em>SYN boost</em>:</div><ul class=\"examples\"><li><em>his efforts to bolster his career</em></li></ul></div>","760":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊlt $ boʊlt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[lock]</strong> a metal bar that you slide across a door or window to fasten it</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[screw]</strong> a screw with a flat head and no point, for fastening things together</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bolt from/out of the blue</strong> news that is sudden and unexpected:</div><ul class=\"examples\"><li><em>Was this money a bolt from the blue or did you know you were going to get it?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>bolt of lightning</strong> lightning that appears as a white line in the sky: → thunderbolt</div><ul class=\"examples\"><li><em>There’s not much left of his house after it was struck by a bolt of lightning.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>make a bolt for it</strong> <em>British English</em> to suddenly try to escape from somewhere:</div><ul class=\"examples\"><li><em>They attacked the driver and he straightaway made a bolt for it.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[weapon]</strong> a short heavy arrow that is fired from a crossbow</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[cloth]</strong> a large long roll of cloth</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to suddenly run somewhere very quickly, especially in order to escape or because you are frightened: ► see thesaurus at run</div><ul class=\"examples\"><li><em>The horse reared up and bolted.</em></li><li><em>Kevin had bolted through the open window.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> (also bolt down) to eat very quickly <em>SYN gobble</em>:</div><ul class=\"examples\"><li><em>He bolted down his breakfast.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to fasten two things together using a bolt</div><ul class=\"examples\"><li><strong><em>bolt something to something</strong>: The cell contained an iron bedframe bolted to the floor.</em></li><li><strong><em>bolt something together</strong>: The boxes were made of heavy panels of metal bolted together.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to lock a door or window by sliding a bolt across</div></div></div>","761":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɒm $ bɑːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[weapon]</strong> a weapon made of material that will explode: → smoke bomb, stink bomb</div><ul class=\"examples\"><li><em>The bomb went off at 9.30 in the morning.</em></li><li><em>Enemy planes dropped over 200 bombs during the raid.</em></li><li><em>He was killed in a bomb explosion.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[bad performance/event]</strong> <em>American English</em> <em>informal</em> a play, film, event etc that is not successful:</div><ul class=\"examples\"><li><em>This is just another one of Hollywood’s bland and boring bombs.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be the bomb</strong> <em>informal</em> to be very good or exciting:</div><ul class=\"examples\"><li><em>That new P Diddy CD is the bomb.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the bomb</strong> used to describe nuclear weapons, and especially the hydrogen bomb:</div><ul class=\"examples\"><li><em>Voices of dissent began to rise against the bomb.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>cost a bomb</strong> <em>British English</em> <em>informal</em> to cost a lot of money</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>make a bomb</strong> <em>British English</em> <em>informal</em> to get a lot of money by doing something</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>drop the c-bomb/f-bomb</strong> <em>informal</em> to say a very rude word beginning with C or F</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to attack a place by leaving a bomb there, or by dropping bombs on it from a plane: → carpet-bomb, dive-bomb</div><ul class=\"examples\"><li><em>The town was heavily bombed in World War II.</em></li><li><em>Government aircraft have been bombing civilian areas.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>British English</em> <em>informal</em> to move or drive very quickly:</div><ul class=\"examples\"><li><em>Suddenly a police car came bombing down the high street.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> <em>American English</em> <em>informal</em> to fail a test very badly:</div><ul class=\"examples\"><li><em>I bombed my midterm.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> <em>American English</em> if a play, film, event etc bombs, it is not successful:</div><ul class=\"examples\"><li><em>His latest play bombed on Broadway.</em></li></ul></div></div>","762":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bom‧bard</span><span class=\"meta-item\"><strong>IPA:</strong> /bɒmˈbɑːd $ bɑːmˈbɑːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to attack a place for a long time using large weapons, bombs etc: ► see thesaurus at shoot</div><ul class=\"examples\"><li><em>I had been in action, bombarding the Normandy coast.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to do something too often or too much, for example criticizing or questioning someone, or giving too much information:</div><ul class=\"examples\"><li><em>The office was bombarded by telephone calls.</em></li><li><strong><em>bombard somebody with something</strong>: They bombarded him with questions. / Today we are bombarded with advice on what to eat and what to avoid.</em></li></ul></div>","763":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bomb‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒmə $ ˈbɑːmər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a plane that carries and drops bombs</div><div class=\"sense\"><span class=\"snum\">2</span> someone who hides a bomb somewhere in order to destroy something</div></div>","764":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bomb‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒmɪŋ $ ˈbɑːm-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the use of bombs to attack a place:</div><ul class=\"examples\"><li><em>The southwest of the country suffered an intensive bombing campaign.</em></li><li><em>They were planning bombing raids in some of America’s major cities.</em></li><li><em>a terrorist network responsible for a wave of bombings in Paris</em></li><li><strong><em>bombing of</strong>: the bombing of Hiroshima</em></li></ul></div>","765":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɒnd $ bɑːnd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[money]</strong> an official document promising that a government or company will pay back money that it has borrowed, often with interest: → see also junk bond, premium bond, savings bond</div><ul class=\"examples\"><li><em>My father put all his money into stock market bonds.</em></li><li><em>furious trading on the bond market</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[relationship]</strong> something that unites two or more people or groups, such as love, or a shared interest or idea → tie</div><ul class=\"examples\"><li><strong><em>bond between</strong>: the emotional bond between mother and child</em></li><li><strong><em>bond with</strong>: the United States’ special bond with Britain</em></li><li><strong><em>bond of</strong>: lifelong bonds of friendship</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>bonds</strong> <span class=\"gram\">[plural]</span> <em>literary</em> something that limits your freedom and prevents you from doing what you want</div><ul class=\"examples\"><li><strong><em>bond of</strong>: the bonds of fear and guilt</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[with glue]</strong> the way in which two surfaces become attached to each other using glue:</div><ul class=\"examples\"><li><em>Use a glue gun to form a strong bond on wood or china.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[chemistry]</strong> <em>technical</em> the chemical force that holds atoms together in a molecule:</div><ul class=\"examples\"><li><em>In each methane molecule there are four CH bonds.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[written agreement]</strong> a written agreement to do something, that makes you legally responsible for doing it → contract</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>my word is my bond</strong> <em>formal</em> used to say that you will definitely do what you have promised</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>in/out of bond</strong> <em>technical</em> in or out of a bonded warehouse</div></div>","766":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊn $ boʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> one of the hard parts that together form the frame of a human, animal, or fish body:</div><ul class=\"examples\"><li><em>The X-ray showed that the bone was broken in two places.</em></li><li><strong><em>hip/leg/cheek etc bone</strong> (=the bone in your hip etc): He broke his collar bone.</em></li><li><strong><em>big-boned/fine-boned/small-boned etc</strong> (=with big etc bones): She was tall and big-boned.</em></li><li><em>Amelia had inherited her mother’s good bone structure.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a substance made of bones:</div><ul class=\"examples\"><li><em>the bone handle of his dagger</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the bare bones</strong> the simplest and most important details of something:</div><ul class=\"examples\"><li><em>I can’t tell you more than the bare bones of what happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>make no bones about (doing) something</strong> to not feel nervous or ashamed about doing or saying something:</div><ul class=\"examples\"><li><em>Mary made no bones about enjoying a drink.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>bone of contention</strong> something that causes arguments between people:</div><ul class=\"examples\"><li><em>The examination system has long been a serious bone of contention in this country.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be chilled/frozen to the bone</strong> to be extremely cold</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>skin and bone</strong> very thin:</div><ul class=\"examples\"><li><em>She was all skin and bone.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>a bag of bones</strong> someone who is much too thin</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>feel/know something in your bones</strong> to be certain that something is true, even though you have no proof and cannot explain why you are certain:</div><ul class=\"examples\"><li><em>She knew that something good was sure to happen; she could feel it in her bones.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>have a bone to pick with somebody</strong> <em>spoken</em> used to tell someone that you are annoyed with them and want to talk about it</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>close to the bone</strong> a remark, statement etc that is close to the bone is close to the truth in a way that may offend someone:</div><ul class=\"examples\"><li><em>His jokes were a bit close to the bone.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>cut something to the bone</strong> to reduce costs, services etc as much as possible:</div><ul class=\"examples\"><li><em>Shops cut prices to the bone in the January sales.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>on the bone</strong> meat that is served on the bone is still joined to the bone:</div><ul class=\"examples\"><li><em>a boiled ham on the bone</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>off the bone</strong> meat that is served off the bone has been cut away from the bone:</div><ul class=\"examples\"><li><em>roasted duck, off the bone</em></li></ul></div>","767":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bo‧nus</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbəʊnəs $ ˈboʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> money added to someone’s wages, especially as a reward for good work:</div><ul class=\"examples\"><li><em>Long-term savers qualify for a cash bonus.</em></li><li><em>Further additions to your pay may take the form of bonus payments.</em></li><li><em>a Christmas bonus</em></li><li><em>Each worker receives an annual bonus.</em></li><li><em>a £20,000 bonus</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something good that you did not expect in a situation</div><ul class=\"examples\"><li><strong><em>bonus for</strong>: Britain’s possession of North Sea oil has proved a bonus for British technology.</em></li><li><em>He promised to take me to the match, with the added bonus of an afternoon off school.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>no-claims bonus</strong> <em>British English</em> a reduction in the cost of your car insurance when you do not make a claim in a particular year</div></div>","768":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʊk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[printed pages]</strong> <span class=\"gram\">[countable]</span> a set of printed pages that are held together in a cover so that you can read them:</div><ul class=\"examples\"><li><em>I’ve just started reading a book by Graham Greene.</em></li><li><em>a cookery book</em></li><li><strong><em>book about/on</strong>: a book about cats</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[to write in]</strong> <span class=\"gram\">[countable]</span> a set of sheets of paper held together in a cover so that you can write on them:</div><ul class=\"examples\"><li><em>a black address book</em></li><li><em>a notebook</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[set of things]</strong> <span class=\"gram\">[countable]</span> a set of things such as stamps, matches, or tickets, held together inside a paper cover:</div><ul class=\"examples\"><li><em>a cheque book</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>books</strong> <span class=\"gram\">[plural]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>[accounts]</strong> written records of the financial accounts of a business: → cook the books at cook1(3)</div><ul class=\"examples\"><li><em>An accountant will examine the company’s books.</em></li><li><em>a small firm that is having problems balancing the books (=keeping its profits and spending equal)</em></li><li><strong><em>on the books</strong>: They have £50 billion worth of orders on the books.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>[jobs]</strong> the names of people who use a company’s services, or who are sent by a company to work for other people</div><ul class=\"examples\"><li><strong><em>on somebody’s books</strong>: an agent with a lot of popular actors on his books</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>by the book</strong> exactly according to rules or instructions:</div><ul class=\"examples\"><li><em>She feels she has to go by the book and can’t use her creativity.</em></li><li><strong><em>do/play something by the book</strong>: The police were careful to do everything by the book.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>a closed book</strong> a subject that you do not understand or know anything about:</div><ul class=\"examples\"><li><em>Chemistry is a closed book to me.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be in somebody’s good/bad books</strong> <em>informal</em> used to say that someone is pleased or annoyed with you</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[law]</strong> <strong>be on the books</strong> if a law is on the books, it is part of the set of laws in a country, town, area etc</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[part of a book]</strong> <span class=\"gram\">[countable]</span> one of the parts that a very large book such as the Bible is divided into</div><ul class=\"examples\"><li><strong><em>book of</strong>: the Book of Isaiah</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>in my book</strong> <em>spoken</em> said when giving your opinion:</div><ul class=\"examples\"><li><em>In my book, nothing is more important than football.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>bring somebody to book</strong> to punish someone for breaking laws or rules, especially when you have been trying to punish them for a long time:</div><ul class=\"examples\"><li><em>War criminals must be brought to book.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to make arrangements to stay in a place, eat in a restaurant, go to a theatre etc at a particular time in the future → reserve:</div><ul class=\"examples\"><li><em>Have you booked a holiday this year?</em></li><li><em>The flight was already fully booked (=no more seats were available).</em></li><li><em>To get tickets, you have to book in advance.</em></li><li><em>The show’s booked solid (=all the tickets have been sold) until February.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to arrange for someone such as a singer to perform on a particular date:</div><ul class=\"examples\"><li><em>The band was booked for a benefit show in Los Angeles.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be booked up</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a hotel, restaurant etc is booked up, there are no more rooms, places, seats etc still available:</div><ul class=\"examples\"><li><em>The courses quickly get booked up.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if someone is booked up, they are extremely busy and have arranged a lot of things they must do:</div><ul class=\"examples\"><li><em>I’m all booked up this week – can we get together next Friday?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> to arrange for someone to go to a hotel, fly on a plane etc:</div><ul class=\"examples\"><li><em>I’ve booked you a flight on Saturday.</em></li><li><strong><em>book somebody on/in etc</strong>: I’ll book you in at the Hilton.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to put someone’s name officially in police records, along with the charge made against them:</div><ul class=\"examples\"><li><em>Smith was booked on suspicion of attempted murder.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[transitive]</span> <em>British English</em> when a referee in a sports game books a player who has broken the rules, he or she officially writes down the player’s name in a book as a punishment</div></div></div>","769":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> book‧case</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊk-keɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of furniture with shelves to hold books</div></div>","770":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> book‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊkɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an arrangement to travel by train, use a hotel room etc at a particular time in the future → reservation:</div><ul class=\"examples\"><li><em>bookings on cruise ships</em></li><li><em>I made a booking for two double rooms.</em></li><li><em>I’m calling to confirm my booking (=say definitely that I want to travel etc).</em></li><li><em>If you cancel your booking, there will be a small charge.</em></li><li><em>Places on the course are limited and advance booking is essential.</em></li><li><strong><em>block booking</strong> (=a booking for a large number of dates, seats, rooms etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an arrangement made by a performer to perform at a particular time in the future</div><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> the act of writing a football player’s name in a book as a punishment for breaking the rules</div></div>","771":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> book‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊklɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a very short book that usually contains information on one particular subject → leaflet:</div><ul class=\"examples\"><li><em>a free booklet on drug abuse</em></li></ul></div>","772":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> book‧shelf</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊkʃelf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural bookshelves /-ʃelvz/)</span></div><div class=\"entry-body\"><div class=\"sense\">a shelf that you keep books on, or a piece of furniture used for holding books → bookcase</div></div>","773":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> book‧shop</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊkʃɒp $ -ʃɑːp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>especially British English</em> a shop that sells books SYN bookstore<em>American English</em></div></div>","774":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /buːm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[increase in business]</strong> <span class=\"gram\">[singular]</span> a quick increase of business activity <em>OPP slump</em>: → boom town</div><ul class=\"examples\"><li><em>The boom has created job opportunities.</em></li><li><strong><em>boom in</strong>: a sudden boom in the housing market</em></li><li><strong><em>consumer/investment/property etc boom</strong>: the post-war property boom</em></li><li><strong><em>boom years/times</strong>: In boom times, airlines do well.</em></li><li><em>the economic boom of the 1950s</em></li><li><em>The economy went from boom to bust (=from increasing to decreasing) very quickly.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[when something is popular]</strong> <span class=\"gram\">[singular]</span> an increase in how popular or successful something is, or in how often it happens: → baby boom</div><ul class=\"examples\"><li><em>the disco boom of the 1970s</em></li><li><strong><em>boom in</strong>: the boom in youth soccer in the U.S.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[sound]</strong> <span class=\"gram\">[countable]</span> a deep loud sound that you can hear for several seconds after it begins, especially the sound of an explosion or a large gun → sonic boom ► see thesaurus at sound</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[boat]</strong> <span class=\"gram\">[countable]</span> a long pole on a boat that is attached to the bottom of a sail, and that you move to change the position of the sail</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[long pole]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a long pole used as part of a piece of equipment that loads and unloads things</div><div class=\"subsense\"><span class=\"subnum\">b)</span> a long pole that has a camera or microphone on the end</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[on a river/harbour]</strong> <span class=\"gram\">[countable]</span> something that is stretched across a river or a bay to prevent things floating down or across it</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive usually in progressive]</span> if business, trade, or a particular area is booming, it is increasing and being very successful:</div><ul class=\"examples\"><li><em>Business was booming, and money wasn’t a problem.</em></li><li><em>Tourism on the island has boomed.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also boom out) <span class=\"gram\">[transitive]</span> to say something in a loud deep voice:</div><ul class=\"examples\"><li><em>‘Ladies and gentlemen,’ his voice boomed out.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (also boom out) <span class=\"gram\">[intransitive]</span> to make a loud deep sound:</div><ul class=\"examples\"><li><em>Guns boomed in the distance.</em></li></ul></div></div>","775":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /buːst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to increase or improve something and make it more successful: ► see thesaurus at increase</div><ul class=\"examples\"><li><em>The new resort area has boosted tourism.</em></li><li><strong><em>boost somebody’s confidence/morale/ego</strong>: The win boosted the team’s confidence.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also boost up) to help someone reach a higher place by lifting or pushing them:</div><ul class=\"examples\"><li><em>He boosted her up.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> if a rocket or motor boosts a spacecraft, it makes it go up into space or go in a particular direction</div><div class=\"sense\"><span class=\"snum\">4</span> <em>American English</em> <em>informal</em> to steal something</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> something that gives someone more confidence, or that helps something increase, improve, or become successful</div><ul class=\"examples\"><li><strong><em>boost to</strong>: a major boost to the economy</em></li><li><strong><em>boost for</strong>: a multimillion-pound boost for the British film industry</em></li><li><em>Add a little more vanilla, to give the flavor a boost.</em></li><li><strong><em>get/receive a boost</strong>: The community will get a boost from a new library and recreation center.</em></li><li><strong><em>morale/ego boost</strong>: The poll provided a morale boost for the Conservatives.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>give somebody a boost (up)</strong> to lift someone so that they can reach a higher place:</div><ul class=\"examples\"><li><em>If I give you a boost, could you reach the window?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> an increase in the amount of power available to a rocket, piece of electrical equipment etc</div></div></div>","776":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /buːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a type of shoe that covers your whole foot and the lower part of your leg → Wellington: → rubber boot</div><ul class=\"examples\"><li><em>hiking boots</em></li><li><em>a pair of boots</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>British English</em> an enclosed space at the back of a car, used for carrying bags etc SYN trunk<em>American English</em>:</div><ul class=\"examples\"><li><em>The new model has a bigger boot.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the boot</strong> <em>informal</em> when someone is forced to leave their job SYN the sack<em>British English</em> → dismiss:</div><ul class=\"examples\"><li><em>The chairman denied that he had been given the boot.</em></li><li><em>He should have got the boot years ago.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>to boot</strong> in addition to everything else you have mentioned:</div><ul class=\"examples\"><li><em>She was a great sportswoman, and beautiful to boot.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>put the boot in</strong> <em>British English</em> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to criticize or be cruel to someone who is already in a bad situation</div><div class=\"subsense\"><span class=\"subnum\">b)</span> to attack someone by kicking them repeatedly, especially when they are on the ground</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>the boot is on the other foot</strong> <em>British English</em> used to say someone who has caused problems for other people in the past is now in a situation in which people are causing problems for them</div><div class=\"sense\"><span class=\"snum\">7</span> <em>American English</em> a metal object that the police attach to one of the wheels of an illegally parked car so that it cannot be moved SYN wheel clamp<em>British English</em></div><div class=\"sense\"><span class=\"snum\">8</span> <strong>boots on the ground</strong> soldiers present somewhere taking military action, or prepared to take military action</div></div>","777":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /buːð $ buːθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small partly enclosed place where one person can do something privately, such as use the telephone or vote:</div><ul class=\"examples\"><li><em>a voting booth</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small partly enclosed structure where you can buy things, play games, or get information, usually at a market or a fair:</div><ul class=\"examples\"><li><em>a crafts booth</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a partly enclosed place in a restaurant, with a table between two long seats</div></div>","778":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bor‧der</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔːdə $ ˈbɔːrdər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the official line that separates two countries, states, or areas, or the area close to this line:</div><ul class=\"examples\"><li><em>To cross the border, you will need a valid passport.</em></li><li><strong><em>border between</strong>: the border between the US and Mexico</em></li><li><strong><em>border with</strong>: regular patrols along the border with France</em></li><li><strong><em>on the border</strong>: a market town on the border of England and Wales</em></li><li><strong><em>across the border</strong>: He helped them to get across the border.</em></li><li><strong><em>south/north etc of the border</strong>: The coach took us south of the border to Tijuana.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a band along or around the edge of something such as a picture or piece of material:</div><ul class=\"examples\"><li><em>writing paper with a black border</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an area of soil where you plant flowers or bushes, along the edge of an area of grass:</div><ul class=\"examples\"><li><em>a flower and shrub border</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> something that separates one situation, state etc from another:</div><ul class=\"examples\"><li><em>new scientific discoveries that are stretching the borders of knowledge</em></li></ul></div>","779":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bor‧der‧line</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔːdəlaɪn $ ˈbɔːrdər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very close to not being acceptable:</div><ul class=\"examples\"><li><em>In borderline cases, the student’s coursework is considered, as well as exam grades.</em></li><li><em>The referee’s decision was borderline.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[usually before noun]</span> having qualities of both one situation, state etc and another more extreme situation or state:</div><ul class=\"examples\"><li><em>a borderline schizophrenic (=someone who has some signs of being mentally ill)</em></li></ul></div>","780":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to make someone feel bored, especially by talking too much about something they are not interested in:</div><ul class=\"examples\"><li><em>He’s the sort of person who bores you at parties.</em></li><li><em>a film that will bore its young audience</em></li><li><strong><em>bore somebody with something</strong>: I won’t bore you with all the technical details.</em></li><li><strong><em>bore somebody to death/tears</strong> (=make them very bored)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to make a deep round hole in a hard surface ► see thesaurus at dig</div><ul class=\"examples\"><li><strong><em>bore something through/into/in something</strong>: The machine bores a hole through the cards.</em></li><li><strong><em>bore through/into</strong>: To build the tunnel they had to bore through solid rock.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive + into]</span> if someone’s eyes bore into you, they look at you in a way that makes you feel uncomfortable</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[singular]</span> something that is not interesting to you or that annoys you:</div><ul class=\"examples\"><li><em>Waiting is a bore.</em></li><li><em>You’ll find it’s a terrible bore.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> someone who is boring, especially because they talk too much about themselves or about things that do not interest you:</div><ul class=\"examples\"><li><em>He turned out to be a crashing bore (=used to emphasize that someone is very boring).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[singular]</span> the measurement of the width of the inside of a long hollow object such as a pipe or the barrel of a gun:</div><ul class=\"examples\"><li><em>Take a length of piping with a bore of about 15 mm.</em></li><li><strong><em>12-/16-/20- etc bore</strong>: a 12-bore shotgun</em></li><li><strong><em>wide-/narrow-/fine- bore</strong>: a fine-bore tube</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[singular]</span> a wave of water that moves quickly along a river from the sea at particular times of the year:</div><ul class=\"examples\"><li><em>the Severn bore</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a borehole</div></div></div>","781":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɔːd $ bɔːrd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\">tired and impatient because you do not think something is interesting, or because you have nothing to do:</div><ul class=\"examples\"><li><em>He was easily bored.</em></li><li><em>After a while, I got bored and left.</em></li><li><strong><em>bored with</strong>: Are you bored with your present job?</em></li><li><strong><em>bored stiff/to tears/to death/out of your mind</strong> (=extremely bored)</em></li></ul></div>","782":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bore‧dom</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔːdəm $ ˈbɔːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the feeling you have when you are bored, or the quality of being boring:</div><ul class=\"examples\"><li><em>a game to relieve the boredom of a long journey</em></li><li><em>the sheer boredom of being in jail</em></li><li><strong><em>boredom with</strong>: his boredom with life in a small town</em></li></ul></div>","783":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bor‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔːrɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\">not interesting in any way:</div><ul class=\"examples\"><li><em>Her husband is about the most boring person I’ve ever met.</em></li><li><em>The job was dull and boring.</em></li><li><strong><em>dead/incredibly/terribly etc boring</strong> (=very boring)</em></li></ul></div>","784":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>be born</strong> when a person or animal is born, they come out of their mother’s body or out of an egg: ► Don’t say ‘I born’, ‘I have been born’, or ‘I am born’. Say I was born: I was born in Pakistan.</div><ul class=\"examples\"><li><em>Forty lambs were born this spring.</em></li><li><strong><em>born in</strong>: Swift was born in 1667.</em></li><li><strong><em>born at</strong>: Then, most babies were born at home.</em></li><li><strong><em>born on</strong>: I was born on December 15th, 1973.</em></li><li><strong><em>be born into/to/of something</strong> (=be born in a particular situation, type of family etc): One third of all children are born into single-parent families.</em></li><li><strong><em>be born with something</strong> (=have a particular disease, type of character etc since birth): Jenny was born with a small hole in her heart.</em></li><li><em>I was born and raised (=was born and grew up) in Alabama.</em></li><li><strong><em>be born blind/deaf etc</strong> (=be blind, deaf etc when born)</em></li><li><em>a newly-born baby</em></li><li><em>the queen’s firstborn son</em></li><li><strong><em>be born lucky/unlucky etc</strong> (=always be lucky, unlucky etc)</em></li><li><strong><em>Australian/French etc born</strong> (=born in or as a citizen of Australia etc)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[start existing]</strong> <strong>be born</strong> something that is born starts to exist:</div><ul class=\"examples\"><li><em>the country where the sport of cricket was born</em></li><li><strong><em>born (out) of</strong> (=as a result of a particular situation): The alliance was born of necessity in 1941. / Bill spoke with a cynicism born of bitter experience.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>born and bred</strong> born and having grown up in a particular place and having the typical qualities of someone from that place:</div><ul class=\"examples\"><li><em>I was born and bred in Liverpool.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be born to do/be something</strong> to be very suitable for a particular job, activity etc:</div><ul class=\"examples\"><li><em>He was born to be a politician.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>I wasn’t born yesterday</strong> <em>spoken</em> used to tell someone you think is lying to you that you are not stupid enough to believe them</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>there’s one born every minute</strong> <em>spoken</em> used to say that someone has been very stupid or easily deceived</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>be born under a lucky/unlucky star</strong> to always have good or bad luck in your life</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>be born with a silver spoon in your mouth</strong> to be born into a rich family → natural-born</div></div>","785":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bor‧row</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒrəʊ $ ˈbɑːroʊ, ˈbɔː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to use something that belongs to someone else and that you must give back to them later → lend, loan: ► Do not confuse borrow and lend (=give someone permission to use something of yours): I borrowed his bike. | Can you lend me your pen?</div><ul class=\"examples\"><li><em>Can I borrow your pen for a minute?</em></li><li><strong><em>borrow something from somebody</strong>: You are allowed to borrow six books from the library at a time.</em></li><li><em>They borrowed heavily (=borrowed a lot of money) from the bank to start their new business.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to take or copy someone’s ideas, words etc and use them in your own work, language etc</div><ul class=\"examples\"><li><strong><em>borrow something from somebody/something</strong>: I borrowed my ideas from Eliot’s famous poem ‘The Waste Land’.</em></li><li><em>To borrow a phrase (=use what someone else has said), if you can’t stand the heat, get out of the kitchen.</em></li><li><strong><em>borrow from</strong>: English has borrowed words from many languages.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>borrow trouble</strong> <em>American English</em> <em>informal</em> to worry about something when it is not necessary</div></div>","786":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɒs $ bɒːs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the person who employs you or who is in charge of you at work → employer, manager, supervisor:</div><ul class=\"examples\"><li><em>I’ll have to ask my boss for a day off.</em></li><li><em>Since I’m my own boss (=I work for myself, rather than for an employer), my hours are flexible.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>informal</em> someone with an important position in a company or other organization:</div><ul class=\"examples\"><li><em>the new boss at Paramount Pictures</em></li><li><em>union bosses</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the person who is the strongest in a relationship, who controls a situation etc:</div><ul class=\"examples\"><li><em>When you first start training a dog, it’s important to let him see that you’re the boss.</em></li><li><em>You’ve got to show the kids who’s boss.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a round decoration on the surface of something, for example on the ceiling of an old building</div></div>","787":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> boss‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒsi $ ˈbɒːsi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(comparative bossier, superlative bossiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> always telling other people what to do, in a way that is annoying:</div><ul class=\"examples\"><li><em>her loud bossy sister</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bossy-boots</strong> <em>British English</em> <em>informal</em> someone who you think tells other people what to do too often</div></div>","788":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊθ $ boʊθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to talk about two people, things etc together, and emphasize that each is included → either:</div><ul class=\"examples\"><li><em>Both Helen’s parents are doctors.</em></li><li><em>Hold it in both hands.</em></li><li><em>You can both swim, can’t you?</em></li><li><em>They both started speaking together.</em></li><li><em>Oxford is not far from Stratford, so you can easily visit both in a day.</em></li><li><strong><em>both of</strong>: Both of my grandfathers are farmers.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>somebody can’t have it both ways</strong> used to say that someone cannot have the advantages that come from two separate situations because they cannot exist together:</div><ul class=\"examples\"><li><em>It’s either me or her. You can’t have it both ways.</em></li></ul></div>","789":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> both‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒðə $ ˈbɑːðər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[make an effort]</strong> <span class=\"gram\">[intransitive, transitive usually in questions and negatives]</span> to make the effort to do something</div><ul class=\"examples\"><li><strong><em>(not) bother to do something</strong>: He didn’t bother to answer the question.</em></li><li><strong><em>not bother about/with</strong>: He didn’t bother with a reply.</em></li><li><strong><em>(not) bother doing something</strong>: Many young people didn’t bother voting.</em></li><li><strong><em>don’t/didn’t/won’t etc bother</strong>: ‘Do you want me to wait for you?’ ‘No, don’t bother.’</em></li><li><em>Why bother to go abroad, when there are so many nice places here?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[worry]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make someone feel slightly worried, upset, or concerned:</div><ul class=\"examples\"><li><em>Being in a crowd really bothers me.</em></li><li><em>It was very noisy, but that didn’t bother me.</em></li><li><strong><em>bother about<em>especially British English</em></strong>: I try not to bother about what other people think.</em></li><li><strong><em>it bothers somebody that/how/when</strong>: It really bothered me that he’d forgotten my birthday.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[annoy]</strong> <span class=\"gram\">[intransitive, transitive]</span> to annoy someone, especially by interrupting them when they are trying to do something:</div><ul class=\"examples\"><li><em>Danny, don’t bother Ellen while she’s reading.</em></li><li><em>Would it bother you if I put on some music?</em></li><li><strong><em>bother somebody about/with something</strong>: It didn’t seem worth bothering the doctor about.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>somebody can’t/couldn’t be bothered (to do something)</strong> <em>especially British English</em> used to say that you do not want to make the effort to do something, or that you are not interested in doing something:</div><ul class=\"examples\"><li><em>It was so hot I couldn’t be bothered to cook.</em></li><li><em>I should be revising, but I just can’t be bothered.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[cause pain]</strong> <span class=\"gram\">[transitive]</span> if a part of your body bothers you, it is slightly painful or uncomfortable:</div><ul class=\"examples\"><li><em>My back’s been bothering me.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>sorry to bother you</strong> <em>spoken</em> used as a very polite way of interrupting someone when you want their attention:</div><ul class=\"examples\"><li><em>Sorry to bother you, but Mr. Grey is on the line.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[frighten]</strong> <span class=\"gram\">[transitive]</span> to upset or frighten someone by talking to them when they do not want to talk to you, trying to hurt them, touch them sexually etc:</div><ul class=\"examples\"><li><em>Don’t worry – my dog won’t bother you.</em></li><li><em>If he starts bothering you, let me know.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>not bother yourself/not bother your head</strong> to not spend time or effort on something, either because it is not important or because it is too difficult</div><ul class=\"examples\"><li><strong><em>bother with/about</strong>: Cliff didn’t want to bother himself with details.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bother it/them etc</strong> <em>British English</em> <em>spoken</em> <em>old-fashioned</em> used to express a sudden feeling of annoyance about something:</div><ul class=\"examples\"><li><em>Oh bother it! The thread’s broken again!</em></li></ul></div>","790":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bot‧tle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒtl $ ˈbɑːtl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a container with a narrow top for keeping liquids in, usually made of plastic or glass:</div><ul class=\"examples\"><li><em>an empty bottle</em></li><li><strong><em>a wine/milk/beer etc bottle</em></strong></li><li><strong><em>bottle of</strong>: a bottle of champagne</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> (also bottleful) the amount of liquid that a bottle contains:</div><ul class=\"examples\"><li><em>Between us, we drank three bottles of wine.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a container for babies to drink from, with a rubber part on top that they suck, or the milk contained in this bottle:</div><ul class=\"examples\"><li><em>My first baby just wouldn’t take a bottle at all.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>the bottle</strong> alcoholic drink – used when talking about the problems drinking can cause:</div><ul class=\"examples\"><li><em>Peter let the bottle ruin his life.</em></li><li><strong><em>hit the bottle</strong> (=regularly drink too much): She was under a lot of stress, and started hitting the bottle.</em></li><li><strong><em>be on the bottle<em>British English</em></strong> (=be drinking a lot of alcohol regularly)</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[uncountable]</span> <em>British English</em> <em>informal</em> courage to do something that is dangerous or unpleasant <em>SYN nerve</em>:</div><ul class=\"examples\"><li><em>I never thought she’d have the bottle to do it!</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>bring a bottle</strong> <em>British English</em>, bring your own bottle<em>American English</em> used when you invite someone to an informal party, to tell them that they should bring their own bottle of alcoholic drink</div></div>","791":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bot‧tom</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒtəm $ ˈbɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[lowest part]</strong> <strong>the bottom</strong> the lowest part of something <em>OPP the top</em></div><ul class=\"examples\"><li><strong><em>bottom of</strong>: Can you hold the bottom of the ladder for me?</em></li><li><strong><em>at the bottom (of something)</strong>: Grandma was standing at the bottom of the stairs. / at the bottom of the page / Go downstairs and wait for me at the bottom.</em></li><li><strong><em>the bottom of the page/screen</strong>: There should be a menu bar at the bottom of your screen.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[lowest side]</strong> <span class=\"gram\">[countable usually singular]</span> the flat surface on the lowest side of an object</div><ul class=\"examples\"><li><strong><em>the bottom of something</strong>: What’s that on the bottom of your shoe?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[lowest inner part]</strong> <span class=\"gram\">[countable usually singular]</span> the lowest inner surface of something such as a container</div><ul class=\"examples\"><li><strong><em>at/in the bottom of something</strong>: I found the keys – they were at the bottom of my handbag.</em></li><li><em>The drugs had been hidden in a suitcase with a false bottom.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[lowest social position/rank]</strong> <strong>the bottom</strong> the lowest position in an organization or company <em>OPP the top</em></div><ul class=\"examples\"><li><strong><em>bottom of</strong>: The Giants are at the bottom of the league.</em></li><li><strong><em>the bottom of the ladder/pile/heap</strong> (=the lowest position in society, an organization etc): Immigrants were at the bottom of the pile.</em></li><li><em>Higgins had started at the bottom (=in a low position in a company) and worked his way up to become managing director.</em></li><li><strong><em>second/third etc from bottom</strong>: United currently lie second from bottom of the Premier League.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[ocean/river]</strong> <strong>the bottom</strong> the ground under a sea, river etc, or the flat land in a valley</div><ul class=\"examples\"><li><strong><em>bottom of</strong>: The bottom of the pool is very slippery.</em></li><li><strong><em>at/on the bottom (of something)</strong>: A body was found at the bottom of the canal.</em></li><li><strong><em>the sea/river bottom</strong>: fish living on the sea bottom</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[body]</strong> <span class=\"gram\">[countable]</span> the part of your body that you sit on <em>SYN backside</em>:</div><ul class=\"examples\"><li><em>I just sat on my bottom and slid down.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[clothes]</strong> <span class=\"gram\">[countable usually plural]</span> the part of a set of clothes that you wear on the lower part of your body:</div><ul class=\"examples\"><li><em>pyjama bottoms</em></li><li><em>a blue bikini bottom</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[furthest part]</strong> <strong>the bottom of a road/garden etc</strong> <em>especially British English</em> the part of a road, area of land etc that is furthest from where you are:</div><ul class=\"examples\"><li><em>There’s a shop at the bottom of the street.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>get to the bottom of something</strong> to find out the cause of a problem or situation:</div><ul class=\"examples\"><li><em>I never got to the bottom of this!</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be/lie at the bottom of something</strong> to be the basic cause of a problem or situation:</div><ul class=\"examples\"><li><em>Lack of money is at the bottom of many family problems.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be at/hit/reach rock bottom</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be in a very bad situation that could not be any worse:</div><ul class=\"examples\"><li><em>I was at rock bottom, and knew I had to try and stop drinking.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to be at a very low level:</div><ul class=\"examples\"><li><em>We bought the house when prices were at rock bottom.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>from the bottom of your heart</strong> in a very sincere way:</div><ul class=\"examples\"><li><em>Thank you from the bottom of my heart.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>the bottom drops/falls out of the market</strong> when people stop buying a particular product, so that the people who sell it can no longer make any money</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>bottoms up!</strong> <em>spoken</em> used to tell someone to enjoy or finish their alcoholic drink</div><div class=\"sense\"><span class=\"snum\">15</span> <strong>big-bottomed/round-bottomed etc</strong> having a bottom or base that is big, round etc</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>at bottom</strong> <em>formal</em> the way a person or situation really is, although they may seem different:</div><ul class=\"examples\"><li><em>She’s a good kind person at bottom.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[only before noun]</span> in the lowest place or position <em>OPP top</em>:</div><ul class=\"examples\"><li><em>It’s on the bottom shelf.</em></li><li><em>The towels are in the bottom drawer.</em></li><li><em>You’ve got some butter on your bottom lip.</em></li><li><em>the bottom right-hand corner of the page</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[not before noun]</span> the least important, successful etc <em>OPP top</em>:</div><ul class=\"examples\"><li><em>I was bottom of the class (=the least successful student) in Spanish.</em></li><li><em>Britain came bottom on efforts to tackle pollution and global warming.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[only before noun]</span> <em>especially British English</em> in the place furthest away from where you are:</div><ul class=\"examples\"><li><em>the bottom field</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>bottom gear</strong> the lowest gear of a vehicle</div></div></div>","792":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baʊns/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[ball/object]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a ball or other object bounces, or you bounce it, it immediately moves up or away from a surface after hitting it</div><ul class=\"examples\"><li><strong><em>bounce off</strong>: The ball bounced off the post and into the goal.</em></li><li><strong><em>bounce something on/against etc something</strong>: The kids were bouncing a ball against the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[jump up and down]</strong> <span class=\"gram\">[intransitive]</span> to move up and down, especially because you are hitting a surface that is made of rubber, has springs etc ► see thesaurus at jump</div><ul class=\"examples\"><li><strong><em>bounce on</strong>: Lyn was bouncing on the trampoline.</em></li><li><em>Stop bouncing up and down on the sofa.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[cheque]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a cheque bounces, or if a bank bounces a cheque, the bank will not pay any money because there is not enough money in the account of the person who wrote it</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[walk]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to walk quickly and with a lot of energy:</div><ul class=\"examples\"><li><em>Olivia came bouncing into the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[something moves up and down]</strong> <span class=\"gram\">[intransitive]</span> if something bounces, it moves quickly up and down as you move:</div><ul class=\"examples\"><li><em>Her hair bounced when she walked.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[light/sound]</strong> <span class=\"gram\">[intransitive, transitive]</span> if light or sound bounces, it hits a surface and then moves quickly away from it</div><ul class=\"examples\"><li><strong><em>bounce (something) off something</strong>: The radio signals are bounced off a satellite.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[email]</strong> (also bounce back) <span class=\"gram\">[intransitive, transitive]</span> if an email that you send bounces or is bounced, it is returned to you and the other person does not receive it because of a technical problem</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>bounce ideas off somebody</strong> to talk about your ideas with someone in order to get their opinion:</div><ul class=\"examples\"><li><em>When you work in a team you can bounce your ideas off each other.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[force somebody to leave]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to force someone to leave a place, job, or organization, especially because they have done something wrong</div><ul class=\"examples\"><li><strong><em>bounce somebody from something</strong>: Taylor was bounced from the team for assaulting another player.</em></li></ul></div>","793":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[no comparative]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[likely]</strong> <strong>be bound to</strong> to be very likely to do or feel a particular thing: RegisterBound to is used mainly in spoken English. In written English, people usually use certain to, it is inevitable that instead: Mistakes are bound to happen. ➔ It is inevitable that mistakes will happen.</div><ul class=\"examples\"><li><em>Don’t lie to her. She’s bound to find out.</em></li><li><strong><em>it is bound to be</strong> (=used to say that something should have been expected): ‘It’s hot!’ ‘Well, it was bound to be – I just took it out of the oven.’</em></li><li><em>When you are dealing with so many patients, mistakes are bound to happen.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[law/agreement]</strong> <strong>be bound (by something)</strong> to be forced to do what a law or agreement says you must do → binding</div><ul class=\"examples\"><li><strong><em>bound (by something) to do something</strong>: The Foundation is bound by the treaty to help any nation that requests aid.</em></li><li><em>You are legally bound to report the accident.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[duty]</strong> <strong>be/feel bound to do something</strong> to feel that you ought to do something, because it is morally right or your duty to do it:</div><ul class=\"examples\"><li><em>Ian felt bound to tell Joanna the truth.</em></li><li><em>Well, I’m bound to say (=I feel I ought to say), I think you’re taking a huge risk.</em></li><li><strong><em>be duty bound/honour bound to do something</strong>: A son is duty bound to look after his mother.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[travelling towards]</strong> <strong>bound for London/Mexico etc</strong> (also London-bound/Mexico-bound etc) travelling towards a particular place or in a particular direction:</div><ul class=\"examples\"><li><em>a plane bound for Somalia</em></li><li><em>We tried to get seats on a Rome-bound flight.</em></li><li><em>homeward-bound (=travelling towards home) commuters</em></li><li><strong><em>northbound/southbound/eastbound/westbound</strong>: All eastbound trains have been cancelled due to faulty signals.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[relationship]</strong> <strong>be bound (together) by something</strong> if two people or groups are bound together by something, they share a particular experience or situation that causes them to have a relationship → unite:</div><ul class=\"examples\"><li><em>The two nations were bound together by a common history.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be bound up in something</strong> to be very involved in something, so that you cannot think about anything else:</div><ul class=\"examples\"><li><em>He was too bound up in his own problems to listen to mine.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>be bound up with something</strong> to be very closely connected with a particular problem or situation:</div><ul class=\"examples\"><li><em>Mark’s problems are all bound up with his mother’s death when he was ten.</em></li><li><em>The people of Transkei began to realize that their future was inseparably bound up with that of South Africa.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>snow-bound/strike-bound/tradition-bound etc</strong> controlled or limited by something, so that you cannot do what you want or what other people want you to:</div><ul class=\"examples\"><li><em>a fog-bound airport</em></li><li><em>people who are wheelchair-bound</em></li><li><em>a desk-bound sergeant (=having to work in an office, instead of doing a more active job)</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> a bound book is covered on the outside with paper, leather etc → bind</div><ul class=\"examples\"><li><strong><em>bound in</strong>: a Bible bound in leather</em></li><li><em>a leather-bound volume of Shakespeare’s plays</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>I’ll be bound</strong> <em>old-fashioned</em> used when you are very sure that what you have just said is true:</div><ul class=\"examples\"><li><em>He had good reasons for doing that, I’ll be bound.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>bound and determined</strong> <em>American English</em> very determined to do or achieve something, especially something difficult:</div><ul class=\"examples\"><li><em>Klein is bound and determined to win at least five races this year.</em></li></ul></div>","794":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bound‧a‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbaʊndəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(plural boundaries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the real or imaginary line that marks the edge of a state, country etc, or the edge of an area of land that belongs to someone ► see thesaurus at border</div><ul class=\"examples\"><li><strong><em>boundary between</strong>: The Mississippi River forms a natural boundary between Iowa and Illinois.</em></li><li><em>National boundaries are becoming increasingly meaningless in the global economy.</em></li><li><em>We would need their agreement to build outside the city boundary.</em></li><li><em>The stream curves round to mark the boundary of his property.</em></li><li><em>Anything that crosses the boundary of a black hole cannot get back.</em></li><li><em>We walked through the churchyard towards the boundary wall.</em></li><li><em>The property’s boundary line is 25 feet from the back of the house.</em></li><li><em>boundary disputes between neighbouring countries</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually plural]</span> the limit of what is acceptable or thought to be possible</div><ul class=\"examples\"><li><strong><em>boundary of</strong>: the boundaries of human knowledge</em></li><li><strong><em>within/beyond the boundaries of something</strong>: within the boundaries of the law</em></li><li><strong><em>push back the boundaries (of something)</strong> (=to make a new discovery, work of art etc that is very different from what people have known before, and that changes the way they think): art that pushes back the boundaries</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> the point at which one feeling, idea, quality etc stops and another starts</div><ul class=\"examples\"><li><strong><em>boundary of/between</strong>: the boundaries between work and play / the blurring of the boundaries between high and popular culture</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> the outer limit of the playing area in cricket, or a shot that sends the ball across this limit for extra points</div></div>","795":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bou‧quet</span><span class=\"meta-item\"><strong>IPA:</strong> /bəʊˈkeɪ, buː- $ boʊ-, buː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> an arrangement of flowers, especially one that you give to someone</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the smell of a wine</div></div>","796":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baʊt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>a bout of depression/flu/sickness etc</strong> a short period of time during which you suffer from an illness</div><div class=\"sense\"><span class=\"snum\">2</span> a short period of time during which you do something a lot, especially something that is bad for you:</div><ul class=\"examples\"><li><em>a drinking bout</em></li><li><strong><em>bout of</strong>: a bout of unemployment</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a boxing or wrestling match</div></div>","797":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bou‧tique</span><span class=\"meta-item\"><strong>IPA:</strong> /buːˈtiːk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small shop that sells fashionable clothes or other objects</div></div>","798":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to bend the top part of your body forward in order to show respect for someone important, or as a way of thanking an audience:</div><ul class=\"examples\"><li><em>She bowed and left the stage.</em></li><li><em>Corbett entered the room, bowing respectfully.</em></li><li><em>The servant bowed low and handed his master the sealed note.</em></li><li><strong><em>bow before/to</strong>: He bowed before the king.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bow your head</strong> to bend your neck so that you are looking at the ground, especially because you want to show respect for God, or because you are embarrassed or upset:</div><ul class=\"examples\"><li><em>She bowed her head and prayed.</em></li><li><em>Phil stood, his head bowed in shame.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to bend your body over something, especially in order to see it more closely</div><ul class=\"examples\"><li><strong><em>bow over</strong>: Teague sat at his desk, bowed over a book.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive, transitive]</span> to bend, or to make something bend:</div><ul class=\"examples\"><li><em>The trees bowed in the wind.</em></li><li><em>His back was bowed under the weight of the heavy bag.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>bow and scrape</strong> to show too much respect to someone in authority – used to show disapproval</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> the act of bending the top part of your body forward to show respect for someone when you meet them, or as a way of thanking an audience</div><ul class=\"examples\"><li><strong><em>take/give a bow</strong> (=bow to the audience at the end of a performance): The music ended and the girl took a bow. / He gave a final bow just as the curtains came down.</em></li><li><em>This is done with a formal bow to the king or queen.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> (also bows<span class=\"gram\">[plural]</span>) <span class=\"gram\">[countable]</span> the front part of a ship → stern, yacht</div></div></div>","799":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bow‧el</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbaʊəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>bowels</strong> <span class=\"gram\">[plural]</span> the system of tubes inside your body where food is made into solid waste material and through which it passes out of your body → intestine</div><ul class=\"examples\"><li><strong><em>move/empty/open your bowels</strong> (=get rid of solid waste from your body)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[singular]</span> one part of this system of tubes:</div><ul class=\"examples\"><li><em>cancer of the bowel</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bowel movement</strong> <em>formal</em> the act of getting rid of solid waste from your body</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>the bowels of something</strong> <em>literary</em> the lowest or deepest part of something</div><ul class=\"examples\"><li><strong><em>the bowels of the earth</strong> (=deep under the ground)</em></li></ul></div>","800":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bəʊl $ boʊl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[container]</strong> <span class=\"gram\">[countable]</span> a wide round container that is open at the top, used to hold liquids, food, flowers etc → dish:</div><ul class=\"examples\"><li><em>Mix all the ingredients thoroughly in a large bowl.</em></li><li><em>Fill the bowl with water.</em></li><li><strong><em>a mixing/serving bowl</strong> (=a bowl used for mixing foods or serving them): Beat the butter in a mixing bowl until creamy and soft.</em></li><li><strong><em>a soup/salad/cereal etc bowl</strong> (=a bowl to eat or serve soup, salad etc from)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[amount]</strong> <span class=\"gram\">[countable]</span> (also bowlful) the amount of something contained in a bowl</div><ul class=\"examples\"><li><strong><em>bowl of</strong>: a bowl of rice / a bowl of fruit</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[game]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <strong>bowls</strong> <em>British English</em> <span class=\"gram\">[plural]</span> an outdoor game played on grass, in which you try to roll big balls as near as possible to a small ball SYN lawn bowling<em>American English</em></div><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[countable usually singular]</span> a special game in American football played by the best teams after the normal playing season:</div><ul class=\"examples\"><li><em>the Rose Bowl</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[ball]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> a ball that you use in the game of bowls</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[shape]</strong> <span class=\"gram\">[countable]</span> the part of an object such as a spoon, pipe, toilet etc that is shaped like a bowl:</div><ul class=\"examples\"><li><em>the bowl of a pipe</em></li><li><strong><em>a toilet/lavatory bowl</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[stadium]</strong> <span class=\"gram\">[countable usually singular]</span> <em>American English</em> a large stadium shaped like a bowl, where people go to watch special events such as sports games or music concerts:</div><ul class=\"examples\"><li><em>the Hollywood Bowl</em></li></ul></div>","801":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bowl‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbəʊlɪŋ $ ˈboʊ-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an indoor game in which you roll a large heavy ball along a wooden track in order to knock down a group of pins (=wooden objects shaped like bottles):</div><ul class=\"examples\"><li><em>Do you want to go bowling with us Friday?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> the act of throwing a ball at the batsman in cricket</div></div>","802":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɒks $ bɑːks/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[container]</strong> <span class=\"gram\">[countable]</span> a container for putting things in, especially one with four stiff straight sides</div><ul class=\"examples\"><li><strong><em>cardboard/wooden/plastic etc box</strong>: a strong cardboard box</em></li><li><strong><em>toolbox/shoebox/matchbox etc</strong> (=a box used for keeping tools etc in)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[amount]</strong> (also boxful) <span class=\"gram\">[countable]</span> the amount of something contained in a box</div><ul class=\"examples\"><li><strong><em>box of</strong>: a box of chocolates</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[shape]</strong> <span class=\"gram\">[countable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a small square on a page for people to write information in:</div><ul class=\"examples\"><li><em>Put an ‘X’ in the box if you would like to join our mailing list.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a square or rectangle on a page where information is given or where an answer can be written:</div><ul class=\"examples\"><li><em>The box on the left gives a short history of the battle.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[in a court/theatre etc]</strong> <span class=\"gram\">[countable]</span> a small area of a theatre or court that is separate from where other people are sitting:</div><ul class=\"examples\"><li><em>the jury box</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[small building]</strong> <span class=\"gram\">[countable]</span> a small building or structure used for a particular purpose <em>SYN booth</em>:</div><ul class=\"examples\"><li><em>a sentry box</em></li><li><strong><em>telephone box<em>British English</em></strong></em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[at a post office]</strong> <strong>box 25/450 etc</strong> a box with a number in a post office, where you can have letters etc sent instead of to your own address <em>SYN PO Box</em></div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[sports field]</strong> <span class=\"gram\">[countable usually singular]</span> a special area of a sports field that is marked by lines and used for a particular purpose:</div><ul class=\"examples\"><li><em>the penalty box</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[protection]</strong> <span class=\"gram\">[countable]</span> <em>British English</em> a piece of plastic that a man wears over his sex organs to protect them when he is playing a sport, especially cricket</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[tree]</strong> <span class=\"gram\">[countable, uncountable]</span> a small tree that keeps its leaves in winter and is often planted around the edge of a garden or field:</div><ul class=\"examples\"><li><em>a box hedge</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[television]</strong> <strong>the box</strong> <em>informal</em> the television:</div><ul class=\"examples\"><li><em>What’s on the box tonight?</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>be out of your box</strong> <em>British English</em> <em>informal</em> to be very drunk or have taken an illegal drug</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to fight someone as a sport by hitting them with your closed hands inside big leather gloves</div><div class=\"sense\"><span class=\"snum\">2</span> (also box up) <span class=\"gram\">[transitive]</span> to put things in boxes: → boxed</div><ul class=\"examples\"><li><em>Help me box up the Christmas tree lights.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to draw a box around something on a page</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>box somebody’s ears</strong> <em>old-fashioned</em> to hit someone on the side of their head</div></div></div>","803":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> box‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒksə $ ˈbɑːksər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who boxes, especially as a job</div><div class=\"sense\"><span class=\"snum\">2</span> a large dog with short light brown hair and a flat nose</div></div>","804":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈboxer ˌshorts</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">loose cotton underwear for men</div></div>","805":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> box‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɒksɪŋ $ ˈbɑːk-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the sport of fighting while wearing big leather gloves</div></div>","806":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɔɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a male child, or a male person in general → girl: ► see thesaurus at man</div><ul class=\"examples\"><li><em>The boys wanted to play football.</em></li><li><em>boys and girls aged 11–18</em></li><li><strong><em>a teenage/adolescent boy</strong>: A group of teenage boys stood talking in a group outside.</em></li><li><strong><em>bad/naughty boy</strong>: ‘You naughty boy!’ she said in a harsh voice.</em></li><li><em>What a polite little boy (=young male child) you are.</em></li><li><em>Come on, Timmy, act like a big boy (=an older boy) now.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a son:</div><ul class=\"examples\"><li><em>I love my boys, but I’d like to have a girl, too.</em></li><li><em>How old is your little boy (=young son)?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>office/paper/delivery etc boy</strong> a young man who does a particular job</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>city/local/country boy</strong> <em>informal</em> a man of any age who is typical of people from a particular place, or who feels a strong connection with the place he grew up in:</div><ul class=\"examples\"><li><em>The classic story of a local boy who’s made good (=who has succeeded).</em></li><li><em>I’m just a country boy.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>the boys</strong> <span class=\"gram\">[plural]</span> <em>informal</em> a group of men who are friends and often go out together:</div><ul class=\"examples\"><li><em>Friday is his night out with the boys.</em></li><li><em>He considers himself just one of the boys (=not anyone special, but liked by other men).</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> a way of talking to a male horse or dog:</div><ul class=\"examples\"><li><em>Good boy!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>boys</strong> <span class=\"gram\">[plural]</span> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> a group of men who do the same job:</div><ul class=\"examples\"><li><em>Oh no! Wait until the press boys get hold of this story.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> men in the army, navy etc, especially those who are fighting in a war:</div><ul class=\"examples\"><li><em>our boys on the front lines</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>boys will be boys</strong> used to say that you should not be surprised when boys or men behave badly, are noisy etc</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>the boys in blue</strong> <em>informal</em> the police</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>old boy/my dear boy</strong> <em>British English</em> <em>old-fashioned</em> a friendly way for one man to speak to another man</div><div class=\"sense\"><span class=\"snum\">11</span> <em>American English</em> <em>not polite</em> an offensive way of talking to a black man</div></div>","807":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> boy‧cott</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔɪkɒt $ -kɑːt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to refuse to buy something, use something, or take part in something as a way of protesting:</div><ul class=\"examples\"><li><em>We boycott all products tested on animals.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an act of boycotting something, or the period of time when it is boycotted:</div><ul class=\"examples\"><li><em>They are now trying to organize a boycott.</em></li><li><strong><em>boycott of/on/against</strong>: a boycott on GM crops / He called for a boycott of the elections.</em></li></ul></div></div>","808":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> boy‧friend</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɔɪfrend/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a man that you are having a romantic relationship with → girlfriend</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>boyfriend jeans/cardigan/jacket etc</strong> used to refer to a piece of clothing for women that is quite big and loose</div></div>","809":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɑː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of underwear that a woman wears to support her breasts</div></div>","810":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brace‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪslɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a band or chain that you wear around your wrist or arm as a decoration → bangle:</div><ul class=\"examples\"><li><em>a gold bracelet</em></li></ul></div>","811":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brack‧et</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrækɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> (also round bracket) <span class=\"gram\">[usually plural]</span> <em>British English</em> one of the pair of signs () put around words to show extra information SYN parenthesis<em>American English</em> → angle brackets, square bracket, punctuation mark</div><ul class=\"examples\"><li><strong><em>in brackets</strong>: Last year’s sales figures are given in brackets.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>income/tax/age etc bracket</strong> a particular income, tax etc range:</div><ul class=\"examples\"><li><em>the highest tax bracket</em></li><li><em>families in lower income brackets</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a piece of metal, wood, or plastic, often in the shape of the letter L, fixed to a wall to support something such as a shelf</div></div>","812":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bræɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive, transitive]</span></span><span class=\"meta-item\">(past tense and past participle bragged, present participle bragging)</span></div><div class=\"entry-body\"><div class=\"sense\">to talk too proudly about what you have done, what you own etc – used to show disapproval <em>SYN boast</em>:</div><ul class=\"examples\"><li><em>‘I came out top in the test,’ he bragged.</em></li><li><strong><em>brag about</strong>: Ben’s always bragging about his success with women.</em></li><li><strong><em>brag that</strong>: Julia used to brag that her family had a villa in Spain.</em></li></ul></div>","813":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /breɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[organ]</strong> <span class=\"gram\">[countable]</span> the organ inside your head that controls how you think, feel, and move:</div><ul class=\"examples\"><li><em>Messages from the brain are carried by the central nervous system.</em></li><li><em>the chemistry of the brain</em></li><li><em>the human brain</em></li><li><strong><em>the right/left hemisphere of the brain</strong> (=the right or left side of the brain): Emotional responses are a function of the right hemisphere of the brain.</em></li><li><em>She died of a brain tumour.</em></li><li><strong><em>brain tissue/cell</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[intelligence]</strong> <span class=\"gram\">[countable usually plural, uncountable]</span> the ability to think clearly and learn quickly:</div><ul class=\"examples\"><li><em>If you had any brains, you’d know what I meant.</em></li><li><em>The job requires brains.</em></li><li><em>Something’s addled your brains (=made you confused).</em></li><li><em>Come on, use your brain, John.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[person]</strong> <span class=\"gram\">[countable usually plural]</span> <em>informal</em> someone who is intelligent, with good ideas and useful skills: → brain drain</div><ul class=\"examples\"><li><em>Some of our best brains are leaving the country to work in the US.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[food]</strong> <span class=\"gram\">[uncountable]</span> (also brains<span class=\"gram\">[plural]</span>) the brain of an animal, used as food</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>have something on the brain</strong> <em>informal</em> to be always thinking about something:</div><ul class=\"examples\"><li><em>I’ve got that song on the brain today.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be the brains behind/of something</strong> to be the person who thought of and developed a particular plan, system, or organization, especially a successful one:</div><ul class=\"examples\"><li><em>Danny’s definitely the brains of the project.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>brain dead</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in a state where your brain has stopped working properly, even though your heart may still be beating</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> in a state in which you seem stupid or uninteresting, especially because you live a boring life or are very tired</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>something is not brain surgery</strong> <em>informal</em> used to say that something is not difficult to do</div></div>","814":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brain‧storm</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪnstɔːm $ -stɔːrm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable usually singular]</span> <em>American English</em> a sudden clever idea SYN brainwave<em>British English</em>:</div><ul class=\"examples\"><li><em>Kirby had a sudden brainstorm.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> <em>British English</em> <em>informal</em> if you have a brainstorm, you are suddenly unable to think clearly or sensibly:</div><ul class=\"examples\"><li><em>I must have had a brainstorm that afternoon.</em></li></ul></div>","815":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brain‧wave</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪnweɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a sudden clever idea SYN brainstorm<em>American English</em>: ► see thesaurus at idea</div><ul class=\"examples\"><li><em>I’ve had a brainwave! Let’s go this weekend instead.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an electrical force that is produced by the brain and that can be measured</div></div>","816":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brain‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪni/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(comparative brainier, superlative brainiest)</span></div><div class=\"entry-body\"><div class=\"sense\">able to learn easily and think quickly <em>SYN clever</em>, smart<em>American English</em>: ► see thesaurus at intelligent</div><ul class=\"examples\"><li><em>He always was the brainy one.</em></li></ul></div>","817":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /breɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[often plural]</span> a piece of equipment that makes a vehicle go more slowly or stop: → anti-lock braking system, emergency brake, handbrake, parking brake</div><ul class=\"examples\"><li><em>Test your brakes after driving through water.</em></li><li><em>I managed to put the brakes on just in time.</em></li><li><em>Moira slammed on the brakes (=used them suddenly and with a lot of force).</em></li><li><strong><em>apply the brakes<em>formal</em></strong>: He applied the brakes but failed to stop in time.</em></li><li><strong><em>the rear/front brakes</em></strong></li><li><em>the screech of brakes (=the loud unpleasant noise they can make)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>act as a brake on something</strong> to make something develop more slowly, be more difficult to do, or happen less:</div><ul class=\"examples\"><li><em>Rises in interest rates act as a brake on expenditure.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>put the brakes on something</strong> to stop something that is happening</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[intransitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to make a vehicle or bicycle go more slowly or stop by using its brake</div><ul class=\"examples\"><li><strong><em>brake sharply/hard</strong> (=brake quickly): He braked sharply to avoid the dog.</em></li></ul></div></div>","818":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɑːntʃ $ bræntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[of a tree]</strong> a part of a tree that grows out from the trunk (=main stem) and that has leaves, fruit, or smaller branches growing from it → limb:</div><ul class=\"examples\"><li><em>After the storm, the ground was littered with twigs and branches.</em></li><li><em>The topmost branches were full of birds.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[of a business/shop/company etc]</strong> a local business, shop etc that is part of a larger business etc:</div><ul class=\"examples\"><li><em>The bank has branches all over the country.</em></li><li><em>a branch office in Boston</em></li><li><em>She now works in our Denver branch.</em></li><li><em>Where’s their nearest branch?</em></li><li><em>They’re planning to open a branch in St. Louis next year.</em></li><li><em>Have you met our branch manager, Mr. Carlson?</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[of government]</strong> a part of a government or other organization that deals with one particular part of its work → department:</div><ul class=\"examples\"><li><em>All branches of government are having to cut costs.</em></li><li><strong><em>the executive/judicial/legislative branch</strong> (=the three main parts of the US government)</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[of a subject]</strong> one part of a large subject of study or knowledge → field</div><ul class=\"examples\"><li><strong><em>a branch of mathematics/physics/biology etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[of a family]</strong> a group of members of a family who all have the same ancestors → side:</div><ul class=\"examples\"><li><em>the wealthy South American branch of the family</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[of a river/road etc]</strong> a smaller less important part of a river, road, or railway that leads away from the larger more important part of it:</div><ul class=\"examples\"><li><em>The rail company may have to close the branch line to Uckfield.</em></li></ul></div>","819":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brænd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a type of product made by a particular company, that has a particular name or design → make</div><ul class=\"examples\"><li><strong><em>brand of</strong>: What brand of detergent do you use?</em></li><li><strong><em>brand leader/leading brand</strong> (=the brand that sells the most)</em></li><li><em>products which lack a strong brand image</em></li><li><strong><em>brand loyalty</strong> (=the tendency to always buy a particular brand)</em></li><li><strong><em>own brand<em>British English,</em></strong> <strong>store brand</em>American English</strong><em> (=a product made and sold by a particular store)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>brand of humour/politics/religion etc</strong> a particular type of humour, politics, religion etc:</div><ul class=\"examples\"><li><em>a strange macabre brand of humour</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a mark made or burned on a farm animal’s skin that shows who it belongs to</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to describe someone or something as a very bad type of person or thing, often unfairly</div><ul class=\"examples\"><li><strong><em>brand somebody (as) something</strong>: You can’t brand all football supporters as hooligans.</em></li><li><em>Stealing that money has branded Jim for life – no one will trust him again.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to burn a mark onto something, especially a farm animal, in order to show who it belongs to</div><ul class=\"examples\"><li><strong><em>brand something with something</strong>: Each cow was branded with the ranch’s logo.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>technical</em> to give a name to a product or group of products so that they can be easily recognized by their name or design</div></div></div>","820":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌbrand-ˈnew</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\">new and not yet used:</div><ul class=\"examples\"><li><em>a brand-new car</em></li><li><em>His clothes looked brand-new.</em></li></ul></div>","821":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɑːs $ bræs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[metal]</strong> <span class=\"gram\">[uncountable]</span> a very hard bright yellow metal that is a mixture of copper and zinc:</div><ul class=\"examples\"><li><em>an old brass bedstead</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[music]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> musical instruments that are made of metal, such as the trumpet and the trombone: → percussion, stringed instrument, wind instrument, woodwind</div><ul class=\"examples\"><li><em>brass instruments</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>the brass (section)</strong> the people in an orchestra or band who play musical instruments that are made of metal</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[decorations]</strong> <span class=\"gram\">[countable usually plural]</span> an object made of brass, usually with a design cut into it, or several brass objects</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>get down to brass tacks</strong> <em>informal</em> to start talking about the most important facts or details of something</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>[people with top jobs]</strong> <strong>the brass</strong> <em>American English</em> <em>informal</em> people who hold the most important positions SYN top brass<em>British English</em></div><div class=\"sense\"><span class=\"snum\">6</span> <strong>it’s brass monkeys/brass monkey weather</strong> <em>British English</em> <em>spoken</em> <em>informal</em> used to say that it is very cold</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[money]</strong> <span class=\"gram\">[uncountable]</span> <em>British English</em> <em>old-fashioned</em> <em>informal</em> money</div></div>","822":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /breɪv/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\">(comparative braver, superlative bravest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> dealing with danger, pain, or difficult situations with courage and confidence <em>SYN courageous</em>:</div><ul class=\"examples\"><li><em>brave soldiers</em></li><li><em>her brave fight against cancer</em></li><li><strong><em>it is brave of somebody (to do something)</strong>: It was brave of you to speak in front of all those people.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <strong>the brave</strong> <span class=\"gram\">[plural]</span> brave people:</div><ul class=\"examples\"><li><em>Today we remember the brave who died in the last war.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> very good:</div><ul class=\"examples\"><li><em>Despite their captain’s brave performance, Arsenal lost 2–1.</em></li><li><strong><em>brave effort/attempt</strong>: the brave efforts of the medical staff to save his life</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>put on a brave face/front</strong> to pretend that you are happy when you are really very upset</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>brave new world</strong> a situation or a way of doing something that is new and exciting and meant to improve people’s lives:</div><ul class=\"examples\"><li><em>the brave new world of digital television</em></li></ul></div>","823":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brav‧e‧ry</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪvəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">actions, behaviour, or an attitude that shows courage and confidence <em>SYN courage</em> <em>OPP cowardice</em>:</div><ul class=\"examples\"><li><em>an act of great bravery</em></li></ul></div>","824":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /briːtʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> an action that breaks a law, rule, or agreement</div><ul class=\"examples\"><li><strong><em>breach of</strong>: This was a clear breach of the 1994 Trade Agreement. / They sued the company for breach of contract. / a breach of professional duty</em></li><li><strong><em>be in breach of something</strong>: He was clearly in breach of the law.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a serious disagreement between people, groups, or countries</div><ul class=\"examples\"><li><strong><em>breach with</strong>: Britain did not want to risk a breach with the US over sanctions.</em></li><li><strong><em>breach between</strong>: What had caused the sudden breach between Henry and his son?</em></li><li><em>She wanted to help heal the breach between them.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>breach of confidence/trust</strong> an action in which someone does something that people have trusted them not to do:</div><ul class=\"examples\"><li><em>We regard the publication of this information as a serious breach of trust.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>breach of security</strong> an action in which someone manages to learn secret information or manages to get into a place that is guarded:</div><ul class=\"examples\"><li><em>There had been a major breach of security at the airbase.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>breach of the peace</strong> <em>British English</em> the crime of making too much noise or fighting in a public place:</div><ul class=\"examples\"><li><em>He was arrested and charged with breach of the peace.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <span class=\"gram\">[countable]</span> a hole made in a wall that is intended to protect a place</div><ul class=\"examples\"><li><strong><em>breach in</strong>: a breach in the castle wall</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>step into the breach</strong> to help by doing someone else’s job or work when they are unable to do it <em>SYN step in</em>:</div><ul class=\"examples\"><li><em>Thanks for stepping into the breach last week.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to break a law, rule, or agreement <em>SYN break</em>:</div><ul class=\"examples\"><li><em>The company accused him of breaching his contract.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to break a hole in a wall that is intended to protect a place:</div><ul class=\"examples\"><li><em>The storm had breached the sea wall in two places.</em></li></ul></div></div>","825":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bred/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a type of food made from flour and water that is mixed together and then baked:</div><ul class=\"examples\"><li><em>Would you like some bread with your soup?</em></li><li><em>a loaf of brown bread</em></li><li><em>a piece of bread and butter</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>your/somebody’s bread and butter</strong> <em>informal</em> the work that provides you with most of the money that you need in order to live:</div><ul class=\"examples\"><li><em>Writing is my bread and butter.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>know which side your bread is buttered on</strong> <em>informal</em> to know which people to be nice to in order to get advantages for yourself</div><div class=\"sense\"><span class=\"snum\">4</span> <em>old-fashioned</em> <em>informal</em> money</div></div>","826":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bredθ, bretθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the distance from one side of something to the other <em>SYN width</em> → broad, depth, length</div><ul class=\"examples\"><li><strong><em>breadth of</strong>: the breadth of the river</em></li><li><strong><em>5 metres/3 feet etc in breadth</strong>: The boat measured 15 feet in length and 4 feet in breadth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the quality of including a lot of different people, things, or ideas → broad, depth</div><ul class=\"examples\"><li><strong><em>breadth of</strong>: The job wasn’t giving him the breadth of experience he wanted. / His breadth of knowledge was amazing. / a politician known for his breadth of vision</em></li><li><em>We need to provide more breadth in the college curriculum.</em></li></ul></div>","827":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /breɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense broke /brəʊk $ broʊk/, past participle broken /ˈbrəʊkən $ ˈbroʊ-/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[separate into pieces]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> if you break something, you make it separate into two or more pieces, for example by hitting it, dropping it, or bending it:</div><ul class=\"examples\"><li><em>I had to break a window to get into the house.</em></li><li><em>Don’t lean on the fence like that – you’ll break it!</em></li><li><strong><em>break something in half/two</strong>: He broke the biscuit in half and handed one piece to me.</em></li><li><em>Break the chocolate into small pieces and melt it over a gentle heat.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> if something breaks, it separates into two or more pieces:</div><ul class=\"examples\"><li><em>He kept pulling at the rope until it broke.</em></li><li><em>The frames are made of plastic and they tend to break quite easily.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[bones]</strong> <span class=\"gram\">[transitive]</span> to damage a bone in your body by making it crack or split: ► see thesaurus at hurt</div><ul class=\"examples\"><li><em>She fell downstairs and broke her hip.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[machines]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[transitive]</span> to damage a machine so that it does not work properly:</div><ul class=\"examples\"><li><em>Don’t mess about with my camera – you’ll break it.</em></li><li><em>Someone’s broken the TV.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[intransitive]</span> if a machine breaks, it stops working properly:</div><ul class=\"examples\"><li><em>The washing machine’s broken again.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[rules/laws]</strong> <span class=\"gram\">[transitive]</span> to disobey a rule or law:</div><ul class=\"examples\"><li><em>They’re breaking the law by employing such young children.</em></li><li><em>If you break the rules, you will be punished.</em></li><li><em>The cameras catch motorists who break the speed limit.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[promise/agreement]</strong> <span class=\"gram\">[transitive]</span> to not do something that you have promised to do or signed an agreement to do:</div><ul class=\"examples\"><li><em>I never break my promises.</em></li><li><em>You betrayed me. You broke your word.</em></li><li><strong><em>break an agreement/contract</strong>: He was worried that he might be breaking his contract.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[stop/rest]</strong> <span class=\"gram\">[intransitive]</span> to stop for a short time in order to have a rest or eat something</div><ul class=\"examples\"><li><strong><em>break for</strong>: Shall we break for lunch now?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[end something]</strong> <span class=\"gram\">[transitive]</span> to stop something from continuing:</div><ul class=\"examples\"><li><em>We need to break the cycle of poverty and crime in the inner cities.</em></li><li><em>We took turns driving, in order to try and break the monotony.</em></li><li><em>New talks will begin on Monday in an effort to break the deadlock.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[defeat somebody]</strong> <span class=\"gram\">[transitive]</span> to make someone feel that they have been completely defeated and they cannot continue working or living:</div><ul class=\"examples\"><li><em>Losing his business nearly broke him.</em></li><li><em>I won’t give in. I won’t be broken by him.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[destroy an organization]</strong> <span class=\"gram\">[transitive]</span> to damage an organization so badly that it no longer has any power:</div><ul class=\"examples\"><li><em>The government succeeded in breaking the unions.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[day/dawn]</strong> <span class=\"gram\">[intransitive]</span> when the day or the dawn breaks, the sky gets light:</div><ul class=\"examples\"><li><em>Dawn was breaking by the time we arrived home.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[storm]</strong> <span class=\"gram\">[intransitive]</span> if a storm breaks, it begins:</div><ul class=\"examples\"><li><em>We were keen to get back to the hotel before the storm broke.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[weather]</strong> <span class=\"gram\">[intransitive]</span> if the weather breaks, it suddenly changes and becomes cold or wet:</div><ul class=\"examples\"><li><em>The following day the weather broke and we had ten days of solid rain.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[waves]</strong> <span class=\"gram\">[intransitive]</span> when waves break, they fall onto the land at the edge of the water:</div><ul class=\"examples\"><li><em>We sat and watched the waves breaking on the shore.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[somebody’s voice]</strong> <span class=\"gram\">[intransitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> when a boy’s voice breaks, it becomes lower and starts to sound like a man’s voice:</div><ul class=\"examples\"><li><em>He was fifteen, and his voice was just beginning to break.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if your voice breaks, it does not sound smooth because you are feeling strong emotions:</div><ul class=\"examples\"><li><em>Her voice broke as she told us what had happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[news]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive]</span> if news about an important event breaks, it becomes known:</div><ul class=\"examples\"><li><em>News of his resignation broke yesterday.</em></li><li><em>The minister has refused to give any interviews since the scandal broke.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> if you break unpleasant news to someone, you tell it to them:</div><ul class=\"examples\"><li><em>I didn’t know how I was going to break the news to my mother.</em></li><li><em>The doctor finally broke it to me that there was no cure.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>break a habit</strong> to stop doing something that you do regularly, especially something that you should not do:</div><ul class=\"examples\"><li><em>a new drug which helps smokers to break their habit</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>break a record</strong> to do something even faster or even better than the previous best time, amount etc:</div><ul class=\"examples\"><li><em>an attempt to break the 10,000-metres world record</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>break a journey</strong> <em>British English</em> to stop somewhere for a short time during a long journey:</div><ul class=\"examples\"><li><em>We decided to break our journey in Oxford.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>break somebody’s heart</strong> to make someone very unhappy by ending a relationship with them or doing something that upsets them a lot:</div><ul class=\"examples\"><li><em>He broke my heart when he left me.</em></li><li><em>It’ll break your father’s heart if you tell him you’re giving up college.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>break a strike</strong> to force workers to end a strike:</div><ul class=\"examples\"><li><em>The government has threatened to bring in the army to break the 10-month-old strike.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>break a link/tie/connection</strong> to end a relationship with a person or organization:</div><ul class=\"examples\"><li><em>The US has now broken all diplomatic links with the regime.</em></li><li><em>Sometimes it is necessary to break family ties in order to protect the child.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>break the skin</strong> to cut the skin on your body:</div><ul class=\"examples\"><li><em>Their teeth are sharp enough to break the skin.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>break the back of something</strong> to finish the main or worst part of something:</div><ul class=\"examples\"><li><em>I think we’ve broken the back of the job now.</em></li></ul><div class=\"sense\"><span class=\"snum\">24</span> <strong>break the bank</strong> to cost a lot of money, or more money than you have:</div><ul class=\"examples\"><li><em>A new hard drive doesn’t have to break the bank.</em></li></ul><div class=\"sense\"><span class=\"snum\">25</span> <strong>break somebody’s concentration</strong> to interrupt someone and stop them from being able to continue thinking or talking about something:</div><ul class=\"examples\"><li><em>The slightest sound would break his concentration.</em></li></ul><div class=\"sense\"><span class=\"snum\">26</span> <strong>break the silence</strong> to end a period of silence by talking or making a noise:</div><ul class=\"examples\"><li><em>The silence was broken by a loud scream.</em></li></ul><div class=\"sense\"><span class=\"snum\">27</span> <strong>break somebody’s spirit</strong> to destroy someone’s feeling of determination:</div><ul class=\"examples\"><li><em>They could not break her spirit.</em></li><li><em>The spirit of our soldiers will never be broken.</em></li></ul><div class=\"sense\"><span class=\"snum\">28</span> <strong>break somebody’s power</strong> to take away someone’s position of power or control:</div><ul class=\"examples\"><li><em>At last the power of the Church had been broken.</em></li></ul><div class=\"sense\"><span class=\"snum\">29</span> <strong>break the ice</strong> <em>informal</em> to make people feel more friendly and willing to talk to each other:</div><ul class=\"examples\"><li><em>Sam’s arrival broke the ice and people began to talk and laugh.</em></li></ul><div class=\"sense\"><span class=\"snum\">30</span> <strong>break a code</strong> to succeed in understanding something that is written in a secret way:</div><ul class=\"examples\"><li><em>Scientists worked day and night to break the code.</em></li></ul><div class=\"sense\"><span class=\"snum\">31</span> <strong>break wind</strong> to allow gas to escape from your bottom, making a noise and an unpleasant smell</div><div class=\"sense\"><span class=\"snum\">32</span> <strong>break (somebody’s) serve</strong> to win a game in tennis when your opponent is starting the game by hitting the ball first:</div><ul class=\"examples\"><li><em>Hewitt broke serve twice in the second set.</em></li></ul><div class=\"sense\"><span class=\"snum\">33</span> <strong>break a leg</strong> <em>spoken</em> used to wish someone luck, especially just before they perform on stage</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[stop working]</strong> <span class=\"gram\">[countable]</span> a period of time when you stop working in order to rest, eat etc:</div><ul class=\"examples\"><li><em>We’ll have a short break for lunch, then start again at two o&#x27;clock.</em></li><li><em>Let’s take a ten-minute break.</em></li><li><em>We’d worked for ten hours without a break.</em></li><li><em>I’ll go shopping during my lunch break.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[stop doing something]</strong> <span class=\"gram\">[countable]</span> a period of time when you stop doing something before you start again</div><ul class=\"examples\"><li><strong><em>break from</strong>: I wanted a break from university life.</em></li><li><em>She decided to take a career break when she had children.</em></li><li><strong><em>break in</strong>: a welcome break in my normal routine</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[holiday]</strong> <span class=\"gram\">[countable]</span> a short holiday:</div><ul class=\"examples\"><li><em>I was beginning to feel that I needed a break.</em></li><li><em>We flew off for a week’s break in Spain.</em></li><li><em>They’re offering weekend breaks in Paris for only £100.</em></li><li><strong><em>the Easter/Christmas etc break</strong>: Are you looking forward to the summer break?</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[at school]</strong> <span class=\"gram\">[uncountable]</span> the time during the school day when classes stop and teachers and students can rest, eat, play etc</div><ul class=\"examples\"><li><strong><em>at break</strong>: I’ll speak to you at break.</em></li><li><em>They get together with their friends at break time.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[on tv]</strong> <span class=\"gram\">[countable]</span> a pause for advertisements during a television or radio programme:</div><ul class=\"examples\"><li><em>Join us again after the break.</em></li><li><em>We’ll be back with more after a short break.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[something stops happening]</strong> <span class=\"gram\">[countable]</span> a period of time when something stops happening before it starts again</div><ul class=\"examples\"><li><strong><em>break in</strong>: We’ll go for a walk if there’s a break in the rain. / Latecomers will be admitted at a suitable break in the performance. / She waited for a break in the conversation.</em></li><li><em>There was no sign of a break in the weather (=an improvement in bad weather).</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[end a relationship]</strong> <span class=\"gram\">[singular]</span> a time when you leave a person or group, or end a relationship with someone:</div><ul class=\"examples\"><li><em>I wanted a clean break so that I could restart my life.</em></li><li><em>It was years before I plucked up enough courage to make the break and leave him.</em></li><li><strong><em>break with</strong>: He was beginning to regret his break with the Labour Party.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[space/hole]</strong> <span class=\"gram\">[countable]</span> a space or hole in something</div><ul class=\"examples\"><li><strong><em>break in</strong>: We crawled through a break in the hedge. / The sun shone through a break in the clouds.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[chance]</strong> <span class=\"gram\">[countable]</span> <em>informal</em> a sudden or unexpected chance to do something that allows you to become successful in your job:</div><ul class=\"examples\"><li><em>There are hundreds of young musicians out there looking for their first break.</em></li><li><em>He got his first big break in 1998.</em></li><li><em>a lucky break</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[bones]</strong> <span class=\"gram\">[countable]</span> the place where a bone in your body has broken:</div><ul class=\"examples\"><li><em>It’s quite a bad break, which will take several months to heal.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[tennis]</strong> <span class=\"gram\">[countable]</span> a situation in a game of tennis in which you win a game when your opponent is starting the game by hitting the ball first:</div><ul class=\"examples\"><li><em>She really needs a break of serve now if she wants to win this match.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[snooker]</strong> <span class=\"gram\">[countable]</span> the number of points that a player wins when it is their turn to hit the ball in a game such as snooker</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>break with tradition/the past</strong> a time when people stop following old customs and do something in a completely different way:</div><ul class=\"examples\"><li><em>It is time for a complete break with the past.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>make a break for something</strong> to suddenly start running towards something in order to escape from a place:</div><ul class=\"examples\"><li><em>As soon as the guard’s back was turned, they made a break for the door.</em></li><li><em>Two of the prisoners made a break for it but were soon recaptured.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>give me/it a break!</strong> <em>spoken</em> used when you want someone to stop doing or saying something that is annoying you</div><div class=\"sense\"><span class=\"snum\">16</span> <strong>give somebody a break</strong> <em>spoken</em> to stop being strict with someone so that a situation becomes easier for them:</div><ul class=\"examples\"><li><em>Give the kid a break. It’s only his second day on the job.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>the break of day</strong> <em>literary</em> the time early in the morning when it starts getting light</div></div></div>","828":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> break‧down</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪkdaʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> the failure of a relationship or system</div><ul class=\"examples\"><li><strong><em>breakdown of</strong>: He moved away after the breakdown of his marriage. / A sudden rise in oil prices could lead to a breakdown of the economy.</em></li><li><strong><em>breakdown in</strong>: There has been a serious breakdown in relations between the two countries.</em></li><li><strong><em>marriage/marital/family breakdown</strong>: Family breakdown can lead to behavioural problems in children.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable]</span> a serious medical condition in which someone becomes mentally ill and is unable to work or deal with ordinary situations in life:</div><ul class=\"examples\"><li><em>I was worried he might have a breakdown if he carried on working so hard.</em></li><li><em>Two years ago he suffered a mental breakdown.</em></li><li><em>She had already had one nervous breakdown.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> an occasion when a car or a piece of machinery breaks and stops working:</div><ul class=\"examples\"><li><em>Always carry a phone with you in case you have a breakdown on the motorway.</em></li><li><strong><em>breakdown in</strong>: a breakdown in the cooling system</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> a list of all the separate parts of something</div><ul class=\"examples\"><li><strong><em>breakdown of</strong>: Can you give us a breakdown of the figures?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[singular]</span> the changing of a substance into other substances: → break down at break1</div><ul class=\"examples\"><li><em>the breakdown of glucose in the body to release energy</em></li></ul></div>","829":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> break‧fast</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrekfəst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the meal you have in the morning:</div><ul class=\"examples\"><li><em>We had bacon and eggs for breakfast.</em></li><li><em>I never eat breakfast.</em></li><li><em>After a hearty breakfast (=large breakfast), we set out for a hike.</em></li><li><em>a light breakfast (=small breakfast)</em></li><li><em>a working breakfast (=a breakfast at which you talk about business)</em></li></ul></div>","830":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> break‧through</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbreɪkθruː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">an important new discovery in something you are studying, especially one made after trying for a long time → break through at break1 ► see thesaurus at progress</div><ul class=\"examples\"><li><strong><em>breakthrough in</strong>: Scientists have made a major breakthrough in the treatment of cancer.</em></li></ul></div>","831":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brest/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[woman’s body]</strong> <span class=\"gram\">[countable]</span> one of the two round raised parts on a woman’s chest that produce milk when she has a baby:</div><ul class=\"examples\"><li><em>These bras are specially designed for women with large breasts.</em></li><li><em>breast milk</em></li><li><em>breast cancer</em></li><li><strong><em>bare-breasted/small-breasted etc</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[chest]</strong> <span class=\"gram\">[countable]</span> <em>written</em> the part of your body between your neck and your stomach:</div><ul class=\"examples\"><li><em>Dick cradled her photograph against his breast.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bird]</strong> <span class=\"gram\">[countable]</span> the front part of a bird’s body, below its neck:</div><ul class=\"examples\"><li><em>a robin with a red breast</em></li><li><strong><em>red-breasted/white-breasted etc</strong>: red-breasted geese</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[meat]</strong> <span class=\"gram\">[uncountable]</span> meat that comes from the front part of the body of a bird such as a chicken:</div><ul class=\"examples\"><li><em>turkey breast</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[clothes]</strong> <span class=\"gram\">[countable usually singular]</span> the part of a jacket, shirt etc that covers the top part of your chest → double-breasted, single-breasted</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>make a clean breast of it/things</strong> to admit that you have done something wrong</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[emotions]</strong> <span class=\"gram\">[countable]</span> <em>literary</em> where your feelings of sadness, love, anger, fear etc come from:</div><ul class=\"examples\"><li><em>a troubled breast</em></li></ul></div>","832":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /breθ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> ► Do not confuse the noun breath /breθ/ with the verb breathe /briːð/: She took a deep breath and continued. | I can’t breathe in here!</div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[uncountable]</span> the air that you send out of your lungs when you breathe:</div><ul class=\"examples\"><li><em>Leo could smell the wine on her breath.</em></li><li><em>Let your breath out slowly.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[uncountable]</span> air that you take into your lungs:</div><ul class=\"examples\"><li><em>When he reached the top of the stairs, his heart was pounding and he was gasping for breath.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> <span class=\"gram\">[countable]</span> an amount of air that you take into your lungs:</div><ul class=\"examples\"><li><em>Shaun took a deep breath and dived in.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>a breath of fresh air</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> something that is new and different in a way you think is exciting and good:</div><ul class=\"examples\"><li><em>Osborne’s play brought a breath of fresh air to the British theatre.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> clean air outside, that you feel you need after being inside for a long time:</div><ul class=\"examples\"><li><em>I’m going outside for a breath of fresh air.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>don’t hold your breath</strong> <em>informal</em> used to say that something is not going to happen soon:</div><ul class=\"examples\"><li><em>The system’s due for an update, but don’t hold your breath.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>catch your breath</strong> (also get your breath back) to start breathing normally again after running or making a lot of effort:</div><ul class=\"examples\"><li><em>Slow down, I need to catch my breath.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>don’t waste your breath</strong> (also save your breath) <em>spoken</em> used to say that someone will not be able to persuade someone else, so there is no point in trying:</div><ul class=\"examples\"><li><em>Save your breath. She’s already made up her mind.</em></li><li><em>Will he listen to me or will I just be wasting my breath?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>take somebody’s breath away</strong> to be extremely beautiful or exciting:</div><ul class=\"examples\"><li><em>The view from the top will take your breath away.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>under your breath</strong> in a quiet voice so that no one can hear you:</div><ul class=\"examples\"><li><em>‘Son of a bitch,’ he muttered under his breath.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>in the same breath</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> (also in the next breath) used to say that someone has said two things at once that are so different from each other they cannot both be true:</div><ul class=\"examples\"><li><em>He criticized the film, then predicted in the same breath that it would be a great success.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if you mention two people or things in the same breath, you show that you think they are alike or are related:</div><ul class=\"examples\"><li><em>I became nervous when the doctor mentioned my mother’s name and ‘cancer’ in the same breath.</em></li><li><strong><em>breath as/with</strong>: a young poet mentioned in the same breath as T.S. Eliot</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>with your last/dying breath</strong> at the moment when you are dying:</div><ul class=\"examples\"><li><em>With his last breath, he cursed his captors.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <span class=\"gram\">[singular]</span> <em>written</em> a very small amount or a sign of something</div><ul class=\"examples\"><li><strong><em>breath of</strong>: They did everything they could to avoid the slightest breath of scandal.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>a breath of air/wind</strong> <em>literary</em> a slight movement of air:</div><ul class=\"examples\"><li><em>Scarcely a breath of air disturbed the stillness of the day.</em></li></ul></div>","833":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /briːð/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[air]</strong> <span class=\"gram\">[intransitive, transitive]</span> to take air into your lungs and send it out again:</div><ul class=\"examples\"><li><em>The room filled with smoke, and it was becoming difficult to breathe.</em></li><li><em>People are concerned about the quality of the air they breathe.</em></li><li><em>Relax and breathe deeply (=take in a lot of air).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[blow]</strong> <span class=\"gram\">[intransitive, transitive]</span> to blow air or smoke out of your mouth</div><ul class=\"examples\"><li><strong><em>breathe on</strong>: Roy breathed on his hands and rubbed them together vigorously.</em></li><li><strong><em>breathe something over somebody</strong>: The fat man opposite was breathing garlic all over me.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>somebody can breathe easy/easily</strong> used when saying that someone can relax because a worrying or dangerous situation has ended:</div><ul class=\"examples\"><li><em>With stocks going up, investors can breathe easily.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>breathe a sigh of relief</strong> to stop being worried or frightened about something:</div><ul class=\"examples\"><li><em>Once the deadline passed, everyone breathed a sigh of relief.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be breathing down somebody’s neck</strong> <em>informal</em> to pay very close attention to what someone is doing, in a way that makes them feel nervous or annoyed:</div><ul class=\"examples\"><li><em>How can I concentrate with you breathing down my neck all the time?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>not breathe a word</strong> to not tell anyone anything at all about something, because it is a secret:</div><ul class=\"examples\"><li><em>Don’t breathe a word; it’s supposed to be a surprise.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>breathe life into something</strong> to change a situation so that people feel more excited or interested:</div><ul class=\"examples\"><li><em>Critics are hoping the young director can breathe new life into the French film industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[skin]</strong> <span class=\"gram\">[intransitive]</span> if your skin can breathe, air can reach it</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[clothes/fabric]</strong> <span class=\"gram\">[intransitive]</span> if cloth or clothing breathes, air can pass through it so that your body feels pleasantly cool and dry</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[wine]</strong> <span class=\"gram\">[intransitive]</span> if you let wine breathe, you open the bottle to let the air get to it before you drink it</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>[say something quietly]</strong> <span class=\"gram\">[transitive]</span> <em>written</em> to say something very quietly, almost in a whisper:</div><ul class=\"examples\"><li><em>‘Wait,’ he breathed.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>breathe your last (breath)</strong> <em>literary</em> to die</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>breathe fire</strong> to talk and behave in a very angry way → live and breathe something at live1(19)</div></div>","834":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> breath‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbriːðɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the process of breathing air in and out:</div><ul class=\"examples\"><li><em>His breathing was deep and regular.</em></li><li><em>When I picked up the phone, all I heard was heavy breathing (=loud breathing).</em></li></ul></div>","835":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /briːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle bred /bred/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> if animals breed, they mate in order to have babies:</div><ul class=\"examples\"><li><em>Eagles breed during the cooler months of the year.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to keep animals or plants in order to produce babies or new plants, especially ones with particular qualities: → crossbreed1, purebred, thoroughbred</div><ul class=\"examples\"><li><em>These dogs were originally bred in Scotland to round up sheep.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to cause a particular feeling or condition:</div><ul class=\"examples\"><li><em>Poor living conditions breed violence and despair.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> if a place, situation, or thing breeds a particular type of person, it produces that type:</div><ul class=\"examples\"><li><em>Society’s obsession with sex has bred a generation of unhappy children.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a type of animal that is kept as a pet or on a farm</div><ul class=\"examples\"><li><strong><em>breed of</strong>: Spaniels are my favourite breed of dog.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a particular kind of person or type of thing:</div><ul class=\"examples\"><li><em>Real cowboys are a dying breed (=not many exist anymore).</em></li><li><em>Dodd was one of that rare breed (=there are not many of them) who could make the game of football look simple.</em></li><li><strong><em>breed of</strong>: a new breed of international criminal</em></li></ul></div></div>","836":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /briːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a gentle wind → breezy: ► see thesaurus at wind</div><ul class=\"examples\"><li><em>flowers waving in the breeze</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be a breeze</strong> <em>informal</em> to be very easy:</div><ul class=\"examples\"><li><em>Don’t think that learning Dutch will be a breeze.</em></li></ul></div>","837":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bruː/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to make beer:</div><ul class=\"examples\"><li><em>Every beer on the menu was brewed locally.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive]</span> if a drink of tea or coffee is brewing, the taste is getting into the hot water:</div><ul class=\"examples\"><li><em>He read the paper while the tea brewed.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> to make a drink of tea or coffee:</div><ul class=\"examples\"><li><em>freshly brewed coffee</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>be brewing</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something unpleasant is brewing, it will happen soon:</div><ul class=\"examples\"><li><em>There’s trouble brewing in the office.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if a storm is brewing, it will happen soon</div></div>","838":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brew‧er‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbruːəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural breweries)</span></div><div class=\"entry-body\"><div class=\"sense\">a place where beer is made, or a company that makes beer</div></div>","839":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /braɪb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to illegally give someone, especially a public official, money or a gift in order to persuade them to do something for you:</div><ul class=\"examples\"><li><em>The only way we could get into the country was by bribing the border officials.</em></li><li><strong><em>bribe somebody to do something</strong>: He bribed one of the guards to smuggle out a note.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> to offer someone, especially a child, something special in order to persuade them to do something</div><ul class=\"examples\"><li><strong><em>bribe somebody with something</strong>: Sam wouldn’t do her homework until I bribed her with ice cream.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> money or a gift that you illegally give someone to persuade them to do something for you:</div><ul class=\"examples\"><li><em>The officials said that they had been offered bribes before an important game.</em></li><li><strong><em>accept/take a bribe</strong>: A Supreme Court judge was charged with taking bribes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> something special offered to someone, especially a child, in order to persuade them to do something</div></div></div>","840":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brib‧er‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbraɪbəri/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the act of giving bribes:</div><ul class=\"examples\"><li><em>We tried everything – persuasion, bribery, threats.</em></li><li><em>He was found guilty of bribery and corruption (=bribery and dishonest behaviour).</em></li></ul></div>","841":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɪk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable, uncountable]</span> a hard block of baked clay used for building walls, houses etc:</div><ul class=\"examples\"><li><em>a brick wall</em></li><li><em>a house made of brick</em></li><li><em>Protesters attacked the police with stones and bricks.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>bricks and mortar</strong> houses – used especially when talking about them as an investment</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> <em>British English</em> a small square block of wood, plastic etc used as a toy</div><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable]</span> <em>old-fashioned</em> a good person who you can depend on when you are in trouble</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>bricks to clicks</strong> used to talk about changing from selling things in shops to selling things on the Internet</div></div>","842":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /braɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a woman at the time she gets married or just after she is married → groom</div></div>","843":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bride‧groom</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbraɪdɡruːm, -ɡrʊm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a man at the time he gets married, or just after he is married</div></div>","844":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brides‧maid</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbraɪdzmeɪd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a girl or woman, usually unmarried, who helps a bride on her wedding day and is with her at the wedding</div></div>","845":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɪdʒ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[over a river/road etc]</strong> <span class=\"gram\">[countable]</span> a structure built over a river, road etc that allows people or vehicles to cross from one side to the other → suspension bridge, swing bridge</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>[connection]</strong> <span class=\"gram\">[countable]</span> something that provides a connection between two things <em>SYN link</em></div><ul class=\"examples\"><li><strong><em>bridge between/to</strong>: The training programme is seen as a bridge between school and work. / a scheme to build bridges (=make a better relationship) between the police and the community</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[ship]</strong> <span class=\"gram\">[countable usually singular]</span> the raised part of a ship from which the officers control it</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[card game]</strong> <span class=\"gram\">[uncountable]</span> a card game for four players, who play in pairs</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>the bridge of your nose</strong> the upper part of your nose between your eyes</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>[pair of glasses]</strong> <span class=\"gram\">[countable usually singular]</span> the part of a pair of glasses that rests on your nose</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[musical instrument]</strong> <span class=\"gram\">[countable usually singular]</span> a small piece of wood under the strings of a violin or guitar, used to keep them in position</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[for teeth]</strong> <span class=\"gram\">[countable]</span> a small piece of metal that keeps false teeth in place by attaching them to your real teeth</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to reduce or get rid of the difference between two things:</div><ul class=\"examples\"><li><em>The differences between our two cultures can be bridged if we continue to communicate.</em></li><li><em>Alvin managed to bridge the gap between ballet and modern dance.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>written</em> to build or form a bridge over something:</div><ul class=\"examples\"><li><em>a fallen tree bridging the stream</em></li></ul></div></div>","846":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /briːf/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> continuing for a short time → brevity: ► see thesaurus at short</div><ul class=\"examples\"><li><em>We stopped by Alice’s house for a brief visit.</em></li><li><em>Let’s keep this conversation brief; I have a plane to catch.</em></li><li><strong><em>a brief period/moment/spell etc</strong>: Greene spent a brief time at Cambridge.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> using very few words or including few details → brevity:</div><ul class=\"examples\"><li><em>The president read a brief statement to reporters before boarding his plane.</em></li><li><em>a brief description of the film</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be brief</strong> to say or write something using only a few words, especially because there is little time:</div><ul class=\"examples\"><li><em>I’ll be brief; a lot of changes are going to happen.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> clothes that are brief are short and cover only a small area of your body:</div><ul class=\"examples\"><li><em>a very brief bikini</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[usually singular]</span> official instructions that explain what someone’s job is, what their duties are etc:</div><ul class=\"examples\"><li><em>The architect’s brief is to design an extension that is modern but blends with the rest of the building.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>law</em> a short spoken or written statement giving facts about a law case:</div><ul class=\"examples\"><li><em>The ACLU filed a brief (=gave one to the court) opposing the decision.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <em>British English</em> <em>law</em> a law case that a lawyer will argue in a court</div><div class=\"sense\"><span class=\"snum\">4</span> a short report about something</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>in brief</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> in as few words as possible:</div><ul class=\"examples\"><li><em>We should, in brief, invest heavily in digital systems.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> without any details:</div><ul class=\"examples\"><li><em>Here again are today’s headlines in brief.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>briefs</strong> <span class=\"gram\">[plural]</span> men’s or women’s underwear worn on the lower part of the body</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span></div><div class=\"entry-body\"><div class=\"sense\">to give someone all the information about a situation that they will need → briefing ► see thesaurus at tell</div><ul class=\"examples\"><li><strong><em>brief somebody on something</strong>: The president has been fully briefed on the current situation in Haiti.</em></li></ul></div></div>","847":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brief‧case</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbriːfkeɪs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a flat case used especially by business people for carrying papers or documents</div></div>","848":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brief‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbriːfɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">information or instructions that you get before you have to do something</div></div>","849":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brief‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbriːfli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3 AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> for a short time:</div><ul class=\"examples\"><li><em>We stopped off briefly in London.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> in as few words as possible <em>SYN in brief</em>:</div><ul class=\"examples\"><li><em>Sonia explained briefly what we had to do.</em></li><li><em>Briefly, I think we should accept their offer.</em></li></ul></div>","850":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /braɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\">(comparative brighter, superlative brightest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[light]</strong> shining strongly, or with plenty of light:</div><ul class=\"examples\"><li><em>Her eyes were hurting from the bright lights.</em></li><li><em>bright sunshine</em></li><li><em>a large bright room</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[sunny]</strong> if the weather is bright, the sun is shining and there is a lot of light <em>OPP dull</em>:</div><ul class=\"examples\"><li><em>The weather was bright and sunny.</em></li><li><em>a bright autumn day</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[intelligent]</strong> intelligent and able to learn things quickly: ► see thesaurus at intelligent</div><ul class=\"examples\"><li><em>He was an exceptionally bright child.</em></li><li><em>a bright ambitious young man</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>a bright idea</strong> a very good idea – sometimes used ironically (ironic):</div><ul class=\"examples\"><li><em>Whose bright idea was this?</em></li><li><em>He is constantly coming up with bright ideas for making money.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[colours]</strong> bright colours are strong and easy to see: ► see thesaurus at colour</div><ul class=\"examples\"><li><em>a bright red jumper</em></li><li><em>I never wear bright colours.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[cheerful]</strong> happy and full of energy:</div><ul class=\"examples\"><li><em>Her voice was bright and cheerful.</em></li><li><em>She gave him a bright smile.</em></li><li><em>He looked up at me with bright eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[successful]</strong> if the future looks bright, you think that something will be successful <em>SYN promising</em>:</div><ul class=\"examples\"><li><em>The school’s future now looks very bright.</em></li><li><em>I’m sure the company has a bright future now.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>as bright as a button</strong> very intelligent and full of energy</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>look on the bright side</strong> to see the good points in a situation that seems to be bad:</div><ul class=\"examples\"><li><em>Come on, try to look on the bright side.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>bright and early</strong> very early in the morning:</div><ul class=\"examples\"><li><em>He was up bright and early, keen to get started.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>bright spark</strong> <em>informal</em> someone who says or does something that they think is intelligent but is really wrong or stupid:</div><ul class=\"examples\"><li><em>Some bright spark thought the building was on fire and called the fire brigade.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>bright and breezy</strong> happy and confident</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>bright-eyed and bushy-tailed</strong> happy and full of energy</div><div class=\"sense\"><span class=\"snum\">14</span> <strong>the bright lights</strong> the interesting exciting life in a big city:</div><ul class=\"examples\"><li><em>She missed the bright lights of London.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>bright spot</strong> an event or a period of time that is more pleasant when everything else is unpleasant:</div><ul class=\"examples\"><li><em>The only bright spot of the weekend was our trip to the theatre.</em></li></ul></div>","851":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bril‧liant</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrɪljənt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[bright]</strong> brilliant light or colour is very bright and strong: ► see thesaurus at bright, colour</div><ul class=\"examples\"><li><em>She closed her eyes against the brilliant light.</em></li><li><em>We sat outside in the brilliant sunshine.</em></li><li><em>She was dressed in brilliant white.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[clever]</strong> extremely clever or skilful: ► see thesaurus at intelligent</div><ul class=\"examples\"><li><em>I think that’s a brilliant idea.</em></li><li><em>a brilliant performance</em></li><li><em>a brilliant young musician</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[excellent]</strong> <em>British English</em> excellent: ► see thesaurus at good GRAMMARIn this meaning, brilliant is not used with ‘very’. You say: · We had an absolutely brilliant time. ✗Don’t say: We had a very brilliant time.Grammar guide ‒ ADJECTIVES</div><ul class=\"examples\"><li><em>The film was absolutely brilliant.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[successful]</strong> very successful:</div><ul class=\"examples\"><li><em>He had a long and brilliant career.</em></li><li><em>The project was a brilliant success.</em></li></ul></div>","852":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle brought /brɔːt $ brɒːt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> ► see thesaurus at take</div><div class=\"subsense\"><span class=\"subnum\">a)</span> to take something or someone with you to the place where you are now, or to the place you are talking about → take:</div><ul class=\"examples\"><li><em>Did you bring an umbrella?</em></li><li><em>It was the first time Joey had ever brought a girl home.</em></li><li><em>They brought news of further fighting along the border.</em></li><li><strong><em>bring somebody/something to somebody/something</strong>: Is it OK if I bring some friends to the party?</em></li><li><strong><em>bring somebody/something with you</strong>: For some reason, Jesse had brought a tape recorder with him.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to get something for someone and take it to them</div><ul class=\"examples\"><li><strong><em>bring somebody something</strong>: Can you bring me another beer? / Robert asked the waiter to bring him the check. / While she was in prison, friends used to bring her books.</em></li><li><strong><em>bring somebody/something to somebody/something</strong>: He expects me to bring everything to him.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> to make a particular situation exist, or cause a particular feeling:</div><ul class=\"examples\"><li><em>efforts to bring peace to the region</em></li><li><em>The strikes are expected to bring chaos.</em></li><li><em>The senator’s speech brought an angry response from civil rights groups.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to cause someone or something to reach a particular state or condition</div><ul class=\"examples\"><li><strong><em>bring something to an end/close/halt/conclusion</strong> (=make something stop): The trial was swiftly brought to an end.</em></li><li><em>It was the war that first brought him to power (=made him have power over a country).</em></li><li><em>So far the US has been unable to bring him to justice (=make him be punished for his actions).</em></li><li><em>Bring the sauce to the boil (=heat it until it boils).</em></li><li><em>The country had been brought to its knees (=caused to be in such a bad condition that it is almost impossible to continue).</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[always + adverb/preposition]</span> to make something move in a particular direction</div><ul class=\"examples\"><li><strong><em>bring something up/down/round etc</strong>: Bring your arm up slowly until it’s level with your shoulder. / The storm brought the old oak tree crashing down.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[always + adverb/preposition]</span> if something brings people to a place, it makes them go there:</div><ul class=\"examples\"><li><em>The discovery of gold brought thousands of people to the Transvaal.</em></li><li><strong><em>what brings you here?</strong> (=used to ask why someone is in a particular place): What brings you here on a night like this?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> to make something available for people to use, have, enjoy etc:</div><ul class=\"examples\"><li><em>The expansion of state education brought new and wider opportunities for working class children.</em></li><li><strong><em>bring something to somebody/something</strong>: The government is launching a new initiative to bring jobs to deprived areas.</em></li><li><strong><em>bring somebody something</strong>: It’s a good sign – let’s hope it will bring us some luck.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> if a period of time brings a particular event or situation, the event or situation happens during that time:</div><ul class=\"examples\"><li><em>The 1930s brought unemployment and economic recession.</em></li><li><em>Who knows what the future will bring?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bring charges/a lawsuit/a court case/a prosecution/a claim (against somebody)</strong> to begin a court case in order to try to prove that someone has done something wrong or is legally responsible for something wrong:</div><ul class=\"examples\"><li><em>Survivors of the fire later brought a billion-dollar lawsuit against the company.</em></li><li><em>The police say they are planning to bring charges against him.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>bring a smile to somebody’s lips/face</strong> to make someone smile:</div><ul class=\"examples\"><li><em>Her words brought a sudden smile to his lips.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>bring tears to somebody’s eyes</strong> to make someone start to cry:</div><ul class=\"examples\"><li><em>The pain brought tears to his eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>bring the total/number/score etc to something</strong> used when saying what the new total etc is:</div><ul class=\"examples\"><li><em>This brings the total to 46.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>cannot/could not bring yourself to do something</strong> to feel unable to do something because it would upset you or someone else too much:</div><ul class=\"examples\"><li><em>She still can’t bring herself to talk about it.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <em>spoken</em> used when saying that something is the next thing that you want to talk about</div><ul class=\"examples\"><li><strong><em>that/this/which brings me to...</strong>: This brings me to the main point of today’s meeting.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> if a programme is brought to you by a particular television or radio company, they broadcast it or make it</div><ul class=\"examples\"><li><strong><em>something is brought to you by somebody</strong>: This programme is brought to you by the BBC.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>bring something to bear (on/upon something)</strong> <em>formal</em> to use something, for example your power, authority, or your knowledge, in a way that will have a big effect on something or someone:</div><ul class=\"examples\"><li><em>The full force of the law was brought to bear on anyone who criticized the government.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>bring home the bacon</strong> <em>informal</em> to earn the money that your family needs to live</div></div>","853":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɪŋk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the brink (of something)</strong> a situation when you are almost in a new situation, usually a bad one</div><ul class=\"examples\"><li><strong><em>on the brink of death/disaster/war etc</strong>: In October 1962 the world seemed on the brink of nuclear war. / The company had huge debts and was on the brink of collapse.</em></li><li><strong><em>to the brink (of something)</strong>: managers who have taken their companies to the brink of disaster</em></li><li><strong><em>back from the brink (of something)</strong>: He will go down in history as the leader who pulled us back from the brink (=saved us from disaster).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>push/tip somebody over the brink</strong> to make someone start doing crazy or extreme things</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the brink of something</strong> <em>literary</em> the edge of a very high place such as a cliff</div></div>","854":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɪsk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> quick and full of energy: ► see thesaurus at fast</div><ul class=\"examples\"><li><em>a brisk walk</em></li><li><em>They set off at a brisk pace.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> quick, practical, and showing that you want to get things done quickly:</div><ul class=\"examples\"><li><em>Her tone of voice is brisk.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> trade or business that is brisk is very busy, with a lot of products being sold:</div><ul class=\"examples\"><li><em>The public bar was already doing a brisk trade.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> weather that is brisk is cold and clear</div></div>","855":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɔːd $ brɒːd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[wide]</strong> a road, river, or part of someone’s body etc that is broad is wide <em>OPP narrow</em> → breadth: RegisterIn everyday English, wide is more common than broad:· a wide river/street/corridor· They sell a wide range of bikes.Broad is often used when describing someone&#x27;s shoulders.</div><ul class=\"examples\"><li><em>We went along a broad passage.</em></li><li><em>He was six feet tall, with broad shoulders.</em></li><li><strong><em>six feet/three metres etc broad</strong>: The room is three metres long and two metres broad.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[including a lot]</strong> including many different kinds of things or people <em>OPP narrow</em> → breadth:</div><ul class=\"examples\"><li><em>The show aims to reach the broadest possible audience.</em></li><li><strong><em>broad range/spectrum</strong>: Students here study a broad range of subjects.</em></li><li><strong><em>broad category/field/area etc</strong>: Private pension schemes fall into two broad categories.</em></li><li><em>a party which lacks a broad base of political support</em></li><li><em>The play is a comedy, in the broadest sense of the word.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[general]</strong> concerning the main ideas or parts of something rather than all the details:</div><ul class=\"examples\"><li><em>The client should understand, in broad terms, the likely cost of the case.</em></li><li><strong><em>broad consensus/agreement etc</strong>: The members were in broad agreement.</em></li><li><strong><em>broad outline/framework</strong>: I’ll give you a broad outline of the plan.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[large area]</strong> covering a large area:</div><ul class=\"examples\"><li><em>a broad expanse of water</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[way of speaking]</strong> a broad accent clearly shows where you come from <em>SYN strong</em>:</div><ul class=\"examples\"><li><em>a broad Scottish accent</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>broad smile/grin</strong> a big smile:</div><ul class=\"examples\"><li><em>Abby came in with a broad smile on her face.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>in broad daylight</strong> if something, especially a crime, happens in broad daylight, it happens in the daytime and in public:</div><ul class=\"examples\"><li><em>The attack happened in broad daylight, in one of the busiest parts of town.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>broad hint</strong> a hint (=suggestion) that is very clear and easy to understand:</div><ul class=\"examples\"><li><em>In June he gave a broad hint that he might retire.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>a broad church</strong> <em>British English</em> an organization that contains a wide range of opinions:</div><ul class=\"examples\"><li><em>The Labour Party has to be a broad church.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[humour]</strong> broad humour is rather rude or concerned with sex</div><div class=\"sense\"><span class=\"snum\">11</span> <strong>broad in the beam</strong> <em>informal</em> having large or fat hips</div></div>","856":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> broad‧band</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrɔːdbænd $ ˈbrɒːd-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>technical</em> a system of sending radio signals, that allows several messages to be sent at the same time</div><div class=\"sense\"><span class=\"snum\">2</span> a system of connecting computers to the Internet and moving information, such as messages or pictures, at a very high speed</div></div>","857":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> broad‧cast</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrɔːdkɑːst $ ˈbrɒːdkæst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a programme on the radio or on television:</div><ul class=\"examples\"><li><em>a news broadcast</em></li><li><em>CNN’s live broadcast of the trial (=sent out at the same time as the events are happening)</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(past tense and past participle broadcast)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> to send out radio or television programmes:</div><ul class=\"examples\"><li><em>The interview was broadcast live across Europe.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to tell something to a lot of people:</div><ul class=\"examples\"><li><em>Don’t broadcast the fact that he lost his job.</em></li></ul></div></div>","858":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> broad‧en</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrɔːdn $ ˈbrɒːdn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[transitive]</span> to increase something such as your knowledge, experience, or range of activities:</div><ul class=\"examples\"><li><em>The course helps school-leavers broaden their knowledge of the world of work.</em></li><li><em>I’d like to work abroad to broaden my horizons (=learn, experience, or attempt new things).</em></li><li><em>Travel broadens the mind (=helps you to understand and accept other people’s beliefs, customs etc).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to affect or include more people or things, or to make something affect or include more people or things <em>SYN widen, expand</em>:</div><ul class=\"examples\"><li><em>Mr Mates said the party must broaden its appeal to younger voters.</em></li><li><em>Flynn’s appeal broadened as the campaign continued into the summer months.</em></li><li><em>I want to broaden the discussion to other aspects of the problem.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to make something wider, or to become wider <em>SYN widen</em>:</div><ul class=\"examples\"><li><em>Mark’s smile broadened.</em></li><li><em>The council decided to broaden the pavement.</em></li></ul></div>","859":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> broad‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrɔːdli $ ˈbrɒːd-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> in a general way, relating to the main facts rather than details:</div><ul class=\"examples\"><li><em>She knows broadly what to expect.</em></li><li><strong><em>broadly similar/comparable/equivalent etc</strong>: We reached broadly similar conclusions.</em></li><li><em>Broadly speaking, there are four types of champagne.</em></li><li><em>Independent films are, broadly defined, movies that appeal to sophisticated audiences.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>smile/grin broadly</strong> to have a big smile on your face that clearly shows that you are happy or amused</div><div class=\"sense\"><span class=\"snum\">3</span> including a range of different things or subjects:</div><ul class=\"examples\"><li><em>a broadly based school curriculum</em></li><li><em>We invest broadly to lessen the risk.</em></li></ul></div>","860":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bro‧chure</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrəʊʃə, -ʃʊə $ broʊˈʃʊr/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a thin book giving information or advertising something:</div><ul class=\"examples\"><li><em>a holiday brochure</em></li></ul></div>","861":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[piece of equipment]</strong> not working properly:</div><ul class=\"examples\"><li><em>The CD player’s broken again.</em></li><li><em>Do you know how the phone got broken (=became broken)?</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[object]</strong> in small pieces because it has been hit, dropped etc:</div><ul class=\"examples\"><li><em>Mind the broken glass.</em></li><li><em>Wrap it up well so it doesn’t get broken (=become broken) in the mail.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[bone]</strong> cracked because you have had an accident:</div><ul class=\"examples\"><li><em>a badly broken leg</em></li><li><em>Gibbs had an X-ray, which revealed no broken bones.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[not continuous]</strong> interrupted and not continuous:</div><ul class=\"examples\"><li><em>a broken white line</em></li><li><em>a long noisy night of broken sleep</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[person]</strong> extremely weak mentally or physically because you have suffered a lot:</div><ul class=\"examples\"><li><em>He returned from the war a broken man.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>broken English/French etc</strong> if you speak in broken English, French etc, you speak slowly and make a lot of mistakes because you know only a little of the language</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>broken home</strong> a family that no longer lives together because the parents have divorced:</div><ul class=\"examples\"><li><em>The majority of offenders do not come from broken homes.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>broken marriage</strong> a marriage that has ended because the husband and wife do not live together anymore</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>a broken heart</strong> a feeling of extreme sadness, especially because someone you love has died or left you:</div><ul class=\"examples\"><li><em>I reckon she died of a broken heart.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>a broken society</strong> a society which has many social and financial problems:</div><ul class=\"examples\"><li><em>This report paints a depressing picture of Britain&#x27;s broken society.</em></li></ul></div>","862":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bro‧ker</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrəʊkə $ ˈbroʊkər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who buys and sells things such as shares in companies or foreign money for other people → stockbroker</div><div class=\"sense\"><span class=\"snum\">2</span> someone who arranges sales or business agreements for other people:</div><ul class=\"examples\"><li><em>a real estate broker</em></li></ul></div>","863":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brɒnz $ brɑːnz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a hard metal that is a mixture of copper and tin:</div><ul class=\"examples\"><li><em>a bell cast in bronze</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the dark reddish brown colour of bronze</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> a work of art such as a statue (=model of a person), made of bronze:</div><ul class=\"examples\"><li><em>three bronzes by Giacometti</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[countable, uncountable]</span> a bronze medal:</div><ul class=\"examples\"><li><em>King won a bronze in the 100-metres.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> made of bronze:</div><ul class=\"examples\"><li><em>a bronze statuette</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having the dark reddish brown colour of bronze</div></div></div>","864":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bruːm, brʊm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a large brush with a long handle, used for sweeping floors</div><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> a large bush with small yellow flowers</div></div>","865":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> broth‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbrʌðə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a male who has the same parents as you → sister:</div><ul class=\"examples\"><li><em>I have two brothers, William and Mark.</em></li><li><strong><em>elder/older/younger etc brother</strong>: My younger brother is a doctor.</em></li><li><strong><em>little/kid brother</strong> (=younger brother): I have to take my little brother to school.</em></li><li><em>My big brother (=older brother) has always looked after me.</em></li><li><em>my twin brother</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>spoken</em> <em>informal</em> a word meaning a black man, used especially by other black men</div><div class=\"sense\"><span class=\"snum\">3</span> a male member of a group with the same interests, religion, profession etc as you</div><div class=\"sense\"><span class=\"snum\">4</span> (plural brothers or brethren) a male member of a religious group, especially a monk:</div><ul class=\"examples\"><li><em>Brother Justin</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>American English</em> a member of a fraternity (=a club of male university students)</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>brothers in arms</strong> <em>literary</em> soldiers who have fought together in a war</div></div>","866":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈbrother-in-law</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural brothers-in-law)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the brother of your husband or wife</div><div class=\"sense\"><span class=\"snum\">2</span> the husband of your sister</div><div class=\"sense\"><span class=\"snum\">3</span> the husband of your husband or wife’s sister</div></div>","867":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /braʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>literary</em> the part of your face above your eyes and below your hair <em>SYN forehead</em></div><ul class=\"examples\"><li><strong><em>mop/wipe your brow</strong> (=dry your brow with your hand or a cloth because you are hot or nervous)</em></li><li><strong><em>your brow furrows/creases/wrinkles</strong> (=lines appear on your brow because you are thinking or are worried): His brow furrowed. ‘I don’t understand,’ he said.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> an eyebrow</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>the brow of a hill</strong> the top part of a slope or hill</div></div>","868":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adjective</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /braʊn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> having the colour of earth, wood, or coffee:</div><ul class=\"examples\"><li><em>dark brown hair</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> having skin that has been turned brown by the sun:</div><ul class=\"examples\"><li><em>He’d been on vacation and looked very brown.</em></li><li><em>He was as brown as a berry after two weeks in the sun.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the colour of earth, wood, or coffee:</div><ul class=\"examples\"><li><em>This particular model is available in brown, white, or grey.</em></li><li><em>the browns and greens of the landscape</em></li></ul></div></div>","869":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /braʊz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive]</span> to look through the pages of a book, magazine etc without a particular purpose, just looking at the most interesting parts</div><ul class=\"examples\"><li><strong><em>browse through</strong>: Jon was browsing through the photographs.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive, transitive]</span> to look at the goods in a shop without wanting to buy any particular thing</div><ul class=\"examples\"><li><strong><em>browse around</strong>: The trip allows you plenty of time for browsing around the shops.</em></li><li><em>tourists browsing the boutiques and souvenir stalls</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> to search for information on a computer or on the Internet:</div><ul class=\"examples\"><li><em>a feature that allows you to browse your hard drive and choose the graphic you want to display</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[intransitive]</span> if a goat, deer etc browses, it eats plants</div></div>","870":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> brows‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbraʊzə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a computer program that finds information on the Internet and shows it on your computer screen:</div><ul class=\"examples\"><li><em>a Web browser</em></li></ul></div>","871":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bruːz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a purple or brown mark on your skin that you get because you have fallen, been hit etc: ► see thesaurus at injury</div><ul class=\"examples\"><li><em>minor cuts and bruises</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a mark on a piece of fruit that spoils its appearance</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive, transitive]</span> if part of your body bruises, or if you bruise part of your body, it gets hit or hurt and a bruise appears: ► see thesaurus at hurt</div><ul class=\"examples\"><li><em>She fell off her bike and bruised her knee.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[transitive]</span> to affect someone badly and make them feel less confident</div><ul class=\"examples\"><li><strong><em>bruise somebody’s pride/ego</strong>: The incident had bruised his pride.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[intransitive, transitive]</span> if a piece of fruit bruises, or is bruised, it gets a bruise by being hit, dropped etc</div></div></div>","872":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brʌntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a meal eaten in the late morning, as a combination of breakfast and lunch</div></div>","873":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /brʌʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[object for cleaning/painting]</strong> <span class=\"gram\">[countable]</span> an object that you use for cleaning, painting, making your hair tidy etc, made with a lot of hairs, bristles, or thin pieces of plastic, fastened to a handle → broom: → hairbrush, nailbrush, paintbrush, toothbrush</div><ul class=\"examples\"><li><em>a scrubbing brush</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[trees]</strong> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> small bushes and trees that cover an area of land</div><div class=\"subsense\"><span class=\"subnum\">b)</span> branches that have broken off bushes and trees</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[movement]</strong> <span class=\"gram\">[singular]</span> a movement in which you brush something to remove dirt, make something smooth, tidy etc:</div><ul class=\"examples\"><li><em>I’ll just give my hair a quick brush.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[touch]</strong> <span class=\"gram\">[singular]</span> a quick light touch, made by chance when two things or people pass each other:</div><ul class=\"examples\"><li><em>the brush of her silk dress as she walked past</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[countable]</span> a time when you only just avoid an unpleasant situation or argument</div><ul class=\"examples\"><li><strong><em>brush with</strong>: His first brush with the law came when he was 16.</em></li><li><em>A brush with death can make you appreciate life more.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[tail]</strong> <span class=\"gram\">[countable]</span> the tail of a fox</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[clean/make tidy]</strong> <span class=\"gram\">[transitive]</span> to clean something or make something smooth and tidy using a brush → sweep:</div><ul class=\"examples\"><li><em>Don’t forget to brush your teeth.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[remove]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to remove something with a brush or with your hand</div><ul class=\"examples\"><li><strong><em>brush something off/from etc something</strong>: Ella brushed the crumbs off her jacket. / He brushed the tears from his eyes.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[touch lightly]</strong> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to touch someone or something lightly when passing them:</div><ul class=\"examples\"><li><em>Something brushed her shoulders.</em></li><li><strong><em>brush against</strong>: I felt her hair brush against my arm.</em></li><li><strong><em>brush past</strong>: Nell brushed past him in the doorway.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[put something on something]</strong> <span class=\"gram\">[transitive always + adverb/preposition]</span> to put a liquid onto something using a brush</div><ul class=\"examples\"><li><strong><em>brush something with something</strong>: Brush the pastry with milk.</em></li><li><strong><em>brush something over/onto something</strong>: Brush a little oil over the top of the pizza.</em></li></ul></div></div>","874":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bru‧tal</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbruːtl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> very cruel and violent ► see thesaurus at cruel, violent</div><ul class=\"examples\"><li><strong><em>brutal murder/attack/assault</strong>: a brutal attack on a defenceless old man</em></li><li><em>a brutal man</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> not pleasant and not sensitive to people’s feelings:</div><ul class=\"examples\"><li><em>He replied with brutal honesty.</em></li></ul></div>","875":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bub‧ble</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌbəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a ball of air or gas in liquid:</div><ul class=\"examples\"><li><em>When water boils, bubbles rise to the surface.</em></li><li><em>soap bubbles</em></li><li><em>She was blowing bubbles in her milk with a straw.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small amount of air trapped in a solid substance:</div><ul class=\"examples\"><li><em>Examine the glass carefully for bubbles.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bubble of something</strong> <em>literary</em> a small amount of a feeling:</div><ul class=\"examples\"><li><em>A bubble of anger rose in Pol’s throat.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> (also speech bubble) a circle around the words said by someone in a cartoon</div><div class=\"sense\"><span class=\"snum\">5</span> a situation in which the prices of something such as company shares or houses increase a lot very quickly, so they are too high and will quickly come down again:</div><ul class=\"examples\"><li><em>Eager investors created a stock market bubble.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>the bubble bursts</strong> used for saying that a very successful or happy period of time suddenly ends:</div><ul class=\"examples\"><li><em>The bubble has finally burst in the mobile phone industry.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>burst/prick somebody’s bubble</strong> to make someone suddenly realize that something is not as good as they thought it was</div></div>","876":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> buck‧et</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌkɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an open container with a handle, used for carrying and holding things, especially liquids <em>SYN pail</em></div><div class=\"sense\"><span class=\"snum\">2</span> (also bucketful) the quantity of liquid that a bucket can hold</div><ul class=\"examples\"><li><strong><em>bucket of</strong>: a bucket of water</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a part of a machine shaped like a large bucket and used for moving earth, water etc</div><div class=\"sense\"><span class=\"snum\">4</span> <em>informal</em> a large amount of something:</div><ul class=\"examples\"><li><em>They were drinking beer by the bucket.</em></li><li><strong><em>bucket of</strong>: They made buckets of cash on the deal.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>weep buckets</strong> <em>informal</em> to cry a lot</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>in buckets</strong> <em>informal</em> if rain comes down in buckets, it is raining very hard</div></div>","877":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌd/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a young tightly rolled-up flower or leaf before it opens:</div><ul class=\"examples\"><li><em>rose buds</em></li><li><strong><em>in bud</strong> (=having buds but no flowers yet)</em></li><li><strong><em>come into bud</strong> (=start to produce buds)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> <em>spoken</em> buddy:</div><ul class=\"examples\"><li><em>Hey, bud, how’s it going?</em></li></ul></div>","878":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bud‧get</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌdʒɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the money that is available to an organization or person, or a plan of how it will be spent</div><ul class=\"examples\"><li><strong><em>budget of</strong>: a welfare program with a budget of $2 million</em></li><li><strong><em>budget for</strong>: The budget for photography has been cut.</em></li><li><em>We had a really tight budget.</em></li><li><strong><em>on/within budget</strong> (=not using more money than planned): The project was completed within budget.</em></li><li><strong><em>under budget</strong> (=using less money than planned): If you come in under budget, everyone will be very impressed.</em></li><li><strong><em>over budget</strong> (=using more money than planned): Feature movies always run over budget.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>on a budget</strong> if you are on a budget, you do not have much money to spend:</div><ul class=\"examples\"><li><em>Travellers on a budget might prefer to camp.</em></li><li><em>a book which offers great ideas for decorating on a budget</em></li><li><em>families on a tight budget</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> (also Budget) <em>British English</em> an official statement that a government makes about how much it intends to spend and what taxes will be necessary</div></div>","879":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> buf‧fet</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊfeɪ $ bəˈfeɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a meal at a party or other occasion, in which people serve themselves at a table and then move away to eat:</div><ul class=\"examples\"><li><em>a cold buffet</em></li><li><strong><em>buffet breakfast/lunch/supper</strong>: The price includes morning coffee, buffet lunch, and afternoon tea.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a place in a railway station, bus station etc where you can buy and eat food or drink</div><div class=\"sense\"><span class=\"snum\">3</span> <em>American English</em> a piece of furniture in which you keep the things you use to serve and eat a meal SYN sideboard<em>British English</em></div></div>","880":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌɡ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>informal</em> an illness that people catch very easily from each other but is not very serious ► see thesaurus at illness</div><ul class=\"examples\"><li><strong><em>catch/pick up/get a bug</strong>: I picked up a bug last weekend.</em></li><li><em>There’s a nasty bug going round (=that a lot of people have caught).</em></li><li><strong><em>tummy/stomach bug</strong> (=illness affecting your stomach): He’s off work with a stomach bug.</em></li><li><em>a 24-hour flu bug</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <em>especially American English</em> a small insect</div><div class=\"sense\"><span class=\"snum\">3</span> a fault in the system of instructions that operates a computer: → debug ► see thesaurus at fault</div><ul class=\"examples\"><li><em>a bug in the software</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> a small piece of electronic equipment for listening secretly to other people’s conversations</div><div class=\"sense\"><span class=\"snum\">5</span> <em>informal</em> a sudden strong interest in doing something</div><ul class=\"examples\"><li><strong><em>the travel/sailing etc bug</strong>: She’s got the travel bug.</em></li><li><em>I had one flying lesson and immediately caught the bug (=became very interested in flying).</em></li></ul></div>","881":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɪld/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle built /bɪlt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[make something]</strong> <span class=\"gram\">[intransitive, transitive]</span> to make something, especially a building or something large:</div><ul class=\"examples\"><li><em>The purpose is to build new houses for local people.</em></li><li><em>The road took many years to build.</em></li><li><em>They needed $3 million to build the bridge.</em></li><li><em>It is the female birds that build the nests.</em></li><li><em>Developers want to build on the site of the old gasworks.</em></li><li><em>a row of recently built houses</em></li><li><strong><em>build somebody something</strong>: He’s going to build the children a doll’s house.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[make something develop]</strong> (also build up) <span class=\"gram\">[transitive]</span> to make something develop or form:</div><ul class=\"examples\"><li><em>She had built a reputation as a criminal lawyer.</em></li><li><em>She’s been busy building her career.</em></li><li><em>Ross took 20 years to build up his business.</em></li><li><strong><em>build (up) a picture of somebody/something</strong> (=form a clear idea about someone or something): We’re trying to build up a picture of what happened.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>be built of something</strong> to be made using particular materials:</div><ul class=\"examples\"><li><em>The church was built of brick.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[feeling]</strong> (also build up) <span class=\"gram\">[intransitive, transitive]</span> if a feeling builds, or if you build it, it increases gradually over a period of time:</div><ul class=\"examples\"><li><em>Tension began to build as they argued more frequently.</em></li><li><em>In order to build your self-esteem, set yourself targets you can reach.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>build bridges</strong> to try to establish a better relationship between people who do not like each other:</div><ul class=\"examples\"><li><em>Peter needs to try and build bridges with Lizzie.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[singular, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">the shape and size of someone’s body → built:</div><ul class=\"examples\"><li><em>a woman of slim build</em></li><li><em>You’re a surprisingly strong swimmer for one of such a slight build.</em></li><li><em>I wanted a more athletic and muscular build.</em></li></ul></div></div>","882":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> build‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪldə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><em>especially British English</em> a person or a company that builds or repairs buildings</div></div>","883":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> build‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪldɪŋ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> a structure such as a house, church, or factory, that has a roof and walls:</div><ul class=\"examples\"><li><em>The offices are on the top two floors of the building.</em></li><li><em>a farmhouse and other farm buildings</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[uncountable]</span> the process or business of building things → construction:</div><ul class=\"examples\"><li><em>There is a limited supply of land for building.</em></li><li><em>stone, timber, and other building materials</em></li><li><strong><em>building of</strong>: The enquiry recommended the building of a tunnel.</em></li></ul></div>","884":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˌbuilt-ˈin</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">forming a part of something that cannot be separated from it → inbuilt:</div><ul class=\"examples\"><li><em>a built-in microphone</em></li></ul></div>","885":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌlb/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the glass part of an electric light, that the light shines from <em>SYN light bulb</em>:</div><ul class=\"examples\"><li><em>a 100-watt bulb</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a root shaped like a ball that grows into a flower or plant:</div><ul class=\"examples\"><li><em>tulip bulbs</em></li></ul></div>","886":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌlk/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○ AWL</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>the bulk (of something)</strong> the main or largest part of something:</div><ul class=\"examples\"><li><em>The bulk of consumers are based in towns.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable usually singular]</span> a big mass or shape of something: ► see thesaurus at size</div><ul class=\"examples\"><li><em>the great bulk of a building</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[uncountable]</span> the size of something or someone:</div><ul class=\"examples\"><li><em>The dough will rise until it is double in bulk.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>in bulk</strong> if you buy goods in bulk, you buy large amounts each time you buy them</div></div>","887":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʊl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[male cow]</strong> <span class=\"gram\">[countable]</span> an adult male animal of the cattle family:</div><ul class=\"examples\"><li><em>a herd of cows with one bull</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[male animal]</strong> <span class=\"gram\">[countable]</span> the male of some other large animals such as the elephant or whale</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>take the bull by the horns</strong> to bravely or confidently deal with a difficult, dangerous, or unpleasant problem:</div><ul class=\"examples\"><li><em>Nora decided to take the bull by the horns and organize things for herself.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[nonsense]</strong> <span class=\"gram\">[uncountable]</span> <em>informal</em> nonsense or something that is completely untrue <em>SYN rubbish</em>:</div><ul class=\"examples\"><li><em>What a load of bull!</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>like a bull in a china shop</strong> if you are like a bull in a china shop, you keep knocking things over, dropping things, breaking things etc</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>like a bull at a gate</strong> if you move somewhere like a bull at a gate, you move there very fast, ignoring everything in your way</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[religion]</strong> <span class=\"gram\">[countable]</span> an official statement from the Pope</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>[centre]</strong> <span class=\"gram\">[countable]</span> (also bullseye) the centre of a target that you are shooting at</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>[business]</strong> <span class=\"gram\">[countable]</span> <em>technical</em> someone who buys shares because they expect prices to rise → bear → bull market</div></div>","888":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bul‧let</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊlɪt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a small piece of metal that you fire from a gun → shell, shot:</div><ul class=\"examples\"><li><em>He was killed by a single bullet.</em></li><li><em>a bullet wound in the shoulder</em></li><li><em>Several bullet holes could be seen beside a window.</em></li></ul></div>","889":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bul‧le‧tin</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊlətɪn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a news report on radio or television</div><div class=\"sense\"><span class=\"snum\">2</span> an official statement that tells people about something important</div><div class=\"sense\"><span class=\"snum\">3</span> a letter or printed statement that a group or organization produces to tell people its news</div></div>","890":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bul‧ly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊli/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural bullies)</span></div><div class=\"entry-body\"><div class=\"sense\">someone who uses their strength or power to frighten or hurt someone who is weaker:</div><ul class=\"examples\"><li><em>Bullies are often cowards.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle bullied, present participle bullying, third person singular bullies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> to threaten to hurt someone or frighten them, especially someone smaller or weaker</div><div class=\"sense\"><span class=\"snum\">2</span> to put pressure on someone in order to make them do what you want</div><ul class=\"examples\"><li><strong><em>bully somebody into (doing) something</strong>: Don’t let them bully you into working on Saturdays.</em></li></ul></div></div>","891":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌm/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> the part of your body that you sit on <em>SYN bottom</em></div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> someone, especially a man, who has no home or job, and who asks people for money</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>beach/ski etc bum</strong> someone who spends all their time on the beach, skiing etc without having a job</div><div class=\"sense\"><span class=\"snum\">4</span> someone who is very lazy</div><div class=\"sense\"><span class=\"snum\">5</span> <strong>get/put bums on seats</strong> <em>British English</em> <em>informal</em> to make a large number of people go to see a film, play, sports match etc:</div><ul class=\"examples\"><li><em>She’s the kind of star who will put bums on seats.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>give somebody the bum&#x27;s rush</strong> <em>informal</em> to make someone leave a place, especially a public place, quickly</div></div>","892":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌmp/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[intransitive always + adverb/preposition, transitive]</span> to hit or knock against something ► see thesaurus at hit</div><ul class=\"examples\"><li><strong><em>bump against</strong>: I ran after him, bumping against people in my hurry.</em></li><li><strong><em>bump into</strong>: Tim was a clumsy boy, always bumping into the furniture.</em></li><li><strong><em>bump something on something</strong>: She bumped her arm on the table.</em></li><li><em>The roof was so low he bumped his head (=his head hit the roof).</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move up and down as you move forward, especially in a vehicle:</div><ul class=\"examples\"><li><em>A police car bumped down the track.</em></li><li><strong><em>bump along</strong>: The plane was bumping along the runway.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive always + adverb/preposition]</span> to push or pull something somewhere in an irregular or unsteady way:</div><ul class=\"examples\"><li><em>Flora was bumping her bags down the steps.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> <em>informal</em> to move someone or something into a different class or group, or to remove them from a class or group altogether:</div><ul class=\"examples\"><li><em>The flight was overbooked, and Dad was the first one to be bumped.</em></li><li><strong><em>bump somebody up to/out of/from etc something</strong>: The reforms bumped many families off the state-provided health care list.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <span class=\"gram\">[transitive]</span> to move a radio or television programme to a different time:</div><ul class=\"examples\"><li><em>‘Married with Children’ will be bumped from Sundays to Saturdays.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an area of skin that is raised because you have hit it on something → lump: ► see thesaurus at injury</div><ul class=\"examples\"><li><em>She has a bump on the back of her head.</em></li><li><em>He had a few injuries, mostly bumps and bruises.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small raised area on a surface: → speed bump</div><ul class=\"examples\"><li><em>The car hit a bump on the road.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> the sound or sudden movement of something hitting a hard surface:</div><ul class=\"examples\"><li><em>We heard a bump in the next room.</em></li><li><strong><em>fall/sit down etc with a bump</strong>: Rose fell, landing with a bump.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>informal</em> a small accident in which your car hits something but you are not hurt</div></div></div>","893":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bump‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌmpi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\">(comparative bumpier, superlative bumpiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a bumpy surface is flat but has a lot of raised parts, so it is difficult to walk or drive on it <em>SYN uneven</em> <em>OPP smooth</em>: ► see thesaurus at rough</div><ul class=\"examples\"><li><em>a bumpy road</em></li><li><em>The ground is bumpy in places.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a bumpy journey by car or plane is uncomfortable, with movements up and down because of bad road or weather conditions <em>OPP smooth</em>:</div><ul class=\"examples\"><li><em>The plane made a bumpy landing.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>a bumpy ride/time</strong> having a lot of problems for a long time:</div><ul class=\"examples\"><li><em>Shareholders have had a bumpy ride.</em></li></ul></div>","894":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌntʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[group of things]</strong> <span class=\"gram\">[countable]</span> a group of things that are fastened, held, or growing together ► see thesaurus at group</div><ul class=\"examples\"><li><strong><em>bunch of</strong>: I’ll send her a bunch of flowers. / He had a bunch of keys on his belt. / a bunch of grapes</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[group of people]</strong> <span class=\"gram\">[singular]</span> <em>informal</em> a group of people:</div><ul class=\"examples\"><li><em>The ancient Egyptians were a clever bunch.</em></li><li><strong><em>bunch of</strong>: a friendly bunch of people</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the best/pick of the bunch</strong> the best among a group of people or things</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>[large amount]</strong> <span class=\"gram\">[singular]</span> <em>American English</em> <em>informal</em> a large number of people or things, or a large amount of something</div><ul class=\"examples\"><li><strong><em>bunch of</strong>: There’s a whole bunch of places I want to visit.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>bunches</strong> <span class=\"gram\">[plural]</span> <em>British English</em> if a girl wears her hair in bunches, she ties it together at each side of her head</div></div>","895":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bun‧dle</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌndl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a group of things such as papers, clothes, or sticks that are fastened or tied together ► see thesaurus at group</div><ul class=\"examples\"><li><strong><em>bundle of</strong>: bundles of newspapers</em></li><li><em>a small bundle containing mostly clothing</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a number of things that belong or are dealt with together</div><ul class=\"examples\"><li><strong><em>bundle of</strong>: bundles of data</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> computer software, and sometimes other equipment or services that are included with a new computer at no extra cost</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>a bundle</strong> <em>informal</em> a lot of money:</div><ul class=\"examples\"><li><em>College evening classes cost a bundle.</em></li><li><em>A company can make a bundle by selling unwanted property.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be a bundle of nerves</strong> <em>informal</em> to be very nervous</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>be a bundle of laughs/fun</strong> <em>British English</em> <em>informal</em> an expression meaning a person or situation that is fun or makes you laugh, often used jokingly when they are not fun at all:</div><ul class=\"examples\"><li><em>Being a teenager isn’t a bundle of laughs.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>not go a bundle on something/somebody</strong> <em>British English</em> <em>informal</em> to not like something or someone very much:</div><ul class=\"examples\"><li><em>Jim never drank, and certainly didn’t go a bundle on gambling.</em></li></ul></div>","896":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bun‧ga‧low</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌŋɡələʊ $ -loʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <em>British English</em> a house that is all on ground level</div><div class=\"sense\"><span class=\"snum\">2</span> <em>American English</em> a small house that is often on one level</div></div>","897":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bur‧den</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɜːdn $ ˈbɜːrdn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> something difficult or worrying that you are responsible for:</div><ul class=\"examples\"><li><em>His family responsibilities had started to become a burden.</em></li><li><strong><em>burden of</strong>: The burden of taxation has risen considerably.</em></li><li><strong><em>burden on</strong>: I don’t like being a burden on other people.</em></li><li><strong><em>bear/carry the burden</strong>: If things go wrong he will bear the burden of guilt.</em></li><li><strong><em>the tax/financial/debt burden</em></strong></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the burden of proof</strong> <em>law</em> the duty to prove that something is true</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> something that is carried <em>SYN load</em></div></div>","898":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bu‧reau</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbjʊərəʊ $ ˈbjʊroʊ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural bureaus or bureaux /-rəʊz $ -roʊz/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an office or organization that collects or provides information:</div><ul class=\"examples\"><li><em>an employment bureau</em></li><li><em>the Citizens Advice Bureau</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a government department or a part of a government department in the US:</div><ul class=\"examples\"><li><em>the Federal Bureau of Investigation</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> an office of a company or organization that has its main office somewhere else:</div><ul class=\"examples\"><li><em>the London bureau of the Washington Post</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>British English</em> a large desk or writing table</div><div class=\"sense\"><span class=\"snum\">5</span> <em>American English</em> a piece of furniture with several drawers, used to keep clothes in SYN chest of drawers<em>British English</em></div></div>","899":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bu‧reauc‧ra‧cy</span><span class=\"meta-item\"><strong>IPA:</strong> /bjʊəˈrɒkrəsi $ bjʊˈrɑː-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\">(plural bureaucracies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[uncountable]</span> a complicated official system that is annoying or confusing because it has a lot of rules, processes etc → red tape:</div><ul class=\"examples\"><li><em>the reduction of unnecessary bureaucracy</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <span class=\"gram\">[countable, uncountable]</span> the officials who are employed rather than elected to do the work of a government, business etc</div></div>","900":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bu‧reau‧crat</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbjʊərəkræt $ ˈbjʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who works in a bureaucracy and uses official rules very strictly</div></div>","901":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bu‧reau‧crat‧ic</span><span class=\"meta-item\"><strong>IPA:</strong> /ˌbjʊərəˈkrætɪk◂ $ ˌbjʊr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\">involving a lot of complicated official rules and processes</div></div>","902":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> burg‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɜːɡə $ ˈbɜːrɡər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a flat round piece of finely cut beef, which is cooked and eaten, or one of these served in a bread bun <em>SYN hamburger</em></div></div>","903":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bur‧glar</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɜːɡlə $ ˈbɜːrɡlər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">someone who goes into houses, shops etc to steal things → robber, thief, cat burglar ► see thesaurus at thief</div></div>","904":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈburglar aˌlarm</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a piece of equipment that makes a loud noise when someone tries to get into a building illegally</div></div>","905":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bur‧glar‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɜːɡləri $ ˈbɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span><span class=\"meta-item\">(plural burglaries)</span></div><div class=\"entry-body\"><div class=\"sense\">the crime of getting into a building to steal things: ► see thesaurus at crime</div><ul class=\"examples\"><li><em>Burglaries have risen by 5%.</em></li><li><em>He was charged with burglary.</em></li><li><em>Most burglaries happen at night.</em></li></ul></div>","906":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bur‧i‧al</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈberiəl/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable, uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the act or ceremony of putting a dead body into a grave</div><div class=\"sense\"><span class=\"snum\">2</span> the act of burying something in the ground</div><ul class=\"examples\"><li><strong><em>burial of</strong>: the burial of solid waste</em></li></ul></div>","907":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-High\">High</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɜːn $ bɜːrn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span><span class=\"meta-item\">(past tense and past participle burnt /bɜːnt $ bɜːrnt/ or burned)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[produce flames and heat]</strong> <span class=\"gram\">[intransitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if a fire burns, it produces heat and flames:</div><ul class=\"examples\"><li><em>There was a fire burning in the fireplace.</em></li><li><em>An average household candle will burn for about six hours.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if something is burning, it is producing flames and being damaged or destroyed by fire:</div><ul class=\"examples\"><li><em>Parts of the building are still burning.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[destroy something with fire]</strong> <span class=\"gram\">[transitive]</span> to destroy or damage something with fire:</div><ul class=\"examples\"><li><em>I burnt all his old letters.</em></li><li><em>Cars were burned and shops were looted during the rioting.</em></li><li><em>The Grand Hotel had burnt to the ground.</em></li><li><em>Make sure the iron isn’t too hot or you’ll burn the cloth.</em></li><li><em>He dropped his cigarette and burnt a hole in the carpet.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[injure/kill somebody with fire]</strong> <span class=\"gram\">[transitive]</span> to hurt yourself or someone else with fire or something hot:</div><ul class=\"examples\"><li><em>I burned my hand on the oven door.</em></li><li><em>She was badly burned in a road accident.</em></li><li><em>Sixteen passengers were burned to death (=died in a fire).</em></li><li><em>A family of five were burned alive in their home last night (=died in a fire).</em></li><li><em>Heretics were burnt at the stake (=burnt in a fire as a punishment).</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[sun]</strong> <span class=\"gram\">[intransitive, transitive]</span> if the sun burns your skin, or if your skin burns, it becomes red and painful from the heat of the sun → sunburn:</div><ul class=\"examples\"><li><em>I burn quite easily.</em></li><li><em>Don’t forget you can still get burnt when you’re swimming or when it’s cloudy.</em></li><li><em>Her face and neck were quite badly burned.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[food]</strong> <span class=\"gram\">[intransitive, transitive]</span> to spoil food by cooking it for too long, or to become spoiled in this way:</div><ul class=\"examples\"><li><em>I’m afraid I’ve burnt the pizza.</em></li><li><strong><em>burn something to a crisp/cinder</strong>: The meat was burned to a crisp.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[chemicals]</strong> <span class=\"gram\">[transitive]</span> to damage or destroy something by a chemical action:</div><ul class=\"examples\"><li><em>Quite a lot of household chemicals can burn your skin.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[fuel]</strong> <span class=\"gram\">[intransitive, transitive]</span> if you burn a fuel, or if it burns, it is used to produce power, heat, light etc:</div><ul class=\"examples\"><li><em>The boiler burns oil to produce heat.</em></li><li><em>greenhouse gases caused by the burning of fossil fuels</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[fat/energy]</strong> <span class=\"gram\">[transitive]</span> if you burn fat or calories, you use up energy stored in your body by being physically active:</div><ul class=\"examples\"><li><em>Taking a brisk walk every morning is a great way to burn calories.</em></li><li><em>a fat-burning exercise</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[light]</strong> <span class=\"gram\">[intransitive]</span> if a light or lamp burns, it shines or produces light:</div><ul class=\"examples\"><li><em>A lamp was burning in the kitchen window.</em></li><li><em>The hall light was still burning.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[feel hot and painful]</strong> <span class=\"gram\">[intransitive, transitive]</span> if a part of your body burns, or if something burns it, it feels unpleasantly hot:</div><ul class=\"examples\"><li><em>The whisky burned my throat as it went down.</em></li><li><em>My eyes were burning from the smoke.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[face/cheeks]</strong> <span class=\"gram\">[intransitive]</span> if your face or cheeks are burning, they feel hot because you are embarrassed or upset:</div><ul class=\"examples\"><li><em>I could feel my cheeks burning as I spoke.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[CD]</strong> <span class=\"gram\">[transitive]</span> if you burn a CD or DVD, you record music, images, or other information onto it using special computer equipment</div><div class=\"sense\"><span class=\"snum\">13</span> <strong>be burning with rage/desire etc</strong> to feel a particular emotion very strongly:</div><ul class=\"examples\"><li><em>She was burning with curiosity.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>be burning to do something</strong> to want to do or find out something very much:</div><ul class=\"examples\"><li><em>I was burning to know how he had got on in New York.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>be/get burned</strong> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be emotionally hurt by someone or something:</div><ul class=\"examples\"><li><em>Take things slowly – don’t get burned again.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to lose a lot of money:</div><ul class=\"examples\"><li><em>The company got badly burned in the dot.com collapse.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>burn your fingers/get your fingers burned</strong> <em>informal</em> to suffer the unpleasant results of something that you have done:</div><ul class=\"examples\"><li><em>I tried a dating agency once, but got my fingers badly burnt – I’ll never do it again.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>burn a hole in your pocket</strong> if money burns a hole in your pocket, you want to spend it as soon as you can</div><div class=\"sense\"><span class=\"snum\">18</span> <strong>burn your bridges/boats</strong> <em>informal</em> to do something with the result that you will not be able to return to a previous situation again, even if you want to:</div><ul class=\"examples\"><li><em>I’m really tempted to take up that job offer in Washington, but I don’t want to burn my boats with this company.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>burn the candle at both ends</strong> <em>informal</em> to get very tired by doing things until very late at night and getting up early in the mornings</div><div class=\"sense\"><span class=\"snum\">20</span> <strong>burn the midnight oil</strong> <em>informal</em> to work or study until late at night</div><div class=\"sense\"><span class=\"snum\">21</span> <strong>it burns somebody that/how etc</strong> <em>American English</em> used to say that something makes someone feel angry or jealous:</div><ul class=\"examples\"><li><em>It really burns me the way they treat us.</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>[go fast]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> <em>informal</em> to travel very fast</div><ul class=\"examples\"><li><strong><em>burn along/up etc</strong>: a sports car burning up the motorway</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> an injury caused by fire, heat, the light of the sun, or acid:</div><ul class=\"examples\"><li><em>His body was covered in cigarette burns.</em></li><li><strong><em>severe/serious burns</strong>: She was taken to the hospital with serious burns. / Several of the survivors suffered severe burns.</em></li><li><em>She is being treated for minor burns.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a mark on something caused by fire or heat:</div><ul class=\"examples\"><li><em>The desk was covered with graffiti and burn marks.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a painful mark on the skin caused by it rubbing hard against something rough</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>the burn</strong> <em>informal</em> a painful hot feeling in your muscles when you exercise a lot:</div><ul class=\"examples\"><li><em>Go for the burn.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>British English</em> a small stream</div></div></div>","908":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> burn‧ing</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɜːnɪŋ $ ˈbɜːr-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[only before noun]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> on fire:</div><ul class=\"examples\"><li><em>She was rescued from a burning building.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> feeling very hot:</div><ul class=\"examples\"><li><em>Claudia put her hands to her burning face.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>burning ambition/desire/need etc</strong> a burning ambition, desire, need etc is very strong:</div><ul class=\"examples\"><li><em>My burning ambition is to be world champion.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>burning issue/question</strong> a burning issue or question is very important and urgent:</div><ul class=\"examples\"><li><em>Education has become a burning issue in this election.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <em>written</em> burning eyes look at you very hard or show very strong feeling</div></div>","909":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> damaged or hurt by burning:</div><ul class=\"examples\"><li><em>burnt toast</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>burnt offering</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> something that is offered as a gift to a god by being burnt on an altar</div><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>British English</em> <em>humorous</em> food that you accidentally burnt while you were cooking it</div></div>","910":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bɜːst $ bɜːrst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ W3</span><span class=\"meta-item\">(past tense and past participle burst)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[break open]</strong> <span class=\"gram\">[intransitive, transitive]</span> if something bursts, or if you burst it, it breaks open or apart suddenly and violently so that its contents come out: ► see thesaurus at break, explode</div><ul class=\"examples\"><li><em>The pipes had burst and the house was under two feet of water.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>be bursting with something</strong> to have a lot of something or be filled with something:</div><ul class=\"examples\"><li><em>John was bursting with ideas and good humour.</em></li><li><em>The shops are bursting with food.</em></li><li><strong><em>be bursting with pride/energy/excitement etc</strong>: Your mum’s bursting with pride for you.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[move suddenly]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span> to move somewhere suddenly or quickly, especially into or out of a place</div><ul class=\"examples\"><li><strong><em>burst into/through/in etc</strong>: Jo burst into the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>burst open</strong> to open suddenly:</div><ul class=\"examples\"><li><em>The door burst open and Tom ran into the room.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>be bursting to do something</strong> <em>informal</em> to want to do something very much:</div><ul class=\"examples\"><li><em>Zach was bursting to tell them something.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>be bursting</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> <em>British English</em> <em>informal</em> to need to go to the toilet very soon</div><div class=\"subsense\"><span class=\"subnum\">b)</span> (also be bursting at the seams) to be so full that nothing else can fit inside</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>burst somebody’s bubble</strong> to make someone suddenly realize that something is not as good as they thought it was:</div><ul class=\"examples\"><li><em>Steve was so happy I couldn’t bear to burst his bubble.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>burst its banks</strong> if a river bursts its banks, water from it goes onto the land</div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> the act of something bursting or the place where it has burst:</div><ul class=\"examples\"><li><em>a burst in the water pipe</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> a short sudden effort or increase in activity</div><ul class=\"examples\"><li><strong><em>burst of</strong>: The van gave a sudden burst of speed.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> a short sudden and usually loud sound</div><ul class=\"examples\"><li><strong><em>burst of</strong>: sharp bursts of machine gun fire</em></li></ul><div class=\"subsense\"><span class=\"subnum\">c)</span> a sudden strong feeling or emotion</div><ul class=\"examples\"><li><strong><em>burst of anger/enthusiasm/temper etc</em></strong></li></ul></div></div>","911":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bur‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈberi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle buried, present participle burying, third person singular buries)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[dead person]</strong> to put someone who has died in a grave</div><ul class=\"examples\"><li><strong><em>bury somebody in/at etc something</strong>: He was buried in the churchyard of St Mary’s.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[object]</strong> to put something under the ground, often in order to hide it:</div><ul class=\"examples\"><li><em>Electric cables are buried beneath the streets.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[fall on something]</strong> <span class=\"gram\">[usually passive]</span> to fall on top of someone or something, usually harming or destroying them</div><ul class=\"examples\"><li><strong><em>be buried under/beneath etc something</strong>: The skiers were buried under the snow.</em></li><li><em>Fifty-seven miners were buried alive.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[hidden]</strong> to cover something so that it cannot be found GRAMMAR Bury is usually passive in this meaning.</div><ul class=\"examples\"><li><strong><em>be buried under/in something</strong>: His glasses were buried under a pile of papers.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[feeling/memory]</strong> to ignore a feeling or memory and pretend that it does not exist:</div><ul class=\"examples\"><li><em>a deeply buried memory</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>bury your face/head etc (in something)</strong> to press your face etc into something soft:</div><ul class=\"examples\"><li><em>Noel buried his face in the pillow.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>bury your face/head in your hands</strong> to cover your face with your hands because you are very upset</div><div class=\"sense\"><span class=\"snum\">8</span> <strong>bury your head in the sand</strong> to ignore an unpleasant situation and hope it will stop if you do not think about it</div><div class=\"sense\"><span class=\"snum\">9</span> <strong>bury the hatchet/bury your differences</strong> to agree to stop arguing about something and become friends</div><div class=\"sense\"><span class=\"snum\">10</span> <strong>[in a surface]</strong> to push something, especially something sharp, into something else with a lot of force</div><ul class=\"examples\"><li><strong><em>bury something in something</strong>: The dog buried its teeth in my leg. / The bullet buried itself in the wall.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>bury yourself in your work/studies etc</strong> to give all your attention to something:</div><ul class=\"examples\"><li><em>After the divorce, she buried herself in her work.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[information]</strong> to put information in a document in a place where it is unlikely to be noticed, or to not make it available to people:</div><ul class=\"examples\"><li><em>The story was buried at the back of the paper.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[loved one]</strong> <em>literary</em> to have someone you love die:</div><ul class=\"examples\"><li><em>She had buried her husband, two sons, and a daughter.</em></li></ul></div>","912":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural buses or busses especially American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a large vehicle that people pay to travel on</div><ul class=\"examples\"><li><strong><em>on a bus</strong>: There were a lot of people on the bus.</em></li><li><strong><em>by bus</strong>: The best way to get there is by bus.</em></li><li><em>I took a bus to San Francisco.</em></li><li><em>Buses run at 15 and 30 minutes past the hour.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a circuit that connects the main parts of a computer so that signals can be sent from one part of the computer to another</div></div>","913":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> ˈbus stop</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\">a place at the side of a road, marked with a sign, where buses stop for passengers</div></div>","914":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʊʃ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a plant with many thin branches growing up from the ground → tree, shrub:</div><ul class=\"examples\"><li><em>a rose bush</em></li><li><em>The child was hiding in the bushes.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the bush</strong> wild country that has not been cleared, especially in Australia or Africa</div><div class=\"sense\"><span class=\"snum\">3</span> a bush of hair is a lot of thick untidy hair</div></div>","915":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> busi‧ness</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪznəs/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[buying or selling goods or services]</strong> <span class=\"gram\">[uncountable]</span> the activity of making money by producing or buying and selling goods, or providing services: GRAMMARDon’t use ‘the business’ when talking in general about the activity of making money. You say: · Tourism is good for business. ✗Don’t say: Tourism is good for the business.Grammar guide ‒ NOUNS</div><ul class=\"examples\"><li><em>Students on the course learn about all aspects of business.</em></li><li><em>Carl began in the music business by running a recording studio.</em></li><li><em>We do business with a number of Italian companies.</em></li><li><em>He has a wide range of business interests.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[company]</strong> <span class=\"gram\">[countable]</span> an organization such as a company, shop, or factory that produces or sells goods or provides a service: ► see thesaurus at company</div><ul class=\"examples\"><li><em>She now has her own $25 million home-shopping business.</em></li><li><em>They don’t know how to run a business.</em></li><li><em>The company began as a small family business.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[how much work a company has]</strong> <span class=\"gram\">[uncountable]</span> the amount of work a company does or the amount of money it makes:</div><ul class=\"examples\"><li><em>We’re now doing twice as much business as we did last year.</em></li><li><em>Exports account for 72% of overall business.</em></li><li><strong><em>business is good/bad/slow etc</strong>: Business is slow during the summer.</em></li><li><strong><em>drum up business</strong> (=try to get more work for you or your company): Perot was in Europe, drumming up business for his new investment company.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[for your job]</strong> <span class=\"gram\">[uncountable]</span> work that you do as part of your job:</div><ul class=\"examples\"><li><em>She’s in New York this week on business (=for her work).</em></li><li><em>Hi Maggie! Is this phone call business or pleasure?</em></li><li><strong><em>business trip/meeting etc</strong>: We discussed the idea over a business lunch.</em></li><li><em>useful business contacts</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[what someone should be involved in]</strong> <span class=\"gram\">[uncountable]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if something is not your business or none of your business, you should not be involved in it or ask about it:</div><ul class=\"examples\"><li><em>It was not her business, she decided, to ask where the money came from.</em></li><li><em>It’s none of your business how much I weigh.</em></li><li><em>‘Who’s that girl you were with?’ ‘Mind your own business (=Don’t ask questions about something that does not concern you)!’</em></li><li><em>‘Are you going out with Kate tonight?’ ‘That’s my business (=it doesn’t concern you, so don’t ask me questions about it)’.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> if it is someone’s business to do something, it is their duty or responsibility to do it</div><ul class=\"examples\"><li><strong><em>it is the business of somebody to do something</strong>: It is the business of government to listen to the various groups within society.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[things to be dealt with]</strong> <span class=\"gram\">[uncountable]</span> things that need to be done or discussed:</div><ul class=\"examples\"><li><em>Okay, let’s get down to business (=start doing or discussing something).</em></li><li><em>‘Is there any other business?’ the chairman asked.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[matter]</strong> <span class=\"gram\">[singular]</span> a situation or activity, especially one that you have a particular opinion about or attitude towards</div><ul class=\"examples\"><li><strong><em>a serious/strange/funny etc business</strong>: Leon regards keeping fit as a serious business.</em></li><li><em>Tanya found the whole business ridiculous.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>be in business</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to be involved in business activities:</div><ul class=\"examples\"><li><em>The company has been in business for over 30 years.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>spoken</em> to have all that you need to start doing something:</div><ul class=\"examples\"><li><em>I’ve just got to buy the paint and then we’re in business.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>(go) out of business</strong> if a company goes out of business, or something puts it out of business, it stops operating, especially because of financial problems:</div><ul class=\"examples\"><li><em>Higher interest rates will drive small firms out of business.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>be back in business</strong> to be working or operating in a normal way again:</div><ul class=\"examples\"><li><em>The band are back in business after a long break.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>somebody was (just) minding their own business</strong> <em>spoken</em> used to say that someone was not doing anything unusual or wrong at the time when something unfair or bad happened to them:</div><ul class=\"examples\"><li><em>I was driving along, minding my own business, when the police stopped my car.</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>go about your business</strong> to do the things that you normally do:</div><ul class=\"examples\"><li><em>The street was full of ordinary people going about their business.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>make it your business to do something</strong> to make a special effort to do something:</div><ul class=\"examples\"><li><em>Ruth made it her business to get to know the customers.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>mean business</strong> <em>informal</em> to be serious about doing something even if it involves harming someone:</div><ul class=\"examples\"><li><em>The border is guarded by troops who mean business.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>unfinished business</strong> something you need to discuss further with someone or a situation that has not yet reached a satisfactory solution:</div><ul class=\"examples\"><li><em>The sudden death of a loved one can often leave the bereaved with an agonising sense of unfinished business.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>business is business</strong> <em>spoken</em> used to say that profit is the most important thing to consider:</div><ul class=\"examples\"><li><em>We can’t afford to employ someone who isn’t good at the job – business is business.</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>business as usual</strong> when someone or something is still working or operating normally when you think they might not be:</div><ul class=\"examples\"><li><em>Despite last night’s scare, it was business as usual in the White House today.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>have no business doing something/have no business to do something</strong> to do something you should not be doing:</div><ul class=\"examples\"><li><em>He was drunk and had no business driving.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>not be in the business of doing something</strong> to not be intending to do something because you think it is a bad idea:</div><ul class=\"examples\"><li><em>I’m not in the business of selling my best players.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>and all that business</strong> <em>spoken</em> <em>informal</em> and other things of the same general kind:</div><ul class=\"examples\"><li><em>She handles the publicity and all that business.</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>(it’s) the business</strong> <em>British English</em> <em>informal</em> used to say that something is very good or works well:</div><ul class=\"examples\"><li><em>Have you seen David’s new car? It’s the business!</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>do the business</strong> <em>British English</em> <em>informal</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to do what you are expected to do or what people want you to do:</div><ul class=\"examples\"><li><em>Come on, then, and do the business.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to have sex</div></div>","916":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> busi‧ness‧man</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪznəsmən/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural businessmen /-mən/)</span></div><div class=\"entry-body\"><div class=\"sense\">a man who works in business</div></div>","917":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">verb</span><span class=\"sub-badge badge-Medium\">Medium</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌst/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[transitive]</span></span><span class=\"meta-item\">(past tense and past participle bust British English, busted especially American English)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[break]</strong> <em>informal</em> to break something:</div><ul class=\"examples\"><li><em>I bust my watch this morning.</em></li><li><em>Tony busted the door down.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[police]</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> if the police bust someone, they charge them with a crime:</div><ul class=\"examples\"><li><em>He was busted by US inspectors at the border.</em></li><li><strong><em>bust somebody for something</strong>: Davis got busted for drugs.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <em>informal</em> if the police bust a place, they go into it to look for something illegal:</div><ul class=\"examples\"><li><em>Federal agents busted several money-exchange businesses.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[try hard]</strong> <strong>bust a gut</strong> (also bust your butt/ass<em>American English</em> <em>spoken</em>) <em>informal</em> to try extremely hard to do something:</div><ul class=\"examples\"><li><em>I bust a gut trying to finish that work on time.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[money]</strong> <em>American English</em> <em>informal</em> to use too much money, so that a business etc must stop operating:</div><ul class=\"examples\"><li><em>The trip to Spain will probably bust our budget.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>crime-busting/union-busting/budget-busting etc</strong> <em>informal</em> used with nouns to show that a situation is being ended or an activity is being stopped:</div><ul class=\"examples\"><li><em>crime-busting laws</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>... or bust!</strong> <em>informal</em> used to say that you will try very hard to go somewhere or do something:</div><ul class=\"examples\"><li><em>Idaho or bust!</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[military]</strong> <em>especially American English</em> to give someone a lower military rank as a punishment <em>SYN demote</em></div></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">noun</span><span class=\"sub-badge badge-Low\">Low</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a model of someone’s head, shoulders, and upper chest, usually made of stone or metal</div><ul class=\"examples\"><li><strong><em>bust of</strong>: a bust of Beethoven</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a woman’s breasts, or the part of her clothes that covers her breasts</div><div class=\"sense\"><span class=\"snum\">3</span> a measurement around a woman’s breast and back:</div><ul class=\"examples\"><li><em>a 36-inch bust</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <em>informal</em> a situation in which the police go into a place in order to catch people doing something illegal:</div><ul class=\"examples\"><li><em>a drug bust</em></li></ul></div></div>","918":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> bus‧y</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbɪzi/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W2</span><span class=\"meta-item\">(comparative busier, superlative busiest)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[person]</strong> if you are busy, you are working hard and have a lot of things to do: GRAMMARYou are busy with something: · I’m very busy with work at the moment. ✗Don’t say: busy for something | busy on somethingGrammar guide ‒ ADJECTIVES</div><ul class=\"examples\"><li><em>She’s busy now – can you phone later?</em></li><li><em>a busy mother of four</em></li><li><strong><em>busy with</strong>: Mr Haynes is busy with a customer at the moment.</em></li><li><strong><em>busy doing something</strong>: Rachel’s busy studying for her exams.</em></li><li><em>There were lots of activities to keep the kids busy.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[time]</strong> a busy period of time is full of work or other activities:</div><ul class=\"examples\"><li><em>December is the busiest time of year for shops.</em></li><li><em>a busy day</em></li><li><em>He took time out of his busy schedule to visit us.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[place]</strong> a busy place is very full of people or vehicles and movement:</div><ul class=\"examples\"><li><em>We live on a very busy road.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[telephone]</strong> <em>especially American English</em> if a telephone you are calling is busy, it makes a repeated sound to tell you that the person you are calling is talking on their telephone SYN engaged<em>British English</em>:</div><ul class=\"examples\"><li><em>I called Sonya, but her line was busy.</em></li><li><em>I keep getting a busy signal.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[pattern]</strong> a pattern or design that is busy is too full of small details – used to show disapproval</div></div>","919":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">conjunction</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bət; strong bʌt/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> used to connect two statements or phrases when the second one adds something different or seems surprising after the first one:</div><ul class=\"examples\"><li><em>It’s an old car, but it’s very reliable.</em></li><li><em>They rushed to the hospital, but they were too late.</em></li><li><em>We’ve invited the boss, but she may decide not to come.</em></li><li><em>an expensive but extremely useful book</em></li><li><em>‘Has he got any experience?’ ‘No, but he’s keen to learn.’</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to introduce a statement that explains why the thing you have mentioned did not happen or is not possible:</div><ul class=\"examples\"><li><em>I’d like to go but I’m too busy.</em></li><li><em>They would have married sooner, but they had to wait for her divorce.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> used after a negative to emphasize that it is the second part of the sentence that is true:</div><ul class=\"examples\"><li><em>He lied to the court not just once, but on several occasions.</em></li><li><em>The purpose of the scheme is not to help the employers but to provide work for young people.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> except: ► see thesaurus at except</div><ul class=\"examples\"><li><em>What can we do but sit and wait?</em></li><li><em>I had no choice but to accept the challenge.</em></li><li><em>Not a day goes by but I think of dear old Larry (=I think of him every day).</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>but for</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when you are saying that something would have happened if something or someone else had not prevented it:</div><ul class=\"examples\"><li><em>But for these interruptions, the meeting would have finished earlier.</em></li><li><em>The score could have been higher but for some excellent goalkeeping by Simon.</em></li><li><em>I might never have got to university but for you.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> except for something or someone:</div><ul class=\"examples\"><li><em>All was silent but for the sound of the wind in the trees.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>but then (again)</strong> <em>spoken</em></div><div class=\"subsense\"><span class=\"subnum\">a)</span> used when you are adding a statement that says almost the opposite of what you have just said:</div><ul class=\"examples\"><li><em>John might be ready to help us, but then again, he might not.</em></li><li><em>You feel really sorry for him. But then again, it’s hard to like him.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> used when you are adding a statement that makes what you have just said seem less surprising:</div><ul class=\"examples\"><li><em>Dinah missed the last rehearsal, but then she always was unreliable, wasn’t she?</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <em>spoken</em> used when you are replying to someone and expressing strong feelings such as anger, surprise etc:</div><ul class=\"examples\"><li><em>But that’s marvellous news!</em></li><li><em>‘They won’t even discuss the problem.’ ‘But how stupid!’</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>somebody cannot but do something</strong> <em>formal</em> used to say that someone has to do something or cannot stop themselves from doing it:</div><ul class=\"examples\"><li><em>I could not but admire her.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <em>spoken</em> used when disagreeing with someone:</div><ul class=\"examples\"><li><em>‘It was a good idea.’ ‘But it didn’t work.’</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <em>spoken</em> used to emphasize a word or statement:</div><ul class=\"examples\"><li><em>It’ll be a great party – everyone, but everyone, is coming.</em></li><li><em>They’re rich, but I mean rich.</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <em>spoken</em> used to change the subject of a conversation:</div><ul class=\"examples\"><li><em>But now to the main question.</em></li><li><em>But tell me, are you really planning to retire?</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <em>spoken</em> used after expressions such as ‘Excuse me’ and ‘I’m sorry’:</div><ul class=\"examples\"><li><em>Excuse me, but I’m afraid this is a no-smoking area.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2 W3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> apart from <em>SYN except</em>:</div><ul class=\"examples\"><li><em>I could come any day but Thursday.</em></li><li><em>There’s no one here but me.</em></li><li><em>I could still see nothing but the spirals of desert dust.</em></li><li><em>He was unable to swallow anything but liquids.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>the last but one/the next but two etc</strong> <em>especially British English</em> the last or next thing or person except for one, two etc:</div><ul class=\"examples\"><li><em>Pauline and Derek live in the next house but one (=they live two houses away from us).</em></li></ul></div></div>","920":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> butch‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʊtʃə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <span class=\"gram\">[countable]</span> someone who owns or works in a shop that sells meat</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>the butcher’s</strong> a shop where you can buy meat</div><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[countable]</span> someone who has killed someone else cruelly and unnecessarily, especially someone who has killed a lot of people</div><div class=\"sense\"><span class=\"snum\">4</span> <strong>have/take a butcher’s</strong> <em>British English</em> <em>spoken</em> <em>informal</em> to have a look at something</div></div>","921":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> but‧ter</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌtə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[uncountable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a solid yellow food made from milk or cream that you spread on bread or use in cooking → bread-and-butter</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>butter wouldn’t melt in somebody’s mouth</strong> used to say that someone seems to be very kind and sincere but is not really</div></div>","922":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> but‧ter‧fly</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌtəflaɪ $ -ər-/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span><span class=\"meta-item\">(plural butterflies)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a type of insect that has large wings, often with beautiful colours</div><div class=\"sense\"><span class=\"snum\">2</span> <strong>have/get butterflies (in your stomach)</strong> <em>informal</em> to feel very nervous before doing something:</div><ul class=\"examples\"><li><em>I always get butterflies before an exam.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>the butterfly</strong> a way of swimming by lying on your front and moving your arms together over your head while your legs move up and down</div><div class=\"sense\"><span class=\"snum\">4</span> someone who usually moves on quickly from one activity or person to the next:</div><ul class=\"examples\"><li><em>Gwen’s a real social butterfly.</em></li></ul></div>","923":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> but‧tock</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌtək/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span><span class=\"meta-item\"><span class=\"gram\">[countable usually plural]</span></span></div><div class=\"entry-body\"><div class=\"sense\">one of the fleshy parts of your body that you sit on</div></div>","924":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> but‧ton</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbʌtn/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S2</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> a small round flat object on your shirt, coat etc that you pass through a hole to fasten it:</div><ul class=\"examples\"><li><em>small pearl buttons</em></li><li><em>A button was missing from his shirt.</em></li><li><em>She undid (=unfastened) the buttons of her blouse.</em></li><li><strong><em>do up a button<em>British English</em></strong> (=fasten a button)</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> a small part or area of a machine that you press to make it do something: → push-button</div><ul class=\"examples\"><li><em>Press the pause button.</em></li><li><em>Click on the icon with the right mouse button.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> a small area on a computer screen, especially on a website, that you click on in order to perform an action</div><div class=\"sense\"><span class=\"snum\">4</span> <em>American English</em> a small metal or plastic pin with a message or picture on it SYN badge<em>British English</em>:</div><ul class=\"examples\"><li><em>presidential campaign buttons</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>button nose/eyes</strong> a nose or eyes that are small and round</div><div class=\"sense\"><span class=\"snum\">6</span> <strong>on the button</strong> <em>especially American English</em> <em>informal</em> exactly right, or at exactly the right time:</div><ul class=\"examples\"><li><em>She got to our house at two, on the button.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>press/push (all) the right buttons</strong> to get what you want by behaving in a clever way:</div><ul class=\"examples\"><li><em>She seemed to push all the right buttons.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>press/push somebody’s buttons</strong> to make someone angry by doing or saying something that annoys them:</div><ul class=\"examples\"><li><em>He really knows how to push Dad’s buttons.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>at/with the push/touch of a button</strong> used to emphasize how easy a machine is to use because it is controlled by pushing a button:</div><ul class=\"examples\"><li><em>The instrument can gauge a distance with the push of a button.</em></li></ul></div>","925":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span><span class=\"meta-item\">(past tense and past participle bought /bɔːt $ bɒːt/)</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> </div><div class=\"subsense\"><span class=\"subnum\">a)</span> <span class=\"gram\">[intransitive, transitive]</span> to get something by paying money for it <em>OPP sell</em>:</div><ul class=\"examples\"><li><em>Where did you buy that dress?</em></li><li><em>Ricky showed her the painting he’d bought that morning.</em></li><li><strong><em>buy somebody something</strong>: Let me buy you a drink.</em></li><li><strong><em>buy something for somebody/something</strong>: The money will be used to buy equipment for the school.</em></li><li><strong><em>buy (something) from somebody</strong>: It’s cheaper to buy direct from the manufacturer.</em></li><li><strong><em>buy something for $10/£200 etc</strong>: Dan bought the car for $2,000.</em></li><li><em>It’s much cheaper to buy in bulk (=buy large quantities of something).</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> <span class=\"gram\">[transitive]</span> if a sum of money buys something, it is enough to pay for it:</div><ul class=\"examples\"><li><em>$50 doesn’t buy much these days.</em></li><li><strong><em>buy somebody something</strong>: $15 should buy us a pizza and a drink.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>buy (somebody) time</strong> to deliberately make more time for yourself to do something, for example by delaying a decision:</div><ul class=\"examples\"><li><em>‘Can we talk about it later?’ he said, trying to buy a little more time.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <span class=\"gram\">[transitive]</span> <em>informal</em> to believe something that someone tells you, especially when it is not likely to be true:</div><ul class=\"examples\"><li><em>‘Let’s just say it was an accident.’ ‘He’ll never buy that.’</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <span class=\"gram\">[transitive]</span> <em>informal</em> to pay money to someone, especially someone in a position of authority, in order to persuade them to do something dishonest <em>SYN bribe</em>:</div><ul class=\"examples\"><li><em>People say the judge had been bought by the Mafia.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>buy something at the cost/expense/price of something</strong> to get something that you want, but only by losing something else:</div><ul class=\"examples\"><li><em>The town has been careful not to buy prosperity at the expense of its character.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>somebody bought it</strong> <em>old-fashioned</em> <em>informal</em> someone was killed</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>buy off-plan</strong> if you buy property off-plan, you buy a house, flat etc that is just starting to be built, with an arrangement to pay part of the cost of the property at that time and the balance when the property is finished</div></div>","926":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>Syllables:</strong> buy‧er</span><span class=\"meta-item\"><strong>IPA:</strong> /ˈbaɪə $ -ər/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●○ S3 W3</span><span class=\"meta-item\"><span class=\"gram\">[countable]</span></span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> someone who buys something expensive such as a house or car <em>OPP seller</em> <em>, vendor</em>:</div><ul class=\"examples\"><li><em>There were several potential buyers.</em></li><li><em>discounts for first-time buyers</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> someone whose job is to choose and buy the goods for a shop or company:</div><ul class=\"examples\"><li><em>a buyer for a chain store</em></li></ul></div>","927":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /bʌz/</span><span class=\"meta-item\"><strong>Freq:</strong> ●○○</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[make a sound]</strong> <span class=\"gram\">[intransitive]</span> to make a continuous sound, like the sound of a bee:</div><ul class=\"examples\"><li><em>a loud buzzing noise</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[moving around]</strong> <span class=\"gram\">[intransitive always + adverb/preposition]</span>:</div><ul class=\"examples\"><li><em>Pamela buzzed around checking that everything was ready.</em></li><li><em>There were all sorts of rumours buzzing through the office.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">a)</span> to move around in the air making a continuous sound like a bee:</div><ul class=\"examples\"><li><em>Bees were buzzing around the picnic tables.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to move quickly around a place</div><div class=\"sense\"><span class=\"snum\">3</span> <strong>[excitement]</strong> <span class=\"gram\">[intransitive]</span> if a group of people or a place is buzzing, there is a lot of activity or excitement</div><ul class=\"examples\"><li><strong><em>buzz with</strong>: a classroom buzzing with activity</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[call]</strong> <span class=\"gram\">[intransitive, transitive]</span></div><div class=\"subsense\"><span class=\"subnum\">a)</span> to call someone by pressing a buzzer:</div><ul class=\"examples\"><li><em>Kramer buzzed at the security door, and I let him in.</em></li><li><strong><em>buzz for</strong>: Tina buzzed for her secretary.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> to make something happen, for example make a door or gate open or close, by pressing a buzzer</div><ul class=\"examples\"><li><strong><em>buzz somebody in/out</strong>: She buzzed them in and greeted them warmly.</em></li><li><strong><em>buzz somebody through something</strong>: The guard buzzed me through the gate.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[thoughts]</strong> <span class=\"gram\">[intransitive]</span> if your head or mind is buzzing with thoughts, ideas etc, you cannot stop thinking about them</div><ul class=\"examples\"><li><strong><em>buzz with</strong>: My mind was buzzing with new ideas.</em></li><li><em>Questions started buzzing round in my head.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[ears]</strong> <span class=\"gram\">[intransitive]</span> if your ears or head are buzzing, you can hear a continuous low unpleasant sound</div><div class=\"sense\"><span class=\"snum\">7</span> <strong>[aircraft]</strong> <span class=\"gram\">[transitive]</span> <em>informal</em> to fly an aircraft low and fast over buildings, people etc:</div><ul class=\"examples\"><li><em>Military jets buzzed the city.</em></li></ul></div>","928":"<div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">preposition</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> <strong>[who/what does something]</strong> used especially with a passive verb to say who or what does something or makes something happen:</div><ul class=\"examples\"><li><em>I was attacked by a dog.</em></li><li><em>a church designed by the famous architect, Sir Christopher Wren</em></li><li><em>We are all alarmed by the rise in violent crime.</em></li><li><em>interference by the state in the affairs of the Church</em></li><li><em>his appointment by the BBC as a producer</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> <strong>[means/method]</strong> used to say what means or method someone uses to do something:</div><ul class=\"examples\"><li><em>You can reserve the tickets by phone.</em></li><li><em>Send it by airmail.</em></li><li><em>Some customers prefer to pay by cheque.</em></li><li><strong><em>by car/train/bus/taxi etc</strong>: They travelled to Chicago by train.</em></li><li><strong><em>by air/sea/land/road/rail etc</strong>: All supplies are transported by air.</em></li><li><strong><em>by doing something</strong>: She earns her living by selling insurance.</em></li><li><em>He was taken from his home by force.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> <strong>[road/door]</strong> used to say which road, entrance, door etc someone uses to get to a place:</div><ul class=\"examples\"><li><em>They came in by the back door.</em></li><li><em>It’s quicker to go by the country route.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> <strong>[taking hold]</strong> used to say which part of an object or of a person’s body someone takes hold of:</div><ul class=\"examples\"><li><em>He took Elaine by the arm and led her across the road.</em></li><li><em>She grabbed the hammer by the handle.</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>[writer/composer etc]</strong> used to give the name of someone who wrote a book, produced a film, wrote a piece of music etc:</div><ul class=\"examples\"><li><em>the ‘New World symphony’ by Dvorak</em></li><li><em>a short story by Charles Dickens</em></li><li><em>Who’s it by?</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>[beside]</strong> beside or near something:</div><ul class=\"examples\"><li><em>She stood by the window.</em></li><li><em>Jane went and sat by Patrick.</em></li></ul><div class=\"sense\"><span class=\"snum\">7</span> <strong>[past]</strong> past someone or something without stopping:</div><ul class=\"examples\"><li><em>He walked right by me without even saying hello.</em></li><li><em>I pass by the farm every day on my way to work.</em></li></ul><div class=\"sense\"><span class=\"snum\">8</span> <strong>[before]</strong> before or not later than a particular time: ► see thesaurus at before</div><ul class=\"examples\"><li><em>The documents need to be ready by next Friday.</em></li><li><em>I reckon the film should be over by 9.30.</em></li><li><em>By the end of the day we had sold over 2,000 tickets.</em></li><li><em>By the time we got home we were tired and hungry.</em></li></ul><div class=\"sense\"><span class=\"snum\">9</span> <strong>[according to]</strong> according to a particular rule, method, or way of doing things:</div><ul class=\"examples\"><li><em>You’ve got to play by the rules.</em></li><li><em>Profits were £6 million, but by our standards this is low.</em></li></ul><div class=\"sense\"><span class=\"snum\">10</span> <strong>[change/difference]</strong> used to say how great a change or difference is:</div><ul class=\"examples\"><li><em>The price of oil fell by a further $2 a barrel.</em></li><li><em>I was overcharged by £3.</em></li><li><em>Godard’s first film was better by far (=by a large amount or degree).</em></li></ul><div class=\"sense\"><span class=\"snum\">11</span> <strong>[measurements]</strong> used to give the measurements of a room, container etc:</div><ul class=\"examples\"><li><em>a room 15 metres by 23 metres</em></li></ul><div class=\"sense\"><span class=\"snum\">12</span> <strong>[quantity]</strong> used to show what unit of measurement or quantity is involved in selling, paying for, producing etc something:</div><ul class=\"examples\"><li><em>Eggs are sold by the dozen.</em></li><li><em>We’re paid by the hour.</em></li><li><em>She wanted to tear his hair out by the handful.</em></li></ul><div class=\"sense\"><span class=\"snum\">13</span> <strong>[gradual change]</strong> used to say that something happens gradually:</div><ul class=\"examples\"><li><em>Day by day, he grew weaker.</em></li><li><em>Little by little, I was beginning to discover the truth about Garfield.</em></li><li><em>One by one, the men stepped forward.</em></li></ul><div class=\"sense\"><span class=\"snum\">14</span> <strong>[quick change]</strong> used to say that something or someone is quickly becoming worse, better etc:</div><ul class=\"examples\"><li><em>The financial crisis was growing more serious by the hour.</em></li></ul><div class=\"sense\"><span class=\"snum\">15</span> <strong>[light]</strong> used to say that something happens in a particular kind of light:</div><ul class=\"examples\"><li><em>We walked through the palace gardens by moonlight.</em></li></ul><div class=\"sense\"><span class=\"snum\">16</span> <strong>by day/night</strong> during the day or the night:</div><ul class=\"examples\"><li><em>a tour of Paris by night</em></li></ul><div class=\"sense\"><span class=\"snum\">17</span> <strong>[job/nature etc]</strong> used when you are giving information about someone’s character, job, origin etc:</div><ul class=\"examples\"><li><em>George I and George II were Germans by birth.</em></li><li><em>Cautious by nature, Simpkin was reluctant to interfere.</em></li><li><em>Robert Key was a teacher by profession.</em></li></ul><div class=\"sense\"><span class=\"snum\">18</span> <strong>[visiting]</strong> in order to visit a person or place for a short time:</div><ul class=\"examples\"><li><em>On the way, I stopped by the post office.</em></li></ul><div class=\"sense\"><span class=\"snum\">19</span> <strong>(all) by yourself</strong></div><div class=\"subsense\"><span class=\"subnum\">a)</span> completely alone:</div><ul class=\"examples\"><li><em>Dave spent Christmas all by himself.</em></li></ul><div class=\"subsense\"><span class=\"subnum\">b)</span> without help from anyone:</div><ul class=\"examples\"><li><em>You can’t move the furniture all by yourself.</em></li></ul><div class=\"sense\"><span class=\"snum\">20</span> <strong>[multiplying/dividing]</strong> used between two numbers when talking about multiplying or dividing:</div><ul class=\"examples\"><li><em>What’s 48 divided by 4?</em></li></ul><div class=\"sense\"><span class=\"snum\">21</span> <strong>[emphasis]</strong> used when expressing strong feelings or making serious promises:</div><ul class=\"examples\"><li><em>By God, I’ll kill that boy when I see him!</em></li></ul><div class=\"sense\"><span class=\"snum\">22</span> <strong>[father]</strong> if a woman has children by a particular man, that man is the children’s father:</div><ul class=\"examples\"><li><em>She’s got two children by her previous husband.</em></li></ul><div class=\"sense\"><span class=\"snum\">23</span> <strong>by the by</strong> <em>spoken</em> used when mentioning something that may be interesting but is not particularly important: → by the way at way1</div><ul class=\"examples\"><li><em>By the by, Ian said he might call round tonight.</em></li></ul></div></div><div class=\"pos-section\"><div class=\"pos-header\"><span class=\"pos-pill\">adverb</span></div><div class=\"entry-meta\"><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1 W1</span></div><div class=\"entry-body\"><div class=\"sense\"><span class=\"snum\">1</span> past someone or something:</div><ul class=\"examples\"><li><em>As I was standing on the platform, the Liverpool train went whizzing by.</em></li><li><em>James walked by without even looking in my direction.</em></li></ul><div class=\"sense\"><span class=\"snum\">2</span> used to say that time passes:</div><ul class=\"examples\"><li><em>As the summer days slipped by, it was easy to forget about the war.</em></li><li><em>Ten years had gone by since I had last seen Marilyn.</em></li></ul><div class=\"sense\"><span class=\"snum\">3</span> beside or near someone or something:</div><ul class=\"examples\"><li><em>A crowd of people were standing by, waiting for an announcement.</em></li></ul><div class=\"sense\"><span class=\"snum\">4</span> in order to visit a person or place for a short time:</div><ul class=\"examples\"><li><em>Why don’t you stop by for a drink after work?</em></li></ul><div class=\"sense\"><span class=\"snum\">5</span> <strong>by and large</strong> used when making a general statement:</div><ul class=\"examples\"><li><em>By and large, the new arrangements have worked well.</em></li></ul><div class=\"sense\"><span class=\"snum\">6</span> <strong>by and by</strong> <em>old use</em> soon:</div><ul class=\"examples\"><li><em>She will be better by and by.</em></li></ul></div></div>","929":"<div class=\"entry-meta\"><span class=\"meta-item\"><strong>IPA:</strong> /baɪ/</span><span class=\"meta-item\"><strong>Freq:</strong> ●●● S1</span></div><div class=\"entry-body\"><div class=\"sense\"><em>informal</em> goodbye:</div><ul class=\"examples\"><li><em>Bye, Dave.</em></li><li><strong><em>bye for now</strong> (=used to say that you will see or speak to someone again soon)</em></li></ul></div>"};